	public static sbyte GetCharacterInjuryCount(GameData.Domains.Character.Character character)
	{
		Injuries injuries = character.GetInjuries();
		sbyte count = 0;
		for (sbyte i = 0; i < 7; i++)
		{
			(sbyte, sbyte) tuple = injuries.Get(i);
			count += tuple.Item1;
			count += tuple.Item2;
		}
		return count;
	}

