	public static bool CanStartRelation(int charId, int relatedCharId, ushort relationType)
	{
		if (relationType != 16384 && !RelationTypeHelper.AllowAddingRelation(charId, relatedCharId, relationType))
		{
			return false;
		}
		GameData.Domains.Character.Character selfChar = DomainManager.Character.GetElement_Objects(charId);
		GameData.Domains.Character.Character targetChar = DomainManager.Character.GetElement_Objects(relatedCharId);
		RelatedCharacter selfToTarget = DomainManager.Character.GetRelation(charId, relatedCharId);
		RelatedCharacter targetToSelf = DomainManager.Character.GetRelation(relatedCharId, charId);
		selfToTarget.Favorability = 30000;
		return relationType switch
		{
			32768 => AiHelper.Relation.CanStartRelation_Enemy(selfToTarget, selfChar.GetBehaviorType()), 
			16384 => AiHelper.Relation.CanStartRelation_BoyOrGirlFriend(selfToTarget, selfChar.GetBehaviorType(), targetToSelf, targetChar.GetBehaviorType()), 
			1024 => AiHelper.Relation.CanStartRelation_HusbandOrWife(charId, selfToTarget, selfChar.GetBehaviorType(), relatedCharId, targetToSelf, targetChar.GetBehaviorType()), 
			8192 => AiHelper.Relation.CanStartRelation_Friend(selfToTarget, selfChar.GetBehaviorType(), targetToSelf, targetChar.GetBehaviorType()), 
			512 => AiHelper.Relation.CanStartRelation_SwornBrotherOrSister(selfToTarget, selfChar.GetBehaviorType(), targetToSelf, targetChar.GetBehaviorType()), 
			64 => AiHelper.Relation.CanStartRelation_AdoptiveParent(charId, selfToTarget, selfChar.GetCurrAge(), relatedCharId, targetToSelf, targetChar.GetCurrAge()), 
			128 => AiHelper.Relation.CanStartRelation_AdoptiveChild(charId, selfToTarget, selfChar.GetCurrAge(), relatedCharId, targetToSelf, targetChar.GetCurrAge()), 
			_ => throw new Exception($"Unsupported relation type for starting in event: {relationType}"), 
		};
	}

	public static bool CanEndRelation(int charId, int relatedCharId, ushort relationType)
	{
		RelatedCharacter selfToTarget = DomainManager.Character.GetRelation(charId, relatedCharId);
		RelatedCharacter targetToSelf = DomainManager.Character.GetRelation(relatedCharId, charId);
		return relationType switch
		{
			16384 => RelationType.HasRelation(selfToTarget.RelationType, 16384) && RelationType.HasRelation(targetToSelf.RelationType, 16384), 
			32768 => RelationType.HasRelation(targetToSelf.RelationType, 32768), 
			8192 => RelationType.HasRelation(selfToTarget.RelationType, 8192), 
			512 => RelationType.HasRelation(selfToTarget.RelationType, 512), 
			_ => throw new Exception($"Unsupported relation type for ending in event: {relationType}"), 
		};
	}

