	public static bool CheckConfessLoveSucceed(int charId, int relatedCharId)
	{
		DomainManager.Character.TryGetElement_Objects(charId, out var selfChar);
		DomainManager.Character.TryGetElement_Objects(relatedCharId, out var relatedChar);
		if (CheckHasRelationship(relatedChar, selfChar, 16384))
		{
			return true;
		}
		int successRate = GetConfessLoveSucceedProb(charId, relatedCharId);
		bool success = Domain.MainThreadDataContext.Random.CheckPercentProb(successRate);
		if (!success && DomainManager.TaiwuEvent.InteractCheckData != null)
		{
			DomainManager.TaiwuEvent.InteractCheckData.FailPhase = 0;
			DomainManager.TaiwuEvent.InteractCheckData.FailPhaseIndex = 0;
		}
		return success;
	}

