	public static void ChangeCombatResources(int charId, sbyte healingCountAdd, sbyte detoxCountAdd)
	{
		CombatResources usableCombatResource = DomainManager.Character.GetUsableCombatResources(charId);
		CombatResources usedCombatResource = DomainManager.Character.GetUsedCombatResources(charId);
		healingCountAdd = (sbyte)Math.Clamp(healingCountAdd, -usedCombatResource.HealingCount, usableCombatResource.HealingCount);
		detoxCountAdd = (sbyte)Math.Clamp(detoxCountAdd, -usedCombatResource.DetoxCount, usableCombatResource.DetoxCount);
		DomainManager.Character.UseCombatResources(Domain.MainThreadDataContext, charId, EHealActionType.Healing, healingCountAdd);
		DomainManager.Character.UseCombatResources(Domain.MainThreadDataContext, charId, EHealActionType.Detox, detoxCountAdd);
	}

