	public static bool CheckConfessionLoveOptionIsVisible(int charId)
	{
		if (!DomainManager.Taiwu.IsNormalInteractionUnlocked())
		{
			return false;
		}
		GameData.Domains.Character.Character taiwu = DomainManager.Character.GetElement_Objects(DomainManager.Taiwu.GetTaiwuCharId());
		GameData.Domains.Character.Character character = DomainManager.Character.GetElement_Objects(charId);
		if (taiwu == null || character == null)
		{
			return false;
		}
		if (CheckRespondLoveOptionIsVisible(charId))
		{
			return false;
		}
		if (GetRoleAgeAvailableForLove(taiwu) && GetRoleAgeAvailableForLove(character) && CheckHasRelationship(taiwu, character, 8192))
		{
			if (CheckHasRelationship(taiwu, character, 16384) && CheckHasRelationship(character, taiwu, 16384))
			{
				return false;
			}
			if (CheckHasRelationship(taiwu, character, 2048) || CheckHasRelationship(character, taiwu, 2048))
			{
				return false;
			}
			if (HasNominalBloodRelation(taiwu.GetId(), character.GetId()))
			{
				return false;
			}
			if (HasBloodExclusionRelation(taiwu.GetId(), character.GetId()) && !CheckHasRelationship(taiwu, character, 1024))
			{
				return false;
			}
			return true;
		}
		return false;
	}

