	public static bool IsCharacterRefuseAppointment(GameData.Domains.Character.Character character, Location location, out int needMonth)
	{
		needMonth = 1;
		GameData.Domains.Character.Character taiwuChar = DomainManager.Taiwu.GetTaiwu();
		short favor = GetFavorability(character, taiwuChar);
		sbyte favorType = FavorabilityType.GetFavorabilityType(favor);
		Location fromLocation = character.GetLocation();
		Location toLocation = location;
		if (!fromLocation.IsValid() || !toLocation.IsValid())
		{
			return false;
		}
		if (fromLocation.AreaId == toLocation.AreaId)
		{
			needMonth = 1;
		}
		else
		{
			CrossAreaMoveInfo crossTravelRoute = DomainManager.Map.CalcAreaTravelRoute(character, fromLocation.AreaId, fromLocation.BlockId, toLocation.AreaId);
			int totalDays = 0;
			foreach (short item in crossTravelRoute.Route.CostList)
			{
				totalDays += item;
			}
			needMonth = (totalDays + 29) / 30;
		}
		return favorType < 3 || character.CurrentActionBlockAppointment();
	}

