	public static bool CheckStartRelationSucceed(int charIdA, int charIdB, ushort relationType, bool isBothWayRelation = true)
	{
		CharacterDomain characterDomain = DomainManager.Character;
		if (!characterDomain.TryGetElement_Objects(charIdA, out var characterA) || !characterDomain.TryGetElement_Objects(charIdB, out var characterB))
		{
			throw new Exception($"Wrong Checking Request Between {charIdA} & {charIdB}!");
		}
		if (characterA.GetCreatingType() != 1 || characterB.GetCreatingType() != 1)
		{
			return false;
		}
		if (charIdB == EventArgBox.TaiwuCharacterId)
		{
			return true;
		}
		if (!characterDomain.TryGetRelation(charIdA, charIdB, out var selfToTarget))
		{
			characterDomain.TryCreateGeneralRelation(DomainManager.TaiwuEvent.MainThreadDataContext, characterA, characterB);
			selfToTarget = characterDomain.GetRelation(charIdA, charIdB);
		}
		if (!characterDomain.TryGetRelation(charIdB, charIdA, out var targetToSelf))
		{
			characterDomain.TryCreateGeneralRelation(DomainManager.TaiwuEvent.MainThreadDataContext, characterB, characterA);
			targetToSelf = characterDomain.GetRelation(charIdB, charIdA);
		}
		switch (relationType)
		{
		case 512:
		case 8192:
			return true;
		case 64:
		case 128:
			if (FavorabilityType.GetFavorabilityType(selfToTarget.Favorability) >= 4 && FavorabilityType.GetFavorabilityType(targetToSelf.Favorability) >= 4)
			{
				return true;
			}
			return false;
		case 2048:
			return true;
		case 16384:
		{
			int successRate;
			if (isBothWayRelation)
			{
				successRate = AiHelper.Relation.GetStartRelationSuccessRate_BoyOrGirlFriend(characterA, characterB, selfToTarget, targetToSelf);
				if (CheckProbability(successRate))
				{
					return true;
				}
				return false;
			}
			if (CheckHasRelationship(characterB, characterA, 16384))
			{
				return false;
			}
			successRate = AiHelper.Relation.GetStartRelationSuccessRate_Adored(characterA, characterB, selfToTarget, targetToSelf);
			if (CheckProbability(successRate))
			{
				return true;
			}
			return false;
		}
		case 32768:
		{
			sbyte behavior = characterB.GetBehaviorType();
			sbyte prob = AiHelper.RelationsRelatedConstants.SeverEnemyNotMutuallyChance[behavior];
			return CheckProbability(prob);
		}
		case 1024:
		{
			int successRate = AiHelper.Relation.GetStartRelationSuccessRate_HusbandOrWife(characterA, characterB, selfToTarget, targetToSelf);
			if (CheckProbability(successRate))
			{
				return true;
			}
			return false;
		}
		default:
			return false;
		}
	}

	public static bool CheckEndRelationSucceed(int charIdA, int charIdB, ushort relationType, bool isBothWayRelation = true)
	{
		if (!DomainManager.Character.TryGetElement_Objects(charIdA, out var _) || !DomainManager.Character.TryGetElement_Objects(charIdB, out var characterB))
		{
			throw new Exception($"Wrong Checking Request Between {charIdA} & {charIdB}!");
		}
		if (charIdB == EventArgBox.TaiwuCharacterId)
		{
			return true;
		}
		sbyte targetBehaviorType = characterB.GetBehaviorType();
		switch (relationType)
		{
		case 512:
		case 8192:
			return true;
		case 64:
		case 128:
		case 1024:
		case 2048:
			return true;
		case 32768:
		{
			bool targetStillHateSelf = CheckProbability(AiHelper.RelationsRelatedConstants.SeverEnemyNotMutuallyChance[targetBehaviorType]);
			return !targetStillHateSelf;
		}
		case 16384:
			if (isBothWayRelation)
			{
				bool targetStillLoveSelf = CheckProbability(AiHelper.RelationsRelatedConstants.BreakupMutuallyChance[targetBehaviorType]);
				return !targetStillLoveSelf;
			}
			return true;
		default:
			return false;
		}
	}

