	public static bool CheckMajorEventActivated(Location location, int coreId)
	{
		if (!location.IsValid())
		{
			return false;
		}
		AdventureCacheData cache = DomainManager.Adventure.GetAdventureCache();
		AdventureBlockCacheData data = cache.GetCacheData(location);
		if (data == null || !data.AnyMajorEvent)
		{
			return false;
		}
		AdventureMajorEvent majorEvent = DomainManager.Adventure.GetElement_AdventureMajorEvents(data.MajorEventId);
		return majorEvent.CoreId == coreId && majorEvent.StatusType == EAdventureStatusType.Ready;
	}

	public static bool CheckAdventureActivated(Location location, int coreId)
	{
		if (!location.IsValid())
		{
			return false;
		}
		AdventureCacheData cache = DomainManager.Adventure.GetAdventureCache();
		AdventureBlockCacheData data = cache.GetCacheData(location);
		if (data == null || !data.AnyAdventure)
		{
			return false;
		}
		AdventureRuntime adventure = DomainManager.Adventure.GetElement_Adventures(data.AdventureId);
		return adventure.CoreId == coreId && adventure.StatusType == EAdventureStatusType.Ready;
	}

	public static bool ForceOverrideMajorEvent(Location location, int coreId)
	{
		if (!location.IsValid())
		{
			return false;
		}
		AdventureCacheData cache = DomainManager.Adventure.GetAdventureCache();
		AdventureBlockCacheData data = cache.GetCacheData(location);
		if (data != null && data.AnyMajorEvent)
		{
			DomainManager.Adventure.RemoveMajorEvent(Domain.MainThreadDataContext, data.MajorEventId, EAdventureRemoveType.Instruction);
		}
		DomainManager.Adventure.GenerateMajorEvent(Domain.MainThreadDataContext, coreId, location);
		return true;
	}

	public static bool ForceOverrideAdventure(Location location, int coreId, bool visible)
	{
		if (!location.IsValid())
		{
			return false;
		}
		AdventureCacheData cache = DomainManager.Adventure.GetAdventureCache();
		AdventureBlockCacheData data = cache.GetCacheData(location);
		if (data != null && data.AnyAdventure)
		{
			DomainManager.Adventure.RemoveAdventure(Domain.MainThreadDataContext, data.AdventureId, EAdventureRemoveType.Instruction);
		}
		IAdventureRuntime runtime = DomainManager.Adventure.GenerateAny(Domain.MainThreadDataContext, coreId, location);
		if (runtime != null)
		{
			runtime.CallCharacters(Domain.MainThreadDataContext);
			if (visible)
			{
				DomainManager.Map.GetBlock(location.AreaId, location.BlockId)?.SetVisible(visible: true, Domain.MainThreadDataContext);
			}
		}
		return true;
	}

