	public static bool IsSecretInformationCharacterAlive(int secretId, int partyIndex)
	{
		bool result = false;
		GameData.Domains.Information.Secret.SecretInformation secret = DomainManager.Information.QuerySecretInformation((SecretInformationId)secretId);
		SecretOccurence occurence;
		byte[] secretParams = secret.QueryParameters(out occurence);
		secretParams.ExtractSecretParameters(Config.SecretInformation.Instance.GetItem(occurence.TemplateId), delegate(int idx, int charId)
		{
			if (idx == partyIndex)
			{
				result = DomainManager.Character.IsCharacterAlive(charId);
			}
		});
		return result;
	}

