	private static void LeadToGoodSuccess(int charId, int metaDataId, int offset)
	{
		AddAdmonishSucceed(charId);
		AddChangeBehaviorTypeByAdmonishedGood(charId);
		ApplyLeadToGoodAiEffect(charId, metaDataId, offset);
		if (SecretInformationProcessor_Event.Instance.IsContentAskKeepContent())
		{
			DiscardSecretInformation(DomainManager.Taiwu.GetTaiwuCharId(), metaDataId);
		}
	}

	private static void LeadToEvilSuccess(int charId, int metaDataId, int offset)
	{
		AddAdmonishSucceed(charId);
		AddChangeBehaviorTypeByAdmonishedBad(charId);
		ApplyLeadToEvilAiEffect(charId, metaDataId, offset);
		if (SecretInformationProcessor_Event.Instance.IsContentAskKeepContent())
		{
			DiscardSecretInformation(DomainManager.Taiwu.GetTaiwuCharId(), metaDataId);
		}
	}

	private static int GetLeadToGoodAiEffectTime(int charId, int secretId, int offsetValue)
	{
		GameData.Domains.Character.Character character = DomainManager.Character.GetElement_Objects(charId);
		SecretInformationItem config = DomainManager.Information.CalcSecretInformationConfig((SecretInformationId)secretId);
		return config.SortValue * 12 / 2 + offsetValue / 10 + LeadToGoodAiBehaviorTypeParam[character.GetBehaviorType()];
	}

	private static int GetLeadToEvilAiEffectTime(int charId, int secretId, int offsetValue)
	{
		GameData.Domains.Character.Character character = DomainManager.Character.GetElement_Objects(charId);
		SecretInformationItem config = DomainManager.Information.CalcSecretInformationConfig((SecretInformationId)secretId);
		return config.SortValue * 12 / 2 + Math.Abs(offsetValue) / 10 + LeadToEvilAiBehaviorTypeParam[character.GetBehaviorType()];
	}

	private static void ApplyLeadToGoodAiEffect(int charId, int secretId, int offset)
	{
		SecretInformationItem config = DomainManager.Information.CalcSecretInformationConfig((SecretInformationId)secretId);
		(sbyte, sbyte) actionType = GetSecretInformationType(config);
		int effectTime = GetLeadToGoodAiEffectTime(charId, secretId, offset);
		ForbidCharacterAiAction(charId, actionType.Item1, actionType.Item2, effectTime);
	}

	private static void ApplyLeadToEvilAiEffect(int charId, int secretId, int offset)
	{
		SecretInformationItem config = DomainManager.Information.CalcSecretInformationConfig((SecretInformationId)secretId);
		(sbyte, sbyte) actionType = GetSecretInformationType(config);
		int effectTime = GetLeadToEvilAiEffectTime(charId, secretId, offset);
		AddCharacterAiActionRateAdjust(charId, actionType.Item1, actionType.Item2, 20, effectTime);
	}

	private static (sbyte, sbyte) GetSecretInformationType(SecretInformationItem config)
	{
		if (config.TemplateId == 87)
		{
			return (1, 4);
		}
		if (config.TemplateId == 88)
		{
			return (1, 1);
		}
		if (config.TemplateId == 89)
		{
			return (1, 2);
		}
		if (config.TemplateId == 90)
		{
			return (1, 3);
		}
		if (config.TemplateId == 91)
		{
			return (0, 4);
		}
		if (config.TemplateId == 92)
		{
			return (0, 1);
		}
		if (config.TemplateId == 93)
		{
			return (0, 2);
		}
		if (config.TemplateId == 94)
		{
			return (0, 3);
		}
		if (config.TemplateId == 95)
		{
			return (7, -1);
		}
		if (config.TemplateId == 96)
		{
			return (8, -1);
		}
		if (config.TemplateId == 97)
		{
			return (5, 1);
		}
		if (config.TemplateId == 98)
		{
			return (5, 2);
		}
		if (config.TemplateId == 99)
		{
			return (3, 1);
		}
		if (config.TemplateId == 100)
		{
			return (3, 2);
		}
		if (config.TemplateId == 101)
		{
			return (2, 1);
		}
		if (config.TemplateId == 102)
		{
			return (2, 2);
		}
		if (config.TemplateId == 103)
		{
			return (9, -1);
		}
		if (config.TemplateId == 104)
		{
			return (6, -1);
		}
		if (config.TemplateId == 105)
		{
			return (4, 1);
		}
		if (config.TemplateId == 106)
		{
			return (4, 3);
		}
		if (config.TemplateId == 110)
		{
			return (11, -1);
		}
		throw new Exception($"Wrong SecretInformation TemplateId: {config.TemplateId}");
	}

