	public static IReadOnlyList<TemplateKey> GetMajorEventEnterItems(EventArgBox argBox)
	{
		int count = argBox.GetInt("EnterItems_Count");
		if (count == 0)
		{
			return Array.Empty<TemplateKey>();
		}
		List<TemplateKey> result = new List<TemplateKey>();
		for (int i = 0; i < count; i++)
		{
			argBox.Get("EnterItems_" + i, out TemplateKey key);
			result.Add(key);
		}
		return result;
	}

