	public static ItemKey RandomGiftForTaiwuMarriageAdventure(int charId, bool firstMarriage)
	{
		if (!DomainManager.Character.TryGetElement_Objects(charId, out var character))
		{
			throw new Exception($"{charId} is not an exist character id for RandomGiftForTaiwuMarriageAdventure");
		}
		Inventory inventory = character.GetInventory();
		List<ItemKey> bestItemList = new List<ItemKey>();
		List<ItemKey> midItemList = new List<ItemKey>();
		List<ItemKey> lowItemList = new List<ItemKey>();
		foreach (KeyValuePair<ItemKey, int> pair in inventory.Items)
		{
			short subType = ItemTemplateHelper.GetItemSubType(pair.Key.ItemType, pair.Key.TemplateId);
			if (subType != 1203 && ItemTemplateHelper.IsTransferable(pair.Key.ItemType, pair.Key.TemplateId) && !IsItemPoisoned(pair.Key))
			{
				sbyte itemGrade = ItemTemplateHelper.GetGrade(pair.Key.ItemType, pair.Key.TemplateId);
				if (itemGrade >= 6)
				{
					bestItemList.Add(pair.Key);
				}
				else if (itemGrade >= 3)
				{
					midItemList.Add(pair.Key);
				}
				else
				{
					lowItemList.Add(pair.Key);
				}
			}
		}
		if (lowItemList.Count + midItemList.Count + bestItemList.Count <= 0)
		{
			return ItemKey.Invalid;
		}
		sbyte favorType = GetFavorabilityType(character, DomainManager.Taiwu.GetTaiwu());
		List<ItemKey> list = null;
		switch (favorType)
		{
		case 6:
			list = ((!firstMarriage) ? GetRandomResult(25, 75, 0, midItemList) : GetRandomResult(0, 75, 25, midItemList));
			if (list.Count <= 0)
			{
				list.AddRange(bestItemList);
			}
			if (list.Count <= 0)
			{
				list.AddRange(midItemList);
			}
			if (list.Count <= 0)
			{
				list.AddRange(lowItemList);
			}
			return list.Sample();
		case 5:
			list = ((!firstMarriage) ? GetRandomResult(50, 50, 0, lowItemList) : GetRandomResult(25, 75, 0, midItemList));
			if (list.Count <= 0)
			{
				list.AddRange(midItemList);
			}
			if (list.Count <= 0)
			{
				list.AddRange(lowItemList);
			}
			if (list.Count <= 0)
			{
				list.AddRange(bestItemList);
			}
			return list.Sample();
		case 4:
			list = ((!firstMarriage) ? GetRandomResult(75, 25, 0, lowItemList) : GetRandomResult(50, 50, 0, lowItemList));
			if (list.Count <= 0)
			{
				list.AddRange(lowItemList);
			}
			if (list.Count <= 0)
			{
				list.AddRange(midItemList);
			}
			if (list.Count <= 0)
			{
				list.AddRange(bestItemList);
			}
			return list.Sample();
		default:
			list = ((!firstMarriage) ? GetRandomResult(100, 0, 0, lowItemList) : GetRandomResult(75, 25, 0, lowItemList));
			if (list.Count <= 0)
			{
				list.AddRange(lowItemList);
			}
			if (list.Count <= 0)
			{
				list.AddRange(midItemList);
			}
			if (list.Count <= 0)
			{
				list.AddRange(bestItemList);
			}
			return list.Sample();
		}
		List<ItemKey> GetRandomResult(int obbLow, int obbMid, int obbHigh, List<ItemKey> baseList)
		{
			List<ItemKey> randomCore = new List<ItemKey>();
			randomCore.AddRange(baseList);
			if (baseList != bestItemList && Domain.MainThreadDataContext.Random.CheckPercentProb(obbHigh))
			{
				randomCore.AddRange(bestItemList);
			}
			if (baseList != midItemList && Domain.MainThreadDataContext.Random.CheckPercentProb(obbMid))
			{
				randomCore.AddRange(midItemList);
			}
			if (baseList != lowItemList && Domain.MainThreadDataContext.Random.CheckPercentProb(obbLow))
			{
				randomCore.AddRange(lowItemList);
			}
			return randomCore;
		}
	}

	public static Location CreateJuniorXiangshuAdventure(int juniorXiangshuCharId, int coreId, Location location)
	{
		if (CheckMainStoryLineProgress(28))
		{
			return location;
		}
		DataContext context = Domain.MainThreadDataContext;
		AdventureMajorEvent majorEvent = null;
		if (!CheckBlockHasAdventure(location))
		{
			majorEvent = DomainManager.Adventure.GenerateMajorEventWithoutComplement(context, coreId, location);
		}
		if (majorEvent == null)
		{
			location = GetAdventureGenerateRandomLocation(location, 1, 4, 118, 119, 120, 121, 122, 123);
			if (DomainManager.Character.TryGetElement_Objects(juniorXiangshuCharId, out var xiangshuChar))
			{
				MoveFixedCharacter(xiangshuChar, location);
			}
			majorEvent = DomainManager.Adventure.GenerateMajorEventWithoutComplement(context, coreId, location);
		}
		if (majorEvent != null)
		{
			DomainManager.Adventure.ComplementGenerateMajorEvent(context, majorEvent);
		}
		return location;
	}

	public static short GetXiangshuAvatarTemplateIdByXiangshuProgress(short startTemplateId)
	{
		sbyte xiangshuProgress = GetXiangshuProgress();
		int index = Math.Clamp(xiangshuProgress / 2, 0, 8);
		return (short)(startTemplateId + index);
	}

	public static void AddElopeLifeRecord(EventArgBox argBox)
	{
		GameData.Domains.Character.Character lover = argBox.GetCharacter("Lover");
		sbyte behaviorType = argBox.GetSbyte("SuccessLifeRecordBehaviorType");
		LifeRecordCollection collection = GetLifeRecordCollection();
		int taiwuId = DomainManager.Taiwu.GetTaiwuCharId();
		int date = DomainManager.World.GetCurrDate();
		Settlement settlement = DomainManager.Organization.GetSettlementByOrgTemplateId(lover.GetOrganizationInfo().OrgTemplateId);
		if (settlement != null)
		{
			switch (behaviorType)
			{
			case 0:
				collection.AddSectPunishElopeSucceedJust(taiwuId, date, lover.GetId(), settlement.GetId());
				break;
			case 1:
				collection.AddSectPunishElopeSucceedKind(taiwuId, date, lover.GetId(), settlement.GetId());
				break;
			case 2:
				collection.AddSectPunishElopeSucceedEven(taiwuId, date, lover.GetId(), settlement.GetId());
				break;
			default:
				collection.AddSectPunishElopeSucceed(taiwuId, date, lover.GetId(), settlement.GetId());
				break;
			}
		}
	}

