	private static MapBlockData GetSettlementRandomMapBlock(sbyte orgTemplateId)
	{
		Settlement settlement = DomainManager.Organization.GetSettlementByOrgTemplateId(orgTemplateId);
		Location location = settlement.GetLocation();
		List<short> blocks = ObjectPool<List<short>>.Instance.Get();
		DomainManager.Map.GetSettlementBlocks(location.AreaId, location.BlockId, blocks);
		short blockId = blocks.GetRandom(Domain.MainThreadDataContext.Random);
		ObjectPool<List<short>>.Instance.Return(blocks);
		return DomainManager.Map.GetBlock(new Location(location.AreaId, blockId));
	}

	public static void ChangeAlertnessOnGiveTeammateResource(int charId, sbyte resourceType, int amount)
	{
