		}
		InteractAlertnessFormulaItem alertnessFormulaItem = InteractAlertnessFormula.Instance[0];
		long worth = (long)GlobalConfig.ResourcesWorth[resourceType] * (long)amount;
		int clampedWorth = (int)Math.Clamp(worth, -2147483648L, 2147483647L);
		int result = -alertnessFormulaItem.Calculate(clampedWorth);
		result = DomainManager.Character.CalcAlertnessChangeValue(result);
		int date = DomainManager.World.GetCurrDate();
		CharacterAlertnessData alertnessData = DomainManager.Character.GetAlertnessData(Domain.MainThreadDataContext, charId, init: true);
