	private static void ChangeAlertnessOnSendGift(int templateId, int charId, ItemKey gift, bool isReduce)
	{
		if (!DomainManager.Character.TryGetElement_Objects(charId, out var _))
		{
			return;
		}
		InteractAlertnessFormulaItem alertnessFormulaItem = InteractAlertnessFormula.Instance[templateId];
		int favorabilityChange = DomainManager.Item.GetBaseItem(gift).GetBaseFavorabilityChange();
		int result = alertnessFormulaItem.Calculate(favorabilityChange);
		result = (isReduce ? (-result) : result);
		result = DomainManager.Character.CalcAlertnessChangeValue(result);
		int date = DomainManager.World.GetCurrDate();
		CharacterAlertnessData alertnessData = DomainManager.Character.GetAlertnessData(Domain.MainThreadDataContext, charId, init: true);
		if (alertnessData == null)
		{
			return;
		}
		CharacterAlertnessData characterAlertnessData = alertnessData;
		if (characterAlertnessData.RecordCollection == null)
		{
			characterAlertnessData.RecordCollection = new CharacterAlertnessRecordCollection();
		}
		alertnessData.RecordCollection.AddSendGif(date, gift.ItemType, gift.TemplateId, result);
		DomainManager.Character.ChangeAlertness(Domain.MainThreadDataContext, charId, result);
		if (isReduce)
		{
			GameData.Domains.Character.Character character = DomainManager.Character.GetElement_Objects(charId);
			OrganizationInfo charOrgInfo = character.GetOrganizationInfo();
			OrganizationItem orgCfg = Config.Organization.Instance[charOrgInfo.OrgTemplateId];
			if (DomainManager.Extra.MartialArtistSkill0Useful(orgCfg) && orgCfg.IsSect)
			{
				ChangeAlertnessOnProfessionMartialArtistSkill0(charId, result);
			}
			if (DomainManager.Extra.CivilianSkill0Useful(orgCfg) && orgCfg.IsCivilian)
			{
				ChangeAlertnessOnProfessionCivilianSkill0(charId, result);
			}
		}
	}

	public static void ChangeAlertnessOnSendGiftLove(int charId, ItemKey gift, bool isReduce)
	{
		ChangeAlertnessOnSendGift(4, charId, gift, isReduce);
	}

	public static void ChangeAlertnessOnSendGiftNormal(int charId, ItemKey gift, bool isReduce)
	{
		ChangeAlertnessOnSendGift(5, charId, gift, isReduce);
	}

	public static void ChangeAlertnessOnSendGiftHate(int charId, ItemKey gift, bool isReduce)
	{
		ChangeAlertnessOnSendGift(6, charId, gift, isReduce);
	}

