	public static void ChangeAlertnessOnSneer(int charId, EPraiseContentType contentType)
	{
		if (!DomainManager.Character.TryGetElement_Objects(charId, out var character))
		{
			return;
		}
		int result = GlobalConfig.Instance.ChangeAlertnessOnSneer[character.GetBehaviorType()];
		result = DomainManager.Character.CalcAlertnessChangeValue(result);
		int date = DomainManager.World.GetCurrDate();
		CharacterAlertnessData alertnessData = DomainManager.Character.GetAlertnessData(Domain.MainThreadDataContext, charId, init: true);
		if (alertnessData != null)
		{
			CharacterAlertnessData characterAlertnessData = alertnessData;
			if (characterAlertnessData.RecordCollection == null)
			{
				characterAlertnessData.RecordCollection = new CharacterAlertnessRecordCollection();
			}
			switch (contentType)
			{
			case EPraiseContentType.SevenElement:
				alertnessData.RecordCollection.AddSneerSevenElement(date, result);
				break;
			case EPraiseContentType.Charm:
				alertnessData.RecordCollection.AddSneerCharm(date, result);
				break;
			case EPraiseContentType.Fame:
				alertnessData.RecordCollection.AddSneerFame(date, result);
				break;
			case EPraiseContentType.Feature:
				alertnessData.RecordCollection.AddSneerFeature(date, result);
				break;
			case EPraiseContentType.Money:
				alertnessData.RecordCollection.AddSneerMoney(date, result);
				break;
			default:
				throw new ArgumentOutOfRangeException("contentType", contentType, null);
			}
			DomainManager.Character.ChangeAlertness(Domain.MainThreadDataContext, charId, result);
		}
	}

