	public static bool IsMeetAlertnessOnCharJoinTaiwuVillage(int charId)
	{
		if (!DomainManager.Character.TryGetElement_Objects(charId, out var character))
		{
			return false;
		}
		int alertness = DomainManager.Character.GetAlertnessValue(charId);
		sbyte grade = character.GetOrganizationInfo().Grade;
		sbyte xiangshuLevel = DomainManager.World.GetXiangshuLevel();
		InteractAlertnessFormulaItem alertnessFormulaItem = InteractAlertnessFormula.Instance[44];
		int offset = grade - xiangshuLevel;
		int result = alertnessFormulaItem.Calculate(offset);
		return alertness < 0 || alertness <= result;
	}

	public static bool IsMeetsAlertnessLevelOnTaiwuGetTaught(int charId)
	{
		sbyte level = DomainManager.Character.GetAlertnessLevel(charId);
		return level <= 3;
	}

