	public static string HandleAnimalCombatResult(EventArgBox argBox, bool isDieCombat)
	{
		GameData.Domains.Character.Character taiwu = argBox.GetCharacter("RoleTaiwu");
		int animalId = -1;
		argBox.Get(EventTriggerParameter.DefValue.AnimalId, ref animalId);
		GameData.Domains.Character.Animal animal = TryGetAnimal(animalId);
		short animalTemplateId = -1;
		argBox.Get("AnimalCharacterTemplateId", ref animalTemplateId);
		CharacterItem animalConfig = Config.Character.Instance[animalTemplateId];
		ItemKey escapeCarrier = animal.ItemKey;
		bool useHunterSkill1 = false;
		if (argBox.Get("CarrierItemKeyGotInCombat", out ItemKey animalItem))
		{
			argBox.Get("ItemKeySeizeCarrierInCombat", out ItemKey seizeItem);
			argBox.Remove<ItemKey>("CarrierItemKeyGotInCombat");
			argBox.Remove<ItemKey>("ItemKeySeizeCharacterInCombat");
			ProfessionFormulaItem formulaItemHunter3 = ProfessionFormula.Instance[10];
			ChangeProfessionSeniority(1, formulaItemHunter3.Calculate(animalConfig.ConsummateLevel));
			string nextString = "";
			if (escapeCarrier.IsValid())
			{
				RemoveInventoryOrEquipItem(taiwu, animalItem);
				animalItem = escapeCarrier;
				RemoveFleeCarrierLocation(animalItem);
				argBox.Set("EscapeCarriers", Config.Carrier.Instance[animalItem.TemplateId].Name);
				AddItemToRole(taiwu, escapeCarrier, 1, -1);
				ApplyAnimalTamingResult(taiwu, animal, isWin: true, taiwu.GetLocation(), seizeItem);
				LifeRecordCollection lifeRecordCollection = GetLifeRecordCollection();
				int date = GetGameDate();
				lifeRecordCollection.AddTameCarrierSucceed(taiwu.GetId(), date, escapeCarrier.ItemType, escapeCarrier.TemplateId, taiwu.GetLocation());
				nextString = "33fb78b2-c124-4919-96d6-6b98d4ce3712";
			}
			ShowGetItemPageForItems(new List<(ItemKey, int)> { (animalItem, 1) }, nextString, argBox);
			RemoveAnimal(animal);
			SetOnHandlingMonthlyEventBlock(blockOperation: false);
			return string.Empty;
		}
		ProfessionFormulaItem formulaItemHunter4 = ProfessionFormula.Instance[9];
		int combatResult = 0;
		if (argBox.Get("CombatResult", ref combatResult))
		{
			switch (combatResult)
			{
			case 0:
			case 5:
				ChangeProfessionSeniority(1, formulaItemHunter4.Calculate(animalConfig.ConsummateLevel));
				if (argBox.Get("UseHunterSkill1", ref useHunterSkill1) && useHunterSkill1)
				{
					Dictionary<Location, List<short>> dict = new Dictionary<Location, List<short>>();
					dict.Add(taiwu.GetLocation(), new List<short> { animalTemplateId });
					List<ItemKey> escapeCarriers = new List<ItemKey>();
					List<(ItemKey, int)> items = HunterGetCarriers(dict, ref escapeCarriers);
					if (escapeCarriers.Count > 0)
					{
						string itemKeyName = "";
						for (int i = 0; i < escapeCarriers.Count; i++)
						{
							CarrierItem config = Config.Carrier.Instance[escapeCarriers[i].TemplateId];
							itemKeyName += config.Name;
							if (i != escapeCarriers.Count - 1)
							{
								itemKeyName += "、";
							}
						}
						argBox.Set("EscapeCarriers", itemKeyName);
					}
					string nextString2 = ((escapeCarriers.Count > 0) ? "33fb78b2-c124-4919-96d6-6b98d4ce3712" : string.Empty);
					ShowGetItemPageForItems(items, nextString2, argBox);
				}
				else if (escapeCarrier.IsValid())
				{
					string nextString3 = "33fb78b2-c124-4919-96d6-6b98d4ce3712";
					RemoveFleeCarrierLocation(escapeCarrier);
					argBox.Set("EscapeCarriers", Config.Carrier.Instance[escapeCarrier.TemplateId].Name);
					AddItemToRole(taiwu, escapeCarrier, 1, -1);
					ApplyAnimalTamingResult(taiwu, animal, isWin: true, taiwu.GetLocation(), ItemKey.Invalid);
					LifeRecordCollection lifeRecordCollection3 = GetLifeRecordCollection();
					int date3 = GetGameDate();
					lifeRecordCollection3.AddTameCarrierSucceed(taiwu.GetId(), date3, escapeCarrier.ItemType, escapeCarrier.TemplateId, taiwu.GetLocation());
					ShowGetItemPageForItems(new List<(ItemKey, int)> { (escapeCarrier, 1) }, nextString3, argBox);
				}
				RemoveAnimal(animal);
				SetOnHandlingMonthlyEventBlock(blockOperation: false);
				return string.Empty;
			case 1:
			case 2:
			case 4:
				if (combatResult != 2 && isDieCombat)
				{
					return "36747168-c095-4365-8f5c-69795b1c216c";
				}
				if (escapeCarrier.IsValid())
				{
					LifeRecordCollection lifeRecordCollection4 = GetLifeRecordCollection();
					int date4 = GetGameDate();
					lifeRecordCollection4.AddTameCarrierFail(taiwu.GetId(), date4, escapeCarrier.ItemType, escapeCarrier.TemplateId, taiwu.GetLocation());
				}
				return "91afe2cb-ae83-4167-a834-811b7dcf7008";
			case 3:
				ChangeProfessionSeniority(1, formulaItemHunter4.Calculate(animalConfig.ConsummateLevel));
				if (escapeCarrier.IsValid())
				{
					LifeRecordCollection lifeRecordCollection2 = GetLifeRecordCollection();
					int date2 = GetGameDate();
					lifeRecordCollection2.AddTameCarrierFail(taiwu.GetId(), date2, escapeCarrier.ItemType, escapeCarrier.TemplateId, taiwu.GetLocation());
				}
				return "3a863e8f-5dc2-46d5-8f20-d405c7dcd98b";
			default:
				return string.Empty;
			}
		}
		SetOnHandlingMonthlyEventBlock(blockOperation: false);
		return string.Empty;
	}

