	public static void HandleEffect_YuJingChenSi(GameData.Domains.Character.Character character, bool isGoodFeature)
	{
		if (character == null)
		{
			throw new Exception("null character to HandleEffect_YuJingChenSi!");
		}
		List<short> featureIds = character.GetFeatureIds();
		List<short[]> randomCore = new List<short[]>();
		for (int i = 0; i < featureIds.Count; i++)
		{
			CharacterFeatureItem config = CharacterFeature.Instance.GetItem(featureIds[i]);
			if (!config.Mergeable)
			{
				continue;
			}
			if (isGoodFeature)
			{
				sbyte level = config.Level;
				if (level > 0 && level < 3)
				{
					randomCore.Add(new short[2] { config.TemplateId, config.AppearProb });
				}
			}
			if (!isGoodFeature && config.Level < -1)
			{
				randomCore.Add(new short[2] { config.TemplateId, config.AppearProb });
			}
		}
		if (randomCore.Count <= 0)
		{
			return;
		}
		short[] targetFeature = GetRandomCellFromWeightCore(randomCore);
		CharacterFeatureItem targetFeatureConfig = CharacterFeature.Instance.GetItem(targetFeature[0]);
		short replaceFeatureId = targetFeatureConfig.TemplateId;
		CharacterFeature.Instance.Iterate(delegate(CharacterFeatureItem characterFeatureItem)
		{
			if (characterFeatureItem.MutexGroupId == targetFeatureConfig.MutexGroupId && characterFeatureItem.Level == targetFeatureConfig.Level + 1)
			{
				replaceFeatureId = characterFeatureItem.TemplateId;
				return false;
			}
			return true;
		});
		if (replaceFeatureId == targetFeatureConfig.TemplateId)
		{
			return;
		}
		for (int i2 = 0; i2 < featureIds.Count; i2++)
		{
			if (featureIds[i2] == targetFeatureConfig.TemplateId)
			{
				featureIds[i2] = replaceFeatureId;
				break;
			}
		}
		character.SetFeatureIds(featureIds, Domain.MainThreadDataContext);
	}

	public unsafe static List<(ItemKey, short, bool)> GetCharacterEatingItems(GameData.Domains.Character.Character character)
	{
		if (character == null)
		{
			throw new Exception("null character to GetCharacterEatingItems!");
		}
		EatingItems eatingItems = character.GetEatingItems();
		List<(ItemKey, short, bool)> resultList = new List<(ItemKey, short, bool)>(9);
		for (int i = 0; i < 9; i++)
		{
			ItemKey itemKey = (ItemKey)eatingItems.ItemKeys[i];
			short duration = eatingItems.Durations[i];
			bool isWug = EatingItems.IsWug(itemKey);
			resultList.Add((itemKey, duration, isWug));
		}
		return resultList;
	}

	public static void HealCharacterRandomInjury(GameData.Domains.Character.Character character)
	{
		DataContext context = Domain.MainThreadDataContext;
		List<sbyte> bodyPartTypeList = ObjectPool<List<sbyte>>.Instance.Get();
		for (sbyte i = 0; i < 7; i++)
		{
			if (CheckRoleBodyPartInjured(character, i))
			{
				bodyPartTypeList.Add(i);
			}
		}
		if (bodyPartTypeList.Count != 0)
		{
			sbyte bodyPartType = bodyPartTypeList.GetRandom(context.Random);
			ChangeRoleBodyPartInjuryByLevel(character, isInnerInjury: true, -6, bodyPartType);
			ChangeRoleBodyPartInjuryByLevel(character, isInnerInjury: false, -6, bodyPartType);
			ObjectPool<List<sbyte>>.Instance.Return(bodyPartTypeList);
		}
	}

	public static void HealCharacterAllInjury(GameData.Domains.Character.Character character)
	{
		for (sbyte bodyPartType = 0; bodyPartType < 7; bodyPartType++)
		{
			ChangeRoleBodyPartInjuryByLevel(character, isInnerInjury: true, -6, bodyPartType);
			ChangeRoleBodyPartInjuryByLevel(character, isInnerInjury: false, -6, bodyPartType);
		}
	}

	public unsafe static void HealCharacterAllPoison(GameData.Domains.Character.Character character)
	{
		DataContext context = Domain.MainThreadDataContext;
		PoisonInts poisoned = character.GetPoisoned();
		for (sbyte poisonType = 0; poisonType < 6; poisonType++)
		{
			if (poisoned.Items[poisonType] > 0)
			{
				character.ChangePoisoned(context, poisonType, 3, -poisoned.Items[poisonType]);
			}
		}
	}

