	private static void SpiritualDebtInteractionChangeMorality(int charId, sbyte targetBehaviorType)
	{
		if (DomainManager.Character.TryGetElement_Objects(charId, out var character))
		{
			short morality = GameData.Domains.Character.BehaviorType.GetMiddleMoralityByBehaviorType(targetBehaviorType);
			int delta = morality - character.GetBaseMorality();
			delta = Math.Sign(delta) * Math.Min(Math.Abs(delta), GlobalConfig.Instance.SpiritualDebtInteractionChangeMoralityMax);
			ChangeRoleBaseBehaviorValue(character, delta);
		}
	}

