	public static void CaravanFilterGiftForCharacter(int caravanId, int getGiftCharId, EventArgBox argBox)
	{
		MerchantData caravanData = DomainManager.Merchant.GetCaravanMerchantData(Domain.MainThreadDataContext, caravanId);
		Tester.Assert(caravanData != null);
		if (!DomainManager.Character.TryGetElement_Objects(getGiftCharId, out var _))
		{
			throw new Exception($"can not get character to getGift,Id = {getGiftCharId}");
		}
		if (!argBox.Get("SelectItemInfo", out EventSelectItemData selectItemData))
		{
			selectItemData = new EventSelectItemData();
			selectItemData.CanSelectItemList = new List<ITradeableContent>();
			selectItemData.FilterList = new List<SelectItemFilter>();
			selectItemData.SlotMode = true;
			argBox.Set("SelectItemInfo", selectItemData);
		}
		SelectItemFilter filter1 = new SelectItemFilter
		{
			Key = "GiftKey1",
			DisplayDataFilterId = 0,
			FilterTemplateId = -1
		};
		SelectItemFilter filter2 = new SelectItemFilter
		{
			Key = "GiftKey2",
			DisplayDataFilterId = 0,
			FilterTemplateId = -1
		};
		Inventory inventory = caravanData.GetGoodsList(1);
		List<ItemDisplayData> displayDataList = DomainManager.Item.GetItemDisplayDataListOptionalFromInventory(inventory, -1, -1);
		selectItemData.CanSelectItemList.AddRange(displayDataList);
		selectItemData.LoveAndHateItemInfo = DomainManager.Character.GetCharacterLoveAndHateItemInfo(Domain.MainThreadDataContext, getGiftCharId);
		selectItemData.FilterList.Add(filter1);
		selectItemData.FilterList.Add(filter2);
	}

	public static void TransferCaravanItemToTaiwu(int caravanId, int index, ItemKey itemKey1, ItemKey itemKey2, string afterEvent, EventArgBox argBox)
	{
		DataContext context = Domain.MainThreadDataContext;
		DomainManager.Merchant.DeleteCaravanItem(context, caravanId, index, itemKey1);
		DomainManager.Merchant.DeleteCaravanItem(context, caravanId, index, itemKey2);
		DomainManager.Item.RemoveItem(context, itemKey1);
		DomainManager.Item.RemoveItem(context, itemKey2);
		ItemKey newItemKey1 = DomainManager.Item.CreateItem(context, itemKey1.ItemType, itemKey1.TemplateId);
		ItemKey newItemKey2 = DomainManager.Item.CreateItem(context, itemKey2.ItemType, itemKey2.TemplateId);
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		List<(ItemKey, int)> giftKeyList = new List<(ItemKey, int)>();
		AddInventoryItem(taiwu, newItemKey1);
		AddInventoryItem(taiwu, newItemKey2);
		giftKeyList.Add((newItemKey1, 1));
		giftKeyList.Add((newItemKey2, 1));
		ShowGetItemPageForItems(giftKeyList, afterEvent, argBox);
	}

