	public static void AddPrisonerToCharacter(int prisonerCharId, int charId, ItemKey ropeItemKey)
	{
		GameData.Domains.Character.Character character = DomainManager.Character.GetElement_Objects(charId);
		if (character.IsActiveExternalRelationState(2uL))
		{
			KidnappedCharacterList kidnappedCharacterList = DomainManager.Character.GetKidnappedCharacters(charId);
			if (kidnappedCharacterList.IndexOf(prisonerCharId) > 0)
			{
				DomainManager.Character.ChangeKidnappedCharacterRope(Domain.MainThreadDataContext, charId, prisonerCharId, ropeItemKey);
			}
			else
			{
				DomainManager.Character.AddKidnappedCharacter(Domain.MainThreadDataContext, charId, prisonerCharId, ropeItemKey);
			}
		}
		else
		{
			DomainManager.Character.AddKidnappedCharacter(Domain.MainThreadDataContext, charId, prisonerCharId, ropeItemKey);
		}
		if (charId == DomainManager.Taiwu.GetTaiwuCharId())
		{
			TryInterruptCharacterPrioritizedAction(prisonerCharId, 22);
		}
	}

	public static void EnsureKidnapperHasRope(int useRopeCharId, int kidnapperCharId, ItemKey ropeItemKey)
	{
		if (useRopeCharId >= 0 && useRopeCharId != kidnapperCharId)
		{
			GameData.Domains.Character.Character useRopeChar = DomainManager.Character.GetElement_Objects(useRopeCharId);
			GameData.Domains.Character.Character kidnapperChar = DomainManager.Character.GetElement_Objects(kidnapperCharId);
			useRopeChar.RemoveInventoryItem(Domain.MainThreadDataContext, ropeItemKey, 1, deleteItem: false);
			kidnapperChar.AddInventoryItem(Domain.MainThreadDataContext, ropeItemKey, 1);
		}
	}

	public static int GetPrisonerResistance(int prisonerCharId)
	{
		if (!DomainManager.Character.TryGetElement_Objects(prisonerCharId, out var prisoner))
		{
			throw new Exception($"failed get character of id {prisonerCharId} to GetPrisonerResistance");
		}
		int kidnapperCharId = prisoner.GetKidnapperId();
		if (kidnapperCharId < 0)
		{
			return 0;
		}
		KidnappedCharacterList kidnappedCharacterList = DomainManager.Character.GetKidnappedCharacters(kidnapperCharId);
		int index = kidnappedCharacterList.IndexOf(prisonerCharId);
		if (index < 0)
		{
			return 0;
		}
		KidnappedCharacter kidnappedCharacter = kidnappedCharacterList.Get(index);
		GameData.Domains.Character.Character kidnapper = DomainManager.Character.GetElement_Objects(kidnapperCharId);
		return DomainManager.Character.CalcKidnappedCharacterTotalResistance(kidnapper, kidnappedCharacter);
	}

	public static void ChangePrisonerResistance(int prisonerCharId, sbyte delta)
	{
		if (!DomainManager.Character.TryGetElement_Objects(prisonerCharId, out var prisoner))
		{
			throw new Exception($"failed get character of id {prisonerCharId} to ChangePrisonerResistance");
		}
		int kidnapperCharId = prisoner.GetKidnapperId();
		if (kidnapperCharId < 0)
		{
			throw new Exception($"character {prisonerCharId} not kidnapped,can not change resistance");
		}
		KidnappedCharacterList kidnappedCharacterList = DomainManager.Character.GetKidnappedCharacters(kidnapperCharId);
		int index = kidnappedCharacterList.IndexOf(prisonerCharId);
		if (index < 0)
		{
			throw new Exception($"character {prisonerCharId} 's kidnapper do not has prisoner {prisonerCharId},can not change resistance");
		}
		KidnappedCharacter kidnappedCharacter = kidnappedCharacterList.Get(index);
		kidnappedCharacter.ExtraResistance = (sbyte)Math.Clamp(kidnappedCharacter.ExtraResistance + delta, 0, 127);
	}

