	public static void KillCharacter(int killerId, int victimId, EKillCharacterType killType)
	{
		if (!DomainManager.Character.TryGetElement_Objects(victimId, out var victim))
		{
			throw new Exception($"can not find character {victimId} to be killed in KillCharacter");
		}
		KillAddTianJieFuLu(killerId, victim);
		if (1 == 0)
		{
		}
		short num = killType switch
		{
			EKillCharacterType.KillInPublic => 4, 
			EKillCharacterType.KillInPrivate => 3, 
			_ => 0, 
		};
		if (1 == 0)
		{
		}
		short deathType = num;
		if (DomainManager.Character.TryGetElement_Objects(killerId, out var killer) && killer.GetTemplateId() == 913)
		{
			deathType = 11;
			DomainManager.Extra.ArchiveKilledByLongYufuCharacter(Domain.MainThreadDataContext, victim);
		}
		DomainManager.Character.MakeCharacterDead(Domain.MainThreadDataContext, victim, deathType, new CharacterDeathInfo(victim.GetValidLocation())
		{
			KillerId = killerId
		});
	}

	public static void KillAddTianJieFuLu(int killerId, GameData.Domains.Character.Character victim, bool needCompletelyInfected = true)
	{
		bool completelyInfected = CheckRoleInfection(victim, 2);
		if (!needCompletelyInfected)
		{
			completelyInfected = true;
		}
		bool unlock = DomainManager.Extra.IsProfessionalSkillUnlocked(5, 2);
		if (killerId == DomainManager.Taiwu.GetTaiwuCharId() && completelyInfected && unlock)
		{
			int consummateLevel = Math.Min(victim.GetConsummateLevel(), ProfessionRelatedConstants.TaoistMonkSkill2GetSecretSignCount.Length - 1);
			int secretSignCount = ProfessionRelatedConstants.TaoistMonkSkill2GetSecretSignCount[consummateLevel];
			ItemKey itemKey = AddItemToRole(DomainManager.Taiwu.GetTaiwu(), 12, 265, secretSignCount, -1);
			DomainManager.World.GetInstantNotificationCollection().AddGetItem(DomainManager.Taiwu.GetTaiwuCharId(), 12, 265);
			Domain.OnEvent_TaiwuGotTianjieFulu(victim.GetId(), itemKey, secretSignCount);
		}
	}

	public static void SaveInfected(GameData.Domains.Character.Character victim)
	{
		SaveInfectedAddTianJieFuLu(victim);
		victim.SavedFromInfected(Domain.MainThreadDataContext);
		DomainManager.Taiwu.RecordLifeSummary(Domain.MainThreadDataContext, 12);
	}

	public static void SaveInfectedAddTianJieFuLu(GameData.Domains.Character.Character victim)
	{
		if (DomainManager.Extra.IsProfessionalSkillUnlocked(5, 2))
		{
			int consummateLevel = Math.Min(victim.GetConsummateLevel(), ProfessionRelatedConstants.TaoistMonkSkill2GetSecretSignCount.Length - 1);
			int secretSignCount = ProfessionRelatedConstants.TaoistMonkSkill2GetSecretSignCountBySave[consummateLevel];
			ItemKey itemKey = AddItemToRole(DomainManager.Taiwu.GetTaiwu(), 12, 265, secretSignCount, -1);
			DomainManager.World.GetInstantNotificationCollection().AddGetItem(DomainManager.Taiwu.GetTaiwuCharId(), 12, 265);
			Domain.OnEvent_TaiwuGotTianjieFulu(victim.GetId(), itemKey, secretSignCount);
		}
	}

