	public static (bool valid, sbyte part) GetMedicineTopicalEffectResult(GameData.Domains.Character.Character targetChar, ItemKey medicineItemKey)
	{
		if (medicineItemKey.ItemType != 8)
		{
			throw new Exception($"Invalid item type: {medicineItemKey.ItemType}");
		}
		MedicineItem medicineCfg = Config.Medicine.Instance[medicineItemKey.TemplateId];
		if (medicineCfg.EffectType != EMedicineEffectType.RecoverOuterInjury && medicineCfg.EffectType != EMedicineEffectType.RecoverInnerInjury)
		{
			throw new Exception($"Invalid EffectType: {medicineCfg.EffectType}");
		}
		bool isInnerInjury = medicineCfg.EffectType == EMedicineEffectType.RecoverInnerInjury;
		Injuries injuries = targetChar.GetInjuries();
		sbyte minLevel = sbyte.MaxValue;
		sbyte minLevelBodyPart = -1;
		for (sbyte bodyPart = 0; bodyPart < 7; bodyPart++)
		{
			sbyte injuryLevel = injuries.Get(bodyPart, isInnerInjury);
			if (injuryLevel > 0 && injuryLevel < minLevel)
			{
				minLevel = injuryLevel;
				minLevelBodyPart = bodyPart;
			}
		}
		return (minLevelBodyPart == -1) ? (valid: false, part: minLevelBodyPart) : (valid: true, part: minLevelBodyPart);
	}

	public static bool CanMedicineApplyInstantEffect(GameData.Domains.Character.Character targetChar, ItemKey medicineItemKey)
	{
		if (medicineItemKey.ItemType != 8)
		{
			throw new Exception($"Invalid item type: {medicineItemKey.ItemType}");
		}
		MedicineItem medicineCfg = Config.Medicine.Instance[medicineItemKey.TemplateId];
		if (medicineCfg.EffectType != EMedicineEffectType.RecoverOuterInjury && medicineCfg.EffectType != EMedicineEffectType.RecoverInnerInjury)
		{
			throw new Exception($"Invalid EffectType: {medicineCfg.EffectType}");
		}
		bool isInnerInjury = medicineCfg.EffectType == EMedicineEffectType.RecoverInnerInjury;
		Injuries injuries = targetChar.GetInjuries();
		for (sbyte bodyPart = 0; bodyPart < 7; bodyPart++)
		{
			sbyte injuryLevel = injuries.Get(bodyPart, isInnerInjury);
			if (injuryLevel > 0)
			{
				return true;
			}
		}
		return false;
	}

	public unsafe static bool TopicalConsumeIsSatisfy(GameData.Domains.Character.Character targetChar, ItemKey medicineItemKey, bool checkMainAttributeEnough = true)
	{
		if (!checkMainAttributeEnough)
		{
			return true;
		}
		MainAttributes currMainAttributes = targetChar.GetCurrMainAttributes();
		MedicineItem medicineCfg = Config.Medicine.Instance[medicineItemKey.TemplateId];
		sbyte mainAttrType = medicineCfg.RequiredMainAttributeType;
		sbyte mainAttrVal = medicineCfg.RequiredMainAttributeValue;
		return mainAttrType < 0 || currMainAttributes.Items[mainAttrType] >= mainAttrVal;
	}

	public static bool CanEatItem(GameData.Domains.Character.Character targetChar, ItemKey itemKey, bool checkMainAttributeEnough = true)
	{
		EatingItems eatingItems = targetChar.GetEatingItems();
		sbyte currMaxEatingSlotsCount = targetChar.GetCurrMaxEatingSlotsCount();
		sbyte index = eatingItems.GetAvailableEatingSlot(currMaxEatingSlotsCount);
		if (itemKey.ItemType == 8)
		{
			if (checkMainAttributeEnough)
			{
				MedicineItem cfg = Config.Medicine.Instance[itemKey.TemplateId];
				if (cfg != null && cfg.RequiredMainAttributeType >= 0 && targetChar.GetCurrMainAttributes()[cfg.RequiredMainAttributeType] < cfg.RequiredMainAttributeValue)
				{
					return false;
				}
			}
			if (Config.Medicine.Instance[itemKey.TemplateId].Duration == 0)
			{
				return true;
			}
		}
		return itemKey.ItemType == 12 || index >= 0;
	}

