	public static GameData.Domains.Character.Character CreateAnimal(short templateId, ItemKey itemKey)
	{
		sbyte gender = Config.Character.Instance[templateId].Gender;
		if (gender == -1)
		{
			gender = Gender.GetRandom(Domain.MainThreadDataContext.Random);
		}
		if (itemKey.IsValid())
		{
			int loongId;
			ChildrenOfLoong loong;
			if (DomainManager.Extra.TryGetJiaoIdByItemKey(itemKey, out var jiaoId) && DomainManager.Extra.TryGetJiao(jiaoId, out var jiao))
			{
				gender = (sbyte)(jiao.Gender ? 1 : 0);
			}
			else if (DomainManager.Extra.TryGetChildrenOfLoongIdByItemKey(itemKey, out loongId) && DomainManager.Extra.TryGetLoong(loongId, out loong))
			{
				gender = (sbyte)(loong.Gender ? 1 : 0);
			}
		}
		FixedEnemyCreationInfo fixedEnemyCreationInfo = new FixedEnemyCreationInfo();
		fixedEnemyCreationInfo.Gender = gender;
		FixedEnemyCreationInfo creationInfo = fixedEnemyCreationInfo;
		GameData.Domains.Character.Character fixedEnemy = DomainManager.Character.CreateFixedEnemy(Domain.MainThreadDataContext, templateId, isTemporary: true, ref creationInfo);
		int enemyId = fixedEnemy.GetId();
		DomainManager.Character.CompleteCreatingCharacter(enemyId);
		return fixedEnemy;
	}

