		ItemKey itemKey = AddCricketToInventory(character, colorId, partId);
		DomainManager.Extra.ForceCricketSmart(Domain.MainThreadDataContext, itemKey);
		GameData.Domains.Item.Cricket cricket = DomainManager.Item.GetElement_Crickets(itemKey.Id);
		cricket.SetWinsCount(15, Domain.MainThreadDataContext);
