	public static ItemKey AddRandomCricketKingToInventory(GameData.Domains.Character.Character character)
	{
		DataContext context = Domain.MainThreadDataContext;
		List<(short, short)> weightTable = context.AdvanceMonthRelatedData.WeightTable.Occupy();
		foreach (CricketPartsItem config in (IEnumerable<CricketPartsItem>)CricketParts.Instance)
		{
			if (config.Type == ECricketPartsType.King)
			{
				weightTable.Add((config.TemplateId, config.Rate));
			}
		}
		short templateId = RandomUtils.GetRandomResult(weightTable, context.Random);
		ItemKey itemKey = DomainManager.Item.CreateCricket(context, templateId, 0);
		character.AddInventoryItem(context, itemKey, 1);
		context.AdvanceMonthRelatedData.WeightTable.Release(ref weightTable);
		return itemKey;
	}

