	public static int CreateIntelligentCharacterWithQualificationBonusWithReturn(sbyte gender, bool hasLifeSkillAdjustBonus, bool hasCombatSkillAdjustBonus)
	{
		DataContext context = Domain.MainThreadDataContext;
		GameData.Domains.Character.Character taiwuChar = DomainManager.Taiwu.GetTaiwu();
		Location location = taiwuChar.GetValidLocation();
		OrganizationInfo orgInfo = taiwuChar.GetOrganizationInfo();
		orgInfo.Grade = 0;
		orgInfo.OrgTemplateId = 0;
		if (gender < 0)
		{
			gender = Gender.GetRandom(context.Random);
		}
		short age = (short)context.Random.Next(18, 25);
		sbyte stateTemplateId = DomainManager.Map.GetStateTemplateIdByAreaId(location.AreaId);
		sbyte orgTemplateId = MapState.Instance[stateTemplateId].SectID;
		short charTemplateId = OrganizationDomain.GetCharacterTemplateId(orgTemplateId, stateTemplateId, gender);
		short[] lifeSkillsAdjustBonus = null;
		if (hasLifeSkillAdjustBonus)
		{
			Span<int> lifeSkillTypesWithBonus = stackalloc int[GlobalConfig.Instance.MixiangzhenLifeSkillAdjustTypeCount];
			RandomUtils.GetRandomUnrepeated(context.Random, 0, 15, lifeSkillTypesWithBonus);
			lifeSkillsAdjustBonus = new short[16];
			for (int i = 0; i < GlobalConfig.Instance.MixiangzhenLifeSkillAdjustTypeCount; i++)
			{
				int lifeSkillType = lifeSkillTypesWithBonus[i];
				lifeSkillsAdjustBonus[lifeSkillType] = GlobalConfig.Instance.MixiangzhenLifeSkillAdjustBonus;
			}
		}
		short[] combatSkillsAdjustBonus = null;
		if (hasCombatSkillAdjustBonus)
		{
			Span<int> combatSkillTypesWithBonus = stackalloc int[GlobalConfig.Instance.XiuluochangCombatSkillAdjustTypeCount];
			RandomUtils.GetRandomUnrepeated(context.Random, 0, 13, combatSkillTypesWithBonus);
			combatSkillsAdjustBonus = new short[14];
			for (int j = 0; j < GlobalConfig.Instance.XiuluochangCombatSkillAdjustTypeCount; j++)
			{
				int combatSkillType = combatSkillTypesWithBonus[j];
				combatSkillsAdjustBonus[combatSkillType] = GlobalConfig.Instance.XiuluochangCombatSkillAdjustBonus;
			}
		}
		IntelligentCharacterCreationInfo intelligentCharacterCreationInfo = new IntelligentCharacterCreationInfo(location, orgInfo, charTemplateId);
		intelligentCharacterCreationInfo.Age = age;
		intelligentCharacterCreationInfo.LifeSkillsLowerBound = lifeSkillsAdjustBonus;
		intelligentCharacterCreationInfo.CombatSkillsLowerBound = combatSkillsAdjustBonus;
		intelligentCharacterCreationInfo.InitializeSectSkills = false;
		IntelligentCharacterCreationInfo info = intelligentCharacterCreationInfo;
		GameData.Domains.Character.Character character = DomainManager.Character.CreateIntelligentCharacter(Domain.MainThreadDataContext, ref info);
		int charId = character.GetId();
		DomainManager.Character.CompleteCreatingCharacter(charId);
		return charId;
	}

	public static void MakeLove(GameData.Domains.Character.Character selfChar, GameData.Domains.Character.Character targetChar, bool isRape)
	{
		selfChar.MakeLove(Domain.MainThreadDataContext, targetChar, isRape);
		int selfCharId = selfChar.GetId();
		int targetCharId = targetChar.GetId();
		PeriAdvanceMonthFixedActionModification.MakeLoveState state = (isRape ? PeriAdvanceMonthFixedActionModification.MakeLoveState.RapeSucceed : ((!DomainManager.Character.HasRelation(selfCharId, targetCharId, 1024)) ? PeriAdvanceMonthFixedActionModification.MakeLoveState.Illegal : PeriAdvanceMonthFixedActionModification.MakeLoveState.Legal));
		int currDate = DomainManager.World.GetCurrDate();
		Location location = selfChar.GetLocation();
		LifeRecordCollection lifeRecordCollection = DomainManager.LifeRecord.GetLifeRecordCollection();
		SecretInformationCollection secretInformationCollection = DomainManager.Information.GetSecretInformationCollection();
		switch (state)
		{
		case PeriAdvanceMonthFixedActionModification.MakeLoveState.RapeSucceed:
		{
			lifeRecordCollection.AddRapeSucceed(selfCharId, currDate, targetCharId, location);
			int secretInfoOffset2 = secretInformationCollection.AddRape(selfCharId, targetCharId);
			SecretInformationId secretInfoId2 = DomainManager.Information.AddSecretInformation(Domain.MainThreadDataContext, secretInfoOffset2);
			break;
		}
		case PeriAdvanceMonthFixedActionModification.MakeLoveState.Illegal:
		{
			lifeRecordCollection.AddMakeLoveIllegal(selfCharId, currDate, targetCharId, location);
			int secretInfoOffset = secretInformationCollection.AddMakeLoveIllegal(selfCharId, targetCharId);
			SecretInformationId secretInfoId = DomainManager.Information.AddSecretInformation(Domain.MainThreadDataContext, secretInfoOffset);
			break;
		}
		default:
			lifeRecordCollection.AddMakeLoveLegal(selfCharId, currDate, targetCharId, location);
			break;
		}
	}

