	public static void ClearHatredTowardTaiwu()
	{
		DataContext context = Domain.MainThreadDataContext;
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		int taiwuCharId = taiwu.GetId();
		CharacterSet hateTaiwuCharIds = DomainManager.Character.GetReversedRelatedCharIds(taiwuCharId, 32768);
		if (hateTaiwuCharIds.GetCount() == 0)
		{
			return;
		}
		HashSet<int> collection = hateTaiwuCharIds.GetCollection();
		foreach (int charId in collection)
		{
			DomainManager.Character.ChangeRelationType(context, charId, taiwuCharId, 32768, 0);
			DomainManager.TaiwuEvent.RecordCharacterRelationChanged(isRemove: true, charId, taiwuCharId, 32768);
		}
		hateTaiwuCharIds.Clear();
	}

	public static bool HasHusbandsOrWives(int charId)
	{
		return DomainManager.Character.GetRelatedCharIds(charId, 1024).Count > 0;
	}

	public static void ClearLove(int charId)
	{
		int[] array = DomainManager.Character.GetRelatedCharIds(charId, 16384).ToArray();
		foreach (int related in array)
		{
			DomainManager.Character.ChangeRelationType(Domain.MainThreadDataContext, charId, related, 16384, 0);
		}
	}

	public static void AddRelation(int charId, int relatedCharId, ushort relationType)
	{
		if (RelationType.ContainBloodRelatedRelations(relationType))
		{
			throw new Exception($"Unable to add blood related relations {relationType} in event.");
		}
		DomainManager.Character.AddRelation(Domain.MainThreadDataContext, charId, relatedCharId, relationType);
		DomainManager.TaiwuEvent.RecordCharacterRelationChanged(isRemove: false, charId, relatedCharId, relationType);
		if (relationType == 16384)
		{
			AddLegacyPoint(2);
		}
	}

