	public static string GetCharacterClickedSpecialNextEvent(GameData.Domains.Character.Character character, EventArgBox argBox, bool createRelation)
	{
		DataContext context = Domain.MainThreadDataContext;
		DomainManager.Global.InvokeGuidingTrigger(context, 29);
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		int charId = character.GetId();
		short age = GetRoleAge(character);
		if (createRelation && character.GetCreatingType() == 1)
		{
			DomainManager.Character.TryCreateRelation(Domain.MainThreadDataContext, EventArgBox.TaiwuCharacterId, character.GetId());
		}
		if (EventConditions.CharacterInSuxiaImpactRange(character))
		{
			return "733764a8-1743-40db-a88d-70535e300bc3";
		}
		if (DomainManager.Character.IsSpecialGroupMember(character))
		{
			return "f65f0df8-60e2-476e-b9cc-3298cd3d4d9e";
		}
		if (character.IsCompletelyInfected())
		{
			return "b268b0c6-0704-41e7-bbb4-d4faf244ebfc";
		}
		if (DomainManager.LegendaryBook.IsLegendaryBookConsumed(charId))
		{
			sbyte bookType = DomainManager.LegendaryBook.GetConsumedCharacterLegendaryBookType(character);
			return LegendaryBookConsumedBookTypeToEvent[bookType];
		}
		if (age < GlobalConfig.Instance.AgeBaby)
		{
			return "0f6a8d46-c065-4d8d-b4cc-2a85be694bd8";
		}
		OrganizationInfo characterOrgInfo = character.GetOrganizationInfo();
		if (GlobalArgBoxContainsKey<int>("ForeverLoverId") && GetIntFromGlobalArgBox("ForeverLoverId") == charId)
		{
			if (GetCharacterChildGrade(character) < 0)
			{
				return "dc4047f7-f266-4d2f-a2e1-37694c3c3247";
			}
			RemoveFromGlobalArgBox<int>("ForeverLoverId");
		}
		else
		{
			if (CanTriggerHuntFugitiveInteraction(character))
			{
				return "d742c92c-470a-496c-8b4a-eccddcc8baee";
			}
			if (CheckHasRelationship(character, taiwu, 32768))
			{
				return "3fd8291d-6f22-4b24-88ff-e11e9c5dbc6b";
			}
			if (CanTriggerTaiwuWantedInteraction(character.GetId(), argBox))
			{
				return "2dc9389a-1341-4671-bc01-d7881a59e432";
			}
			if (TryGetAppointmentOfCharacter(charId, out var location))
			{
				AdaptableLog.Info($"location = {location}");
				MapBlockData mapBlockData = DomainManager.Map.GetBlock(location);
				short blockId = mapBlockData.BlockId;
				if (mapBlockData.RootBlockId >= 0)
				{
					blockId = mapBlockData.RootBlockId;
				}
				List<short> blockIdList = new List<short>();
				DomainManager.Map.GetSettlementBlocks(location.AreaId, blockId, blockIdList);
				Location nowLocation = taiwu.GetLocation();
				for (int i = 0; i < blockIdList.Count; i++)
				{
					if (location.AreaId == nowLocation.AreaId && blockIdList[i] == nowLocation.BlockId)
					{
						return "629311a9-de4e-4189-81b3-cc837948c2ce";
					}
				}
			}
			else if (CharacterIsOrganizationLeader(character, 10))
			{
				if (IsCharacterAtTargetSectLocation(character, 10))
				{
					EventArgBox sectArgBox = GetSectMainStoryEventArgBox(10);
					bool partOneStoryTriggered = false;
					sectArgBox.Get(SectMainStoryEventArgKey.DefValue.KongsangStoryPartOneTriggered, ref partOneStoryTriggered);
					if (!partOneStoryTriggered && GetSectApprovingRate(10) >= 500 && !sectArgBox.Contains<int>("ConchShip_PresetKey_SectMainStoryTriggeringStatus") && !CheckSectStoryIsTriggeredThisMonth(10) && SectMainStory.DefValue.Kongsang.IsReady())
					{
						argBox.Set("SectLeader", charId);
						CreateAdventureActor(71, "SectGuideKongsang", argBox);
						GameData.Domains.Character.Character liaoWuming = GetOrCreateFixedCharacterByTemplateId(749);
						DirectlySetFavorabilities(liaoWuming.GetId(), taiwu.GetId(), 9999, 9999);
						AddPoisonToLiaoWuming(liaoWuming);
						argBox.Set("LiaoWuming", liaoWuming.GetId());
						return "cde605ed-0bc1-4b0b-ae72-cb0247d09da2";
					}
					bool result = false;
					if (partOneStoryTriggered && IsExtraTaskInProgress(101) && sectArgBox.Get(SectMainStoryEventArgKey.DefValue.MissionUnacceptedEventTriggeredSameMonth, ref result) && result)
					{
						argBox.Set("SectLeader", charId);
						SaveArgToSectMainStory(10, SectMainStoryEventArgKey.DefValue.MissionUnacceptedEventTriggeredSameMonth, value: false);
						return "b474ca28-4cd8-46bf-8abb-e808c0d67de7";
					}
				}
			}
			else if (IsExtraTaskInProgress(181) && character.GetOrganizationInfo().OrgTemplateId == 4)
			{
				return "c8c836eb-4fa4-4f4e-bbd2-caed35028969";
			}
		}
		if (GetIsDreamBack() && !IsDejaVuEventCharacter(charId) && (IsPastRelationship(charId) || IsPastTaiwu(charId)))
		{
			AddDejaVuEventCharacter(charId);
			return "7abe76fd-ad0c-4d7e-ad04-6d2c75f89367";
		}
		if (GetIsDreamBack() && !IsDejaVuEventCharacter(charId) && TryGetDreamBackLifeRecordByRelatedCharId(charId, out var _))
		{
			AddDejaVuEventCharacter(charId);
			return "bfa202f2-0d5e-4ed4-a709-5f200eee3bb0";
		}
		if (DomainManager.World.IsExtraTaskInProgress(303))
		{
			short settlementId = character.GetOrganizationInfo().SettlementId;
			if (settlementId >= 0 && character.GetOrganizationInfo().Grade == 8)
			{
				EventArgBox eventArgBox = DomainManager.Extra.GetSectMainStoryEventArgBox(14);
				GameData.Utilities.ShortList triggeredSettlements = eventArgBox.Get<GameData.Utilities.ShortList>(SectMainStoryEventArgKey.DefValue.FulongLoseChickenFeatherInteractionSettlements);
				if (triggeredSettlements.Items == null || !triggeredSettlements.Items.Contains(settlementId))
				{
					Settlement settlement = DomainManager.Organization.GetSettlement(settlementId);
					Location location2 = settlement.GetLocation();
					List<int> chickenIds = DomainManager.Building.GetSettlementChickenIdList(location2);
					List<int> loseFeatherChickens = DomainManager.Extra.GetSectFulongLoseFeatherChickens();
					for (int j = 0; j < chickenIds.Count; j++)
					{
						if (loseFeatherChickens.Contains(chickenIds[j]))
						{
							return "eb4f0e4d-8fed-474b-960a-df783a915a5b";
						}
					}
				}
			}
		}
		return string.Empty;
	}

	public static void TryInvokeCharacterInteractGuidingTrigger(EventArgBox argBox)
	{
