		if (SpiritualDebtInteractionXuannvVisibleCheck(argBox))
		{
			DomainManager.Global.InvokeGuidingTrigger(context, 32);
		}
		else if (SpiritualDebtInteractionXuehouVisibleCheck(argBox))
