		}
		else if (SpiritualDebtInteractionJieqingVisibleCheck(argBox))
		{
			DomainManager.Global.InvokeGuidingTrigger(context, 35);
		}
		else if (SpiritualDebtInteractionRanshanVisibleCheck(argBox))
		{
			DomainManager.Global.InvokeGuidingTrigger(context, 36);
		}
		else if (SpiritualDebtInteractionEmeiVisibleCheck(argBox))
		{
			DomainManager.Global.InvokeGuidingTrigger(context, 37);
		}
		else if (SpiritualDebtInteractionYuanshanVisibleCheck(argBox))
		{
			DomainManager.Global.InvokeGuidingTrigger(context, 38);
		}
		else if (SpiritualDebtInteractionShixiangVisibleCheck(argBox))
		{
			DomainManager.Global.InvokeGuidingTrigger(context, 39);
		}
		else if (SpiritualDebtInteractionBaihuaVisibleCheck(argBox))
		{
			DomainManager.Global.InvokeGuidingTrigger(context, 40);
		}
		else if (SpiritualDebtInteractionWudangVisibleCheck(argBox))
		{
			DomainManager.Global.InvokeGuidingTrigger(context, 41);
		}
		else if (SpiritualDebtInteractionZhujianVisibleCheck(argBox))
		{
			DomainManager.Global.InvokeGuidingTrigger(context, 42);
		}
		else if (SpiritualDebtInteractionShaolinVisibleCheck(argBox))
		{
			DomainManager.Global.InvokeGuidingTrigger(context, 43);
		}
		else if (SpiritualDebtInteractionKongsangVisibleCheck(argBox))
		{
			DomainManager.Global.InvokeGuidingTrigger(context, 44);
		}
		else if (SpiritualDebtInteractionFulongVisibleCheck(argBox))
		{
			DomainManager.Global.InvokeGuidingTrigger(context, 45);
		}
		else if (SpiritualDebtInteractionJingangVisibleCheck(argBox))
		{
			DomainManager.Global.InvokeGuidingTrigger(context, 46);
		}
		if (AbleZhujianOptionVisibleCheck(argBox))
		{
			DomainManager.Global.InvokeGuidingTrigger(context, 30);
		}
		if (PunishmentSeverityCustomizeVisibleCheck(argBox))
		{
			DomainManager.Global.InvokeGuidingTrigger(context, 31);
		}
		if (IntimateInteractionRecommendPupilVisibleCheck(argBox))
		{
			DomainManager.Global.InvokeGuidingTrigger(context, 47);
		}
		GameData.Domains.Character.Character character = argBox.GetCharacter("CharacterId");
		OrganizationInfo organizationInfo = character.GetOrganizationInfo();
		if (organizationInfo.SettlementId < 0)
		{
			return;
		}
		Settlement settlement = DomainManager.Organization.GetSettlement(organizationInfo.SettlementId);
		if (settlement == null)
		{
			return;
		}
		if (settlement.Treasuries.IsGuard(character.GetId()))
		{
			DomainManager.Global.InvokeGuidingTrigger(context, 51);
		}
		if (organizationInfo.Grade >= 6)
		{
			DomainManager.Global.InvokeGuidingTrigger(context, 53);
		}
		if (IsInAnySect(character.GetId()))
		{
			return;
		}
		Location location = settlement.GetLocation();
		MapBlockData blockData = DomainManager.Map.GetBlock(location);
		bool isVillage = blockData.IsVillage();
		bool isTaiwuCun = blockData.IsTaiwuCun();
		if (organizationInfo.Grade == 0 && !isTaiwuCun)
		{
			DomainManager.Global.InvokeGuidingTrigger(context, 56);
		}
		else if (organizationInfo.Grade == 1 && !isVillage && !isTaiwuCun)
		{
			DomainManager.Global.InvokeGuidingTrigger(context, 48);
		}
		else if (organizationInfo.Grade == 1 && (isVillage || isTaiwuCun))
		{
			DomainManager.Global.InvokeGuidingTrigger(context, 57);
		}
		else if (organizationInfo.Grade == 2 && !isTaiwuCun)
		{
			DomainManager.Global.InvokeGuidingTrigger(context, 50);
		}
		else if (organizationInfo.Grade == 3)
		{
			DomainManager.Global.InvokeGuidingTrigger(context, 59);
		}
		else if (organizationInfo.Grade == 4)
		{
			DomainManager.Global.InvokeGuidingTrigger(context, 52);
		}
		else if (organizationInfo.Grade == 5)
		{
			DomainManager.Global.InvokeGuidingTrigger(context, 49);
		}
		else if (organizationInfo.Grade == 6 && !isTaiwuCun)
		{
			DomainManager.Global.InvokeGuidingTrigger(context, 58);
		}
		if (!isTaiwuCun)
		{
			if (organizationInfo.Grade == 8)
			{
				DomainManager.Global.InvokeGuidingTrigger(context, 54);
			}
			else if (organizationInfo.Grade == 7)
			{
				DomainManager.Global.InvokeGuidingTrigger(context, 55);
			}
		}
	}

