	public static bool AbleZhujianOptionVisibleCheck(EventArgBox argBox)
	{
		GameData.Domains.Character.Character character = argBox.GetCharacter("CharacterId");
		bool haveThisInteract = CanInteractWithType(character, 17);
		List<short> taiwuZhujianSwords = FilterDirectCombatSkillOfCharacter(EventArgBox.TaiwuCharacterId, -1, 7, 9);
		if (taiwuZhujianSwords != null && taiwuZhujianSwords.Count > 0)
		{
			taiwuZhujianSwords.RemoveAll((short e) => HasCombatSkillExchangedSpecialWeapon(e));
		}
		List<short> taiwuZhujianBlades = FilterDirectCombatSkillOfCharacter(EventArgBox.TaiwuCharacterId, -1, 8, 9);
		if (taiwuZhujianBlades != null && taiwuZhujianBlades.Count > 0)
		{
			taiwuZhujianBlades.RemoveAll((short e) => HasCombatSkillExchangedSpecialWeapon(e));
		}
		List<short> taiwuZhujianPolearms = FilterDirectCombatSkillOfCharacter(EventArgBox.TaiwuCharacterId, -1, 9, 9);
		if (taiwuZhujianPolearms != null && taiwuZhujianPolearms.Count > 0)
		{
			taiwuZhujianPolearms.RemoveAll((short e) => HasCombatSkillExchangedSpecialWeapon(e));
		}
		return haveThisInteract && IsSectAllowLearning(character.GetOrganizationInfo().OrgTemplateId) && (taiwuZhujianSwords.Count > 0 || taiwuZhujianBlades.Count > 0 || taiwuZhujianPolearms.Count > 0);
	}

