	public static int GetHostileInteractionSelectedCount(EventArgBox argBox)
	{
		int count = 0;
		if (argBox.Get(EventTriggerParameter.DefValue.Amount, ref count) && count > 0)
		{
			return count;
		}
		string countKey = EventTriggerParameter.DefValue.SelectInventoryItemKey.ArgBoxKey + "Count";
		if (argBox.Get(countKey, ref count) && count > 0)
		{
			return count;
		}
		return 1;
	}

	public static int GetHostileInteractionResourceTransferAmount(EventArgBox argBox, GameData.Domains.Character.Character targetChar, sbyte resourceType)
	{
		int inputResult = 0;
		int amount = ((argBox.Get("InputResult", ref inputResult) && inputResult > 0) ? inputResult : GetHostileInteractionSelectedCount(argBox));
		return Math.Min(amount, targetChar.GetResource(resourceType));
	}

	public static void TransferHostileInteractionResource(GameData.Domains.Character.Character selfChar, GameData.Domains.Character.Character targetChar, sbyte resourceType, int amount)
	{
		if (amount > 0)
		{
			ChangeRoleResource(selfChar, resourceType, amount);
			ChangeRoleResource(targetChar, resourceType, -amount);
		}
	}

	public static void ApplyHostileRobResourcePhase4TakeIfNeeded(EventArgBox argBox, GameData.Domains.Character.Character targetChar, sbyte resourceType, sbyte thenState)
	{
		if (thenState == 4)
		{
			int transferAmount = GetHostileInteractionResourceTransferAmount(argBox, targetChar, resourceType);
			if (transferAmount > 0)
			{
				ChangeRoleResource(targetChar, resourceType, -transferAmount);
			}
		}
	}

	public static void ReturnHostileRobResourceToTargetIfTaken(EventArgBox argBox, GameData.Domains.Character.Character targetChar, sbyte resourceType, int amount)
	{
		sbyte thenState = -1;
		if (argBox.Get("ActionThenState", ref thenState) && thenState == 4)
		{
			int transferAmount = GetHostileInteractionResourceTransferAmount(argBox, targetChar, resourceType);
			if (transferAmount <= 0)
			{
				transferAmount = amount;
			}
			if (transferAmount > 0)
			{
				ChangeRoleResource(targetChar, resourceType, transferAmount);
			}
		}
	}

	public static void TransferHostileRobResourceOnSuccess(EventArgBox argBox, GameData.Domains.Character.Character selfChar, GameData.Domains.Character.Character targetChar, sbyte resourceType, int amount)
	{
		int transferAmount = GetHostileInteractionResourceTransferAmount(argBox, targetChar, resourceType);
		if (transferAmount <= 0)
		{
			transferAmount = amount;
		}
		if (transferAmount > 0)
		{
			sbyte thenState = -1;
			argBox.Get("ActionThenState", ref thenState);
			if (thenState == 4)
			{
				ChangeRoleResource(selfChar, resourceType, transferAmount);
			}
			else
			{
				TransferHostileInteractionResource(selfChar, targetChar, resourceType, transferAmount);
			}
		}
	}

	public static string ExecuteScamAction(EventArgBox argBox)
	{
		argBox.Get(EventTriggerParameter.DefValue.SelectInventoryItemKey, out ItemKey targetItem);
		int count = GetHostileInteractionSelectedCount(argBox);
		argBox.Set(EventTriggerParameter.DefValue.Amount, count);
		if (targetItem.ItemType == 12 && targetItem.TemplateId == 388)
		{
			return ExecuteScamAction_NormalInformation(argBox);
		}
		if (targetItem.ItemType == 12 && targetItem.TemplateId == 389)
		{
			return ExecuteScamAction_SecretInformation(argBox);
		}
		if (targetItem.ItemType == 10 && targetItem.Id == -1)
		{
			SkillBookItem bookConfig = Config.SkillBook.Instance[targetItem.TemplateId];
			if (bookConfig.LifeSkillTemplateId >= 0)
			{
				return ExecuteScamAction_LifeSkill(argBox, bookConfig.LifeSkillTemplateId);
			}
			return ExecuteScamAction_CombatSkill(argBox, bookConfig.CombatSkillTemplateId);
		}
		if (targetItem.ItemType == 12 && targetItem.TemplateId == 475)
		{
			return ExecuteScamAction_Item(argBox);
		}
		return ExecuteScamAction_Item(argBox);
	}

	public static string ExecuteScamAction_Item(EventArgBox argBox)
	{
		argBox.Get(EventTriggerParameter.DefValue.SelectInventoryItemKey, out ItemKey targetItem);
		int count = GetHostileInteractionSelectedCount(argBox);
		argBox.Set(EventTriggerParameter.DefValue.Amount, count);
		if (ItemTemplateHelper.IsMiscResource(targetItem.ItemType, targetItem.TemplateId))
		{
			sbyte resourceType = ItemTemplateHelper.GetMiscResourceType(targetItem.ItemType, targetItem.TemplateId);
			argBox.Set("GetResType", resourceType);
			argBox.Set("InputResult", count);
			if (resourceType != -1)
			{
				return ExecuteScamAction_ItemResource(argBox);
			}
			return string.Empty;
		}
		AdvanceDays(5);
		GameData.Domains.Character.Character taiwu = argBox.GetCharacter("RoleTaiwu");
		ChangeRoleMainAttribute(taiwu, 2, -20);
		int charId = -1;
		argBox.Get("CharacterId", ref charId);
		GameData.Domains.Character.Character character = argBox.GetCharacter("CharacterId");
		sbyte thenState = GetScamActionPhase(taiwu, character, targetItem, count, showCheckAnim: true);
		argBox.Set("ActionThenState", thenState);
		return thenState switch
		{
			5 => "c3dc3e5b-f84a-4d22-8507-355f5689c0f4", 
			1 => "e5459805-135e-4c3d-b7a7-677cc2668df3", 
			2 => "66f62a92-372a-43e4-ad3f-6e66cb13f2f2", 
			_ => "7e580097-a8a6-4807-986f-d6a49391b8dd", 
		};
	}

	public static string ExecuteScamAction_ItemResource(EventArgBox argBox)
	{
		AdvanceDays(5);
		GameData.Domains.Character.Character taiwu = argBox.GetCharacter("RoleTaiwu");
		ChangeRoleMainAttribute(taiwu, 2, -20);
		int charId = -1;
		argBox.Get("CharacterId", ref charId);
		GameData.Domains.Character.Character character = argBox.GetCharacter("CharacterId");
		sbyte resType = -1;
		argBox.Get("GetResType", ref resType);
		int getNum = 0;
		argBox.Get("InputResult", ref getNum);
		sbyte thenState = GetScamActionPhase(taiwu, character, resType, getNum, showCheckAnim: true);
		argBox.Set("ActionThenState", thenState);
		if (thenState == 0)
		{
			return "e8324e2b-39d1-44c1-9461-cdd58612bc14";
		}
		if (thenState == 1)
		{
			return "b6ed0819-9baf-45b3-a464-b88d80d3505c";
		}
		if (thenState == 2)
		{
			return "f47397bf-9e91-46f4-ac0e-226ac1c288d7";
		}
		if (thenState == 3)
		{
			return "86222c08-a464-4408-a3f3-fb736fa58f8e";
		}
		if (thenState >= 4)
		{
			return "8a1f9bb3-3b23-4852-9411-d3ee87caf7a5";
		}
		return string.Empty;
	}

	public static string ExecuteScamAction_NormalInformation(EventArgBox argBox)
	{
		AdvanceDays(5);
		GameData.Domains.Character.Character taiwu = argBox.GetCharacter("RoleTaiwu");
		ChangeRoleMainAttribute(taiwu, 2, -20);
		int charId = -1;
		argBox.Get("CharacterId", ref charId);
		GameData.Domains.Character.Character character = argBox.GetCharacter("CharacterId");
		IEnumerable<NormalInformation> charNormalInfo = GetExceptedCharacterNormalInformation(EventArgBox.TaiwuCharacterId, charId);
		if (!charNormalInfo.Any())
		{
			return "081fe73b-e498-432c-a4f5-d94fb13ce478";
		}
		sbyte thenState = GetScamActionPhase(taiwu, character, 100, showCheckAnim: true);
		argBox.Set("ActionThenState", thenState);
		if (thenState > 0 && thenState < 5)
		{
			NormalInformation result = charNormalInfo.OrderBy((NormalInformation e) => e.Level).First();
			ChangeAlertnessOnScamNormalInformation(charId, result.Level, result.TemplateId);
		}
		return thenState switch
		{
			5 => "1fb6203c-b036-4799-91c7-8cf59fd45cfb", 
			1 => "3515a7f6-32d7-472c-b399-8c6c5c5bf9c3", 
			2 => "7ecef08c-89ac-4d76-8ac4-34e6b625bd2b", 
			_ => "2c8ff1e0-3d05-43b1-8f62-b2feaa848f13", 
		};
	}

	public static string ExecuteScamAction_SecretInformation(EventArgBox argBox)
	{
		AdvanceDays(5);
		GameData.Domains.Character.Character taiwu = argBox.GetCharacter("RoleTaiwu");
		ChangeRoleMainAttribute(taiwu, 2, -20);
		int charId = -1;
		argBox.Get("CharacterId", ref charId);
		GameData.Domains.Character.Character character = argBox.GetCharacter("CharacterId");
		List<int> charSecrets = GetSecretInformationOfCharacter(charId, includeBroadcast: false);
		bool hasUsefulSecret = false;
		ICollection<int> diff = ((charSecrets != null && charSecrets.Count > 0) ? GetSecretInformationKnownDiff(charId, EventArgBox.TaiwuCharacterId) : null);
		if (diff != null && diff.Count > 0)
		{
			hasUsefulSecret = true;
		}
		if (!hasUsefulSecret)
		{
			return "2d12dfba-0dfb-4b64-affc-2c2e55d27954";
		}
		sbyte thenState = GetScamActionPhase(taiwu, character, 100, showCheckAnim: true);
		argBox.Set("ActionThenState", thenState);
		int randomSecretInfo = diff.ElementAt(GetRandom(0, diff.Count));
		argBox.Set("GrantedSecretInformation", randomSecretInfo);
		if (thenState > 0 && thenState < 5)
		{
			SecretInformationItem config = DomainManager.Information.CalcSecretInformationConfig((SecretInformationId)randomSecretInfo);
			ChangeAlertnessOnScamSecretInformation(charId, config.SortValue, config.TemplateId, randomSecretInfo);
		}
		return thenState switch
		{
			5 => "bcdd8a0b-9124-41ba-8987-1abaf210c844", 
			1 => "1b40413d-c806-401e-883e-9508a4952701", 
			2 => "c070f96b-099a-40f8-9f9e-6d2e447906c0", 
			_ => "9c143b43-9c19-47dd-a1f8-8fcc911addf8", 
		};
	}

	public static string ExecuteScamAction_LifeSkill(EventArgBox argBox)
	{
		int charId = -1;
		argBox.Get("CharacterId", ref charId);
		GameData.Domains.Character.Character taiwu = argBox.GetCharacter("RoleTaiwu");
		GameData.Domains.Character.Character character = argBox.GetCharacter("CharacterId");
		ChangeRoleMainAttribute(taiwu, 2, -20);
		sbyte learnGrade = (sbyte)(GetXiangshuLevel() + 1);
		if (learnGrade < 0)
		{
			return "cead9ba5-d26d-4c83-8ca5-0101c31d72ad";
		}
		List<short> canLearn = GetCharLifeSkillList(charId, -1, 0, learnGrade, 3, requireTaiwuNotLearn: true);
