		List<short> lowCanLearn = GetMinGradeLifeSkillList(canLearn);
		int rd = GetRandom(0, lowCanLearn.Count);
		argBox.Set("SkillCanLearn", canLearn[rd]);
		sbyte thenState = GetScamActionPhase(taiwu, character, 100, showCheckAnim: true);
		argBox.Set("ThenState", thenState);
		return thenState switch
		{
			0 => "c8925ce9-a92e-4352-9e3d-3bbf796bfd29", 
			1 => "d69c33c4-c436-4ffa-9606-63e84fa3a3b2", 
			2 => "b867e9ce-4515-4397-ad71-3e19f2994d46", 
			_ => "9cf3c423-085e-48e7-9330-6b2e58c1e011", 
		};
	}

