	public static string ExecuteStealAction(EventArgBox argBox)
	{
		argBox.Get(EventTriggerParameter.DefValue.SelectInventoryItemKey, out ItemKey targetItem);
		int count = GetHostileInteractionSelectedCount(argBox);
		argBox.Set(EventTriggerParameter.DefValue.Amount, count);
		if (targetItem.ItemType == 10 && targetItem.Id == -1)
		{
			SkillBookItem bookConfig = Config.SkillBook.Instance[targetItem.TemplateId];
			if (bookConfig.LifeSkillTemplateId >= 0)
			{
				return ExecuteStealAction_LifeSkill(argBox, bookConfig.LifeSkillTemplateId);
			}
			return ExecuteStealAction_CombatSkill(argBox, bookConfig.CombatSkillTemplateId);
		}
		if (targetItem.ItemType == 12 && targetItem.TemplateId == 475)
		{
			return ExecuteStealAction_Item(argBox);
		}
		return ExecuteStealAction_Item(argBox);
	}

	public static string ExecuteStealAction_Item(EventArgBox argBox)
	{
		argBox.Get(EventTriggerParameter.DefValue.SelectInventoryItemKey, out ItemKey targetItem);
		int count = GetHostileInteractionSelectedCount(argBox);
		argBox.Set(EventTriggerParameter.DefValue.Amount, count);
		bool isMiscResource = ItemTemplateHelper.IsMiscResource(targetItem.ItemType, targetItem.TemplateId);
		AdvanceDays(5);
		if (isMiscResource)
		{
			sbyte resourceType = ItemTemplateHelper.GetMiscResourceType(targetItem.ItemType, targetItem.TemplateId);
			argBox.Set("GetResType", resourceType);
			argBox.Set("InputResult", count);
			if (resourceType != -1)
			{
				return ExecuteStealAction_ItemResource(argBox);
			}
			return string.Empty;
		}
		GameData.Domains.Character.Character taiwu = argBox.GetCharacter("RoleTaiwu");
		ChangeRoleMainAttribute(taiwu, 1, -20);
		argBox.Set("ConchShip_PresetKey_ConfirmWaitOptionSignal", "SteelItem");
