	public static string ExecuteStealLifeSkill(EventArgBox argBox)
	{
		int charId = -1;
		argBox.Get("CharacterId", ref charId);
		GameData.Domains.Character.Character taiwu = argBox.GetCharacter("RoleTaiwu");
		GameData.Domains.Character.Character character = argBox.GetCharacter("CharacterId");
		ChangeRoleMainAttribute(taiwu, 5, -20);
		sbyte learnGrade = (sbyte)(GetXiangshuLevel() + 1);
		if (learnGrade < 0)
		{
			return "9758c896-0972-41d6-9a9c-7c1ff3a88d3b";
		}
		List<short> canLearn = GetCharLifeSkillList(charId, -1, 0, learnGrade, 3, requireTaiwuNotLearn: true);
		if (canLearn.Count <= 0)
		{
			return "9758c896-0972-41d6-9a9c-7c1ff3a88d3b";
		}
		List<short> lowCanLearn = GetMinGradeLifeSkillList(canLearn);
		int rd = GetRandom(0, lowCanLearn.Count);
		argBox.Set("SkillCanLearn", canLearn[rd]);
		sbyte thenState = GetStealLifeSkillActionPhase(taiwu, character, canLearn[0], showCheckAnim: true);
		argBox.Set("ThenState", thenState);
		return thenState switch
		{
			0 => "8de6c99c-bf5b-4557-a7a3-148a4ae85f33", 
			1 => "d69c33c4-c436-4ffa-9606-63e84fa3a3b2", 
			2 => "a33c2d04-0f48-4869-b7df-2994a002f94e", 
			3 => "87d09a27-2393-4558-b8b8-bdc225dbe8b6", 
			_ => "79697f58-62b1-4b03-b9b0-8f4ed49733b3", 
		};
	}

