	public static void GetItemFromCharacterToCharacter(sbyte itemType, short templateId, GameData.Domains.Character.Character fromChar, GameData.Domains.Character.Character toChar = null, int maxCount = -1)
	{
		bool transferred = false;
		List<ItemKey> list = new List<ItemKey>();
		fromChar.GetInventory().GetInventoryItemKeyList(itemType, templateId, list);
		foreach (ItemKey itemKey in list)
		{
			if (!fromChar.GetInventory().Items.TryGetValue(itemKey, out var count) || count <= 0)
			{
				continue;
			}
			transferred = true;
			if (maxCount > 0)
			{
				count = Math.Min(maxCount, count);
			}
			if (toChar == null)
			{
				fromChar.RemoveInventoryItem(Domain.MainThreadDataContext, itemKey, count, deleteItem: true, offLine: true);
			}
			else
			{
				fromChar.GetInventory().OfflineRemove(itemKey, count);
			}
			toChar?.GetInventory().OfflineAdd(itemKey, count);
			if (maxCount > 0)
			{
				maxCount -= count;
				if (maxCount <= 0)
				{
					break;
				}
			}
		}
		if (transferred)
		{
			fromChar.SetInventory(fromChar.GetInventory(), Domain.MainThreadDataContext);
			toChar?.SetInventory(toChar.GetInventory(), Domain.MainThreadDataContext);
		}
	}

