		if (DomainManager.Character.TryGetElement_Objects(nominatedCharId, out var nominatedChar) && DomainManager.Character.TryGetElement_Objects(threatenedCharId, out var threatenedChar) && RelationTypeHelper.AllowAddingAdoptiveChildRelation(threatenedCharId, nominatedCharId))
		{
			Location location = threatenedChar.GetLocation();
			int currDate = DomainManager.World.GetCurrDate();
			LifeRecordCollection lifeRecordCollection = DomainManager.LifeRecord.GetLifeRecordCollection();
			DomainManager.Character.AddAdoptiveParentRelations(Domain.MainThreadDataContext, nominatedCharId, threatenedCharId, currDate);
			int spouseId = DomainManager.Character.GetAliveSpouse(threatenedCharId);
			if (spouseId >= 0)
			{
				DomainManager.Character.AddAdoptiveParentRelations(Domain.MainThreadDataContext, nominatedCharId, spouseId, currDate);
			}
			short relatedRecordId = (short)((threatenedChar.GetGender() == 1) ? 459 : 460);
			if (nominatedChar.GetGender() == 1)
			{
				lifeRecordCollection.AddGetAdoptedSonByThreatened(threatenedCharId, currDate, nominatedCharId, location, selfCharId, relatedRecordId);
			}
			else
			{
				lifeRecordCollection.AddGetAdoptedDaughterByThreatened(threatenedCharId, currDate, nominatedCharId, location, selfCharId, relatedRecordId);
			}
			lifeRecordCollection.AddThreatenSucceed(selfCharId, currDate, threatenedCharId, location);
			SecretInformationCollection secretInformationCollection = DomainManager.Information.GetSecretInformationCollection();
			int secretInfoOffset = secretInformationCollection.AddAdoptChild(threatenedCharId, nominatedCharId);
			int secretInfoId = (int)DomainManager.Information.AddSecretInformation(Domain.MainThreadDataContext, secretInfoOffset);
			secretInfoOffset = secretInformationCollection.AddGetAdopted(nominatedCharId, threatenedCharId);
			int secretInfoIdExtra = (int)DomainManager.Information.AddSecretInformation(Domain.MainThreadDataContext, secretInfoOffset);
			if (!GetSecretInformationOfCharacter(selfCharId).Contains(secretInfoId))
			{
				DistributeSecretInformationToCharacter(secretInfoId, selfCharId);
			}
			if (!GetSecretInformationOfCharacter(selfCharId).Contains(secretInfoIdExtra))
			{
				DistributeSecretInformationToCharacter(secretInfoIdExtra, selfCharId);
			}
			ApplyDebtHappinessAndMoodChangeOfAddingRelationByThreaten(selfCharId, threatenedCharId, nominatedCharId);
		}
	}

