			secretInfoOffset = secretInformationCollection.AddAdoptChild(nominatedCharId, threatenedCharId);
			int secretInfoIdExtra = (int)DomainManager.Information.AddSecretInformation(Domain.MainThreadDataContext, secretInfoOffset);
			if (!GetSecretInformationOfCharacter(selfCharId).Contains(secretInfoId))
			{
				DistributeSecretInformationToCharacter(secretInfoId, selfCharId);
			}
			if (!GetSecretInformationOfCharacter(selfCharId).Contains(secretInfoIdExtra))
			{
				DistributeSecretInformationToCharacter(secretInfoIdExtra, selfCharId);
			}
			ApplyDebtHappinessAndMoodChangeOfAddingRelationByThreaten(selfCharId, threatenedCharId, nominatedCharId);
		}
	}

