	public static void ApplyDebtHappinessAndMoodChangeOfAddingRelationByThreaten(int selfCharId, int threatenedCharId, int nominatedCharId)
	{
		if (DomainManager.Character.TryGetElement_Objects(threatenedCharId, out var threatenedChar) && DomainManager.Character.TryGetElement_Objects(nominatedCharId, out var _) && DomainManager.Character.TryGetElement_Objects(selfCharId, out var selfChar))
		{
			short favor = DomainManager.Character.GetFavorability(threatenedCharId, nominatedCharId);
			sbyte favorType = FavorabilityType.GetFavorabilityType(favor);
			short favorDelta = (short)(9000 - Math.Max(favorType, 0) * 1000);
			ChangeFavorabilityOptional(threatenedChar, selfChar, (short)(-favorDelta), 3);
			int moodDelta = 9 - Math.Max(favorType, 0);
			ChangeRoleHappiness(threatenedChar, moodDelta);
		}
	}

	public static void ApplyDebtHappinessAndMoodChangeOfEndingRelationByThreaten(int selfCharId, int threatenedCharId, int nominatedCharId)
	{
		if (DomainManager.Character.TryGetElement_Objects(threatenedCharId, out var threatenedChar) && DomainManager.Character.TryGetElement_Objects(nominatedCharId, out var _) && DomainManager.Character.TryGetElement_Objects(selfCharId, out var selfChar))
		{
			short favor = DomainManager.Character.GetFavorability(threatenedCharId, nominatedCharId);
			sbyte favorType = FavorabilityType.GetFavorabilityType(favor);
			short favorDelta = (short)(3000 + Math.Max(favorType, 0) * 1500);
			ChangeFavorabilityOptional(threatenedChar, selfChar, (short)(-favorDelta), 3);
			int moodDelta = 3 + Math.Max(favorType, 0);
			ChangeRoleHappiness(threatenedChar, -moodDelta);
		}
	}

	public static bool AllowAddingRelationByThreadNeedle(EventArgBox argBox, ushort relationType)
	{
		GameData.Domains.Character.Character character = argBox.GetCharacter("CharacterId");
		int charId = character.GetId();
		GameData.Domains.Character.Character relatedChar = argBox.GetCharacter("SelectedCharIdForThreadNeedleAdding");
		int relatedCharId = relatedChar.GetId();
		return RelationTypeHelper.AllowAddingRelation(charId, relatedCharId, relationType);
	}

	public static bool AllowEndingRelationByThreadNeedle(EventArgBox argBox, ushort relationType)
	{
		GameData.Domains.Character.Character character = argBox.GetCharacter("CharacterId");
		int charId = character.GetId();
		GameData.Domains.Character.Character relatedChar = argBox.GetCharacter("SelectedCharIdForThreadNeedleEnding");
		int relatedCharId = relatedChar.GetId();
		switch (relationType)
		{
		case 512:
		case 8192:
		case 16384:
			return CanEndRelation(charId, relatedCharId, relationType);
		case 32768:
			return CanEndRelation(relatedCharId, charId, relationType);
		case 64:
		case 128:
		case 1024:
		case 2048:
		case 4096:
			return CheckHasRelationship(character, relatedChar, relationType);
		default:
			throw new Exception($"Unsupported relation type for ending in event: {relationType}");
		}
	}

	public static void ApplyStartRelationByThreadNeedle(int charIdA, int charIdB, ushort relationType, bool succeed, bool isBothWayRelation = true)
	{
		if (!DomainManager.Character.TryGetElement_Objects(charIdA, out var characterA) || !DomainManager.Character.TryGetElement_Objects(charIdB, out var characterB))
		{
			return;
		}
		switch (relationType)
		{
		case 16384:
			if (isBothWayRelation)
			{
				AddRelation(charIdA, charIdB, 16384);
				ApplyRelationBecomeBoyOrGirlFriend(characterA, characterB, succeed);
			}
			else
			{
				ApplyRelationBecomeAdore(characterA, characterB, succeed);
			}
			break;
		case 8192:
			if (succeed)
			{
				ApplyRelationBecomeFriend(characterA, characterB);
			}
			break;
		case 512:
			if (succeed)
			{
				ApplyRelationBecomeSwornBrotherOrSister(characterA, characterB);
			}
			break;
		case 64:
			if (succeed)
			{
				ApplyRelationGetAdopted(characterA, characterB);
			}
			break;
		case 128:
			if (succeed)
			{
				ApplyRelationAdoptChild(characterA, characterB);
			}
			break;
		case 1024:
			ApplyRelationBecomeHusbandOrWife(characterA, characterB, succeed);
			break;
		case 2048:
			if (succeed)
			{
				ApplyRelationBecomeMentor(characterA, characterB);
			}
			break;
		case 32768:
			ApplyRelationBecomeEnemy(characterA, characterB);
			if (succeed)
			{
				ApplyRelationBecomeEnemy(characterB, characterA);
			}
			break;
		default:
			throw new Exception($"Wrong Adding Relation Quest: {relationType}");
		}
	}

	public static void ApplyEndRelationByThreadNeedle(int charIdA, int charIdB, ushort relationType, bool succeed, bool isBothWayRelation = true)
	{
		if (!DomainManager.Character.TryGetElement_Objects(charIdA, out var characterA) || !DomainManager.Character.TryGetElement_Objects(charIdB, out var characterB))
		{
			return;
		}
		switch (relationType)
		{
		case 16384:
		{
			if (isBothWayRelation)
			{
				ApplyRelationBreakupWithBoyOrGirlFriend(characterA, characterB, !succeed);
				break;
			}
			sbyte behaviorType = characterA.GetBehaviorType();
			bool selfIsTaiwuPeople = DomainManager.Character.IsTaiwuPeople(charIdA);
			bool targetIsTaiwuPeople = DomainManager.Character.IsTaiwuPeople(charIdB);
			GameData.Domains.Character.Character.ApplySeverAdore(Domain.MainThreadDataContext, characterA, characterB, behaviorType, selfIsTaiwuPeople);
			break;
		}
		case 8192:
			if (succeed)
			{
				ApplyRelationSeverFriend(characterA, characterB);
			}
			break;
		case 512:
			if (succeed)
			{
				ApplyRelationSeverSwornBrotherOrSister(characterA, characterB);
			}
			break;
		case 64:
			if (succeed)
			{
				ApplyRelationSeverAdoptiveParent(characterA, characterB);
			}
			break;
		case 128:
			if (succeed)
			{
				ApplyRelationSeverAdoptedChild(characterA, characterB);
			}
			break;
		case 1024:
			if (succeed)
			{
				ApplyRelationSeverHusbandOrWife(characterA, characterB);
			}
			break;
		case 2048:
			if (succeed)
			{
				ApplyRelationSeverMentor(characterA, characterB);
			}
			break;
		case 32768:
			ApplyRelationSeverEnemy(characterA, characterB);
			if (succeed)
			{
				ApplyRelationSeverEnemy(characterB, characterA);
			}
			break;
		default:
			throw new Exception($"Wrong Ending Relation Quest: {relationType}");
		}
	}

