	public static List<int> PrepareCombatEnemy(int charId, short combatConfigId, bool noGuard = false)
	{
		List<int> enemyTeam = new List<int>();
		DataContext context = Domain.MainThreadDataContext;
		GameData.Domains.Character.Character character = DomainManager.Character.GetElement_Objects(charId);
		if (DomainManager.TaiwuEvent.GetGlobalEventArgumentBox().GetBool("IsGuardCombat") && character.IsTreasuryGuard())
		{
			enemyTeam.Add(charId);
			OrganizationInfo orgInfo = character.GetOrganizationInfo();
			short templateId = ((orgInfo.SettlementId >= 0 && DomainManager.Organization.GetSettlement(orgInfo.SettlementId) is Sect sect) ? GameData.Domains.Character.Character.GetSectRandomEnemyTemplateIdByGrade(sect.GetOrgTemplateId(), orgInfo.Grade) : CivilianSettlement.GetTreasuryGuardTemplateId(orgInfo.Grade));
			int i = 3;
			while (i-- > 0)
			{
				enemyTeam.Add(CreateNonIntelligentCharacter(templateId));
			}
		}
		else if (character.GetCreatingType() == 1)
		{
			CombatConfigItem config = CombatConfig.Instance[combatConfigId];
			CombatType combatType = (CombatType)config.CombatType;
			if (DomainManager.Taiwu.IsInGroup(charId) && config != null && config.IsGroupMemberLeave)
			{
				DomainManager.Taiwu.LeaveGroup(Domain.MainThreadDataContext, charId, bringWards: true, showNotification: true, moveToRandomAdjacentBlock: false);
			}
			if (noGuard)
			{
				enemyTeam.Add(charId);
			}
			else
			{
				DomainManager.Character.GetTaiwuCombatEnemyTeam(context, character, combatType, enemyTeam);
			}
		}
		else if (noGuard)
		{
			enemyTeam.Add(character.GetId());
		}
		else
		{
			enemyTeam = DomainManager.Character.GetNonIntelligentNpcCombatTeam(context, character);
		}
		return enemyTeam;
	}

	public static void CharacterLoseGuard(int charId, int combatType)
	{
		if ((uint)(combatType - 1) <= 1u)
		{
			DomainManager.Character.LoseGuard(Domain.MainThreadDataContext, charId, null);
		}
	}

	public static void StartPickupCombatContinuously(List<int> charIds, short combatConfigId, string combatCompleteEvent, EventArgBox argBox, bool noGuard = false)
	{
		int firstCharId = charIds[0];
		charIds.Remove(firstCharId);
		DomainManager.Map.MapPickBattles = charIds;
		List<int> enemyTeam = PrepareCombatEnemy(firstCharId, combatConfigId, noGuard);
		StartCombat(enemyTeam, combatConfigId, combatCompleteEvent, argBox);
	}

	public static List<int> GetContinuePickupCombat()
	{
		return DomainManager.Map.MapPickBattles;
	}

