	public static string GetTriggeringRandomEnemyEventGuid(short enemyLeaderId)
	{
		if (!DomainManager.Combat.TryGetWipeOutType(enemyLeaderId, out var type))
		{
			return "e5ecfaee-b6bc-4d5a-a15b-71b633b5a17a";
		}
		if (CanWipeOut(enemyLeaderId))
		{
			return (type == WipeOutType.Righteous) ? "9cc242b6-e839-4c95-8100-ce948847533e" : "bcece724-0aa5-4fde-bb58-c820d648e03b";
		}
		return (type == WipeOutType.Righteous) ? "00be2f9c-1215-4cca-a308-699664e60de3" : "e5ecfaee-b6bc-4d5a-a15b-71b633b5a17a";
	}

	public static bool TryTriggerRandomEnemy(EventArgBox argBox)
	{
		if (DomainManager.TaiwuEvent.GetHideAllMapBlockCharacters())
		{
			return false;
		}
		if (IsTaiwuAvoidMapBlockEnemies())
		{
			return false;
		}
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		Location location = taiwu.GetLocation();
		if (!location.IsValid())
		{
			return false;
		}
		MapBlockData blockData = DomainManager.Map.GetBlock(location);
		List<MapTemplateEnemyInfo> templateEnemyList = blockData.TemplateEnemyList;
		if (templateEnemyList == null || templateEnemyList.Count <= 0)
		{
			return false;
		}
		List<MapTemplateEnemyInfo> group = GetMapRandomEnemyGroupForChar(blockData, EventArgBox.TaiwuCharacterId, avoidRandomEnemy: true);
		if (group == null || group.Count == 0)
		{
			return false;
		}
		SetMapRandomEnemyListToArgBox(argBox, "EnemyGroup", group);
		short enemyLeaderId = group[0].TemplateId;
		sbyte taiwuFrameType = taiwu.GetFameType();
		if (enemyLeaderId >= 375 && enemyLeaderId <= 383 && !FameType.AttackByRighteous(taiwuFrameType))
		{
			return false;
		}
		if (CanWipeOut(enemyLeaderId) && !CanAutoWipeOut(enemyLeaderId))
		{
			return false;
		}
		if (GlobalArgBoxContainsKey<bool>("BattleWithXiangshuMinion") && enemyLeaderId == 366 && SmallVillageXiangshu(Config.Character.Instance[enemyLeaderId].OrganizationInfo.OrgTemplateId))
		{
			argBox.Set("EnemyLeader", enemyLeaderId);
			argBox.Set("NextEventGuid", "a114a545-3e31-49d7-b856-2a8940570a66");
			return true;
		}
		if (MoveRandomEnemyJumpEventGuid.TryGetValue(enemyLeaderId, out var toEventGuid))
		{
			argBox.Set("EnemyLeader", enemyLeaderId);
			argBox.Set("NextEventGuid", CanAutoWipeOut(enemyLeaderId) ? "c83b76cc-e844-49dd-bdd3-52c45ef93a45" : toEventGuid);
			return true;
		}
		return false;
	}

