	public static string WipeOut(EventArgBox argBox)
	{
		short enemyLeaderId = -1;
		argBox.Get("EnemyLeader", ref enemyLeaderId);
		if (GlobalArgBoxContainsKey<int>("DefeatXiangshuMinion") && (uint)(enemyLeaderId - 372) <= 2u)
		{
			int amount = GetIntFromGlobalArgBox("DefeatXiangshuMinion");
			SaveGlobalArg("DefeatXiangshuMinion", ++amount);
			Log("amount of DefeatXiangshuMinion:" + amount);
		}
		GetMapRandomEnemyListFromArgBox(argBox, "EnemyGroup", out var group);
		int animalId = -1;
		if (argBox.Get(EventTriggerParameter.DefValue.AnimalId, ref animalId) && DomainManager.Extra.TryGetAnimal(animalId, out var animal))
		{
			WipeOutAnimals(new List<GameData.Domains.Character.Animal> { animal });
		}
		else
		{
			List<short> templateIds = new List<short>();
			foreach (MapTemplateEnemyInfo item in group)
			{
				templateIds.Add(item.TemplateId);
			}
			DomainManager.Combat.WipeOut(Domain.MainThreadDataContext, templateIds);
			Location location = DomainManager.Taiwu.GetTaiwu().GetLocation();
			RemoveMapRandomEnemiesOnBlock(location, group);
			MapRandomEnemiesEscapeByCharacter(location, EventArgBox.TaiwuCharacterId);
		}
		SetOnHandlingMonthlyEventBlock(blockOperation: false);
		if (IsExtraTaskInProgress(189) && IsShixiangSettlementEnemyClean())
		{
			argBox.Set("EnemyTemplateId", enemyLeaderId);
			return "1010bcdb-c7eb-4667-a085-efbcdb104135";
		}
		if ((IsExtraTaskInProgress(172) || IsExtraTaskInProgress(364)) && GameData.Domains.Character.Character.IsXiangshuMinion(enemyLeaderId))
		{
			argBox.Set("EnemyTemplateId", enemyLeaderId);
			if (IsRandomEnemyBelongHeavenlyTree(argBox))
			{
				EventArgBox sectArgBox = GetSectMainStoryEventArgBox(4);
				if (!sectArgBox.Contains<bool>(SectMainStoryEventArgKey.DefValue.WudangKillRandomEnemyTriggered))
				{
					return "6134ab9d-cb0a-419b-8c07-727997310fa5";
				}
				GameData.Domains.Character.Character character = argBox.GetCharacter("CharacterId");
				HeavenlyTreeGrewUp(character, 20, argBox);
			}
		}
		return string.Empty;
	}

	public static void WipeOutInTravel(EventArgBox argBox)
	{
		short enemyLeaderId = -1;
		argBox.Get("EnemyLeader", ref enemyLeaderId);
		List<short> templateIds = new List<short> { enemyLeaderId };
		CharacterItem config = Config.Character.Instance[enemyLeaderId];
		if (config.MinionGroupId >= 0)
		{
			MinionGroupItem minionGroup = MinionGroup.Instance[config.MinionGroupId];
			foreach (short templateId in minionGroup.Minions)
			{
				templateIds.Add(templateId);
			}
		}
		DomainManager.Combat.WipeOut(Domain.MainThreadDataContext, templateIds);
		TravelingEventCollection travelingCollection = GetTravelingEventCollection();
		travelingCollection.AddTravelBattlePerfectWin(DomainManager.Taiwu.GetTaiwuCharId(), enemyLeaderId);
		SetEventSeriesTexture(string.Empty);
		SetOnHandlingTravelingEventBlock(blockOperation: false);
	}

	public static void TryWipeOutAnimals()
	{
		if (!GlobalDomain.Settings.IsTypeAutoWipeOutOn(WipeOutType.Beast))
		{
			return;
		}
		Location location = DomainManager.Taiwu.GetTaiwu().GetLocation();
		if (!DomainManager.Extra.TryGetAnimalsByLocation(location, out var animals))
		{
			return;
		}
		List<GameData.Domains.Character.Animal> res = new List<GameData.Domains.Character.Animal>();
		foreach (GameData.Domains.Character.Animal animal in animals)
		{
			if (CanAutoWipeOut(animal.CharacterTemplateId))
			{
				res.Add(animal);
			}
		}
		WipeOutAnimals(res);
	}

	public static void WipeOutAnimals(List<GameData.Domains.Character.Animal> animals)
	{
		List<short> templateIds = new List<short>();
		foreach (GameData.Domains.Character.Animal animal in animals)
		{
			ProfessionFormulaItem formulaItemHunter2 = ProfessionFormula.Instance[9];
			sbyte level = Config.Character.Instance[animal.CharacterTemplateId].ConsummateLevel;
			int value = formulaItemHunter2.Calculate(level);
			RemoveAnimal(animal);
			templateIds.Add(animal.CharacterTemplateId);
			ChangeProfessionSeniority(1, value);
		}
		DomainManager.Combat.WipeOut(Domain.MainThreadDataContext, templateIds);
	}

