	public static string CheckTeachTaiwuCombatSkillLimit(int charId, EventArgBox argBox)
	{
		List<short> taughtList = GetTeachTaiwuCombatSkillList(charId);
		if (taughtList == null || taughtList.Count < 3)
		{
			return null;
		}
		foreach (short taughtCombat in taughtList)
		{
			if (TaiwuCanLearnCombatSkill(taughtCombat))
			{
				ClearTeachTaiwuCombatSkillList(charId);
				return null;
			}
		}
		argBox.Set("Taught0", taughtList[0]);
		argBox.Set("Taught1", taughtList[1]);
		argBox.Set("Taught2", taughtList[2]);
		return "dc931481-04da-4211-83d3-dc709b69bdf2";
	}

	public static string LearnTargetCombatSkillDependSectApprovingRate(sbyte combatSkillType, EventArgBox argBox)
	{
		GameData.Domains.Character.Character character = argBox.GetCharacter("CharacterId");
		string limitEventGuid = CheckTeachTaiwuCombatSkillLimit(character.GetId(), argBox);
		if (limitEventGuid != null)
		{
			return limitEventGuid;
		}
		GameData.Domains.Character.Character taiwu = argBox.GetCharacter("RoleTaiwu");
		sbyte sectId = character.GetOrganizationInfo().OrgTemplateId;
		List<short> canLearn = GetCharCombatSkillList(character.GetId(), combatSkillType, sectId, 0, 8, needBreak: false, requireTaiwuNotLearnAndRead: true);
		if (canLearn == null || canLearn.Count == 0)
		{
			return argBox.GetString("CombatSkillNoneTeachEventGuid");
		}
		short lowestCombatSkill = GetMinGradeCombatSkillList(canLearn).Sample();
		sbyte canLearnGrade = (sbyte)Math.Max(0, GetSectApprovingRate(sectId) / 100 - 1);
		sbyte lowestGrade = GetCombatSkillGrade(lowestCombatSkill);
		List<short> taiwuList = GetCharCombatSkillList(taiwu.GetId(), combatSkillType, sectId, 0, 8);
		if (lowestGrade > canLearnGrade)
		{
			argBox.Set("CantTeachCombat", lowestCombatSkill);
			return argBox.GetString("CombatSkillBeyondApprovingEventGuid");
		}
		if (GetCombatSkillGrade(lowestCombatSkill) == 0)
		{
			argBox.Set("TeachCombat", lowestCombatSkill);
			return argBox.GetString("CombatSkillTeachEventGuid");
		}
		for (sbyte eGrade = 0; eGrade < lowestGrade; eGrade++)
		{
			short eSkillId = GetCombatSkillId(combatSkillType, sectId, eGrade);
			if (!taiwuList.Contains(eSkillId) || !TaiwuCanLearnCombatSkill(eSkillId))
			{
				argBox.Set("TeachCombatBefore", eSkillId);
				return argBox.GetString("CombatSkillTeachBeforeEventGuid");
			}
		}
		argBox.Set("TeachCombat", lowestCombatSkill);
		return argBox.GetString("CombatSkillTeachEventGuid");
	}

	public static void LearnCombatSkillInSectCompetition(GameData.Domains.Character.Character teacher, GameData.Domains.Character.Character student, short combatSkillId)
	{
		sbyte skillBehaviorType = GetCharCombatSkillBehaviorType(teacher.GetId(), combatSkillId);
		if (skillBehaviorType < 0)
		{
			skillBehaviorType = GetRoleBehavior(teacher);
		}
		bool[] pageIsDirect = new bool[5] { true, true, true, true, true };
		sbyte fullCount = (sbyte)((13 - GetCombatSkillGrade(combatSkillId)) / 3);
		sbyte skillDirection = GetRoleCombatSkillDirection(teacher.GetId(), combatSkillId);
		if (skillDirection == -2)
		{
			skillDirection = -1;
		}
		short prob = GlobalConfig.CombatSkillPageReverseProb[skillDirection + 1];
		for (int i = 0; i < 5; i++)
		{
			if (GetRandom() < prob)
			{
				pageIsDirect[i] = false;
			}
		}
		GetCombatSkillBook(student.GetId(), combatSkillId, skillBehaviorType, pageIsDirect, fullCount);
		short bookTemplateId = Config.CombatSkill.Instance[combatSkillId].BookId;
		ChangeRoleHappiness(student, ItemTemplateHelper.GetBaseHappinessChange(10, bookTemplateId) / 2);
		short change = (short)ItemTemplateHelper.GetBaseFavorabilityChange(10, bookTemplateId);
		ChangeFavorabilityOptional(student, teacher, change, 3);
		List<short> charCombatSkillList = GetCharCombatSkillList(student.GetId(), -1, -1, 0, 8);
		if (!charCombatSkillList.Contains(combatSkillId))
		{
			LearnCombatSkill(student.GetId(), combatSkillId);
		}
	}

