	public static int CalcIdentityExtendFavorValue(sbyte resourceType, int charId)
	{
		GameData.Domains.Character.Character target = DomainManager.Character.GetElement_Objects(charId);
		Settlement targetSettlement = DomainManager.Organization.GetSettlement(target.GetOrganizationInfo().SettlementId);
		MapAreaData targetArea = DomainManager.Map.GetAreaByAreaId(targetSettlement.GetLocation().AreaId);
		MapAreaItem targetAreaConfig = targetArea.GetConfig();
		short templateId = targetAreaConfig.TemplateId;
		int factor;
		if (templateId >= 1 && templateId <= 15)
		{
			factor = GlobalConfig.Instance.ExtendFavorSafetyAndCultureAreaFactor[0];
		}
		else
		{
			sbyte[] organizationId = targetAreaConfig.OrganizationId;
			factor = ((organizationId == null || organizationId.Length <= 0 || !Config.Organization.Instance[targetAreaConfig.OrganizationId[0]].IsSect) ? GlobalConfig.Instance.ExtendFavorSafetyAndCultureAreaFactor[2] : GlobalConfig.Instance.ExtendFavorSafetyAndCultureAreaFactor[1]);
		}
		return (150 + target.GetFame()) * factor / 10;
	}

	public static void PerformIdentityExtendFavor(sbyte resourceType, int charId)
	{
		DataContext ctx = Domain.MainThreadDataContext;
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		taiwu.ChangeResource(ctx, resourceType, -IdentityExtendFavorResourceCost);
		GameData.Domains.Character.Character target = DomainManager.Character.GetElement_Objects(charId);
		Settlement targetSettlement = DomainManager.Organization.GetSettlement(target.GetOrganizationInfo().SettlementId);
		MapAreaData targetArea = DomainManager.Map.GetAreaByAreaId(targetSettlement.GetLocation().AreaId);
		DomainManager.Extra.ChangeAreaSpiritualDebt(ctx, targetArea.GetAreaId(), CalcIdentityExtendFavorValue(resourceType, charId));
	}

