	public static void TaiwuSelectItemForGiveExchangeTool(EventArgBox argBox)
	{
		GameData.Domains.Character.Character taiwuChar = DomainManager.Taiwu.GetTaiwu();
		if (!argBox.Get("SelectItemInfo", out EventSelectItemData data))
		{
			data = new EventSelectItemData();
			argBox.Set("SelectItemInfo", data);
		}
		EventSelectItemData eventSelectItemData = data;
		if (eventSelectItemData.CanSelectItemList == null)
		{
			eventSelectItemData.CanSelectItemList = new List<ITradeableContent>();
		}
		eventSelectItemData = data;
		if (eventSelectItemData.FilterList == null)
		{
			eventSelectItemData.FilterList = new List<SelectItemFilter>();
		}
		data.ItemOperationType = 9;
		for (int i = 0; i < GiveExchangeToolAmount; i++)
		{
			SelectItemFilter filter = new SelectItemFilter
			{
				FilterTemplateId = -1,
				DisplayDataFilterId = 0,
				Key = GiveExchangeToolSelectionKey(i)
			};
			data.FilterList.Add(filter);
		}
		List<(ItemKey, int)> items = new List<(ItemKey, int)>();
		taiwuChar.FindItems((ItemBase _) => true, items, searchInventory: true, searchEquipment: false);
		List<ItemDisplayData> filterItems = CharacterDomain.GetItemDisplayData(taiwuChar.GetId(), items, ItemSourceType.Inventory);
		foreach (ItemDisplayData itemDisplayData in filterItems)
		{
			if (!data.CanSelectItemList.Exists((ITradeableContent d) => d.Key.Equals(itemDisplayData.Key)) && itemDisplayData.Key.ItemType == 6)
			{
				data.CanSelectItemList.Add(itemDisplayData);
			}
		}
	}

	public static List<ItemKey> GetGiveExchangeToolSelections(EventArgBox argBox)
	{
		List<ItemKey> result = new List<ItemKey>();
		for (int i = 0; i < GiveExchangeToolAmount; i++)
		{
			if (argBox.Get(GiveExchangeToolSelectionKey(i), out ItemKey itemKey))
			{
				result.Add(itemKey);
			}
		}
		return result;
	}

	public static void StartFixItem(EventArgBox argBox, GameData.Domains.Character.Character character)
	{
		SelectItemFilter filter = new SelectItemFilter
		{
			DisplayDataFilterId = 1,
			Key = "RepairKey"
		};
		SelectCharacterItemRequest(EventArgBox.TaiwuCharacterId, argBox, filter);
		argBox.Get("SelectItemInfo", out EventSelectItemData data);
		for (int i = 0; i < data.CanSelectItemList.Count; i++)
		{
			ITradeableContent item = data.CanSelectItemList[i];
			sbyte needSkillType = GetItemRequireLifeSkillType(item.RealKey);
			short attainment = GetRoleLifeSkillAttainmentByType(character, needSkillType);
			sbyte grade = ItemTemplateHelper.GetGrade(item.RealKey.ItemType, item.RealKey.TemplateId);
			int needAttainment = grade * (grade + 1) * 5 / 2 + 5;
			if (needAttainment > attainment)
			{
				((ItemDisplayData)item).UnavailableType = ItemDisplayData.ItemUnavailableType.AttainmentNotMeet;
			}
		}
		data.ItemOperationType = 10;
	}

