	public static ItemKey AddEquipmentItemToRole(GameData.Domains.Character.Character character, sbyte itemType, short itemTemplateId, short equipmentEffectId = -1, bool tryEquipOn = true)
	{
		DataContext context = Domain.MainThreadDataContext;
		ItemKey itemKey = DomainManager.Item.CreateItem(context, itemType, itemTemplateId);
		EquipmentBase equipment = DomainManager.Item.GetBaseEquipment(itemKey);
		if (equipmentEffectId >= 0)
		{
			if (equipmentEffectId == 54)
			{
				short durability = (short)(equipment.GetMaxDurability() * 2);
				equipment.SetMaxDurability(durability, context);
				equipment.SetCurrDurability(durability, context);
			}
			equipment.SetEquipmentEffectId(equipmentEffectId, context);
		}
		AddInventoryItem(character, itemKey);
		if (tryEquipOn)
		{
			ItemKey[] equipments = character.GetEquipment();
			bool equipFlag = false;
			sbyte equipType = equipment.GetEquipmentType();
			sbyte[] slotsArray = EquipmentSlot.EquipmentType2Slots[equipType];
			for (int i = 0; i < slotsArray.Length; i++)
			{
				if (!equipments[slotsArray[i]].IsValid())
				{
					character.ChangeEquipment(Domain.MainThreadDataContext, -1, slotsArray[i], itemKey);
					equipFlag = true;
				}
				if (equipFlag)
				{
					break;
				}
			}
		}
		return itemKey;
	}

	public static ItemKey AddItemToRole(GameData.Domains.Character.Character character, sbyte itemType, short itemTemplateId, int amount, short currDurability = -1)
	{
		if (character == null)
		{
			throw new Exception("null character to add item");
		}
		ItemKey itemKey = DomainManager.Item.CreateItem(Domain.MainThreadDataContext, itemType, itemTemplateId);
		AddInventoryItem(character, itemKey, amount);
		if (currDurability >= 0)
		{
			List<(ItemKey, int)> findResult = new List<(ItemKey, int)>();
			CharacterItemFilterWrappers.FindByTemplateId(character, itemType, itemTemplateId, findResult, searchInventory: true, searchEquipment: false);
			DomainManager.Item.GetBaseItem(findResult[0].Item1).SetCurrDurability(currDurability, Domain.MainThreadDataContext);
		}
		AddSeniorityOnFindMaterialAdventure(itemKey);
		return itemKey;
	}

	public static ItemKey AddItemToRole(GameData.Domains.Character.Character character, ItemKey itemKey, int amount, short currDurability = -1)
	{
		if (character == null)
		{
			throw new Exception("null character to add item");
		}
		AddInventoryItem(character, itemKey, amount);
		if (currDurability >= 0)
		{
			List<(ItemKey, int)> findResult = new List<(ItemKey, int)>();
			CharacterItemFilterWrappers.FindByTemplateId(character, itemKey.ItemType, itemKey.TemplateId, findResult, searchInventory: true, searchEquipment: false);
			DomainManager.Item.GetBaseItem(findResult[0].Item1).SetCurrDurability(currDurability, Domain.MainThreadDataContext);
		}
		AddSeniorityOnFindMaterialAdventure(itemKey);
		return itemKey;
	}

