	public static void FilterAllItemForCharacterWithParam(int charId, string itemNameKey, EventArgBox argBox, sbyte maxGrade = -1, bool includeEquipment = false)
	{
		if (!DomainManager.Character.TryGetElement_Objects(charId, out var _))
		{
			throw new Exception($"can not get character,Id = {charId}");
		}
		if (!argBox.Get("SelectItemInfo", out EventSelectItemData selectItemData))
		{
			selectItemData = new EventSelectItemData();
			selectItemData.CanSelectItemList = new List<ITradeableContent>();
			selectItemData.FilterList = new List<SelectItemFilter>();
			argBox.Set("SelectItemInfo", selectItemData);
		}
		List<ItemDisplayData> inventoryItems = DomainManager.Character.GetAllInventoryItems(charId);
		foreach (ItemDisplayData itemDisplayData in inventoryItems)
		{
			Add(itemDisplayData);
		}
		if (includeEquipment)
		{
			List<ItemDisplayData> equipmentItems = DomainManager.Character.GetAllEquipmentItems(charId);
			foreach (ItemDisplayData itemDisplayData2 in equipmentItems)
			{
				Add(itemDisplayData2);
			}
		}
		SelectItemFilter filter = new SelectItemFilter
		{
			Key = itemNameKey,
			DisplayDataFilterId = 0,
			FilterTemplateId = -1
		};
		selectItemData.FilterList.Add(filter);
		void Add(ItemDisplayData itemDisplayData3)
		{
			ItemKey itemKey = itemDisplayData3.Key;
			if (itemKey.IsValid() && ItemTemplateHelper.IsTransferable(itemKey.ItemType, itemKey.TemplateId))
			{
				sbyte grade = ItemTemplateHelper.GetGrade(itemKey.ItemType, itemKey.TemplateId);
				if (maxGrade <= -1 || grade <= maxGrade)
				{
					selectItemData.CanSelectItemList.Add(itemDisplayData3);
				}
			}
		}
	}

	public static void FilterItemForCharacterByType(int charId, string itemSaveKey, EventArgBox argBox, sbyte itemType = -1, short itemSubType = -1, bool includeTransferable = false, List<Predicate<ItemKey>> predicates = null, sbyte itemOperationType = -1)
	{
		if (!DomainManager.Character.TryGetElement_Objects(charId, out var _))
		{
			throw new Exception($"can not get character,Id = {charId}");
		}
		if (!argBox.Get("SelectItemInfo", out EventSelectItemData selectItemData))
		{
			selectItemData = new EventSelectItemData();
			argBox.Set("SelectItemInfo", selectItemData);
		}
		SelectItemFilter filter = new SelectItemFilter
		{
			Key = itemSaveKey,
			DisplayDataFilterId = 0,
			FilterTemplateId = -1
		};
		List<ItemDisplayData> inventoryItems = DomainManager.Character.GetAllInventoryItems(charId);
		foreach (ItemDisplayData itemDisplayData in inventoryItems)
		{
			ItemKey itemKey = itemDisplayData.Key;
			if ((includeTransferable || ItemTemplateHelper.IsTransferable(itemKey.ItemType, itemKey.TemplateId)) && (itemKey.ItemType == itemType || itemType == -1))
			{
				short subType = ItemTemplateHelper.GetItemSubType(itemKey.ItemType, itemKey.TemplateId);
				if ((subType == itemSubType || itemSubType == -1) && ((!(predicates?.Any((Predicate<ItemKey> predicate) => !predicate(itemKey)))) ?? true))
				{
					selectItemData.CanSelectItemList.Add(itemDisplayData);
				}
			}
		}
		selectItemData.FilterList.Add(filter);
		if (itemOperationType > -1)
		{
			selectItemData.ItemOperationType = itemOperationType;
		}
	}

