	public static bool GetSimulateCricketBattleResult(int leftCharId, int rightCharId)
	{
		if (!DomainManager.Character.IsCharacterAlive(leftCharId))
		{
			throw new Exception($"GetSimulateCricketBattleResult: unable to get character of id {leftCharId}");
		}
		if (!DomainManager.Character.IsCharacterAlive(rightCharId))
		{
			throw new Exception($"GetSimulateCricketBattleResult: unable to get character of id {rightCharId}");
		}
		List<ItemDisplayData> leftCharacterCricketsDisplayDataList = DomainManager.Item.GetNpcCricketDisplayDataListForCricketBattle(Domain.MainThreadDataContext, leftCharId, Domain.GetTempCreateItemList(), -1);
		List<ItemDisplayData> rightCharacterCricketsDisplayDataList = DomainManager.Item.GetNpcCricketDisplayDataListForCricketBattle(Domain.MainThreadDataContext, rightCharId, Domain.GetTempCreateItemList(), -1);
		Domain.SetItemListOfLeft(leftCharacterCricketsDisplayDataList.ToArray(), Domain.MainThreadDataContext);
		Domain.SetItemListOfRight(rightCharacterCricketsDisplayDataList.ToArray(), Domain.MainThreadDataContext);
		Domain.SetShowItemWithCricketBattleGuess(value: true, Domain.MainThreadDataContext);
		CollectionUtils.Shuffle(Domain.MainThreadDataContext.Random, leftCharacterCricketsDisplayDataList);
		CollectionUtils.Shuffle(Domain.MainThreadDataContext.Random, rightCharacterCricketsDisplayDataList);
		int leftWinCount = 0;
		for (int i = 0; i < 3; i++)
		{
			CricketBattleSimulator.SetBattlers(leftCharacterCricketsDisplayDataList[i].Key, rightCharacterCricketsDisplayDataList[i].Key, Domain.MainThreadDataContext);
			if (CricketBattleSimulator.GetBattleResult() == 0)
			{
				leftWinCount++;
			}
			if (leftWinCount >= 2)
			{
				break;
			}
		}
		return leftWinCount >= 2;
	}

