	public static bool CalcRequestLegendaryBookResult(int charId)
	{
		sbyte ownLegendaryBookState = GetCharacterOwnLegendaryBookState(charId);
		if (ownLegendaryBookState == 2)
		{
			return false;
		}
		int score = 0;
		int taiwuCharId = EventArgBox.TaiwuCharacterId;
		if (HasRelationBetweenCharacters(charId, taiwuCharId, 1) || HasRelationBetweenCharacters(charId, taiwuCharId, 64) || HasRelationBetweenCharacters(charId, taiwuCharId, 8))
		{
			score += 4;
		}
		if (HasRelationBetweenCharacters(charId, taiwuCharId, 2) || HasRelationBetweenCharacters(charId, taiwuCharId, 128) || HasRelationBetweenCharacters(charId, taiwuCharId, 16))
		{
			score += 3;
		}
		if (HasRelationBetweenCharacters(charId, taiwuCharId, 1024))
		{
			score += 3;
		}
		if (HasRelationBetweenCharacters(charId, taiwuCharId, 512))
		{
			score += 2;
		}
		if (HasRelationBetweenCharacters(charId, taiwuCharId, 4) || HasRelationBetweenCharacters(charId, taiwuCharId, 256) || HasRelationBetweenCharacters(charId, taiwuCharId, 32))
		{
			score += 2;
		}
		if (HasRelationBetweenCharacters(charId, taiwuCharId, 16384))
		{
			score++;
		}
		if (HasRelationBetweenCharacters(charId, taiwuCharId, 8192))
		{
			score++;
		}
		if (HasRelationBetweenCharacters(charId, taiwuCharId, 32768))
		{
			score -= 4;
		}
		short favorability = DomainManager.Character.GetFavorability(charId, taiwuCharId);
		sbyte favorType = FavorabilityType.GetFavorabilityType(favorability);
		score += favorType;
		int rankSelf = DomainManager.Character.GetTopThousandCharacterRanking(taiwuCharId);
		if (rankSelf < 0 || rankSelf > 80)
		{
			return false;
		}
		if (DomainManager.Character.TryGetElement_Objects(charId, out var character))
		{
			int rankChar = DomainManager.Character.GetTopThousandCharacterRanking(charId);
			if (rankSelf > rankChar && rankChar > 0)
			{
				return false;
			}
			sbyte behaviorType = character.GetBehaviorType();
			switch (ownLegendaryBookState)
			{
			case 0:
				return score >= 7 && rankSelf <= GlobalConfig.Instance.RequestLegendaryBookRequireRankWhenOwningBook[behaviorType];
			case 1:
				return score >= 9 && rankSelf <= GlobalConfig.Instance.RequestLegendaryBookRequireRankWhenShocked[behaviorType];
			}
		}
		return false;
	}

	public static int[] CalcExchangeLegendaryBookPrice(int charId)
	{
		if (!DomainManager.Character.TryGetElement_Objects(charId, out var character))
		{
			return new int[3] { 2147483647, 2147483647, 2147483647 };
		}
		int[] priceResult = new int[3]
		{
			GlobalConfig.Instance.ExchangeLegendaryBookBasePriceInCoin,
			0,
			0
		};
		sbyte favorType = GetFavorabilityType(character, DomainManager.Taiwu.GetTaiwu());
		if (favorType == sbyte.MinValue)
		{
			favorType = 0;
		}
		priceResult[0] -= (int)((float)priceResult[0] * ((float)favorType / 9f));
		if (GetCharacterOwnLegendaryBookState(charId) == 1)
		{
			priceResult[0] *= 3;
		}
		priceResult[1] = priceResult[0] / 10;
		priceResult[2] = priceResult[0] / 2;
		return priceResult;
	}

	public static void ProcessExchangeLegendaryBook(int fromCharId, int toCharId, int price, sbyte resourceType, bool isExp, Location location, ItemKey bookKey)
	{
		if (!DomainManager.Character.TryGetElement_Objects(fromCharId, out var fromChar))
		{
			throw new Exception("from character id invalid,exchange legendary book failed!");
		}
		if (!DomainManager.Character.TryGetElement_Objects(toCharId, out var toChar))
		{
			throw new Exception("to character id invalid,exchange legendary book failed!");
		}
		if (isExp && toChar.GetExp() < price)
		{
			throw new Exception("to character exp not enough,exchange legendary book failed!");
		}
		if (!isExp && toChar.GetResource(resourceType) < price)
		{
			throw new Exception($"to character resource {resourceType} not enough,exchange legendary book failed!");
		}
		TransferInventoryItem(fromChar, toChar, bookKey);
		if (isExp)
		{
			ChangeRoleExp(fromChar, price);
			ChangeRoleExp(toChar, -price);
			GetLifeRecordCollection().AddAcceptRequestExchangeLegendaryBookByExp(fromCharId, GetGameDate(), toCharId, location, bookKey.ItemType, bookKey.TemplateId, price);
		}
		else
		{
			ChangeRoleResource(fromChar, resourceType, price, fromCharId == DomainManager.Taiwu.GetTaiwuCharId());
			ChangeRoleResource(toChar, resourceType, -price, toCharId == DomainManager.Taiwu.GetTaiwuCharId());
			GetLifeRecordCollection().AddAcceptRequestExchangeLegendaryBook(fromCharId, GetGameDate(), toCharId, location, bookKey.ItemType, bookKey.TemplateId, resourceType, price);
		}
	}

