	public static string CheckTeachTaiwuLifeSkillLimit(int charId, EventArgBox argBox)
	{
		List<short> taughtList = GetTeachTaiwuLifeSkillList(charId);
		if (taughtList == null || taughtList.Count < 3)
		{
			return null;
		}
		GameData.Domains.Character.Character taiwu = argBox.GetCharacter("RoleTaiwu");
		foreach (short taughtLife in taughtList)
		{
			if (GetLifeSkillReadedPageCount(taiwu.GetId(), taughtLife) >= 3)
			{
				ClearTeachTaiwuLifeSkillList(charId);
				return null;
			}
		}
		argBox.Set("Taught0", taughtList[0]);
		argBox.Set("Taught1", taughtList[1]);
		argBox.Set("Taught2", taughtList[2]);
		return "1d9ddceb-a3dd-43b2-b1e5-6892b1033aca";
	}

	public static string LearnTargetLifeSkillDependSectApprovingRate(sbyte lifeSkillType, EventArgBox argBox)
	{
		GameData.Domains.Character.Character character = argBox.GetCharacter("CharacterId");
		string limitEventGuid = CheckTeachTaiwuLifeSkillLimit(character.GetId(), argBox);
		if (limitEventGuid != null)
		{
			return limitEventGuid;
		}
		GameData.Domains.Character.Character taiwu = argBox.GetCharacter("RoleTaiwu");
		sbyte sectId = character.GetOrganizationInfo().OrgTemplateId;
		List<short> canLearn = GetCharLifeSkillList(character.GetId(), lifeSkillType, 0, 8, 3, requireTaiwuNotLearn: true);
		if (canLearn == null || canLearn.Count == 0)
		{
			return argBox.GetString("LifeSkillNoneTeachEventGuid");
		}
		short lowestLifeSkill = GetMinGradeLifeSkillList(canLearn).Sample();
		sbyte canLearnGrade = (sbyte)Math.Max(0, GetSectApprovingRate(sectId) / 100 - 1);
		sbyte lowestGrade = GetLifeSkillGrade(lowestLifeSkill);
		List<short> taiwuList = GetCharLifeSkillList(taiwu.GetId(), lifeSkillType, 0, 8);
		if (lowestGrade > canLearnGrade)
		{
			argBox.Set("CantTeachLife", lowestLifeSkill);
			return argBox.GetString("LifeSkillBeyondApprovingEventGuid");
		}
		if (GetLifeSkillGrade(lowestLifeSkill) == 0)
		{
			argBox.Set("SkillCanLearn", lowestLifeSkill);
			return argBox.GetString("LifeSkillTeachEventGuid");
		}
		for (sbyte eGrade = 0; eGrade < lowestGrade; eGrade++)
		{
			short eSkillId = GetLifeSkillId(lifeSkillType, eGrade);
			if (!taiwuList.Contains(eSkillId) || GetLifeSkillReadedPageCount(taiwu.GetId(), eSkillId) < 3)
			{
				argBox.Set("SkillBefore", eSkillId);
				return argBox.GetString("LifeSkillTeachBeforeEventGuid");
			}
		}
		argBox.Set("SkillCanLearn", lowestLifeSkill);
		return argBox.GetString("LifeSkillTeachEventGuid");
	}

	public static string LearnTargetLifeSkillDependConsummateLevel(sbyte lifeSkillType, EventArgBox argBox)
	{
		GameData.Domains.Character.Character character = argBox.GetCharacter("CharacterId");
		string limitEventGuid = CheckTeachTaiwuLifeSkillLimit(character.GetId(), argBox);
		if (limitEventGuid != null)
		{
			return limitEventGuid;
		}
		GameData.Domains.Character.Character taiwu = argBox.GetCharacter("RoleTaiwu");
		List<short> canLearn = GetCharLifeSkillList(character.GetId(), lifeSkillType, 0, 8, 3, requireTaiwuNotLearn: true);
		if (canLearn == null || canLearn.Count == 0)
		{
			return "4f1e6679-8a59-4f88-bf46-682e8c155ce7";
		}
		short lowestLifeSkill = GetMinGradeLifeSkillList(canLearn).Sample();
		sbyte lowestGrade = GetLifeSkillGrade(lowestLifeSkill);
		if (CharacterIsInTaiwuGroup(character.GetId()) || lowestGrade <= taiwu.GetConsummateLevel() / 2 + 1)
		{
			argBox.Set("SkillCanLearn", lowestLifeSkill);
			return "2636780e-0cc9-432d-a025-267f218e6c18";
		}
		argBox.Set("CantTeachLife", lowestLifeSkill);
		return "4a987e91-d35d-4bc7-b8a8-212cafa99a6a";
	}

