	public static bool IsCanThreaten(int charA, int charB)
	{
		GameData.Domains.Character.Character characterA = DomainManager.Character.GetElement_Objects(charA);
		GameData.Domains.Character.Character characterB = DomainManager.Character.GetElement_Objects(charB);
		return characterA.GetConsummateLevel() > characterB.GetConsummateLevel();
	}

	public static bool IsThreatenSuccess(int charA, int charB, sbyte concessionCount)
	{
		GameData.Domains.Character.Character characterA = DomainManager.Character.GetElement_Objects(charA);
		GameData.Domains.Character.Character characterB = DomainManager.Character.GetElement_Objects(charB);
		if (characterB.GetBehaviorType() == 0 || characterB.GetBehaviorType() == 4)
		{
			return false;
		}
		int consummateDiff = characterA.GetConsummateLevel() - characterB.GetConsummateLevel();
		if (characterB.GetBehaviorType() == 2)
		{
			int rate = (int)((Math.Pow(1.149999976158142, consummateDiff) - 1.0) * 100.0);
			return CheckProbability(rate);
		}
		if (characterB.GetBehaviorType() == 1)
		{
			int rate2 = (int)((Math.Pow(1.2f + (float)concessionCount * 0.05f, consummateDiff) - 1.0) * 100.0);
			return CheckProbability(rate2);
		}
		if (characterB.GetBehaviorType() == 3)
		{
			int rate3 = (int)((Math.Pow(1.2f - (float)concessionCount * 0.05f, consummateDiff) - 1.0) * 100.0);
			return CheckProbability(rate3);
		}
		throw new Exception($"Error characterB.GetBehaviorType(), charId= : {characterB}");
	}

	public static bool IsLureSuccess(ItemKey itemKey, int charId, sbyte inducementCount)
	{
		GameData.Domains.Character.Character character = DomainManager.Character.GetElement_Objects(charId);
		if (character.GetBehaviorType() == 0 || character.GetBehaviorType() == 4)
		{
			return false;
		}
		int favorabilityChange = GetItemFavorabilityChange(itemKey);
		short itemSubType = ItemTemplateHelper.GetItemSubType(itemKey.ItemType, itemKey.TemplateId);
		short loveSubType = character.GetLovingItemSubType();
		short hateSubType = character.GetHatingItemSubType();
		if (itemSubType == loveSubType)
		{
			favorabilityChange *= 2;
		}
		else if (itemSubType == hateSubType)
		{
			favorabilityChange /= 2;
		}
		if (character.GetBehaviorType() == 2)
		{
			int rate = 50 + (favorabilityChange - 4800) / 108;
			return CheckProbability(rate);
		}
		if (character.GetBehaviorType() == 1)
		{
			int rate2 = 40 + (favorabilityChange - 4800) / 108;
			rate2 = (int)((double)rate2 * Math.Pow(1.1, inducementCount));
			return CheckProbability(rate2);
		}
		if (character.GetBehaviorType() == 3)
		{
			int rate3 = 40 + (favorabilityChange - 4800) / 108;
			return CheckProbability(rate3);
		}
		throw new Exception($"Error charId.GetBehaviorType(), charId= : {charId}");
	}

