	public static string PlayLoongDebuffAnimation(short characterTemplateId, string afterEvent, EventArgBox argBox)
	{
		if (characterTemplateId >= 251 && characterTemplateId <= 255)
		{
			characterTemplateId -= 5;
		}
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		LoongInfo loongInfo = DomainManager.Extra.GetElement_FiveLoongDict(characterTemplateId);
		ushort debuffCount = loongInfo.GetCharacterDebuffCount(taiwu.GetId());
		if (debuffCount <= 0)
		{
			return afterEvent;
		}
		if (!string.IsNullOrEmpty(afterEvent))
		{
			AddEventInListenWithActionName(afterEvent, argBox, "PlayLoongDebuffAnimation");
		}
		GameData.GameDataBridge.GameDataBridge.AddDisplayEvent(DisplayEventType.PlayLoongDebuffAnimation, characterTemplateId);
		LoongDebuffEffect(characterTemplateId);
		return string.Empty;
	}

	public static void LoongDebuffEffect(short loongCharacterTemplateId)
	{
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		LoongInfo loongInfo = DomainManager.Extra.GetElement_FiveLoongDict(loongCharacterTemplateId);
		ushort debuffCount = loongInfo.GetCharacterDebuffCount(taiwu.GetId());
		if (debuffCount <= 0)
		{
			return;
		}
		DataContext context = Domain.MainThreadDataContext;
		int totalHealthReduceLevel = 0;
		sbyte injuryChange = (sbyte)GetRandom(2, 5);
		int totalHealthReduce = 0;
		switch (loongCharacterTemplateId)
		{
		case 246:
		{
			for (int l = 0; l < debuffCount; l++)
			{
				Injuries injuries2 = taiwu.GetInjuries();
				sbyte bodyType2 = injuries2.GetLightestPart(isInner: true);
				int beyondCount2 = injuries2.Get(bodyType2).inner + injuryChange - 6;
				if (beyondCount2 > 0)
				{
					totalHealthReduceLevel += beyondCount2;
				}
				taiwu.ChangeInjury(context, bodyType2, isInnerInjury: true, injuryChange);
			}
			if (totalHealthReduceLevel > 0)
			{
				totalHealthReduce = Math.Clamp(totalHealthReduceLevel * 6, 0, 36);
				taiwu.ChangeHealth(context, -totalHealthReduce);
			}
			break;
		}
		case 247:
		{
			int poisonAddValue = GetRandom(500, 1000);
			for (int j = 0; j < debuffCount; j++)
			{
				for (int k = 0; k < 3; k++)
				{
					PoisonInts poisoned = taiwu.GetPoisoned();
					sbyte poisonType = poisoned.GetLightestType();
					int beforeMark = taiwu.GetPoisonMarkCount();
					taiwu.ChangePoisoned(context, poisonType, 1, poisonAddValue);
					int afterMark = taiwu.GetPoisonMarkCount();
					if (afterMark - beforeMark > 0)
					{
						totalHealthReduceLevel += afterMark - beforeMark;
					}
				}
			}
			totalHealthReduce = Math.Clamp(totalHealthReduceLevel * 2, 0, 36);
			taiwu.ChangeHealth(context, -totalHealthReduce);
			break;
		}
		case 248:
		{
			int disorderChange = GetRandom(400, 800);
			int totalDisorderChange = disorderChange * debuffCount;
			ChangeRoleDisorderOfQi(taiwu, (short)totalDisorderChange);
			totalHealthReduce = Math.Clamp(totalDisorderChange / 1000 * 3, 0, 24);
			taiwu.ChangeHealth(context, -totalHealthReduce);
			break;
		}
		case 249:
		{
			for (int i = 0; i < debuffCount; i++)
			{
				Injuries injuries = taiwu.GetInjuries();
				sbyte bodyType = injuries.GetLightestPart(isInner: false);
				int beyondCount = injuries.Get(bodyType).outer + injuryChange - 6;
				if (beyondCount > 0)
				{
					totalHealthReduceLevel += beyondCount;
				}
				taiwu.ChangeInjury(context, bodyType, isInnerInjury: false, injuryChange);
			}
			if (totalHealthReduceLevel > 0)
			{
				totalHealthReduce = Math.Clamp(totalHealthReduceLevel * 6, 0, 36);
				taiwu.ChangeHealth(context, -totalHealthReduce);
			}
			break;
		}
		case 250:
			totalHealthReduce = debuffCount * 12;
			taiwu.ChangeHealth(context, -totalHealthReduce);
			break;
		}
	}

