	public static string HandleJiaoCombatResult(EventArgBox argBox)
	{
		short characterTemplateId = 0;
		argBox.Get("LoongCharacterTemplateId", ref characterTemplateId);
		int jiaoId = 0;
		argBox.Get("JiaoId", ref jiaoId);
		GameData.Domains.Character.Character taiwu = argBox.GetCharacter("RoleTaiwu");
		Location taiwuLocation = taiwu.GetLocation();
		int animalId = -1;
		argBox.Get(EventTriggerParameter.DefValue.AnimalId, ref animalId);
		GameData.Domains.Character.Animal animal = TryGetAnimal(animalId);
		ItemKey itemKey = animal.ItemKey;
		bool isMaterial = itemKey.ItemType == 5;
		GameData.Domains.Character.Character jiao = argBox.GetCharacter("Jiao");
		RemoveNonIntelligentCharacter(jiao);
		string nextString = string.Empty;
		if (argBox.Get("ItemKeySeizeCarrierInCombat", out ItemKey seizeItem))
		{
			RemoveFleeCarrierLocation(itemKey);
			RemoveAnimal(animal);
			ApplyAnimalTamingResult(taiwu, animal, isWin: true, taiwu.GetLocation(), seizeItem);
			if (!isMaterial)
			{
				AddInventoryItem(taiwu, itemKey);
				argBox.Set("EscapeCarriers", GetJiaoName(jiaoId));
				nextString = "33fb78b2-c124-4919-96d6-6b98d4ce3712";
			}
			else
			{
				(bool, short) tuple = KidnapMiscJiao(jiaoId);
				nextString = ((!tuple.Item1) ? "2c136803-4be2-4cec-9374-63bee19ffb95" : "617c2a29-381b-4292-8c24-4e7910c2c953");
				JiaoPropertyItem config = Config.JiaoProperty.Instance[tuple.Item2];
				argBox.Set("JiaoPropertyDesc", tuple.Item1 ? config.EventDescUp : config.EventDescDown);
			}
			ShowGetItemPageForItems(new List<(ItemKey, int)> { (itemKey, 1) }, nextString, argBox);
			return string.Empty;
		}
		int combatResult = 0;
		if (argBox.Get("CombatResult", ref combatResult))
		{
			if (combatResult == 0 || combatResult == 5)
			{
				if (!isMaterial)
				{
					argBox.Set("EscapeCarriers", GetJiaoName(jiaoId));
					ShowGetItemPageForItems(new List<(ItemKey, int)> { (itemKey, 1) }, "33fb78b2-c124-4919-96d6-6b98d4ce3712", argBox);
					RemoveFleeCarrierLocation(itemKey);
					RemoveAnimal(animal);
					AddInventoryItem(taiwu, itemKey);
					return string.Empty;
				}
				return "5da7e3bd-788f-4564-a0e6-8c7bb41d432a";
			}
			return combatResult switch
			{
				3 => "85fac506-be5c-40ec-833b-ee2dd6835d85", 
				2 => "9205d907-63b3-4e79-bf88-b239f47cb2c6", 
				1 => "cfbe4c8c-829e-4eeb-8051-4f199c971f5a", 
				_ => "9205d907-63b3-4e79-bf88-b239f47cb2c6", 
			};
		}
		return string.Empty;
	}

	public static void ChildOfLoongBaxiaFindItemAccept(EventArgBox argBox, string nextString)
	{
		int childOfLoongId = 0;
		argBox.Get("MonthlyEvent_arg1", ref childOfLoongId);
		GameData.Domains.Character.Character taiwuChar = DomainManager.Taiwu.GetTaiwu();
		int taiwuCharId = DomainManager.Taiwu.GetTaiwuCharId();
		int currDate = DomainManager.World.GetCurrDate();
		Location location = taiwuChar.GetLocation();
		LifeRecordCollection lifeRecordCollection = DomainManager.LifeRecord.GetLifeRecordCollection();
		lifeRecordCollection.AddDLCLoongRidingEffectBaxia(taiwuCharId, currDate, location, childOfLoongId);
		DataContext context = Domain.MainThreadDataContext;
		List<MapBlockData> neighborBlocks = context.AdvanceMonthRelatedData.Blocks.Occupy();
		DomainManager.Map.GetNeighborBlocks(location.AreaId, location.BlockId, neighborBlocks, 3);
		for (int i = neighborBlocks.Count - 1; i >= 0; i--)
		{
			MapBlockData block = neighborBlocks[i];
			if (block.Items == null)
			{
				neighborBlocks.RemoveAt(i);
			}
		}
		int count = context.Random.Next(3) + 1;
		List<(ItemKey, int)> getItems = new List<(ItemKey, int)>();
		for (int j = 0; j < count; j++)
		{
			if (neighborBlocks.Count == 0)
			{
				break;
			}
			int selectedBlockIndex = context.Random.Next(neighborBlocks.Count);
			MapBlockData selectedBlock = neighborBlocks[selectedBlockIndex];
			ItemKeyAndDate itemAndDates = selectedBlock.Items.Keys.GetRandom(context.Random);
			ItemKey itemKey = itemAndDates.ItemKey;
			int amount = selectedBlock.Items[itemAndDates];
			DomainManager.Map.RemoveBlockItem(context, selectedBlock, itemAndDates);
			taiwuChar.AddInventoryItem(context, itemKey, amount);
			getItems.Add((itemKey, amount));
			if (selectedBlock.Items == null)
			{
				neighborBlocks.RemoveAt(selectedBlockIndex);
			}
		}
		context.AdvanceMonthRelatedData.Blocks.Release(ref neighborBlocks);
		ShowGetItemPageForItems(getItems, nextString, argBox);
	}

