	public static Location GetLastSwordTombLocation()
	{
		Span<short> swordTombBlockIds = stackalloc short[9];
		swordTombBlockIds.Fill(-1);
		foreach (AdventureRuntime adventure in DomainManager.Adventure.QueryAdventuresInArea(EventArgBox.TaiwuVillageAreaId))
		{
			sbyte xiangshuAvatarId = XiangshuAvatarIds.GetXiangshuAvatarIdBySwordTomb(adventure.CoreId);
			if (xiangshuAvatarId >= 0)
			{
				swordTombBlockIds[xiangshuAvatarId] = adventure.MapLocation.BlockId;
			}
		}
		sbyte[] xiangshuTaskStatusInOrder = DomainManager.World.GetXiangshuAvatarTasksInOrder();
		for (sbyte i = 8; i >= 0; i--)
		{
			sbyte xiangshuAvatarId2 = xiangshuTaskStatusInOrder[i];
			if (xiangshuAvatarId2 >= 0)
			{
				short blockId = swordTombBlockIds[xiangshuAvatarId2];
				if (blockId >= 0)
				{
					return new Location(EventArgBox.TaiwuVillageAreaId, blockId);
				}
			}
		}
		return Location.Invalid;
	}

	public static void SetNextSwordTombCountDownDate()
	{
		byte invasionSpeedType = DomainManager.World.GetBossInvasionSpeedType();
		short coolDownMonthCount = GlobalConfig.SwordTombAdventureCountDownCoolDown[invasionSpeedType];
		if (DomainManager.World.GetDefeatSwordTombCount() > 5)
		{
			coolDownMonthCount /= 3;
		}
		int date = GetGameDate() + coolDownMonthCount;
		SaveGlobalArg("ConchShip_PresetKey_DateOfNextSwordTombActivate", date);
	}

	public static void SetNextSwordTombAdventureCoolDownByFromAdventure(sbyte xiangshuAvatarId)
	{
		if (!GlobalArgBoxContainsKey<int>("ConchShip_PresetKey_DateOfNextSwordTombActivate"))
		{
			SetNextSwordTombCountDownDate();
			return;
		}
		sbyte[] xiangshuAvatarTasksInOrder = DomainManager.World.GetXiangshuAvatarTasksInOrder();
		IEnumerable<AdventureRuntime> swordTombs = DomainManager.Adventure.QueryAdventuresInArea(EventArgBox.TaiwuVillageAreaId);
		Dictionary<sbyte, IAdventureRuntime> xiangshuAvatarIdToAdventureMap = new Dictionary<sbyte, IAdventureRuntime>();
		foreach (AdventureRuntime swordTomb in swordTombs)
		{
			sbyte avatarId = XiangshuAvatarIds.GetXiangshuAvatarIdBySwordTomb(swordTomb.CoreId);
			if (avatarId >= 0)
			{
				if (swordTomb.RemainMonths > 0)
				{
					return;
				}
				xiangshuAvatarIdToAdventureMap.Add(avatarId, swordTomb);
			}
		}
		foreach (sbyte avatarId2 in xiangshuAvatarTasksInOrder)
		{
			if (xiangshuAvatarIdToAdventureMap.ContainsKey(avatarId2) && avatarId2 == xiangshuAvatarId)
			{
				SetNextSwordTombCountDownDate();
				break;
			}
		}
	}

