	public static Location MoveTaiwuAndRanchenziToDoubleGirl()
	{
		Location curLocation = DomainManager.Taiwu.GetTaiwu().GetLocation();
		List<Location> neighborListOf10 = GetMapBlocksNearLocation(curLocation, 10);
		List<Location> neighborListOf11 = GetMapBlocksNearLocation(curLocation, 9);
		neighborListOf10.RemoveAll((Location e) => neighborListOf11.Contains(e));
		neighborListOf10.RemoveAll((Location e) => CheckBlockMatchTemplate(e, -1, EMapBlockType.City));
		neighborListOf10.RemoveAll((Location e) => CheckBlockMatchTemplate(e, -1, EMapBlockType.Town));
		neighborListOf10.RemoveAll((Location e) => CheckBlockMatchTemplate(e, -1, EMapBlockType.Station));
		neighborListOf10.RemoveAll((Location e) => CheckBlockMatchTemplate(e, -1, EMapBlockType.Invalid, EMapBlockSubType.Ruin));
		neighborListOf10.RemoveAll((Location e) => CheckBlockMatchTemplate(e, -1, EMapBlockType.Invalid, EMapBlockSubType.DarkPool));
		neighborListOf10.RemoveAll((Location e) => CheckBlockMatchTemplate(e, -1, EMapBlockType.Invalid, EMapBlockSubType.Block));
		neighborListOf10.RemoveAll((Location e) => CheckBlockMatchTemplate(e, -1, EMapBlockType.Invalid, EMapBlockSubType.SwordTomb));
		neighborListOf10.RemoveAll((Location e) => !DomainManager.Map.GetBlock(e).IsPassable());
		Location targetLocation = neighborListOf10.Sample();
		DomainManager.Map.SetBlockAndViewRangeVisible(Domain.MainThreadDataContext, targetLocation.AreaId, targetLocation.BlockId);
		GameData.Domains.Character.Character charRanchenzi = GetOrCreateFixedCharacterByTemplateId(916);
		MoveFixedCharacter(charRanchenzi, targetLocation);
		GameData.GameDataBridge.GameDataBridge.AddDisplayEvent(DisplayEventType.MainStoryMoveTaiwuAndRanChenZi, curLocation, targetLocation);
		return targetLocation;
	}

	public static void SetHideAllTeammates(bool hideState)
	{
		int[] savedCombatCharIds = Domain.GetAllCombatGroupChars();
		HashSet<int> groupCharIds = DomainManager.Taiwu.GetGroupCharIds().GetCollection();
		List<int> specialGroup = DomainManager.Taiwu.GetTaiwuSpecialGroup();
		for (int i = 0; i < 3; i++)
		{
			if (hideState)
			{
				int charId = DomainManager.Taiwu.GetElement_CombatGroupCharIds(i);
				savedCombatCharIds[i] = charId;
				DomainManager.Taiwu.SetElement_CombatGroupCharIds(i, -1, Domain.MainThreadDataContext);
				continue;
			}
			int charId2 = savedCombatCharIds[i];
			if (DomainManager.Taiwu.GetTaiwuCharId() == charId2 || !DomainManager.Character.IsCharacterAlive(charId2) || (!groupCharIds.Contains(charId2) && !specialGroup.Contains(charId2)))
			{
				charId2 = -1;
			}
			DomainManager.Taiwu.SetElement_CombatGroupCharIds(i, charId2, Domain.MainThreadDataContext);
		}
		Domain.SetAllCombatGroupChars(savedCombatCharIds, Domain.MainThreadDataContext);
		Domain.SetHideAllTeammates(hideState, Domain.MainThreadDataContext);
	}

