	public static void MakeWorldChaos()
	{
		List<MapBlockData> wildBlocks = new List<MapBlockData>();
		List<MapBlockData> normalBlocks = new List<MapBlockData>();
		List<MapBlockData> developedBlocks = new List<MapBlockData>();
		List<short> ruinBlockTemplateIdList = new List<short> { 118, 119, 120, 121, 122, 123 };
		for (short i = 0; i < 45; i++)
		{
			if (i != EventArgBox.TaiwuVillageAreaId)
			{
				wildBlocks.Clear();
				normalBlocks.Clear();
				developedBlocks.Clear();
				Span<MapBlockData> areaBlockCollection = DomainManager.Map.GetAreaBlocks(i);
				Span<MapBlockData> span = areaBlockCollection;
				for (int j = 0; j < span.Length; j++)
				{
					MapBlockData blockData = span[j];
					MapBlockItem config = blockData.GetConfig();
					if (MapBlockDataMatchers.CanBeRuinedByXiangshu(blockData) && config.Size <= 1)
					{
						if (config.Type == EMapBlockType.Developed)
						{
							developedBlocks.Add(blockData);
						}
						if (config.Type == EMapBlockType.Normal)
						{
							normalBlocks.Add(blockData);
						}
						if ((config.Type == EMapBlockType.Wild || config.Type == EMapBlockType.Bad) && config.SubType != EMapBlockSubType.SwordTomb && config.SubType != EMapBlockSubType.Ruin)
						{
							wildBlocks.Add(blockData);
						}
					}
				}
				ChangeBlockToRuin(wildBlocks, (int)((float)wildBlocks.Count * 0.3f));
				ChangeBlockToRuin(normalBlocks, (int)((float)normalBlocks.Count * 0.2f));
				ChangeBlockToRuin(developedBlocks, (int)((float)developedBlocks.Count * 0.1f));
			}
		}
		DomainManager.World.SetWorldFunctionsStatus(Domain.MainThreadDataContext, 29);
		DomainManager.Character.GenerateSkeletons(Domain.MainThreadDataContext);
		void ChangeBlockToRuin(List<MapBlockData> list, int countMax)
		{
			CollectionUtils.Shuffle(Domain.MainThreadDataContext.Random, list);
			for (int k = 0; k < countMax; k++)
			{
				Location location = new Location(list[k].AreaId, list[k].BlockId);
				ChangeLocationBlockType(location, ruinBlockTemplateIdList.Sample());
				MapBlockData block = DomainManager.Map.GetBlock(location);
				block.SetVisible(visible: true, Domain.MainThreadDataContext);
				block.InitResources(Domain.MainThreadDataContext.Random);
				DomainManager.Map.SetBlockData(Domain.MainThreadDataContext, block);
				if (block.GroupBlockList != null)
				{
					foreach (MapBlockData childBlock in block.GroupBlockList)
					{
						ChangeLocationBlockType(childBlock.GetLocation(), ruinBlockTemplateIdList.Sample());
						childBlock.InitResources(Domain.MainThreadDataContext.Random);
						DomainManager.Map.SetBlockData(Domain.MainThreadDataContext, childBlock);
					}
				}
			}
			list.RemoveRange(countMax, list.Count - countMax);
			if (list.Count > 0)
			{
				GenerateXiangshuMinions(list);
			}
		}
	}

	public static void PrepareSectMembersAndTaiwuVillagersForSpiritualWanderPlace()
	{
		DataContext context = Domain.MainThreadDataContext;
		DomainManager.World.ResetWorldFunctionsStatus(context, 4);
		DomainManager.World.ResetWorldFunctionsStatus(context, 3);
		DomainManager.World.ResetWorldFunctionsStatus(context, 10);
		DomainManager.World.ResetWorldFunctionsStatus(context, 7);
		DomainManager.World.ResetWorldFunctionsStatus(context, 24);
		DomainManager.World.ResetWorldFunctionsStatus(context, 25);
		DomainManager.World.ResetWorldFunctionsStatus(context, 30);
		DomainManager.Adventure.RemoveAllInWorld(context);
		DomainManager.Organization.TryRemoveTaiwuGroupBountyAndPunishment(context);
		Location taiwuLocation = DomainManager.Taiwu.GetTaiwu().GetLocation();
		Location taiwuVillageLocation = DomainManager.Taiwu.GetTaiwuVillageLocation();
		byte mapSize = DomainManager.Map.GetAreaSize(taiwuVillageLocation.AreaId);
		ByteCoordinate centerCoord = ByteCoordinate.IndexToCoordinate(taiwuVillageLocation.BlockId, mapSize);
		List<short> validCenters = ObjectPool<List<short>>.Instance.Get();
		List<MapBlockData> neighborBlocks = ObjectPool<List<MapBlockData>>.Instance.Get();
		List<int> memberIds = ObjectPool<List<int>>.Instance.Get();
		validCenters.Clear();
		(int, int)[] taiwuEnsuredSurroundingBlockOffsets = GameData.Domains.Map.SharedConstValue.TaiwuEnsuredSurroundingBlockOffsets;
		for (int i = 0; i < taiwuEnsuredSurroundingBlockOffsets.Length; i++)
		{
			(int, int) tuple = taiwuEnsuredSurroundingBlockOffsets[i];
			int xOffset = tuple.Item1;
			int yOffset = tuple.Item2;
			ByteCoordinate coord = new ByteCoordinate((byte)(centerCoord.X + xOffset), (byte)(centerCoord.Y + yOffset));
			short blockId = ByteCoordinate.CoordinateToIndex(coord, mapSize);
			validCenters.Add(blockId);
		}
		CollectionUtils.Shuffle(context.Random, validCenters);
		CharacterMatcherItem matcher = CharacterMatcher.DefValue.PrepareCharacterForSpiritualWanderPlace;
		foreach (OrganizationItem item in (IEnumerable<OrganizationItem>)Config.Organization.Instance)
		{
			if (!item.IsSect)
			{
				continue;
			}
			Settlement settlement = DomainManager.Organization.GetSettlementByOrgTemplateId(item.TemplateId);
			GameData.Domains.Character.Character leader = settlement.GetLeader();
			if (leader == null)
			{
				OrganizationMemberItem orgMemberConfig = OrganizationDomain.GetOrgMemberConfig(item.TemplateId, 8);
				sbyte gender = ((orgMemberConfig.Gender >= 0) ? orgMemberConfig.Gender : Gender.GetRandom(context.Random));
				leader = CreateIntelligentCharacter(taiwuLocation, gender, -1, -1, settlement.GetId(), 8);
			}
			else
			{
				MoveIntelligentCharacter(leader, taiwuLocation);
			}
			leader.SpecifyBaseNeiliAllocation(context, default(NeiliAllocation));
			int currNeili = leader.GetMaxNeili() * 30 / 100;
			if (leader.GetCurrNeili() > currNeili)
			{
				leader.SpecifyCurrNeili(context, currNeili);
			}
			context.Equipping.SelectEquipments(context, leader, isOutOfTaiwuGroup: true);
			OrgMemberCollection memberCollection = settlement.GetMembers();
			memberIds.Clear();
			memberIds.AddRange(memberCollection.GetMembers(6));
			memberIds.AddRange(memberCollection.GetMembers(7));
			memberIds.AddRange(memberCollection.GetMembers(8));
			memberIds.Remove(leader.GetId());
			short centerBlockId = validCenters[validCenters.Count - 1];
			validCenters.RemoveAt(validCenters.Count - 1);
			DomainManager.Map.GetRealNeighborBlocks(taiwuVillageLocation.AreaId, centerBlockId, neighborBlocks, 1, includeCenter: true);
			foreach (int memberId in memberIds)
			{
				GameData.Domains.Character.Character character = DomainManager.Character.GetElement_Objects(memberId);
				if (matcher.Match(character) && character.GetLeaderId() != leader.GetId())
				{
					if (character.GetLeaderId() >= 0)
					{
						DomainManager.Character.LeaveGroup(context, character);
					}
					short blockId2 = neighborBlocks.GetRandom(context.Random).BlockId;
					Location location = new Location(taiwuVillageLocation.AreaId, blockId2);
					MoveIntelligentCharacter(character, location);
				}
			}
		}
		short centerBlockId2 = validCenters[0];
		validCenters.Clear();
		DomainManager.Map.GetRealNeighborBlocks(taiwuVillageLocation.AreaId, centerBlockId2, neighborBlocks, 1, includeCenter: true);
		short taiwuVillageSettlementId = DomainManager.Taiwu.GetTaiwuVillageSettlementId();
		Settlement taiwuVillageSettlement = DomainManager.Organization.GetSettlement(taiwuVillageSettlementId);
		taiwuVillageSettlement.GetMembers().GetAllMembers(memberIds);
		foreach (int memberId2 in memberIds)
		{
			GameData.Domains.Character.Character character2 = DomainManager.Character.GetElement_Objects(memberId2);
			if (matcher.Match(character2))
			{
				DomainManager.Taiwu.RemoveVillagerWork(context, memberId2);
				DomainManager.Character.LeaveGroup(context, character2);
				short blockId3 = neighborBlocks.GetRandom(context.Random).BlockId;
				Location location2 = new Location(taiwuVillageLocation.AreaId, blockId3);
				MoveIntelligentCharacter(character2, location2);
			}
		}
		Domain.SaveArgToGlobalArgBox("MainStoryLine_SpiritualWanderPlace_TaiwuVillagersCenter", new Location(taiwuVillageLocation.AreaId, centerBlockId2));
	}

	public static void EnsureTaiwuVillagerLocationForSpiritualWanderPlace()
	{
		DataContext context = DomainManager.TaiwuEvent.MainThreadDataContext;
		EventArgBox globalEventArgumentBox = DomainManager.TaiwuEvent.GetGlobalEventArgumentBox();
		if (!globalEventArgumentBox.Get("MainStoryLine_SpiritualWanderPlace_TaiwuVillagersCenter", out Location centerLocation))
		{
			throw new Exception("MainStoryLine_SpiritualWanderPlace_TaiwuVillagersCenter is not saved.");
		}
		byte mapSize = DomainManager.Map.GetAreaSize(centerLocation.AreaId);
		List<MapBlockData> neighborBlocks = ObjectPool<List<MapBlockData>>.Instance.Get();
		List<int> memberIds = ObjectPool<List<int>>.Instance.Get();
		DomainManager.Map.GetRealNeighborBlocks(centerLocation.AreaId, centerLocation.BlockId, neighborBlocks, 1, includeCenter: true);
		short taiwuVillageSettlementId = DomainManager.Taiwu.GetTaiwuVillageSettlementId();
		Settlement taiwuVillageSettlement = DomainManager.Organization.GetSettlement(taiwuVillageSettlementId);
		taiwuVillageSettlement.GetMembers().GetAllMembers(memberIds);
		foreach (int memberId in memberIds)
		{
			if (!DomainManager.Taiwu.IsInGroup(memberId))
			{
				GameData.Domains.Character.Character character = DomainManager.Character.GetElement_Objects(memberId);
				if (character.GetKidnapperId() < 0 && ByteCoordinate.IndexToCoordinate(character.GetLocation().BlockId, mapSize).GetManhattanDistance(ByteCoordinate.IndexToCoordinate(centerLocation.BlockId, mapSize)) > 1)
				{
					short blockId = neighborBlocks.GetRandom(context.Random).BlockId;
					Location location = new Location(centerLocation.AreaId, blockId);
					MoveIntelligentCharacter(character, location);
				}
			}
		}
	}

	public static void GenerateXiangshuMinions(List<MapBlockData> validBlocks)
	{
		DataContext context = Domain.MainThreadDataContext;
		int factor = DomainManager.World.GetHereticsAmountFactor();
		for (int baseLevel = 0; baseLevel < 3; baseLevel++)
		{
			short enemyId = (short)(366 + baseLevel + 6 - 1);
			int enemyCount = GlobalConfig.Instance.BrokenAreaEnemyCountLevelDist[baseLevel] * factor / 100;
			DomainManager.Map.CreateRandomEnemiesOnValidBlocks(context, 0, Location.Invalid, enemyId, enemyCount, validBlocks);
		}
	}

