	public static void ApplyVowRewards(string afterEvent, EventArgBox argBox, bool selectIgnore = false)
	{
		sbyte orgId = 1;
		short settlementId = 0;
		if (argBox.Contains<short>("MonthlyEvent_arg1"))
		{
			settlementId = argBox.GetShort("MonthlyEvent_arg1");
			orgId = DomainManager.Organization.GetSettlement(settlementId).GetOrgTemplateId();
		}
		else
		{
			orgId = argBox.GetSbyte("OrgTemplateId");
			settlementId = DomainManager.Organization.GetSettlementIdByOrgTemplateId(orgId);
		}
		argBox.Set("OrgTemplateId", orgId);
		OrganizationItem orgConfig = Config.Organization.Instance[orgId];
		if (orgConfig == null)
		{
			return;
		}
		Location villageLocation = DomainManager.Taiwu.GetTaiwuVillageLocation();
		BuildingBlockData taiwuBuildingBlockData = DomainManager.Taiwu.GetTaiwuBuildingBlockData(44);
		BuildingBlockKey blockKey = new BuildingBlockKey(villageLocation.AreaId, villageLocation.BlockId, taiwuBuildingBlockData.BlockIndex);
		sbyte level = DomainManager.Building.BuildingBlockLevel(blockKey);
		if (argBox.Contains<short>("MonthlyEvent_arg3"))
		{
			level = (sbyte)argBox.GetShort("MonthlyEvent_arg3");
		}
		DataContext context = Domain.MainThreadDataContext;
		GameData.Domains.Character.Character taiwuChar = DomainManager.Taiwu.GetTaiwu();
		List<(ItemKey, int)> showItems = new List<(ItemKey, int)>();
		(int, int) bonuses = GetVowRewardBonuses(orgConfig.TemplateId, level);
		List<PresetInventoryItem> vowFixedRewardItems = orgConfig.VowFixedRewardItems;
		if (vowFixedRewardItems != null && vowFixedRewardItems.Count > 0)
		{
			foreach (PresetInventoryItem reward in orgConfig.VowFixedRewardItems)
			{
				ApplyRewardsItemToTaiwu(reward, showItems, bonuses.Item1, bonuses.Item2);
			}
		}
		vowFixedRewardItems = orgConfig.VowRandomRewardItems;
		if (vowFixedRewardItems != null && vowFixedRewardItems.Count > 0)
		{
			foreach (PresetInventoryItem reward2 in RandomUtils.GetRandomUnrepeated(context.Random, orgConfig.VowRandomRewardItemsCount + bonuses.Item2, orgConfig.VowRandomRewardItems))
			{
				ApplyRewardsItemToTaiwu(reward2, showItems, bonuses.Item1, 0);
			}
		}
		List<(ItemKey, int)> showResources = new List<(ItemKey, int)>();
		for (sbyte i = 0; i < 7; i++)
		{
			int price = 5000 * (level + 1);
			int value = CricketSpecialConstants.PriceToResource(i, price);
			taiwuChar.ChangeResource(context, i, value);
			int resourceTemplateId = i;
			showResources.Add((new ItemKey(12, 0, (short)resourceTemplateId, -1), value));
		}
		Location taiwuLocation = taiwuChar.GetLocation();
		if (!taiwuLocation.IsValid())
		{
			taiwuLocation = taiwuChar.GetValidLocation();
		}
		short characterTemplateId = GetVowCharacterTemplateId(argBox);
		GameData.Domains.Character.Character fixedCharacter = GetOrCreateFixedCharacterByTemplateId(characterTemplateId);
		MoveFixedCharacter(fixedCharacter, taiwuLocation);
		ConvertFixedCharacter(fixedCharacter, taiwuLocation, recreateAttributesAndQualifications: true);
		argBox.Set(EventTriggerParameter.DefValue.CharacterId.ArgBoxKey, fixedCharacter.GetId());
		if (!selectIgnore)
		{
			ProcessAndRemoveBooks("VowCombatSkillBookKeyList", "SelectedCombatSkillBookKey");
			ProcessAndRemoveBooks("VowLifeSkillBookKeyList", "SelectedLifeSkillBookKey");
		}
		if (!selectIgnore)
		{
			ShowGetItemPageForItems(showItems, showResources, afterEvent, argBox);
		}
		else
		{
			JoinOrganization(fixedCharacter, taiwuChar.GetOrganizationInfo().SettlementId, 0);
		}
		void ProcessAndRemoveBooks(string itemListDataKey, string selectedItemKey)
		{
			EventSelectItemData itemListData = argBox.Get<EventSelectItemData>(itemListDataKey);
			ItemKey selectedKey = argBox.Get<ItemKey>(selectedItemKey);
			ITradeableContent selectedItem = itemListData?.CanSelectItemList.FirstOrDefault((ITradeableContent c) => c.Key.Equals(selectedKey));
			if (selectedItem != null)
			{
				taiwuChar.AddInventoryItem(context, selectedItem.Key, selectedItem.Amount);
				showItems.Add((selectedItem.Key, selectedItem.Amount));
			}
			if (itemListData == null)
			{
				return;
			}
			foreach (ITradeableContent item in itemListData.CanSelectItemList)
			{
				if (!item.Key.Equals(selectedKey))
				{
					DomainManager.Item.RemoveItem(context, item.Key);
				}
			}
		}
	}

	public static void GenerateSkillBooksForVow(EventArgBox argBox)
	{
		DataContext context = Domain.MainThreadDataContext;
		sbyte orgId = argBox.GetSbyte("OrgTemplateId");
		GenerateCombatSkillBooksForVow(context, argBox, orgId);
		GenerateLifeSkillBooksForVow(context, argBox, orgId);
	}

	private static void GenerateCombatSkillBooksForVow(DataContext context, EventArgBox argBox, sbyte orgId)
	{
		if (argBox.Contains<EventSelectItemData>("VowCombatSkillBookKeyList"))
		{
			AdaptableLog.Info("skip GenerateCombatSkillBooksForVow");
			return;
		}
		IRandomSource random = context.Random;
		EventSelectItemData combatSkillBookItemListData = new EventSelectItemData();
		EventSelectItemData eventSelectItemData = combatSkillBookItemListData;
		if (eventSelectItemData.CanSelectItemList == null)
		{
			eventSelectItemData.CanSelectItemList = new List<ITradeableContent>();
		}
		SelectItemFilter filter = new SelectItemFilter
		{
			Key = "SelectedCombatSkillBookKey",
			DisplayDataFilterId = 0,
			FilterTemplateId = -1
		};
		combatSkillBookItemListData.FilterList.Add(filter);
		sbyte[] vowCombatSkillBookTypes = GetVowCombatSkillBookTypes(orgId);
		sbyte[] array = vowCombatSkillBookTypes;
		foreach (sbyte skillType in array)
		{
			List<short> availableSkills = (from c in Config.CombatSkill.Instance
				where c.SectId == orgId && c.Grade == 3 && c.Type == skillType
				select c.TemplateId).ToList();
			if (availableSkills.Count > 0)
			{
				short selectedSkillId = availableSkills[random.Next(0, availableSkills.Count)];
				short bookTemplateId = Config.CombatSkill.Instance[selectedSkillId].BookId;
				if (bookTemplateId > 0)
				{
					ItemKey normalBook = DomainManager.Item.CreateSkillBook(context, bookTemplateId, 5, 0, -1, 100);
					ItemDisplayData normalBookDisplayData = DomainManager.Item.GetItemDisplayData(normalBook);
					normalBookDisplayData.Amount = 1;
					combatSkillBookItemListData.CanSelectItemList.Add(normalBookDisplayData);
					ItemKey reverseBook = DomainManager.Item.CreateSkillBook(context, bookTemplateId, 5, 0, -1, 0);
					ItemDisplayData reverseBookDisplayData = DomainManager.Item.GetItemDisplayData(reverseBook);
					reverseBookDisplayData.Amount = 1;
					combatSkillBookItemListData.CanSelectItemList.Add(reverseBookDisplayData);
				}
			}
		}
		argBox.Set("VowCombatSkillBookKeyList", combatSkillBookItemListData);
	}

	private static void GenerateLifeSkillBooksForVow(DataContext context, EventArgBox argBox, sbyte orgId)
	{
		if (argBox.Contains<EventSelectItemData>("VowLifeSkillBookKeyList"))
		{
			AdaptableLog.Info("skip GenerateLifeSkillBooksForVow");
			return;
		}
		IRandomSource random = context.Random;
		EventSelectItemData lifeSkillBookItemKeyListData = new EventSelectItemData();
		EventSelectItemData eventSelectItemData = lifeSkillBookItemKeyListData;
		if (eventSelectItemData.CanSelectItemList == null)
		{
			eventSelectItemData.CanSelectItemList = new List<ITradeableContent>();
		}
		SelectItemFilter filter = new SelectItemFilter
		{
			Key = "SelectedLifeSkillBookKey",
			DisplayDataFilterId = 0,
			FilterTemplateId = -1
		};
		lifeSkillBookItemKeyListData.FilterList.Add(filter);
		sbyte[] lifeSkillTypesFromFunc = GetVowLifeSkillBookTypes(orgId);
		sbyte[] array = lifeSkillTypesFromFunc;
		foreach (sbyte skillType in array)
		{
			List<short> availableSkills = (from c in LifeSkill.Instance
				where c.Grade == 3 && c.Type == skillType
				select c.TemplateId).ToList();
			if (availableSkills.Count > 0)
			{
				short selectedSkillId = availableSkills[random.Next(0, availableSkills.Count)];
				short bookTemplateId = LifeSkill.Instance[selectedSkillId].SkillBookId;
				if (bookTemplateId > 0)
				{
