	public static void ApplyRewardsItemToTaiwu(PresetInventoryItem item, List<(ItemKey, int)> showItems, int gradeBonus, int amountBonus)
	{
		GameData.Domains.Character.Character taiwuChar = DomainManager.Taiwu.GetTaiwu();
		short groupId = ItemTemplateHelper.GetGroupId(item.Type, item.TemplateId);
		if (groupId < 0)
		{
			ItemKey itemKey = AddItemToRole(taiwuChar, item.Type, item.TemplateId, item.Amount + amountBonus, -1);
			showItems.Add((itemKey, item.Amount));
			return;
		}
		sbyte initialGrade = ItemTemplateHelper.GetGrade(item.Type, item.TemplateId);
		sbyte expectedGrade = (sbyte)Math.Clamp(initialGrade + gradeBonus, 0, 8);
		short templateId = ItemTemplateHelper.GetTemplateIdInGroup(item.Type, groupId, expectedGrade);
		ItemKey itemKey2 = AddItemToRole(taiwuChar, item.Type, templateId, item.Amount + amountBonus, -1);
		showItems.Add((itemKey2, item.Amount));
	}

