	public static List<MapTemplateEnemyInfo> GetMapRandomEnemyGroupForChar(MapBlockData blockData, int charId, bool avoidRandomEnemy)
	{
		if (!DomainManager.Character.TryGetElement_Objects(charId, out var character))
		{
			throw new Exception("GetMapRandomEnemyGroupForCharacter need a alive character id!");
		}
		if (blockData.TemplateEnemyList == null || blockData.TemplateEnemyList.Count <= 0)
		{
			return null;
		}
		List<MapTemplateEnemyInfo> xiangshuMinionList = new List<MapTemplateEnemyInfo>();
		List<MapTemplateEnemyInfo> righteousList = new List<MapTemplateEnemyInfo>();
		List<MapTemplateEnemyInfo> randomEnemyList = new List<MapTemplateEnemyInfo>();
		int i = 0;
		for (int max = blockData.TemplateEnemyList.Count; i < max; i++)
		{
			MapTemplateEnemyInfo info = blockData.TemplateEnemyList[i];
			if (GameData.Domains.Character.Character.IsXiangshuMinion(info.TemplateId))
			{
				xiangshuMinionList.Add(info);
			}
			else if (GameData.Domains.Character.Character.IsRighteous(info.TemplateId))
			{
				righteousList.Add(info);
			}
			else
			{
				randomEnemyList.Add(info);
			}
		}
		if (xiangshuMinionList.Count > 0)
		{
			if (xiangshuMinionList.Count > 1)
			{
				xiangshuMinionList.Sort(MapTemplateEnemyInfoSortFunc);
			}
			if (xiangshuMinionList.Count > 4)
			{
				xiangshuMinionList.RemoveRange(4, xiangshuMinionList.Count - 4);
			}
			return xiangshuMinionList;
		}
		if (avoidRandomEnemy && DomainManager.Extra.IsProfessionalSkillUnlockedAndEquipped(34))
		{
			return null;
		}
		if (righteousList.Count > 0)
		{
			sbyte fameType = character.GetFameType();
			if (FameType.AttackByRighteous(fameType))
			{
				if (righteousList.Count > 1)
				{
					righteousList.Sort(MapTemplateEnemyInfoSortFunc);
				}
				if (righteousList.Count > 4)
				{
					righteousList.RemoveRange(4, righteousList.Count - 4);
				}
				return righteousList;
			}
		}
		if (randomEnemyList.Count > 0)
		{
			if (randomEnemyList.Count > 1)
			{
				randomEnemyList.Sort(MapTemplateEnemyInfoSortFunc);
			}
			if (randomEnemyList.Count > 4)
			{
				randomEnemyList.RemoveRange(4, randomEnemyList.Count - 4);
			}
			return randomEnemyList;
		}
		return null;
		static int MapTemplateEnemyInfoSortFunc(MapTemplateEnemyInfo a, MapTemplateEnemyInfo b)
		{
			return Config.Character.Instance[b.TemplateId].OrganizationInfo.Grade.CompareTo(Config.Character.Instance[a.TemplateId].OrganizationInfo.Grade);
		}
	}

	public static (List<MapTemplateEnemyInfo> xiangshuMinionList, List<MapTemplateEnemyInfo> righteousList, List<MapTemplateEnemyInfo> randomEnemyList) GetMapRandomEnemyGroupFromBlock(MapBlockData blockData)
	{
		List<MapTemplateEnemyInfo> xiangshuMinionList = new List<MapTemplateEnemyInfo>();
		List<MapTemplateEnemyInfo> righteousList = new List<MapTemplateEnemyInfo>();
		List<MapTemplateEnemyInfo> randomEnemyList = new List<MapTemplateEnemyInfo>();
		if (blockData.TemplateEnemyList != null)
		{
			int i = 0;
			for (int max = blockData.TemplateEnemyList.Count; i < max; i++)
			{
				MapTemplateEnemyInfo info = blockData.TemplateEnemyList[i];
				if (GameData.Domains.Character.Character.IsXiangshuMinion(info.TemplateId))
				{
					xiangshuMinionList.Add(info);
				}
				else if (GameData.Domains.Character.Character.IsRighteous(info.TemplateId))
				{
					righteousList.Add(info);
				}
				else
				{
					randomEnemyList.Add(info);
				}
			}
		}
		if (xiangshuMinionList.Count > 0)
		{
			if (xiangshuMinionList.Count > 1)
			{
				xiangshuMinionList.Sort(MapTemplateEnemyInfoSortFunc);
			}
			if (xiangshuMinionList.Count > 4)
			{
				xiangshuMinionList.RemoveRange(4, xiangshuMinionList.Count - 4);
			}
		}
		if (righteousList.Count > 0)
		{
			if (righteousList.Count > 1)
			{
				righteousList.Sort(MapTemplateEnemyInfoSortFunc);
			}
			if (righteousList.Count > 4)
			{
				righteousList.RemoveRange(4, righteousList.Count - 4);
			}
		}
		if (randomEnemyList.Count > 0)
		{
			if (randomEnemyList.Count > 1)
			{
				randomEnemyList.Sort(MapTemplateEnemyInfoSortFunc);
			}
			if (randomEnemyList.Count > 4)
			{
				randomEnemyList.RemoveRange(4, randomEnemyList.Count - 4);
			}
		}
		return (xiangshuMinionList: xiangshuMinionList, righteousList: righteousList, randomEnemyList: randomEnemyList);
		static int MapTemplateEnemyInfoSortFunc(MapTemplateEnemyInfo a, MapTemplateEnemyInfo b)
		{
			return Config.Character.Instance[b.TemplateId].OrganizationInfo.Grade.CompareTo(Config.Character.Instance[a.TemplateId].OrganizationInfo.Grade);
		}
	}

	public static void StartCombatWithMapRandomEnemyGroup(List<MapTemplateEnemyInfo> group, short combatConfigId, string combatCompleteEvent, EventArgBox argBox, int leaderId = -1)
	{
		DataContext context = Domain.MainThreadDataContext;
		List<int> enemyTeam = new List<int>();
		if (group.Count > 1)
		{
			if (leaderId != -1)
			{
				group.RemoveAt(0);
				enemyTeam.Add(leaderId);
			}
			for (int i = 0; i < group.Count; i++)
			{
				int charId = CreateNonIntelligentCharacter(group[i].TemplateId);
				enemyTeam.Add(charId);
			}
		}
		else
		{
			short leaderTempId = group[0].TemplateId;
			if (leaderId != -1)
			{
				enemyTeam.Add(leaderId);
			}
			else
			{
				int leaderCharId = CreateNonIntelligentCharacter(leaderTempId);
				enemyTeam.Add(leaderCharId);
			}
			short minionGroupId = Config.Character.Instance[leaderTempId].MinionGroupId;
			if (minionGroupId >= 0)
			{
				List<short> minions = MinionGroup.Instance[minionGroupId].Minions;
				for (int j = 0; j < minions.Count; j++)
				{
					int charId2 = CreateNonIntelligentCharacter(minions[j]);
					enemyTeam.Add(charId2);
				}
			}
		}
		Domain.SetListenerWithActionName(combatCompleteEvent, argBox, "CombatOver");
		if (enemyTeam == null || enemyTeam.Count <= 0)
		{
			throw new Exception("no available enemyTeam passed !");
		}
		DomainManager.Combat.CombatEntry(context, enemyTeam, combatConfigId);
	}

	public static void CharacterEscapeToNearbyBlock(EventArgBox argBox, GameData.Domains.Character.Character character, short steps)
	{
		CharacterEscapeToNearbyBlock(argBox, character, steps, hasNotification: false);
	}

	public static void CharacterEscapeToNearbyBlock(EventArgBox argBox, GameData.Domains.Character.Character character, short steps, bool hasNotification)
	{
		Location srcLocation = character.GetLocation();
		if (!srcLocation.IsValid())
		{
			return;
		}
		DataContext dataContext = Domain.MainThreadDataContext;
		int charId = character.GetId();
		int adventureId = -1;
		if (argBox.Get("ConchShipPresetKey_AdventureId", ref adventureId) && DomainManager.Adventure.TryGetElement_Adventures(adventureId, out var adventureRuntime))
		{
			if (character.IsTaiwu())
			{
				AdventureTaiwu adventureTaiwu = DomainManager.Adventure.GetAdventureTaiwu();
				List<AdventureBlockIndex> neighborIndexes = new List<AdventureBlockIndex>(adventureRuntime.GetNeighborPassableIndexes(adventureTaiwu.Index, steps));
				AdventureBlockIndex nextIndex = neighborIndexes.GetRandom(dataContext.Random);
				adventureTaiwu.SetCurrentIndex(nextIndex);
				DomainManager.Adventure.SetAdventureTaiwu(adventureTaiwu, dataContext);
				return;
			}
			AdventureElement characterElement = adventureRuntime.GetAllElements().FirstOrDefault((AdventureElement element) => element.CharacterId == charId);
			if (characterElement != null)
			{
				List<AdventureBlockIndex> neighborIndexes2 = new List<AdventureBlockIndex>(adventureRuntime.GetNeighborPassableIndexes(characterElement.Index, steps));
				AdventureBlockIndex nextIndex2 = neighborIndexes2.GetRandom(dataContext.Random);
				characterElement.SetIndex(nextIndex2);
				DomainManager.Adventure.SetAny(dataContext, adventureRuntime);
			}
			return;
		}
		if (character.GetId() == DomainManager.Taiwu.GetTaiwuCharId())
		{
			Tester.Assert(steps == 1);
			List<MapBlockData> neighborBlocks = ObjectPool<List<MapBlockData>>.Instance.Get();
			DomainManager.Map.GetRealNeighborBlocks(srcLocation.AreaId, srcLocation.BlockId, neighborBlocks, steps);
			if (neighborBlocks.Count > 1 && argBox.Get(EventTriggerParameter.DefValue.BlockFrom, out Location fromBlock))
			{
				if (fromBlock.IsValid())
				{
					MapBlockData fromBlockData = DomainManager.Map.GetBlock(fromBlock);
					neighborBlocks.Remove(fromBlockData);
				}
				foreach (Location location in DomainManager.Map.GetTaiwuMoveRecord())
				{
					if (location.AreaId == srcLocation.AreaId)
					{
						MapBlockData blockData = DomainManager.Map.GetBlock(location);
						neighborBlocks.Remove(blockData);
					}
				}
				if (neighborBlocks.Count == 0 && fromBlock.IsValid())
				{
					neighborBlocks.Add(DomainManager.Map.GetBlock(fromBlock));
				}
			}
			MapBlockData targetBlock = neighborBlocks.GetRandom(Domain.MainThreadDataContext.Random);
			ObjectPool<List<MapBlockData>>.Instance.Return(neighborBlocks);
			if (DomainManager.World.GetAdvancingMonthState() == 0)
			{
				DomainManager.Map.Move(Domain.MainThreadDataContext, targetBlock.BlockId, notCostTime: true);
			}
		}
		else
		{
			DomainManager.Character.EscapeToRandomNearbyBlock(Domain.MainThreadDataContext, character, steps);
		}
		if (hasNotification)
		{
			InstantNotificationCollection instantNotificationCollection = DomainManager.World.GetInstantNotificationCollection();
			instantNotificationCollection.AddCharacterEscape(character.GetId());
		}
	}

	public static void MapRandomEnemiesEscapeToNearbyBlock(Location location)
	{
		if (!location.IsValid())
		{
			return;
		}
		MapBlockData blockData = DomainManager.Map.GetBlock(location);
		if (blockData.TemplateEnemyList != null)
		{
			List<MapBlockData> neighborBlocks = ObjectPool<List<MapBlockData>>.Instance.Get();
			DomainManager.Map.GetValidBlocksForRandomEnemy(location.AreaId, blockData.BlockId, 2, onSettlement: false, nearTaiwu: true, neighborBlocks);
			for (int i = blockData.TemplateEnemyList.Count - 1; i >= 0; i--)
			{
				Location destLocation = ((neighborBlocks.Count > 0) ? neighborBlocks.GetRandom(Domain.MainThreadDataContext.Random).GetLocation() : Location.Invalid);
				Events.RaiseTemplateEnemyLocationChanged(Domain.MainThreadDataContext, blockData.TemplateEnemyList[i], location, destLocation);
			}
			ObjectPool<List<MapBlockData>>.Instance.Return(neighborBlocks);
		}
	}

	public static void MapRandomEnemiesEscapeByCharacter(Location location, int charId)
	{
		if (!DomainManager.Character.TryGetElement_Objects(charId, out var character))
		{
			throw new Exception("MapRandomEnemiesEscapeByCharacter need a alive character id!");
		}
		MapBlockData blockData = DomainManager.Map.GetBlock(location);
		if (blockData.TemplateEnemyList == null)
		{
			return;
		}
		List<MapBlockData> neighborBlocks = ObjectPool<List<MapBlockData>>.Instance.Get();
		DomainManager.Map.GetValidBlocksForRandomEnemy(location.AreaId, blockData.BlockId, 2, onSettlement: false, nearTaiwu: true, neighborBlocks);
		if (neighborBlocks.Count <= 0)
		{
			return;
		}
		sbyte charFameType = character.GetFameType();
		bool righteousNeedEscape = charFameType == 1 || charFameType == 0;
		for (int i = blockData.TemplateEnemyList.Count - 1; i >= 0; i--)
		{
			if (righteousNeedEscape || !GameData.Domains.Character.Character.IsRighteous(blockData.TemplateEnemyList[i].TemplateId))
			{
				MapBlockData targetBlock = neighborBlocks.GetRandom(Domain.MainThreadDataContext.Random);
				Events.RaiseTemplateEnemyLocationChanged(destLocation: new Location(targetBlock.AreaId, targetBlock.BlockId), context: Domain.MainThreadDataContext, templateEnemyInfo: blockData.TemplateEnemyList[i], srcLocation: location);
			}
		}
		ObjectPool<List<MapBlockData>>.Instance.Return(neighborBlocks);
	}

