	public static void SetCricketAtTaiwuLocationFake()
	{
		Location taiwuLocation = DomainManager.Taiwu.GetTaiwu().GetLocation();
		CricketPlaceData cricketData = DomainManager.Map.GetElement_CricketPlaceData(taiwuLocation.AreaId);
		if (cricketData == null)
		{
			return;
		}
		int index = cricketData.CricketBlocks.IndexOf(taiwuLocation.BlockId);
		int groupIndex = index / 3;
		int indexInGroup = index % 3;
		if (index < 0 || cricketData.RealCircketIdx[groupIndex] != indexInGroup)
		{
			return;
		}
		for (byte i = 0; i < 3; i++)
		{
			if (i != indexInGroup && !cricketData.CricketTriggered[groupIndex * 3 + i])
			{
				cricketData.RealCircketIdx[groupIndex] = i;
				break;
			}
		}
		DomainManager.Map.SetCricketPlaceData(Domain.MainThreadDataContext, taiwuLocation.AreaId, cricketData);
	}

