	public static void MakeBlocksBroken(short areaId, IEnumerable<MapBlockData> blocks, Predicate<MapBlockData> excludeCondition, IDictionary<short, byte> protectedBlocks)
	{
		MapDomain mapDomain = DomainManager.Map;
		List<short> edgeBlocks = ObjectPool<List<short>>.Instance.Get();
		HashSet<short> edgeTemplates = ObjectPool<HashSet<short>>.Instance.Get();
		List<short> ruinTemplates = ObjectPool<List<short>>.Instance.Get();
		HashSet<int> killCharacters = ObjectPool<HashSet<int>>.Instance.Get();
		List<short> enemyTemplates = ObjectPool<List<short>>.Instance.Get();
		List<MapBlockData> enemyBlocks = ObjectPool<List<MapBlockData>>.Instance.Get();
		List<ItemKey> itemsToDestroy = ObjectPool<List<ItemKey>>.Instance.Get();
		ruinTemplates.Clear();
		ruinTemplates.Add(118);
		ruinTemplates.Add(119);
		ruinTemplates.Add(120);
		ruinTemplates.Add(121);
		ruinTemplates.Add(122);
		ruinTemplates.Add(123);
		edgeTemplates.Clear();
		edgeTemplates.Add(126);
		edgeTemplates.UnionWith(ruinTemplates);
		killCharacters.Clear();
		enemyTemplates.Clear();
		enemyTemplates.Add(371);
		enemyTemplates.Add(372);
		enemyTemplates.Add(373);
		foreach (MapBlockData block in blocks)
		{
			if (block == null || block.TemplateId == 148 || block.BlockSubType == EMapBlockSubType.Station || !block.IsPassable())
			{
				continue;
			}
			if (block.TemplateId == 0)
			{
				DomainManager.TaiwuEvent.OnEvent_TaiwuVillageDestroyed();
				break;
			}
			if (!MapBlockDataMatchers.CanBeRuinedByXiangshu(block) || (excludeCondition != null && excludeCondition(block)) || (protectedBlocks != null && protectedBlocks.Any(delegate(KeyValuePair<short, byte> p)
			{
				KeyValuePair<short, byte> keyValuePair = p;
				keyValuePair.Deconstruct(out var key, out var value);
				short blockIndex = key;
				byte b = value;
				ByteCoordinate byteCoordinate = ByteCoordinate.IndexToCoordinate(blockIndex, mapDomain.GetAreaSize(areaId));
				return block.GetManhattanDistanceToPos(byteCoordinate.X, byteCoordinate.Y) <= b;
			})))
			{
				continue;
			}
			Location location = block.GetLocation();
			short originTemplateId = block.TemplateId;
			if (block.RootBlockId >= 0)
			{
				location.BlockId = block.RootBlockId;
			}
			mapDomain.ChangeBlockTemplate(Domain.MainThreadDataContext, location, ruinTemplates.Sample(), isTurnVisible: false);
			block.InitResources(Domain.MainThreadDataContext.Random);
			block.DestroyItemsDirect(itemsToDestroy);
			DomainManager.Map.SetBlockData(Domain.MainThreadDataContext, block);
			if (block.GroupBlockList != null)
			{
				foreach (MapBlockData childBlock in block.GroupBlockList)
				{
					childBlock.InitResources(Domain.MainThreadDataContext.Random);
					childBlock.DestroyItemsDirect(itemsToDestroy);
					DomainManager.Map.SetBlockData(Domain.MainThreadDataContext, childBlock);
				}
			}
			if (!ruinTemplates.Contains(originTemplateId) && (block.TemplateEnemyList == null || block.TemplateEnemyList.Count <= 0))
			{
				enemyBlocks.Clear();
				enemyBlocks.Add(block);
				int i = 0;
				for (int count = Domain.MainThreadDataContext.Random.Next(5, 10); i < count; i++)
				{
					DomainManager.Map.CreateRandomEnemiesOnValidBlocks(Domain.MainThreadDataContext, 0, Location.Invalid, enemyTemplates.Sample(), 1, enemyBlocks);
				}
			}
		}
		DomainManager.Item.RemoveItems(Domain.MainThreadDataContext, itemsToDestroy);
		ObjectPool<List<ItemKey>>.Instance.Return(itemsToDestroy);
		ObjectPool<List<short>>.Instance.Return(enemyTemplates);
		ObjectPool<List<MapBlockData>>.Instance.Return(enemyBlocks);
		ObjectPool<HashSet<int>>.Instance.Return(killCharacters);
		ObjectPool<List<short>>.Instance.Return(ruinTemplates);
		ObjectPool<HashSet<short>>.Instance.Return(edgeTemplates);
		ObjectPool<List<short>>.Instance.Return(edgeBlocks);
	}

	public static void MakeAreaGraduallyBroken(short areaId, Location protectedLocation, int protectedRange)
	{
		MapDomain mapDomain = DomainManager.Map;
		AdventureDomain adventureDomain = DomainManager.Adventure;
		CharacterDomain characterDomain = DomainManager.Character;
		MapAreaData areaData = mapDomain.GetElement_Areas(areaId);
		ByteCoordinate protectedCoord = ByteCoordinate.IndexToCoordinate(protectedLocation.BlockId, mapDomain.GetAreaSize(protectedLocation.AreaId));
		List<short> edgeBlocks = ObjectPool<List<short>>.Instance.Get();
		HashSet<short> edgeTemplates = ObjectPool<HashSet<short>>.Instance.Get();
		List<short> ruinTemplates = ObjectPool<List<short>>.Instance.Get();
		HashSet<int> killCharacters = ObjectPool<HashSet<int>>.Instance.Get();
		List<short> enemyTemplates = ObjectPool<List<short>>.Instance.Get();
		List<MapBlockData> enemyBlocks = ObjectPool<List<MapBlockData>>.Instance.Get();
		ruinTemplates.Clear();
		ruinTemplates.Add(118);
		ruinTemplates.Add(119);
		ruinTemplates.Add(120);
		ruinTemplates.Add(121);
		ruinTemplates.Add(122);
		ruinTemplates.Add(123);
		edgeTemplates.Clear();
		edgeTemplates.Add(126);
		edgeTemplates.UnionWith(ruinTemplates);
		killCharacters.Clear();
		enemyTemplates.Clear();
		enemyTemplates.Add(366);
		enemyTemplates.Add(367);
		enemyTemplates.Add(368);
		mapDomain.GetEdgeBlockList(areaId, edgeBlocks, edgeTemplates, excludeTravelBlock: false, strictSelect: false, containsBigBlock: true);
		foreach (short blockId in edgeBlocks)
		{
			if (blockId == areaData.StationBlockId)
			{
				continue;
			}
			MapBlockData block = mapDomain.GetBlock(areaId, blockId);
			if (!MapBlockDataMatchers.CanBeRuinedByXiangshu(block) || block.GetManhattanDistanceToPos(protectedCoord.X, protectedCoord.Y) <= protectedRange)
			{
				continue;
			}
			Location location = new Location(areaId, blockId);
			short originTemplateId = block.TemplateId;
			if (block.RootBlockId >= 0)
			{
				location.BlockId = block.RootBlockId;
			}
			mapDomain.ChangeBlockTemplate(Domain.MainThreadDataContext, location, ruinTemplates.Sample(), isTurnVisible: false);
			if (block.CharacterSet != null)
			{
				killCharacters.UnionWith(block.CharacterSet);
			}
			if (block.GroupBlockList != null)
			{
				foreach (MapBlockData childBlock in block.GroupBlockList)
				{
					if (childBlock.CharacterSet != null)
					{
						killCharacters.UnionWith(childBlock.CharacterSet);
					}
				}
			}
			block.InitResources(Domain.MainThreadDataContext.Random);
			DomainManager.Map.SetBlockData(Domain.MainThreadDataContext, block);
			if (block.GroupBlockList != null)
			{
				foreach (MapBlockData childBlock2 in block.GroupBlockList)
				{
					childBlock2.InitResources(Domain.MainThreadDataContext.Random);
					DomainManager.Map.SetBlockData(Domain.MainThreadDataContext, childBlock2);
				}
			}
			if (!ruinTemplates.Contains(originTemplateId) && (block.TemplateEnemyList == null || block.TemplateEnemyList.Count <= 0) && Domain.MainThreadDataContext.Random.Next(100) < 50)
			{
				enemyBlocks.Clear();
				enemyBlocks.Add(block);
				DomainManager.Map.CreateRandomEnemiesOnValidBlocks(Domain.MainThreadDataContext, 0, Location.Invalid, enemyTemplates.Sample(), 1, enemyBlocks);
			}
		}
		foreach (int characterId in killCharacters)
		{
			GameData.Domains.Character.Character character = characterDomain.GetElement_Objects(characterId);
			characterDomain.MakeCharacterDead(Domain.MainThreadDataContext, character, 10);
		}
		ObjectPool<List<short>>.Instance.Return(enemyTemplates);
		ObjectPool<List<MapBlockData>>.Instance.Return(enemyBlocks);
		ObjectPool<HashSet<int>>.Instance.Return(killCharacters);
		ObjectPool<List<short>>.Instance.Return(ruinTemplates);
		ObjectPool<HashSet<short>>.Instance.Return(edgeTemplates);
		ObjectPool<List<short>>.Instance.Return(edgeBlocks);
	}

