	public static int TriggerLocationFirstPickup(Location location, bool noCombat = false)
	{
		return TriggerLocationPickup(location, 0, noCombat);
	}

	public static int TriggerLocationPickup(Location location, int index, bool noCombat = false)
	{
		MapPickup pickup = DomainManager.Map.FindVisibleMapPickupOnLocation(location, index);
		if (pickup == null || !pickup.IsNormalType)
		{
			return -1;
		}
		DataContext context = Domain.MainThreadDataContext;
		if (pickup.HasXiangshuMinion && !noCombat && !pickup.CalcCanAutoBeatXiangshuMinion())
		{
			return CreateNonIntelligentCharacter(pickup.CalcXiangshuMinionTemplateId());
		}
		if (pickup.HasXiangshuMinion)
		{
			pickup.ApplyMinionEscape(context, location);
		}
		DomainManager.Map.TriggerNormalMapPickup(context, pickup);
		return -1;
	}

	public static bool AnyAutoPickup(Location location)
	{
		if (!GlobalDomain.Settings.AutoTriggerMapNormalPickup)
		{
			return false;
		}
		return DomainManager.Map.GetMapPickups(location).Any((MapPickup x) => IsAutoPickup(x, isPickUpAll: false));
	}

	public static int TriggerLocationAutoPickups(Location location)
	{
		DataContext context = Domain.MainThreadDataContext;
		List<MapPickup> pickups = DomainManager.Map.GetMapPickups(location).ToList();
		pickups.Sort(MapPickupHelper.CompareVisiblePickups);
		foreach (MapPickup pickup in pickups.Where((MapPickup x) => IsAutoPickup(x, isPickUpAll: false)))
		{
			if (pickup.HasXiangshuMinion && !pickup.CalcCanAutoBeatXiangshuMinion())
			{
				DomainManager.Map.SetPickupAtFirst(context, pickup);
				return CreateNonIntelligentCharacter(pickup.CalcXiangshuMinionTemplateId());
			}
			if (pickup.HasXiangshuMinion)
			{
				pickup.ApplyMinionEscape(context, location);
			}
			DomainManager.Map.TriggerNormalMapPickup(context, pickup);
		}
		return -1;
	}

	public static List<int> TriggerLocationBatchPickups(Location location)
	{
		List<int> result = new List<int>();
		DataContext context = Domain.MainThreadDataContext;
		List<MapPickup> pickups = DomainManager.Map.GetMapPickups(location).ToList();
		pickups.Sort(MapPickupHelper.CompareVisiblePickups);
		foreach (MapPickup pickup in pickups.Where((MapPickup x) => IsAutoPickup(x, isPickUpAll: true)))
		{
			if (pickup.HasXiangshuMinion && !pickup.CalcCanAutoBeatXiangshuMinion())
			{
				DomainManager.Map.SetPickupAtFirst(context, pickup);
				result.Add(CreateNonIntelligentCharacter(pickup.CalcXiangshuMinionTemplateId()));
				continue;
			}
			if (pickup.HasXiangshuMinion)
			{
				pickup.ApplyMinionEscape(context, location);
			}
			DomainManager.Map.TriggerNormalMapPickup(context, pickup);
		}
		return result;
	}

	private static bool IsAutoPickup(MapPickup pickup, bool isPickUpAll)
	{
		MapPickupAutoTriggerSetting pickupSetting = GlobalDomain.Settings.NormalMapPickupAutoTriggerSetting;
		if (!pickupSetting.IncludeXiangshuMinion && pickup.CalcNeedBattle())
		{
			return false;
		}
		if (!isPickUpAll)
		{
			if (pickupSetting.MinGrade != -1 && pickup.Type == MapPickup.EMapPickupType.Item && ItemTemplateHelper.GetGrade(pickup.ItemType, pickup.ItemTemplateId) < pickupSetting.MinGrade)
			{
				return false;
			}
			if (!pickupSetting.PickupTypes[(int)pickup.Template.Type2])
			{
				return false;
			}
		}
		return !pickup.CalcMapPickupBanReason().Any();
	}

	public static void OnTaiwuDefeatByMapPickupEnemy(EventArgBox argBox)
	{
		DomainManager.Map.TempDisableTriggerNormalPickupByTaiwuEscape = true;
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		if (!argBox.Get(EventTriggerParameter.DefValue.BlockFrom, out Location _))
		{
			Location lastLocation = DomainManager.Map.TaiwuLastLocation;
			if (lastLocation.IsValid())
			{
				argBox.Set(EventTriggerParameter.DefValue.BlockFrom.ArgBoxKey, lastLocation);
			}
		}
		CharacterEscapeToNearbyBlock(argBox, taiwu, 1);
		DomainManager.Map.TempDisableTriggerNormalPickupByTaiwuEscape = false;
	}

