	public static void CostNormalInformationUsedCount(int charId, NormalInformation normalInformation)
	{
		if (!DomainManager.Information.TryGetElement_Information(charId, out var normalInformationCollection))
		{
			return;
		}
		InformationItem config = Config.Information.Instance.GetItem(normalInformation.TemplateId);
		if (config.InfoIds.CheckIndex(normalInformation.Level))
		{
			InformationInfoItem info = InformationInfo.Instance.GetItem(config.InfoIds[normalInformation.Level]);
			if (!info.Consume)
			{
				return;
			}
		}
		sbyte usedCount = normalInformationCollection.GetUsedCount(normalInformation);
		usedCount = normalInformationCollection.SetUsedCount(normalInformation, (sbyte)(usedCount + 1));
		if (usedCount >= normalInformationCollection.GetUsedCountMax(normalInformation))
		{
			DiscardNormalInformation(charId, normalInformation);
		}
		else
		{
			DomainManager.Information.SetNormalInformationCharacterDataModified(Domain.MainThreadDataContext, charId);
		}
	}

	public unsafe static sbyte GetNormalInformationUseResultType(int targetCharId, NormalInformation normalInformation)
	{
		InformationItem config = Config.Information.Instance[normalInformation.TemplateId];
		InformationInfoItem info = InformationInfo.Instance[config.InfoIds[normalInformation.Level]];
		GameData.Domains.Character.Character targetChar = DomainManager.Character.GetElement_Objects(targetCharId);
		switch (config.Type)
		{
		case 0:
		{
			MapStateItem selfState = MapState.Instance.First((MapStateItem s) => Enumerable.Contains(MapArea.Instance[s.MainAreaID].OrganizationId, info.Oraganization));
			sbyte targetCharStateId = DomainManager.Map.GetStateTemplateIdByAreaId(targetChar.GetLocation().AreaId);
			if ((selfState.TemplateId != targetCharStateId && !Enumerable.Contains(selfState.NeighborStates, targetCharStateId)) || (DomainManager.Map.GetAreaIdByAreaTemplateId(selfState.MainAreaID) == targetChar.GetBirthLocation().AreaId && targetChar.GetBirthLocation().AreaId != targetChar.GetLocation().AreaId))
			{
				return 0;
			}
			if (selfState.TemplateId != targetCharStateId || (selfState.TemplateId == targetCharStateId && normalInformation.Level > targetChar.GetInteractionGrade(targetIsTaiwu: true)))
			{
				return 1;
			}
			return 2;
		}
		case 1:
		{
			sbyte selfOrganizationTemplateId = info.Oraganization;
			OrganizationInfo targetCharOrgInfo = targetChar.GetOrganizationInfo();
			if (selfOrganizationTemplateId != targetCharOrgInfo.OrgTemplateId && targetCharOrgInfo.OrgTemplateId >= 0 && Config.Organization.Instance[selfOrganizationTemplateId].Goodness != Config.Organization.Instance[targetCharOrgInfo.OrgTemplateId].Goodness)
			{
				return 0;
			}
			if (selfOrganizationTemplateId != targetCharOrgInfo.OrgTemplateId)
			{
				return 1;
			}
			return 2;
		}
		case 2:
		{
			NormalInformationCollection targetCharInformation = DomainManager.Information.GetCharacterNormalInformation(targetCharId);
			if (!targetCharInformation.ReceivedCounts.TryGetValue(config.TemplateId, out var receivedCount))
			{
				receivedCount = 0;
			}
			short selfQualification = DomainManager.Taiwu.GetTaiwu().GetLifeSkillQualifications().Items[info.LifeSkillType];
			short targetQualification = targetChar.GetLifeSkillQualifications().Items[info.LifeSkillType];
			if (selfQualification * (normalInformation.Level + 1) >= targetQualification + targetQualification * receivedCount * 2)
			{
				targetCharInformation.ReceivedCounts[config.TemplateId] = (sbyte)(receivedCount + 2);
				return 0;
			}
			if (selfQualification * (normalInformation.Level + 1) >= targetQualification + targetQualification * receivedCount)
			{
				targetCharInformation.ReceivedCounts[config.TemplateId] = (sbyte)(receivedCount + 1);
				return 1;
			}
			return 2;
		}
		case 3:
		case 4:
		{
			NormalInformationCollection normalCollection = DomainManager.Information.GetCharacterNormalInformation(targetCharId);
			if (!normalCollection.GetList().Contains(normalInformation))
			{
				return 0;
			}
			return 2;
		}
		case 5:
			return 3;
		case 6:
		{
			ProfessionData targetCurrentProfession = DomainManager.Character.GetCharacterCurrentProfession(targetCharId);
			OrganizationInfo orgInfo = targetChar.GetOrganizationInfo();
			if (orgInfo.OrgTemplateId >= 0)
			{
				short orgMemberId = OrganizationDomain.GetMemberId(orgInfo.OrgTemplateId, orgInfo.Grade);
				OrganizationMemberItem orgMemberConfig = OrganizationMember.Instance.GetItem(orgMemberId);
				if (orgMemberConfig.PreferProfessions != null)
				{
					IntPair[] preferProfessions = orgMemberConfig.PreferProfessions;
					for (int i = 0; i < preferProfessions.Length; i++)
					{
						IntPair pair = preferProfessions[i];
						if (pair.First == info.Profession && pair.Second == 0)
						{
							return 2;
						}
					}
				}
			}
			if (targetCurrentProfession != null)
			{
				ProfessionItem targetCurrentProfessionConfig = targetCurrentProfession.GetConfig();
				if (targetCurrentProfessionConfig.CompatibleProfessions.Contains(info.Profession))
				{
					return 0;
				}
				if (targetCurrentProfessionConfig.ConflictingProfessions.Contains(info.Profession))
				{
					return 2;
				}
			}
			return 1;
		}
		default:
			throw new NotImplementedException();
		}
	}

	internal static bool NormalInformationCanGiveTaiwu(NormalInformation information)
	{
		InformationItem config = Config.Information.Instance.GetItem(information.TemplateId);
		if (config != null)
		{
			sbyte type = config.Type;
			if ((uint)type <= 1u || type == 6)
			{
				return true;
			}
		}
		return false;
	}

