	public static void ApplyNormalInformationSideEffect(NormalInformation normalInformation, sbyte useResultType, int selfCharId, int targetId)
	{
		ApplyNormalInformationSideEffectWithEffectRate(normalInformation, useResultType, selfCharId, targetId, 100);
	}

	public static void ApplyNormalInformationSideEffectWithEffectRate(NormalInformation normalInformation, sbyte useResultType, int selfCharId, int targetId, int effectRate)
	{
		InformationItem config = Config.Information.Instance[normalInformation.TemplateId];
		GameData.Domains.Character.Character targetChar = DomainManager.Character.GetElement_Objects(targetId);
		LifeRecordCollection lifeRecordCollection = DomainManager.LifeRecord.GetLifeRecordCollection();
		switch (config.Type)
		{
		case 0:
		{
			sbyte areaTemplateId = InformationInfo.Instance[config.InfoIds[normalInformation.Level]].Oraganization;
			Location currentAreaLocation = targetChar.GetLocation();
			if (GetRandom() < config.ChangeLovingAndHatingRate[useResultType] * effectRate / 100)
			{
				if (CheckProbability(config.ChangeLovingRate))
				{
					ChangeLoving();
				}
				else
				{
					ChangeHating();
				}
			}
			break;
		}
		case 1:
		{
			sbyte sectTemplateId = InformationInfo.Instance[config.InfoIds[normalInformation.Level]].Oraganization;
			OrganizationItem sectConfig = Config.Organization.Instance[sectTemplateId];
			Settlement sect = DomainManager.Organization.GetSettlementByOrgTemplateId(sectTemplateId);
			Tester.Assert(sectConfig.IsSect);
			if (GetRandom() < config.ChangeTowardOrganizationRate[useResultType] * effectRate / 100)
			{
				targetChar.SetIdealSect(sectTemplateId, Domain.MainThreadDataContext);
				lifeRecordCollection.AddNormalInformationChangeIdealSect(targetId, DomainManager.World.GetCurrDate(), targetChar.GetLocation(), selfCharId, sect.GetId());
			}
			sbyte idealSectTemplateId = targetChar.GetIdealSect();
			if (normalInformation.TemplateId >= 55 && normalInformation.TemplateId <= 75 && sectTemplateId == idealSectTemplateId && GetRandom() < config.RemoveTowardOrganizationRate[useResultType])
			{
				int randomSectTemplateId;
				do
				{
					randomSectTemplateId = GetRandom(1, 15);
				}
				while (randomSectTemplateId == idealSectTemplateId);
				idealSectTemplateId = (sbyte)randomSectTemplateId;
				targetChar.SetIdealSect(idealSectTemplateId, Domain.MainThreadDataContext);
				lifeRecordCollection.AddNormalInformationChangeIdealSectNegative(targetId, DomainManager.World.GetCurrDate(), targetChar.GetLocation(), selfCharId, sect.GetId());
			}
			if (GetRandom() < config.ChangeBehaviorTypeRate[useResultType] * effectRate / 100)
			{
				short a = targetChar.GetBaseMorality();
				short b = Config.Organization.Instance[sectTemplateId].MainMorality;
				int lerp = a + (b - a) / 10;
				sbyte behaviorTypeBefore = targetChar.GetBehaviorType();
				ChangeRoleBaseBehaviorValue(targetChar, (short)(lerp - a));
				sbyte behaviorTypeAfter = targetChar.GetBehaviorType();
				if (behaviorTypeAfter != behaviorTypeBefore)
				{
					lifeRecordCollection.AddNormalInformationChangeBaseMorality(targetId, DomainManager.World.GetCurrDate(), targetChar.GetLocation(), selfCharId, behaviorTypeAfter);
				}
			}
			break;
		}
		case 2:
		{
			sbyte lifeSkillType = InformationInfo.Instance[config.InfoIds[normalInformation.Level]].LifeSkillType;
			if (useResultType == 0)
			{
				GameData.Domains.Character.Character selfChar = DomainManager.Character.GetElement_Objects(selfCharId);
				lifeRecordCollection.AddNormalInformationChangeLifeSkillTypeInterest(targetId, DomainManager.World.GetCurrDate(), targetChar.GetLocation(), selfCharId, lifeSkillType);
				targetChar.AddGoal(Domain.MainThreadDataContext, 247, lifeSkillType, (int)selfChar.GetLifeSkillAttainment(lifeSkillType));
			}
			break;
		}
		case 5:
			switch (useResultType)
			{
			case 0:
				DomainManager.Character.GetElement_Objects(selfCharId).ChangeResource(Domain.MainThreadDataContext, 7, config.Authority * effectRate / 100);
				break;
			case 1:
				DomainManager.Character.GetElement_Objects(selfCharId).ChangeResource(Domain.MainThreadDataContext, 7, config.Authority / 2 * effectRate / 100);
				break;
			}
			break;
		default:
			if (useResultType == 0)
			{
				DomainManager.Character.GetElement_Objects(selfCharId).ChangeResource(Domain.MainThreadDataContext, 7, config.Authority * effectRate / 100);
			}
			break;
		}
	}

	public static string ApplyNormalInformation(int charId, EventArgBox argBox, NormalInformation normalInformation, string nextEventGuid1, string nextEventGuid2, string nextEventGuid3)
	{
		return ApplyNormalInformationWithEffectRate(charId, argBox, normalInformation, nextEventGuid1, nextEventGuid2, nextEventGuid3, 100);
	}

	public static string ApplyNormalInformationWithEffectRate(int charId, EventArgBox argBox, NormalInformation normalInformation, string nextEventGuid1, string nextEventGuid2, string nextEventGuid3, int effectRate, bool canChangeAlertness = true)
	{
		sbyte useResultType = GetNormalInformationUseResultType(charId, normalInformation);
		InformationItem config = Config.Information.Instance.GetItem(normalInformation.TemplateId);
		InformationInfoItem info = InformationInfo.Instance.GetItem(config.InfoIds[normalInformation.Level]);
		if (6 == config.Type)
		{
			short rate = config.ChangeProfessionRate[useResultType];
			if (CheckProbability(rate) && DomainManager.Character.TryGetElement_Objects(charId, out var character) && character.CanHaveProfession())
			{
				DomainManager.Character.SetCharacterCurrProfession(Domain.MainThreadDataContext, charId, info.Profession);
				GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
				LifeRecordCollection collection = DomainManager.LifeRecord.GetLifeRecordCollection();
				collection.AddNormalInformationChangeProfession(charId, DomainManager.World.GetCurrDate(), taiwu.GetValidLocation(), taiwu.GetId(), info.Profession);
			}
		}
		if (useResultType != 3)
		{
			SetInteractionCooldown(charId, 0);
		}
		switch (useResultType)
		{
		case 0:
			if (2 == config.Type && 13 == info.LifeSkillType)
			{
				ProfessionFormulaItem formula = ProfessionFormula.Instance[48];
				int addSeniority = formula.Calculate(normalInformation.Level);
				DomainManager.Extra.ChangeProfessionSeniority(Domain.MainThreadDataContext, 6, addSeniority);
			}
			else if (2 == config.Type && 12 == info.LifeSkillType)
			{
				ProfessionFormulaItem formula2 = ProfessionFormula.Instance[42];
				int addSeniority2 = formula2.Calculate(normalInformation.Level);
				DomainManager.Extra.ChangeProfessionSeniority(Domain.MainThreadDataContext, 5, addSeniority2);
			}
			else
			{
				ProfessionFormulaItem formula3 = ProfessionFormula.Instance[32];
				int addSeniority3 = formula3.Calculate(normalInformation.Level);
				DomainManager.Extra.ChangeProfessionSeniority(Domain.MainThreadDataContext, 4, addSeniority3);
			}
			CostNormalInformationUsedCount(EventArgBox.TaiwuCharacterId, normalInformation);
			ApplyNormalInformationSideEffectWithEffectRate(normalInformation, 0, EventArgBox.TaiwuCharacterId, charId, effectRate);
			AddLegacyPoint(35);
			if (canChangeAlertness)
			{
				ChangeAlertnessOnTalkByNormalInformationGood(charId, normalInformation.Level, info.TemplateId);
			}
			return nextEventGuid1;
		case 1:
			CostNormalInformationUsedCount(EventArgBox.TaiwuCharacterId, normalInformation);
			ApplyNormalInformationSideEffectWithEffectRate(normalInformation, 1, EventArgBox.TaiwuCharacterId, charId, effectRate);
			if (canChangeAlertness)
			{
				ChangeAlertnessOnTalkByNormalInformationNormal(charId, normalInformation.Level, info.TemplateId);
			}
			return nextEventGuid2;
		case 2:
			CostNormalInformationUsedCount(EventArgBox.TaiwuCharacterId, normalInformation);
			ApplyNormalInformationSideEffectWithEffectRate(normalInformation, 2, EventArgBox.TaiwuCharacterId, charId, effectRate);
			return nextEventGuid3;
		case 3:
			return StartSwordTombInformationEvent(normalInformation, argBox);
		default:
			return string.Empty;
		}
	}

	public static void GetSwordTombInformation(EInformationInfoSwordInformationType type, int xiangshuAvatarId, EventArgBox argBox)
	{
		if (xiangshuAvatarId == -1)
		{
			MapBlockData blockData = DomainManager.Map.GetBlock(DomainManager.Taiwu.GetTaiwu().GetLocation());
			GameData.Domains.Character.Character character = GetBlockXiangshuAvatar(blockData);
			xiangshuAvatarId = XiangshuAvatarIds.GetXiangshuAvatarIdByCharacterTemplateId(character.GetTemplateId());
		}
		NormalInformation normalInformation = DomainManager.Information.CalcSwordTombInformation(type, xiangshuAvatarId);
		InformationItem config = Config.Information.Instance[normalInformation.TemplateId];
		InformationInfoItem infoConfig = InformationInfo.Instance[config.InfoIds[normalInformation.Level]];
		int taiwuId = DomainManager.Taiwu.GetTaiwuCharId();
		if (config.UsedCountWithMax)
		{
			if (DomainManager.Information.TryGetElement_Information(taiwuId, out var normalInformationCollection) && normalInformationCollection.GetList().Contains(normalInformation))
			{
				DiscardNormalInformation(taiwuId, normalInformation);
			}
			DomainManager.Information.AddNormalInformationToCharacter(Domain.MainThreadDataContext, taiwuId, normalInformation);
		}
		else
		{
			DomainManager.Information.GiveRemainUsedCountInformation(Domain.MainThreadDataContext, taiwuId, normalInformation);
		}
		argBox.Set("SwordTombInformationName", infoConfig.Name);
	}

