				if (templateId >= 240 && templateId <= 253)
				{
					obj = "a679dd12-3e7d-404d-8f91-beca19a04cb0";
					goto IL_008a;
				}
			}
			obj = "9ffe7e03-456b-4abc-abf2-82da562cd3a3";
