	public static void FinishSwordTombInformationEvent(EventArgBox argBox)
	{
		int giftType = 0;
		DataContext context = Domain.MainThreadDataContext;
		int taiwuId = DomainManager.Taiwu.GetTaiwuCharId();
		NormalInformationCollection informationCollection = DomainManager.Information.GetElement_Information(taiwuId);
		GameData.Domains.Character.Character character = argBox.GetCharacter("CharacterId");
		int targetCharId = character.GetId();
		argBox.Get("SwordTombInformation", out NormalInformation normalInformation);
		argBox.Get("SwordTombGiftType", ref giftType);
		SetInteractionCooldown(targetCharId, 0);
		sbyte usedCount = informationCollection.GetUsedCount(normalInformation);
		DomainManager.Information.EnsureCharacterNormalInformationCollection(Domain.MainThreadDataContext, targetCharId).ReceivedCounts[normalInformation.TemplateId] = 1;
		switch (giftType)
		{
		case 1:
			usedCount = informationCollection.SetUsedCount(normalInformation, (sbyte)(usedCount + 1));
			break;
		case 2:
			usedCount = informationCollection.SetUsedCount(normalInformation, (sbyte)(usedCount + 1));
			break;
		case 3:
			usedCount = informationCollection.SetUsedCount(normalInformation, (sbyte)(usedCount + GetSwordTombInformationHiringUsedCount()));
			break;
		}
		if (usedCount >= informationCollection.GetUsedCountMax(normalInformation))
		{
			TransformNormalInformation(taiwuId, normalInformation);
		}
		else
		{
			DomainManager.Information.SetNormalInformationCharacterDataModified(Domain.MainThreadDataContext, taiwuId);
		}
		DomainManager.Information.SetNormalInformationCharacterDataModified(Domain.MainThreadDataContext, targetCharId);
	}

