	public static bool IsCharacterSectEnemy(int charId, short settlementId)
	{
		Tester.Assert(settlementId >= 0);
		Settlement settlement = DomainManager.Organization.GetSettlement(settlementId);
		if (!(settlement is Sect sect))
		{
			return false;
		}
		return sect.HasEnemySectBounty(charId) || sect.HasEnemyRelationBounty(charId);
	}

	public static void SendCharacterIntoPrison(int charId, short settlementId, EventArgBox argBox, int duration = -1)
	{
		if (!DomainManager.Character.TryGetElement_Objects(charId, out var character))
		{
			return;
		}
		Settlement settlement = DomainManager.Organization.GetSettlement(settlementId);
		if (!(settlement is Sect sect))
		{
			return;
		}
		DataContext context = Domain.MainThreadDataContext;
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		LifeRecordCollection collection = GetLifeRecordCollection();
		collection.AddSendingToPrisonCriminal(character.GetId(), GetGameDate(), taiwu.GetId(), sect.GetId());
		SettlementPrisonRecordCollection treasuryRecordCollection = DomainManager.Organization.GetSettlementPrisonRecordCollection(context, settlementId);
		treasuryRecordCollection.AddSentToPrisonTaiwu(GetGameDate(), settlementId, charId, taiwu.GetId());
		DomainManager.Organization.SetSettlementPrisonRecordCollection(context, settlementId, treasuryRecordCollection);
		CharacterSet groupCharIds = DomainManager.Taiwu.GetGroupCharIds();
		if (DomainManager.Character.TryGetKidnappedCharacters(taiwu.GetId(), out var kidnappedCharacterList) && kidnappedCharacterList.IndexOf(charId) >= 0)
		{
			RemovePrisonerFromCharacter(charId, taiwu.GetId(), isEscaped: false);
		}
		if (groupCharIds.GetCollection().Contains(charId))
		{
			SettlementPrisonEventEffectItem config = SettlementPrisonEventEffect.Instance[(short)0];
			ChangeFavorabilityOptional(character, taiwu, (short)config.ChangeFavorTeammate, 3);
			RequestRoleLeaveGroup(charId);
		}
		ProfessionFormulaItem seniorityFormula = ProfessionFormula.Instance[27];
		if (duration != -1)
		{
			sbyte punishmentSeverity = DurationToPunishmentSeverityLevel(duration);
			sect.AddPrisoner(context, character, punishmentSeverity, 0, duration);
			collection.AddSendingToPrison2Taiwu(taiwu.GetId(), GetGameDate(), character.GetId(), sect.GetId());
			return;
		}
		sbyte sectOrgTemplateId;
		SettlementBounty bounty = DomainManager.Organization.GetBounty(charId, out sectOrgTemplateId);
		if (IsCharacterSectFugitive(charId, settlementId))
		{
			if (character.IsCompletelyInfected())
			{
				sect.AddPrisoner(context, character, 40);
			}
			else
			{
				DomainManager.Organization.PunishSectMember(context, sect, character, bounty.PunishmentSeverity, bounty.PunishmentType, isArrested: true);
			}
			int addSeniority = seniorityFormula.Calculate(bounty.PunishmentSeverity + 1, character.GetInteractionGrade());
			DomainManager.Extra.ChangeProfessionSeniority(context, 3, addSeniority);
		}
		else if (sect.HasEnemySectBounty(charId))
		{
			PunishmentTypeItem config2 = PunishmentType.Instance[(short)42];
			sbyte severity = sect.GetPunishmentTypeSeverity(config2, includeDefault: true);
			sect.AddPrisoner(context, character, severity, config2.TemplateId);
			int addSeniority2 = seniorityFormula.Calculate(severity + 1, character.GetInteractionGrade());
			DomainManager.Extra.ChangeProfessionSeniority(context, 3, addSeniority2);
		}
		else if (sect.HasEnemyRelationBounty(charId))
		{
			PunishmentTypeItem config3 = PunishmentType.Instance[(short)43];
			sbyte severity2 = sect.GetPunishmentTypeSeverity(config3, includeDefault: true);
			sect.AddPrisoner(context, character, severity2, config3.TemplateId);
			List<int> charIdList = GetEnemyCharacterListOfStateSettlement(charId, settlementId);
			if (charIdList != null && charIdList.Count > 0)
			{
				for (int i = 0; i < charIdList.Count; i++)
				{
					int enemyId = charIdList[i];
					if (DomainManager.Character.TryGetElement_Objects(charIdList[i], out var enemy))
					{
						ChangeFavorabilityOptional(enemy, taiwu, 3000, 3);
						DomainManager.Character.TryRemoveOneWayRelation(context, enemyId, charId, 32768);
					}
				}
			}
			int addSeniority3 = seniorityFormula.Calculate(severity2 + 1, character.GetInteractionGrade());
			DomainManager.Extra.ChangeProfessionSeniority(context, 3, addSeniority3);
		}
		GetBounty(sect, character, argBox);
	}

	private static List<int> GetEnemyCharacterListOfStateSettlement(int charId, short targetSettlementId)
	{
		if (!DomainManager.Character.TryGetElement_Objects(charId, out var _))
		{
			return null;
		}
		Settlement targetSettlement = DomainManager.Organization.GetSettlement(targetSettlementId);
		Tester.Assert(targetSettlement is Sect);
		Location settlementLocation = targetSettlement.GetLocation();
		sbyte stateId = DomainManager.Map.GetStateIdByAreaId(settlementLocation.AreaId);
		List<short> settlementIds = ObjectPool<List<short>>.Instance.Get();
		List<int> characterIdList = new List<int>();
		DomainManager.Map.GetStateSettlementIds(stateId, settlementIds, containsMainCity: true, containsSect: true);
		for (int i = 0; i < settlementIds.Count; i++)
		{
			short settlementId = settlementIds[i];
			Settlement settlement = DomainManager.Organization.GetSettlement(settlementId);
			OrgMemberCollection members = settlement.GetMembers();
			for (sbyte grade = 3; grade < 9; grade++)
			{
				HashSet<int> gradeMembers = members.GetMembers(grade);
				foreach (int gradeMemberId in gradeMembers)
				{
					if (DomainManager.Organization.GetPrisonerSect(gradeMemberId) != targetSettlement.GetOrgTemplateId() && DomainManager.Character.HasRelation(gradeMemberId, charId, 32768))
					{
						characterIdList.Add(gradeMemberId);
					}
				}
			}
		}
		ObjectPool<List<short>>.Instance.Return(settlementIds);
		return characterIdList;
	}

	private static sbyte DurationToPunishmentSeverityLevel(int duration)
	{
		sbyte punishmentSeverity = 1;
		if (duration >= 6)
		{
			punishmentSeverity = 1;
		}
		if (duration >= 12)
		{
			punishmentSeverity = 2;
		}
		if (duration >= 24)
		{
			punishmentSeverity = 3;
		}
		return punishmentSeverity;
	}

	public static void GetBounty(Sect sect, GameData.Domains.Character.Character character, EventArgBox argBox)
	{
		DataContext context = Domain.MainThreadDataContext;
		int count = sect.CalcBountyAmount(character.GetInteractionGrade());
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		if (DomainManager.Extra.IsProfessionalSkillUnlocked(3, 2))
		{
			ProfessionData professionData = DomainManager.Extra.GetProfessionData(3);
			int factor = professionData.GetSeniorityPercent();
			count += count * factor / 100;
			int itemBonusGrade = Math.Clamp(character.GetOrganizationInfo().Grade * professionData.GetSeniorityPercent() / 100 - 2, 0, 8);
			short[] bonusList = Config.Organization.Instance.GetItem(sect.GetOrgTemplateId()).MartialArtistItemBonus;
			if (bonusList != null && bonusList.CheckIndex(itemBonusGrade))
			{
				short groupTemplateId = Config.Weapon.Instance.GetItem(bonusList[itemBonusGrade]).GroupId;
				List<WeaponItem> items = (from templateId in Config.Weapon.Instance.GetAllKeys()
					select Config.Weapon.Instance.GetItem(templateId) into template
					where template.GroupId == groupTemplateId && template.Grade == itemBonusGrade
					select template).ToList();
				if (items.Count > 0)
				{
					WeaponItem bonusItemTemplate = items.GetRandom(context.Random);
					ItemKey itemKey = DomainManager.Item.CreateItem(context, bonusItemTemplate.ItemType, bonusItemTemplate.TemplateId);
					taiwu.AddInventoryItem(context, itemKey, 1);
					DomainManager.World.GetInstantNotificationCollection().AddGetItem(taiwu.GetId(), itemKey.ItemType, itemKey.TemplateId);
					GameData.GameDataBridge.GameDataBridge.AddDisplayEvent(DisplayEventType.OpenGetItem_Item, new List<ItemDisplayData> { DomainManager.Item.GetItemDisplayData(itemKey) }, arg2: false);
				}
			}
		}
		argBox.Set("BountyCount", count);
		LifeRecordCollection collection = GetLifeRecordCollection();
		switch (Config.Organization.Instance[sect.GetOrgTemplateId()].Goodness)
		{
		case -1:
			ChangeRoleResource(taiwu, 6, count);
			argBox.Set("BountyTypeName", Config.ResourceType.Instance.GetItem(6).Name);
			collection.AddSendingToPrison1Taiwu(taiwu.GetId(), GetGameDate(), character.GetId(), sect.GetId(), 6, count);
			break;
		case 1:
			ChangeRoleResource(taiwu, 7, count);
			argBox.Set("BountyTypeName", Config.ResourceType.Instance.GetItem(7).Name);
			collection.AddSendingToPrison1Taiwu(taiwu.GetId(), GetGameDate(), character.GetId(), sect.GetId(), 7, count);
			break;
		case 0:
			ChangeRoleExp(taiwu, count);
			argBox.Set("BountyTypeName", CharacterPropertyDisplay.Instance.GetItem(104).Name);
			collection.AddSendingToPrison1TaiwuByExp(taiwu.GetId(), GetGameDate(), character.GetId(), sect.GetId(), count);
			break;
		}
	}

