			sbyte resourceType = 6;
			if (Config.Organization.Instance[orgInfo.OrgTemplateId].Goodness == 1)
			{
				resourceType = 7;
			}
			collection.AddBuyHandOverTheCriminalTaiwu(taiwu.GetId(), GetGameDate(), hunterId, prisonerId, settlementId, resourceType, bountyCount);
		}
		SecretInformationCollection secretInformationCollection = DomainManager.Information.GetSecretInformationCollection();
		int secretInfoOffset = secretInformationCollection.AddBegPrisoner(taiwu.GetId(), hunterId, prisonerId);
		SecretInformationId secretInfoId = DomainManager.Information.AddSecretInformation(Domain.MainThreadDataContext, secretInfoOffset);
	}

