	public static bool CanTriggerTaiwuWantedInteraction(int charId, EventArgBox argBox)
	{
		if (DomainManager.Character.TryGetElement_Objects(charId, out var character))
		{
			if (character.GetOrganizationInfo().OrgTemplateId == 16)
			{
				return false;
			}
			sbyte sectTemplateId = GetCharacterSettlementStateSectTemplateId(charId);
			if (sectTemplateId < 0)
			{
				return false;
			}
			short settlementId = DomainManager.Organization.GetSettlementIdByOrgTemplateId(sectTemplateId);
			argBox.Set("SettlementId", settlementId);
			return IsTaiwuSectFugitive(settlementId);
		}
		return false;
	}

