	public unsafe static void TaiwuWantedSectPunished(EventArgBox argBox, bool confess)
	{
		DataContext context = Domain.MainThreadDataContext;
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		int taiwuCharId = taiwu.GetId();
		short settlementId = -1;
		argBox.Get("SettlementId", ref settlementId);
		Settlement settlement = DomainManager.Organization.GetSettlement(settlementId);
		if (!(settlement is Sect sect))
		{
			return;
		}
		SettlementBounty bounty = sect.Prison.GetBounty(taiwuCharId);
		sect.RemoveBounty(context, taiwuCharId);
		sbyte severity = bounty.PunishmentSeverity;
		sbyte stateTemplateId = DomainManager.Map.GetStateTemplateIdByAreaId(settlement.GetLocation().AreaId);
		DomainManager.Organization.TryGetCustomizedCityPunishmentSeverity(stateTemplateId, isSect: true, bounty.PunishmentType, ref severity);
		sbyte orgTemplateId = settlement.GetOrgTemplateId();
		PunishmentSeverityItem config = PunishmentSeverity.Instance[severity];
		LifeRecordCollection lifeRecordCollection = DomainManager.LifeRecord.GetLifeRecordCollection();
		int date = DomainManager.World.GetCurrDate();
		int authority = taiwu.GetResource(7);
		int commonAuthorityDelta = config.CommonAuthorityDelta;
		if (confess)
		{
			commonAuthorityDelta /= 2;
		}
		int left = authority - commonAuthorityDelta;
		int spiritualDebtDelta = config.CommonSpiritualDebtDelta;
		if (confess)
		{
			spiritualDebtDelta /= 2;
		}
		int authorityDelta = 0;
		if (left >= 0)
		{
			authorityDelta = commonAuthorityDelta;
		}
		else
		{
			authorityDelta = authority;
			spiritualDebtDelta -= left / 10;
		}
		ChangeRoleResource(taiwu, 7, -authorityDelta);
		DomainManager.Extra.ChangeAreaSpiritualDebt(context, settlement.GetLocation().AreaId, -spiritualDebtDelta);
		lifeRecordCollection.AddTaiwuPunishmentTongyong(taiwuCharId, date, settlementId, authorityDelta, settlement.GetLocation(), spiritualDebtDelta / 10);
		switch (orgTemplateId)
		{
		case 1:
		{
			short delta2 = config.ShaolinDelta;
			HashSet<int> relatedCharIds = new HashSet<int>();
			DomainManager.Character.GetAllRelatedCharIds(taiwuCharId, relatedCharIds);
			foreach (int charId in relatedCharIds)
			{
				DomainManager.Character.ChangeFavorabilityTendToZero(context, charId, taiwuCharId, delta2);
			}
			lifeRecordCollection.AddTaiwuPunishmentShaolin(taiwuCharId, date);
			break;
		}
		case 2:
		{
			sbyte duration7 = AddTaiwuPunishmentFeature(orgTemplateId, severity);
			lifeRecordCollection.AddTaiwuPunishmentEmei(taiwuCharId, date, duration7);
			break;
		}
		case 3:
		{
			taiwu.SetCurrNeili(0, context);
			NeiliAllocation neiliAllocation = default(NeiliAllocation);
			neiliAllocation.Initialize();
			taiwu.SetBaseNeiliAllocation(neiliAllocation, context);
			sbyte duration5 = AddTaiwuPunishmentFeature(orgTemplateId, severity);
			lifeRecordCollection.AddTaiwuPunishmentBaihua(taiwuCharId, date, duration5);
			break;
		}
		case 4:
		{
			sbyte duration4 = AddTaiwuPunishmentFeature(orgTemplateId, severity);
			lifeRecordCollection.AddTaiwuPunishmentWudang(taiwuCharId, date, duration4);
			break;
		}
		case 5:
		{
			List<int> delta = config.YuanshanDelta;
			taiwu.ChangeHappiness(context, delta[0]);
			taiwu.ChangeXiangshuInfection(context, delta[1]);
			lifeRecordCollection.AddTaiwuPunishmentYuanshan(taiwuCharId, date);
			break;
		}
		case 6:
		{
			sbyte duration = AddTaiwuPunishmentFeature(orgTemplateId, severity);
			lifeRecordCollection.AddTaiwuPunishmentShingXiang(taiwuCharId, date, duration);
			break;
		}
		case 7:
		{
			sbyte duration9 = AddTaiwuPunishmentFeature(orgTemplateId, severity);
			lifeRecordCollection.AddTaiwuPunishmentRanShan(taiwuCharId, date, duration9);
			break;
		}
		case 8:
		{
			sbyte duration8 = AddTaiwuPunishmentFeature(orgTemplateId, severity);
			lifeRecordCollection.AddTaiwuPunishmentXuanNv(taiwuCharId, date, duration8);
			break;
		}
		case 9:
			taiwu.ChangeCurrAge(context, config.ZhujianDelta);
			lifeRecordCollection.AddTaiwuPunishmentZhuJian(taiwuCharId, date);
			break;
		case 10:
		{
			Span<short> poisons = stackalloc short[6] { 8, 17, 26, 35, 44, 53 };
			int count3 = config.KongsangDelta;
			for (int l = 0; l < count3; l++)
			{
				taiwu.ApplyEatingItemInstantEffects(context, 8, poisons[context.Random.Next(6)]);
			}
			lifeRecordCollection.AddTaiwuPunishmentKongSang(taiwuCharId, date, count3);
			break;
		}
		case 11:
		{
			sbyte duration6 = AddTaiwuPunishmentFeature(orgTemplateId, severity);
			lifeRecordCollection.AddTaiwuPunishmentJinGang(taiwuCharId, date, duration6);
			break;
		}
		case 12:
		{
			int count2 = config.WuxianDelta;
			Span<sbyte> span = stackalloc sbyte[8];
			SpanList<sbyte> wugs = span;
			for (int j = 0; j < count2; j++)
			{
				sbyte maxSlotCount = taiwu.GetCurrMaxEatingSlotsCount();
				EatingItems eatingItems = taiwu.GetEatingItems();
				if (eatingItems.GetAvailableEatingSlot(maxSlotCount) < 0)
				{
					break;
				}
				wugs.Clear();
				for (sbyte wugType = 0; wugType < 8; wugType++)
				{
					wugs.Add(wugType);
				}
				for (int k = 0; k < 9; k++)
				{
					ItemKey itemKey = (ItemKey)eatingItems.ItemKeys[k];
					if (EatingItems.IsWug(itemKey))
					{
						wugs.Remove(Config.Medicine.Instance[itemKey.TemplateId].WugType);
					}
				}
				if (wugs.Count == 0)
				{
					break;
				}
				sbyte randWug = wugs.GetRandom(context.Random);
				short wugTemplateId = ItemDomain.GetWugTemplateId(randWug, 4);
				taiwu.AddWug(context, wugTemplateId, -1);
			}
			lifeRecordCollection.AddTaiwuPunishmentWuXian(taiwuCharId, date, count2);
			break;
		}
		case 13:
		{
			sbyte duration3 = AddTaiwuPunishmentFeature(orgTemplateId, severity);
			lifeRecordCollection.AddTaiwuPunishmentJieQing(taiwuCharId, date, duration3);
			break;
		}
		case 14:
		{
			sbyte duration2 = AddTaiwuPunishmentFeature(orgTemplateId, severity);
			lifeRecordCollection.AddTaiwuPunishmentFuLong(taiwuCharId, date, duration2);
			break;
		}
		case 15:
		{
			int count = config.XuehouDelta;
			Span<sbyte> bodyPartTypes = stackalloc sbyte[7] { 0, 1, 2, 3, 4, 5, 6 };
			CollectionUtils.Shuffle(context.Random, bodyPartTypes, 7);
			for (int i = 0; i < count; i++)
			{
				sbyte bodyPart = bodyPartTypes[i];
				bool isInner = context.Random.NextBool();
				short featureId = (isInner ? BreakFeatureHelper.BodyPart2HurtFeature[bodyPart] : BreakFeatureHelper.BodyPart2CrashFeature[bodyPart]);
				taiwu.ChangeInjury(context, bodyPart, isInner, 4);
				if (!taiwu.GetFeatureIds().Contains(featureId))
				{
					taiwu.AddFeature(context, featureId);
					DomainManager.SpecialEffect.Add(context, taiwu.GetId(), SpecialEffectDomain.BreakBodyFeatureEffectClassName[featureId]);
				}
				taiwu.AddFeature(context, featureId);
			}
			lifeRecordCollection.AddTaiwuPunishmentXueHou(taiwuCharId, date, count);
			break;
		}
		}
	}

	public static sbyte AddTaiwuPunishmentFeature(sbyte orgTemplateId, sbyte severity)
	{
		DataContext context = Domain.MainThreadDataContext;
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		int taiwuId = taiwu.GetId();
		List<short> group = Config.Organization.Instance[orgTemplateId].TaiwuPunishementFeature;
		bool flag = ((orgTemplateId == 2 || orgTemplateId == 7) ? true : false);
		short featureId = (flag ? group[0] : group[severity]);
		sbyte duration = CharacterFeature.Instance[group[severity]].Duration;
		if (DomainManager.Character.TryGetTemporaryFeatureExpireDate(taiwuId, featureId, out var date))
		{
			DomainManager.Character.RegisterCharacterTemporaryFeature(context, taiwuId, featureId, date + duration);
		}
		else
		{
			taiwu.AddFeature(context, featureId);
			DomainManager.Character.RegisterCharacterTemporaryFeature(context, taiwuId, featureId, DomainManager.World.GetCurrDate() + duration);
		}
		return duration;
	}

