	public static sbyte GetProfessionFavorabilityType(sbyte behaviorType)
	{
		if (behaviorType == 0 || behaviorType == 1)
		{
			return 3;
		}
		switch (behaviorType)
		{
		case 2:
			return 4;
		default:
			if (behaviorType != 4)
			{
				return 3;
			}
			goto case 3;
		case 3:
			return 5;
		}
	}

