	public static sbyte GetDukeSkill2ItemGrade(GameData.Domains.Character.Character character)
	{
		sbyte behaviorType = character.GetBehaviorType();
		int score = ProfessionRelatedConstants.BehaviorTypeScore[behaviorType];
		score += FavorabilityType.GetFavorabilityType(DomainManager.Character.GetFavorability(character.GetId(), DomainManager.Taiwu.GetTaiwuCharId()));
		if (score < 0)
		{
			if (CheckProbability(5))
			{
				return 6;
			}
			if (CheckProbability(25))
			{
				return 5;
			}
			if (CheckProbability(30))
			{
				return 4;
			}
			return 3;
		}
		if (score < 4)
		{
			if (CheckProbability(5))
			{
				return 7;
			}
			if (CheckProbability(25))
			{
				return 6;
			}
			if (CheckProbability(30))
			{
				return 5;
			}
			return 4;
		}
		if (CheckProbability(5))
		{
			return 8;
		}
		if (CheckProbability(25))
		{
			return 7;
		}
		if (CheckProbability(30))
		{
			return 6;
		}
		return 5;
	}

	public static sbyte GetDukeSkill2ItemGrade(Location location)
	{
		MapAreaItem config = DomainManager.Map.GetElement_Areas(location.AreaId).GetConfig();
		sbyte sectId = MapState.Instance[config.StateID].SectID;
		short rate = GetSectApprovingRate(sectId);
		int randomValue = GetRandom(0, 75);
		if (rate <= 300)
		{
			if (randomValue < 5)
			{
				return 6;
			}
			if (randomValue < 15)
			{
				return 5;
			}
			if (randomValue < 35)
			{
				return 4;
			}
			return 3;
		}
		if (rate <= 600)
		{
			if (randomValue < 5)
			{
				return 7;
			}
			if (randomValue < 15)
			{
				return 6;
			}
			if (randomValue < 35)
			{
				return 5;
			}
			return 4;
		}
		if (randomValue < 5)
		{
			return 8;
		}
		if (randomValue < 15)
		{
			return 7;
		}
		if (randomValue < 35)
		{
			return 6;
		}
		return 5;
	}

	public static sbyte GetDukeSkill2WestItemGrade(GameData.Domains.Character.Character character)
	{
		sbyte favorabilityType = FavorabilityType.GetFavorabilityType(DomainManager.Character.GetFavorability(character.GetId(), DomainManager.Taiwu.GetTaiwuCharId()));
		List<sbyte> grades = ObjectPool<List<sbyte>>.Instance.Get();
		grades.Clear();
		if (favorabilityType == 6)
		{
			grades.Add(6);
			grades.Add(7);
			grades.Add(8);
		}
		else
		{
			grades.Add(5);
			grades.Add(6);
			grades.Add(7);
		}
		sbyte grade = grades[GetRandom(0, grades.Count)];
		ObjectPool<List<sbyte>>.Instance.Return(grades);
		return grade;
	}

