	public static void BecomeBuddhistMonk(GameData.Domains.Character.Character character)
	{
		DataContext context = Domain.MainThreadDataContext;
		character.BecomeMonkType(context, 2);
		AvatarData avatar = character.GetAvatar();
		avatar.ResetGrowableElementShowingAbility(0);
		character.SetAvatar(avatar, context);
		SecretInformationCollection secretInformationCollection = DomainManager.Information.GetSecretInformationCollection();
		int charId = character.GetId();
		int taiwuId = DomainManager.Taiwu.GetTaiwuCharId();
		if (RelationTypeHelper.AllowAddingMentorRelation(charId, taiwuId))
		{
			int currDate = DomainManager.World.GetCurrDate();
			DomainManager.Character.AddRelation(Domain.MainThreadDataContext, charId, taiwuId, 2048, currDate);
			int secretInfoOffset1 = secretInformationCollection.AddBecomeMaster(charId, taiwuId);
			DomainManager.Information.AddSecretInformation(context, secretInfoOffset1);
			int secretInfoOffset2 = secretInformationCollection.AddBecomeApprentice(taiwuId, charId);
			DomainManager.Information.AddSecretInformation(context, secretInfoOffset2);
		}
		int secretInfoOffset3 = secretInformationCollection.AddBecomeMonk(character.GetId(), character.GetLocation());
		DomainManager.Information.AddSecretInformation(context, secretInfoOffset3);
	}

	public static bool BuddhistMonkSkill3_CheckCanSelectFeature(short featureId)
	{
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		sbyte fameType = taiwu.GetFameType();
		if ((fameType == -2 || fameType == 3) ? true : false)
		{
			return true;
		}
		if (FameType.IsNonNegative(fameType))
		{
			return featureId >= 242 && featureId < 247;
		}
		return featureId >= 247 && featureId < 252;
	}

	public static void BuddhistMonkSkill2_Execute(EventArgBox argBox)
	{
		if (!argBox.Get("SelectedCharId", out CharacterSet charIds))
		{
			return;
		}
		int count = 0;
		foreach (int charId in charIds.GetCollection())
		{
			if (IsAvailableCharacterId(charId))
			{
				AddSavedSoul(charId);
				count++;
			}
		}
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		LifeRecordCollection lifeRecordCollection = GetLifeRecordCollection();
		int currDate = GetGameDate();
		Location location = taiwu.GetLocation();
		lifeRecordCollection.AddExpiateDeadSouls(taiwu.GetId(), currDate, location);
		DomainManager.World.GetInstantNotificationCollection().AddReleaseSouls(count);
	}

