	public static short GetDisorderOfQi(ItemKey itemKey, GameData.Domains.Character.Character character)
	{
		if (itemKey.ItemType != 9)
		{
			throw new Exception($"Invalid item type: {itemKey.ItemType}");
		}
		TeaWineItem config = Config.TeaWine.Instance[itemKey.TemplateId];
		short recoveryOfQiDisorder = character.GetRecoveryOfQiDisorder();
		return (short)(Math.Abs(config.DirectChangeOfQiDisorder) * (100 - recoveryOfQiDisorder / 20) / 100);
	}

	public static void AddEatingItemTogether(GameData.Domains.Character.Character taiwu, GameData.Domains.Character.Character other, ItemKey itemKey)
	{
		Tester.Assert(taiwu.GetId() == DomainManager.Taiwu.GetTaiwuCharId());
		Tester.Assert(itemKey.ItemType == 9);
		short itemSubType = ItemTemplateHelper.GetItemSubType(itemKey.ItemType, itemKey.TemplateId);
		bool isImmune = (itemSubType == 900 && DomainManager.Extra.IsProfessionalSkillUnlocked(16, 1)) || (itemSubType == 901 && DomainManager.Extra.IsProfessionalSkillUnlocked(7, 1));
		DataContext context = Domain.MainThreadDataContext;
		taiwu.RemoveInventoryItem(context, itemKey, 1, deleteItem: false);
		if (isImmune)
		{
			PoisonInts poisoned = taiwu.GetPoisoned();
			taiwu.AddEatingItem(context, itemKey);
			taiwu.SetPoisoned(ref poisoned, context);
		}
		else
		{
			taiwu.AddEatingItem(context, itemKey);
		}
		ItemKey copyItem = DomainManager.Item.CreateCopyOfItem(context, itemKey);
		other.AddEatingItem(context, copyItem);
	}

	public static (Location, int, short) GetAnimalHunterFight(GameData.Domains.Character.Character taiwu)
	{
		ProfessionData profession = DomainManager.Extra.GetProfessionData(1);
		Location taiwuLocation = taiwu.GetLocation();
		if (profession == null || !DomainManager.Extra.TryGetAnimalAttackInRange(taiwuLocation, 2, isTaiwuVictim: true, out var result))
		{
			return (Location.Invalid, -1, -1);
		}
		sbyte canGetGrade = profession.GetSeniorityCallAnimalGrade();
		foreach (var pair in result)
		{
			if (DomainManager.Extra.TryGetAnimal(pair.Item2, out var animal) && Config.Character.Instance[animal.CharacterTemplateId].RandomAnimalAttack)
			{
				sbyte carrierGrade = GetCarrierGradeByAnimal(animal.CharacterTemplateId);
				if (carrierGrade > canGetGrade)
				{
					DomainManager.Extra.TryGetAnimal(pair.Item2, out animal);
					return (pair.Item1, pair.Item2, animal.CharacterTemplateId);
				}
			}
		}
		return (Location.Invalid, -1, -1);
	}

