	public static Dictionary<Location, List<short>> GetAnimalHunterCanGet(GameData.Domains.Character.Character taiwu)
	{
		ProfessionData profession = DomainManager.Extra.GetProfessionData(1);
		Location taiwuLocation = taiwu.GetLocation();
		if (profession == null || !DomainManager.Extra.TryGetAnimalAttackInRange(taiwuLocation, 2, isTaiwuVictim: true, out var result))
		{
			return null;
		}
		Dictionary<Location, List<short>> allAnimal = new Dictionary<Location, List<short>>();
		sbyte canGetGrade = profession.GetSeniorityCallAnimalGrade();
		foreach (var (location, animalId) in result)
		{
			if (!DomainManager.Extra.TryGetAnimal(animalId, out var animal))
			{
				continue;
			}
			sbyte carrierGrade = GetCarrierGradeByAnimal(animal.CharacterTemplateId);
			if (carrierGrade <= canGetGrade)
			{
				if (!allAnimal.ContainsKey(location))
				{
					allAnimal.Add(location, new List<short>());
				}
				allAnimal[location].Add(animal.CharacterTemplateId);
			}
		}
		return allAnimal;
	}

	public static List<(ItemKey, int)> HunterGetCarriers(Dictionary<Location, List<short>> animals, ref List<ItemKey> escapeCarriers)
	{
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		List<(ItemKey, int)> itemKeys = new List<(ItemKey, int)>();
		foreach (KeyValuePair<Location, List<short>> pair in animals)
		{
			for (int i = 0; i < pair.Value.Count; i++)
			{
				short animalTemplateId = pair.Value[i];
				if (Config.Character.Instance[animalTemplateId].RandomAnimalAttack)
				{
					ItemKey itemKey = DomainManager.Extra.GetFleeCarrierByLocation(animalTemplateId, pair.Key);
					if (itemKey.IsValid())
					{
						escapeCarriers.Add(itemKey);
						DomainManager.Extra.RemoveFleeCarrierLocation(Domain.MainThreadDataContext, itemKey);
						AddItemToRole(taiwu, itemKey, 1, -1);
					}
					else
					{
						CarrierItem carrierItem = GetCarrierConfigByAnimal(animalTemplateId);
						itemKey = AddItemToRole(taiwu, 4, carrierItem.TemplateId, 1, -1);
					}
					RemoveSingleMapAnimalOnBlock(pair.Key, animalTemplateId);
					itemKeys.Add((itemKey, 1));
				}
			}
		}
		if (itemKeys.Count > 0)
		{
			return itemKeys;
		}
		return null;
	}

