	public static bool HasFriendOrFamilyRelation(int charId)
	{
		return RelationTypeToNormalInteractionType(charId) != ENormalInteractionType.Invalid;
	}

	public static ENormalInteractionType RelationTypeToNormalInteractionType(int charId)
	{
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		if (DomainManager.Character.TryGetRelation(taiwu.GetId(), charId, out var relatedCharacterToTaiwu) && DomainManager.Character.TryGetRelation(charId, taiwu.GetId(), out var relatedCharacterToCharacter))
		{
			if (RelationType.HasRelation(relatedCharacterToTaiwu.RelationType, 512) || RelationType.HasRelation(relatedCharacterToTaiwu.RelationType, 8192) || RelationType.HasRelation(relatedCharacterToTaiwu.RelationType, 256) || RelationType.HasRelation(relatedCharacterToTaiwu.RelationType, 32) || RelationType.HasRelation(relatedCharacterToTaiwu.RelationType, 4))
			{
				return ENormalInteractionType.FriendSet;
			}
			if (RelationType.HasRelation(relatedCharacterToTaiwu.RelationType, 1024) || (RelationType.HasRelation(relatedCharacterToTaiwu.RelationType, 16384) && RelationType.HasRelation(relatedCharacterToCharacter.RelationType, 16384)))
			{
				return ENormalInteractionType.LoveSet;
			}
			if (RelationType.HasRelation(relatedCharacterToTaiwu.RelationType, 128) || RelationType.HasRelation(relatedCharacterToTaiwu.RelationType, 2) || RelationType.HasRelation(relatedCharacterToTaiwu.RelationType, 16))
			{
				return ENormalInteractionType.ChildSet;
			}
			if (RelationType.HasRelation(relatedCharacterToTaiwu.RelationType, 64) || RelationType.HasRelation(relatedCharacterToTaiwu.RelationType, 1) || RelationType.HasRelation(relatedCharacterToTaiwu.RelationType, 8))
			{
				return ENormalInteractionType.ParentSet;
			}
			if (RelationType.HasRelation(relatedCharacterToTaiwu.RelationType, 2048))
			{
				return ENormalInteractionType.TeacherSet;
			}
		}
		return ENormalInteractionType.Invalid;
	}

