	public static void ExecuteFriendOrFamilySendGift(int charId, EventArgBox argBox)
	{
		if (DomainManager.Character.TryGetElement_Objects(charId, out var character))
		{
			DataContext context = Domain.MainThreadDataContext;
			GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
			bool addExp = false;
			bool isMiscResource = false;
			if (argBox.Get("AddExp", ref addExp) && addExp)
			{
				int expCount = 0;
				argBox.Get("AddExpCount", ref expCount);
				ChangeRoleExp(taiwu, expCount);
			}
			else if (argBox.Get("IsMiscResource", ref isMiscResource) && isMiscResource)
			{
				sbyte resourceType = 0;
				int resourceCount = 0;
				argBox.Get("ResourceType", ref resourceType);
				argBox.Get("Count", ref resourceCount);
				ChangeRoleResource(character, resourceType, -resourceCount);
				ChangeRoleResource(taiwu, resourceType, resourceCount);
			}
			else
			{
				argBox.Get("ItemKey", out ItemKey itemKey);
				character.RemoveInventoryItem(context, itemKey, 1, deleteItem: false);
				taiwu.AddInventoryItem(context, itemKey, 1);
			}
			sbyte cooldown = 0;
			argBox.Get("Cooldown", ref cooldown);
		}
	}

	public static void RequestDemandAgree(EventArgBox argBox)
	{
		short monthlyEventTemplateId = -1;
		argBox.Get("MonthlyEventTemplateId", ref monthlyEventTemplateId);
		switch (monthlyEventTemplateId)
		{
		case 0:
			RequestHealOuterInjuryByItemAgree(argBox);
			break;
		case 1:
			RequestHealInnerInjuryByItemAgree(argBox);
			break;
		case 2:
			RequestHealPoisonByItemAgree(argBox);
			break;
		case 3:
			RequestHealthAgree(argBox);
			break;
		case 4:
			RequestHealDisorderOfQiAgree(argBox);
			break;
		case 5:
			RequestNeiliAgree(argBox);
			break;
		case 6:
			RequestKillWugAgree(argBox);
			break;
		case 7:
			RequestFoodAgree(argBox);
			break;
		case 8:
			RequestTeaWineAgree(argBox);
			break;
		case 9:
			RequestResourceAgree(argBox);
			break;
		case 10:
			RequestItemAgree(argBox);
			break;
		case 11:
			RequestRepairItemAgree(argBox);
			break;
		case 12:
			RequestAddPoisonToItemAgree(argBox);
			break;
		case 13:
			RequestInstructionOnReadingLifeSkillAgree(argBox);
			break;
		case 15:
			RequestInstructionOnBreakoutAgree(argBox);
			break;
		}
	}

