	public static void CostSecretInformationUsedCount(int charId, int secretId)
	{
		DomainManager.Information.EditCharacterKnownSecret(Domain.MainThreadDataContext, charId, delegate(CharacterKnownSecret known)
		{
			int num = (IsSecretInformationBroadcast(secretId) ? GlobalConfig.Instance.SecretInformationInBroadcastMaxUseCount : GlobalConfig.Instance.SecretInformationInPrivateMaxUseCount);
			SecretInformationId key = (SecretInformationId)secretId;
			known.UsedCounts.TryGetValue(key, out var value);
			value++;
			known.UsedCounts[key] = value;
			if (value > num)
			{
				AdaptableLog.Error($"taiwu({charId}) used secret information {secretId} in {value} times(max: {num})");
			}
		});
	}

