	public static bool DisseminateSecretInformationFromTaiwu(int secretId, int targetCharId)
	{
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		int taiwuCharId = taiwu.GetId();
		InformationDomain informationDomain = DomainManager.Information;
		GameData.Domains.Information.Secret.SecretInformation secret = informationDomain.QuerySecretInformation((SecretInformationId)secretId);
		SecretOccurence occurence;
		byte[] secretParams = secret.QueryParameters(out occurence);
		int cost = informationDomain.CalcSecretInformationAuthorityCostWhenDisseminatingByCharacter(occurence.TemplateId, taiwu.GetFameType(), informationDomain.CalcSecretInformationKnownCharacterCount(secret.Id));
		CostSecretInformationUsedCount(taiwuCharId, secretId);
		SecretInformationItem config = Config.SecretInformation.Instance.GetItem(occurence.TemplateId);
		HashSet<SecretInformationRelationshipType> relationshipTypes = new HashSet<SecretInformationRelationshipType>();
		int actorId = -1;
		int reactorId = -1;
		secretParams.ExtractSecretParameters(config, delegate(int index, int charId)
		{
			switch (index)
			{
			case 0:
				actorId = charId;
				break;
			case 1:
				reactorId = charId;
				break;
			}
		});
		if (actorId != -1)
		{
			informationDomain.CheckSecretInformationRelationship(actorId, SecretOccurenceId.Invalid, targetCharId, SecretOccurenceId.Invalid, relationshipTypes);
		}
		if (reactorId != -1)
		{
			informationDomain.CheckSecretInformationRelationship(reactorId, SecretOccurenceId.Invalid, targetCharId, SecretOccurenceId.Invalid, relationshipTypes);
		}
		if (relationshipTypes.Contains(SecretInformationRelationshipType.Enemy) || relationshipTypes.Contains(SecretInformationRelationshipType.Relative) || relationshipTypes.Contains(SecretInformationRelationshipType.Friend) || actorId == targetCharId || reactorId == targetCharId)
		{
			ProfessionFormulaItem formula = ProfessionFormula.Instance[34];
			int addSeniority = formula.Calculate(cost, config.SortValue);
			DomainManager.Extra.ChangeProfessionSeniority(Domain.MainThreadDataContext, 4, addSeniority);
		}
		if (DistributeSecretInformationToCharacter(secretId, targetCharId, taiwuCharId))
		{
			ChangeRoleResource(taiwu, 7, -Math.Min(taiwu.GetResource(7), cost));
			ProfessionFormulaItem formula2 = ProfessionFormula.Instance[33];
			int addSeniority2 = formula2.Calculate(cost, config.SortValue);
			DomainManager.Extra.ChangeProfessionSeniority(Domain.MainThreadDataContext, 4, addSeniority2);
			return true;
		}
		return false;
	}

