	public static List<int> PickUsableSecretInformationFromMetaDataIdList(int charId, List<int> sourceSecretIds)
	{
		List<int> result = new List<int>();
		DomainManager.Information.TryGetCharacterKnownSecret(charId, out var known);
		int i = 0;
		for (int len = sourceSecretIds.Count; i < len; i++)
		{
			int secretId = sourceSecretIds[i];
			int maxUsedCount = (IsSecretInformationBroadcast(secretId) ? GlobalConfig.Instance.SecretInformationInBroadcastMaxUseCount : GlobalConfig.Instance.SecretInformationInPrivateMaxUseCount);
			int usedCount = 0;
			known?.UsedCounts?.TryGetValue((SecretInformationId)secretId, out usedCount);
			if (usedCount < maxUsedCount)
			{
				result.Add(secretId);
			}
		}
		return result;
	}

