	public static HashSet<int> GetSecretInformationRelatedCharacters(int secretId, int characterId, bool includeGeneral = true, bool includeAlive = true, bool includeDead = true)
	{
		HashSet<int> result = new HashSet<int>();
		GameData.Domains.Information.Secret.SecretInformation secret = DomainManager.Information.QuerySecretInformation((SecretInformationId)secretId);
		if (secret != null)
		{
			secret.QueryParameters(out var occurence);
			if (occurence.CharacterRelationshipSnapshotCollection.TryGetValue(characterId, out CharacterRelationshipSnapshot characterRelationshipSnapshot))
			{
				Dictionary<int, CharacterExtraInfo> dict2 = occurence.CharacterExtraInfoCollection;
				characterRelationshipSnapshot.RelatedCharacters.GetAllRelatedCharIds(result, includeGeneral);
				if (!includeAlive)
				{
					result.RemoveWhere((int charId) => dict2.TryGetValue(charId, out var value) && value.AliveState == 0);
				}
				if (!includeDead)
				{
					result.RemoveWhere((int charId) => dict2.TryGetValue(charId, out var value) && value.AliveState != 0);
				}
			}
		}
		return result;
	}

	public static List<int> GetSecretInformationInitialCharacterIds(int secretId)
	{
		HashSet<int> result = new HashSet<int>();
		HashSet<int> keyChars = new HashSet<int>();
		GameData.Domains.Information.Secret.SecretInformation secret = DomainManager.Information.QuerySecretInformation((SecretInformationId)secretId);
		SecretOccurence occurence;
		byte[] secretParams = secret.QueryParameters(out occurence);
		SecretInformationItem config = Config.SecretInformation.Instance.GetItem(occurence.TemplateId);
		HashSet<int> set = ObjectPool<HashSet<int>>.Instance.Get();
		secretParams.ExtractSecretParameters(config, delegate(int idx, int charId)
		{
			keyChars.Add(charId);
			if (DomainManager.Character.TryGetElement_Objects(charId, out var element) && element != null)
			{
				set.Clear();
				switch (config.InitialTarget)
				{
				case ESecretInformationInitialTarget.Area:
					DomainManager.Character.GetAreaPeople(Domain.MainThreadDataContext.Random, element, set, 100);
					break;
				case ESecretInformationInitialTarget.Nearest:
					DomainManager.Character.GetClosePeople(Domain.MainThreadDataContext.Random, element, set, 100);
					break;
				case ESecretInformationInitialTarget.Local:
					DomainManager.Character.GetSameBlockPeople(Domain.MainThreadDataContext.Random, element, set, 100);
					break;
				}
				result.UnionWith(set);
			}
		});
		ObjectPool<HashSet<int>>.Instance.Return(set);
		result.RemoveWhere((int charId) => keyChars.Contains(charId));
		return result.ToList();
	}

