	public static string GetSecretInformationDesc(int secretId, EventArgBox argBox)
	{
		InformationDomain domain = DomainManager.Information;
		GameData.Domains.Information.Secret.SecretInformation secret = domain.QuerySecretInformation((SecretInformationId)secretId);
		List<string> args = new List<string>();
		int taiwuCharId = DomainManager.Taiwu.GetTaiwuCharId();
		SecretInformationItem config;
		secret.QueryParameters(out var occurence).ExtractSecretParameters(config = Config.SecretInformation.Instance[occurence.TemplateId], delegate(int idx, int charId)
		{
			string text = $"SecretArgCharacterId{idx}";
			argBox.Set(text, charId);
			args.Add("<Character key=" + text + " str=Name/>");
		}, delegate(int _, Location location)
		{
			MapAreaData element_Areas = DomainManager.Map.GetElement_Areas(location.AreaId);
			args.Add(element_Areas.GetConfig().Name ?? "");
		}, delegate(int _, sbyte resourceType)
		{
			args.Add(Config.ResourceType.Instance[resourceType].Name);
		}, delegate(int _, ItemKey itemKey)
		{
			args.Add(ItemTemplateHelper.GetName(itemKey.ItemType, itemKey.TemplateId));
		}, delegate(int _, short templateId)
		{
			args.Add(Config.CombatSkill.Instance[templateId].Name);
		}, delegate(int _, short templateId)
		{
			args.Add(LifeSkill.Instance[templateId].Name);
		}, delegate(int _, int intValue)
		{
			args.Add($"{intValue}");
		});
		while (args.Count < 4)
		{
			args.Add(string.Empty);
		}
		int i = 0;
		for (int count = args.Count; i < count; i++)
		{
			args[i] = "<color=#pinkyellow>" + args[i] + "</color>";
		}
		return string.Format(config.Desc, args[0], args[1], args[2], args[3]);
	}

