	public static int GetThreatenEffect(int selfCharId, int targetCharId, int secretId, short templateId)
	{
		int threatenEffect = -1;
		if (!DomainManager.Character.TryGetElement_Objects(selfCharId, out var selfChar) || !DomainManager.Character.TryGetElement_Objects(targetCharId, out var _) || DomainManager.Character.GetFavorability(targetCharId, selfCharId) == short.MinValue)
		{
			return threatenEffect;
		}
		short sortValue = Config.SecretInformation.Instance.GetItem(templateId).SortValue;
		int sortFactor = sortValue * GlobalConfig.Instance.ThreatenEffectFactorOfSortValue;
		threatenEffect = sortFactor;
		int punishLevel = -1;
		if (IsInAnySect(targetCharId))
		{
			SecretInformationProcessor processor = DomainManager.Information.SecretInformationProcessorPool.Get();
			GameData.Domains.Information.Secret.SecretInformation secret = DomainManager.Information.QuerySecretInformation((SecretInformationId)secretId);
			SecretOccurence occurence;
			byte[] secretParams = secret.QueryParameters(out occurence);
			if (!processor.Initialize(occurence, secretParams))
			{
				AdaptableLog.Warning("Initialize SecretInfo ProcessorPool Failed!");
				DomainManager.Information.SecretInformationProcessorPool.Return(processor);
			}
			punishLevel = processor.CalSectPunishLevel_WithCharId(targetCharId);
			DomainManager.Information.SecretInformationProcessorPool.Return(processor);
		}
		punishLevel++;
		if (!IsInAnySect(targetCharId))
		{
			punishLevel = sortValue / 3;
		}
		threatenEffect += threatenEffect * punishLevel * 20 / 100;
		int holderCount = GetSecretInformationHolderCount(secretId);
		byte broadcastLimit = Config.SecretInformation.Instance.GetItem(templateId).MaxPersonAmount;
		if (IsSecretInformationBroadcast(secretId))
		{
			holderCount = broadcastLimit;
		}
		int holderFactor = Math.Clamp(holderCount * 50 / broadcastLimit, 0, 50);
		threatenEffect += threatenEffect * holderFactor / 100;
		sbyte fame = selfChar.GetFame();
		int fameFactor = Math.Abs(fame) / GlobalConfig.Instance.ThreatenEffectDenominatorOfFame;
		threatenEffect += threatenEffect * fameFactor / 100;
		return Math.Clamp(threatenEffect, int.MinValue, int.MaxValue);
	}

	public static int GetThreatenDifficulty(int selfCharId, int targetCharId, int metaDataId)
	{
		int threatenDifficulty = -1;
		if (!DomainManager.Character.TryGetElement_Objects(selfCharId, out var selfChar) || !DomainManager.Character.TryGetElement_Objects(targetCharId, out var targetChar) || DomainManager.Character.GetFavorability(targetCharId, selfCharId) == short.MinValue)
		{
			return threatenDifficulty;
		}
		sbyte targetCharGrade = targetChar.GetInteractionGrade(selfChar);
		sbyte targetCharBehaviorType = targetChar.GetBehaviorType();
		sbyte favorabilityType = FavorabilityType.GetFavorabilityType(DomainManager.Character.GetFavorability(targetCharId, selfCharId));
		int gradeFactor = targetCharGrade * GlobalConfig.Instance.ThreatenDifficultyFactorOfGrade;
		int behaviorFavor = GlobalConfig.Instance.ThreatenDifficultyFactorOfBehaviorType[targetCharBehaviorType];
		int favorFactor = 0;
		if (favorabilityType > 0)
		{
			favorFactor = GlobalConfig.Instance.ThreatenDifficultyFactorOfPositiveFavorType[targetCharBehaviorType];
		}
		if (favorabilityType < 0)
		{
			favorFactor = GlobalConfig.Instance.ThreatenDifficultyFactorOfNegativeFavorType[targetCharBehaviorType];
		}
		return Math.Clamp(Math.Max(gradeFactor + favorFactor * behaviorFavor / 100, 0), int.MinValue, int.MaxValue);
	}

