	public static int GetThreatenFinalDifficultyOfMarry(int origDifficulty, int threatenedCharId, int nominatedCharId)
	{
		if (!DomainManager.Character.TryGetElement_Objects(threatenedCharId, out var threatenedChar) || !DomainManager.Character.TryGetElement_Objects(nominatedCharId, out var nominatedChar))
		{
			return origDifficulty;
		}
		int genderFactor = 0;
		int monkTypeFactor = 0;
		int sectRuleFactor = 0;
		if (threatenedChar.GetBisexual())
		{
			if (nominatedChar.GetGender() != threatenedChar.GetGender() && nominatedChar.GetDisplayingGender() == threatenedChar.GetDisplayingGender())
			{
				genderFactor = 6;
			}
		}
		else if (nominatedChar.GetGender() == threatenedChar.GetGender() && nominatedChar.GetDisplayingGender() != threatenedChar.GetDisplayingGender())
		{
			genderFactor = 6;
		}
		if (threatenedChar.GetMonkType() != 0)
		{
			monkTypeFactor = 6;
		}
		if (!threatenedChar.OrgAndMonkTypeAllowMarriage())
		{
			sectRuleFactor = 12;
		}
		return origDifficulty + genderFactor + monkTypeFactor + sectRuleFactor;
	}

