		}
		int genderAdjust = 0;
		int monkTypeAdjust = 0;
		int sectRuleAdjust = 0;
		if (targetChar.GetBisexual())
		{
			if (selfChar.GetGender() != targetChar.GetGender() && selfChar.GetDisplayingGender() == targetChar.GetDisplayingGender())
			{
				genderAdjust = 3;
				if (isProPosal)
				{
					genderAdjust = 6;
				}
			}
		}
		else if (selfChar.GetGender() == targetChar.GetGender() && selfChar.GetDisplayingGender() != targetChar.GetDisplayingGender())
		{
			genderAdjust = 3;
			if (isProPosal)
			{
				genderAdjust = 6;
			}
		}
