		{
			monkTypeAdjust = 3;
			if (isProPosal)
			{
				monkTypeAdjust = 6;
			}
		}
		if (!targetChar.OrgAndMonkTypeAllowMarriage())
		{
			sectRuleAdjust = 6;
			if (isProPosal)
			{
				sectRuleAdjust = 12;
			}
		}
		return oriDifficulty + genderAdjust + monkTypeAdjust + sectRuleAdjust;
	}

	private static int GetThreadNeedleDifficultyOfStartRelation(int targetCharId, int selectedCharId, ushort relationType, bool isBothWayRelation = true)
	{
		int difficulty = int.MinValue;
		if (!DomainManager.Character.TryGetElement_Objects(targetCharId, out var targetChar) || !DomainManager.Character.TryGetElement_Objects(selectedCharId, out var nominatedChar))
		{
			return difficulty;
		}
		int gradeFactor = SecretInformationConfig.GradeFactor_StartRelation_Difficulty;
		int grade_target = (targetChar.GetInteractionGrade(targetIsTaiwu: true) + 1) * gradeFactor;
		int grade_selected = (nominatedChar.GetInteractionGrade(targetIsTaiwu: true) + 1) * gradeFactor;
		sbyte behavior_target = targetChar.GetBehaviorType();
		sbyte behavior_nominate = nominatedChar.GetBehaviorType();
		int behaviorAdjust_target = SecretInformationConfig.BehaviorAdjust_StartRelation_Difficulty[behavior_target];
		int behaviorAdjust_nominate = SecretInformationConfig.BehaviorAdjust_StartRelation_Difficulty[behavior_nominate];
		difficulty = Math.Clamp(Math.Max(grade_target + behaviorAdjust_target, grade_selected + behaviorAdjust_nominate), int.MinValue, int.MaxValue);
		short favor = GetFavorability(nominatedChar, targetChar);
		sbyte favorType = FavorabilityType.GetFavorabilityType(favor);
		int behaviorFactor = SecretInformationConfig.FavorFactor_StartRelation_Difficulty[behavior_nominate];
		difficulty += Math.Clamp(Math.Max(difficulty - favorType * behaviorFactor / 100, 0), int.MinValue, int.MaxValue);
		switch (relationType)
		{
		case 16384:
			if (isBothWayRelation)
			{
				return GetConfessLoveDifficultyInThreadNeedle(selectedCharId, targetCharId, difficulty);
			}
			if (targetChar.GetBisexual())
			{
				if (nominatedChar.GetGender() != targetChar.GetGender() && nominatedChar.GetDisplayingGender() == targetChar.GetDisplayingGender())
				{
					difficulty += 3;
				}
			}
			else if (nominatedChar.GetGender() == targetChar.GetGender() && nominatedChar.GetDisplayingGender() != targetChar.GetDisplayingGender())
			{
				difficulty += 3;
			}
			return difficulty;
		case 64:
		case 128:
		case 512:
		case 2048:
		case 8192:
			return difficulty;
		case 1024:
			if (nominatedChar.GetActualAge() < 16 || GetAliveSpouse(selectedCharId) != null || GetAliveSpouse(targetCharId) != null)
			{
				return int.MaxValue;
			}
			return GetConfessLoveDifficultyInThreadNeedle(selectedCharId, targetCharId, difficulty, isProPosal: true);
		case 32768:
			return difficulty - 12;
		default:
			return int.MinValue;
		}
	}

	private static int GetThreadNeedleDifficultyOfEndRelation(int targetCharId, int nominatedCharId, ushort relationType, bool isBothWayRelation = true)
	{
		int difficulty = int.MinValue;
		if (!DomainManager.Character.TryGetElement_Objects(targetCharId, out var targetChar) || !DomainManager.Character.TryGetElement_Objects(nominatedCharId, out var nominatedChar))
		{
			return difficulty;
		}
		int gradeFactor = SecretInformationConfig.GradeFactor_EndRelation_Difficulty;
		int grade_target = (targetChar.GetInteractionGrade(targetIsTaiwu: true) + 1) * gradeFactor;
		int grade_nominate = (nominatedChar.GetInteractionGrade(targetIsTaiwu: true) + 1) * gradeFactor;
		sbyte behavior_target = targetChar.GetBehaviorType();
		sbyte behavior_nominate = nominatedChar.GetBehaviorType();
		int behaviorAdjust_target = SecretInformationConfig.BehaviorAdjust_EndRelation_Difficulty[behavior_target];
		int behaviorAdjust_nominate = SecretInformationConfig.BehaviorAdjust_EndRelation_Difficulty[behavior_nominate];
		difficulty = Math.Clamp(Math.Max(grade_target + behaviorAdjust_target, grade_nominate + behaviorAdjust_nominate), int.MinValue, int.MaxValue);
		short favor_NominateToTarget = GetFavorability(nominatedChar, targetChar);
		sbyte favorType_NominateToTarget = FavorabilityType.GetFavorabilityType(favor_NominateToTarget);
		int behaviorFactor = SecretInformationConfig.FavorFactor_EndRelation_Difficulty[behavior_nominate];
		difficulty = Math.Clamp(Math.Max(difficulty + favorType_NominateToTarget * behaviorFactor / 100, 0), int.MinValue, int.MaxValue);
		short favor_TargetToNominate = GetFavorability(targetChar, nominatedChar);
		sbyte favorType_TargetToNominate = FavorabilityType.GetFavorabilityType(favor_TargetToNominate);
		switch (relationType)
		{
		case 16384:
			if (isBothWayRelation)
			{
				return difficulty + favorType_TargetToNominate * 2;
			}
			return difficulty + favorType_TargetToNominate;
		case 8192:
			return difficulty + favorType_TargetToNominate;
		case 64:
		case 128:
		case 512:
		case 1024:
		case 2048:
			return difficulty + favorType_TargetToNominate * 2;
		case 32768:
			return difficulty - 12;
		default:
			return int.MinValue;
		}
	}

	private static int GetThreadNeedleEffectOfStartRelation(int promotedCharId, int targetCharId, int nominatedCharId, int secretId)
	{
		int effect = int.MinValue;
		if (!DomainManager.Character.TryGetElement_Objects(targetCharId, out var targetChar) || !DomainManager.Character.TryGetElement_Objects(nominatedCharId, out var _) || !DomainManager.Character.TryGetElement_Objects(promotedCharId, out var promotedChar))
		{
			return effect;
		}
		SecretInformationProcessor processor = DomainManager.Information.SecretInformationProcessorPool.Get();
		GameData.Domains.Information.Secret.SecretInformation secret = DomainManager.Information.QuerySecretInformation((SecretInformationId)secretId);
		SecretOccurence occurence;
		byte[] secretParams = secret.QueryParameters(out occurence);
		if (!processor.Initialize(occurence, secretParams))
		{
			throw new Exception($"Can not Initialize Processor Of {secret.Id}!");
		}
		short templateId = processor.GetSecretInformationTemplateId();
		short sortValue = Config.SecretInformation.Instance.GetItem(templateId).SortValue;
		int sortFactor = SecretInformationConfig.SortValueFactor_StartRelation_Effect;
		effect = sortValue * sortFactor;
		int holderCount = GetSecretInformationHolderCount(secretId);
		int holderFactor = SecretInformationConfig.HolderCountFactor_StartRelation_Effect;
		byte broadcastLimit = Config.SecretInformation.Instance.GetItem(templateId).MaxPersonAmount;
		if (IsSecretInformationBroadcast(secretId))
		{
			holderCount = broadcastLimit;
		}
		int holderAdjust = Math.Clamp(holderCount * holderFactor / broadcastLimit, 0, 50);
		effect = effect * (100 + holderAdjust) / 100;
		short favor = GetFavorability(targetChar, promotedChar);
		sbyte favorType = FavorabilityType.GetFavorabilityType(favor);
		sbyte behaviorType = targetChar.GetBehaviorType();
		int favorfactor = SecretInformationConfig.FavorFactor_StartRelation_Effect[behaviorType];
		effect = Math.Max(effect + favorType * favorfactor / 100, 0);
		sbyte fame_promote = promotedChar.GetFame();
		int fameDenominater = SecretInformationConfig.FameDenominator_StartRelation_Effect;
		int fameAdjust = fame_promote / fameDenominater;
		return effect * (100 + fameAdjust) / 100;
	}

