	public static int ApplyThreadNeedle_StartRelation(EventArgBox argBox, ushort relationType, bool isBothWayRelation = true)
	{
		int taiwuId = EventArgBox.TaiwuCharacterId;
		int charId = -1;
		argBox.Get("CharacterId", ref charId);
		int selectedCharId = -1;
		argBox.Get("SelectedCharIdForThreadNeedleAdding", ref selectedCharId);
		int metaDataId = -1;
		argBox.Get("metaDataIdForThreaten", ref metaDataId);
		if (taiwuId == -1 || charId == -1 || selectedCharId == -1 || metaDataId == -1)
		{
			throw new Exception("Wrong Ids In ThreadNeedle Event !");
		}
		int difficulty = int.MinValue;
		int effect = int.MinValue;
		if (relationType != 32768)
		{
			difficulty = GetThreadNeedleDifficultyOfStartRelation(charId, selectedCharId, relationType, isBothWayRelation);
			effect = GetThreadNeedleEffectOfStartRelation(taiwuId, charId, selectedCharId, metaDataId);
		}
		else
		{
			difficulty = GetThreadNeedleDifficultyOfEndRelation(charId, selectedCharId, relationType, isBothWayRelation);
			effect = GetThreadNeedleEffectOfEndRelation(taiwuId, charId, selectedCharId, metaDataId);
		}
		if (difficulty == int.MinValue || effect == int.MinValue)
		{
			throw new Exception("Wrong Values Of ThreadNeedle Event!");
		}
		CostSecretInformationUsedCount(taiwuId, metaDataId);
		if (effect >= difficulty)
		{
			if (CheckStartRelationSucceed(charId, selectedCharId, relationType, isBothWayRelation))
			{
				if (taiwuId == selectedCharId)
				{
					ApplyStartRelationByThreadNeedle(charId, selectedCharId, relationType, succeed: true, isBothWayRelation);
					return 3;
				}
				ApplyStartRelationByThreadNeedle(charId, selectedCharId, relationType, succeed: true, isBothWayRelation);
				return 4;
			}
			ApplyStartRelationByThreadNeedle(charId, selectedCharId, relationType, succeed: false, isBothWayRelation);
			return 2;
		}
		if (taiwuId == selectedCharId)
		{
			return 0;
		}
		return 1;
	}

	public static int ApplyThreadNeedle_EndRelation(EventArgBox argBox, ushort relationType, bool isBothWayRelation = true)
	{
		int taiwuId = EventArgBox.TaiwuCharacterId;
		int charId = -1;
		argBox.Get("CharacterId", ref charId);
		int selectedCharId = -1;
		argBox.Get("SelectedCharIdForThreadNeedleEnding", ref selectedCharId);
		int metaDataId = -1;
		argBox.Get("metaDataIdForThreaten", ref metaDataId);
		if (taiwuId == -1 || charId == -1 || selectedCharId == -1 || metaDataId == -1)
		{
			throw new Exception("Wrong Ids In ThreadNeedle Event !");
		}
		int difficulty = int.MinValue;
		int effect = int.MinValue;
		if (relationType != 32768)
		{
			difficulty = GetThreadNeedleDifficultyOfEndRelation(charId, selectedCharId, relationType, isBothWayRelation);
			effect = GetThreadNeedleEffectOfEndRelation(taiwuId, charId, selectedCharId, metaDataId);
		}
		else
		{
			difficulty = GetThreadNeedleDifficultyOfStartRelation(charId, selectedCharId, relationType, isBothWayRelation);
			effect = GetThreadNeedleEffectOfStartRelation(taiwuId, charId, selectedCharId, metaDataId);
		}
		if (difficulty == int.MinValue || effect == int.MinValue)
		{
			throw new Exception("Wrong Values Of ThreadNeedle Event!");
		}
		CostSecretInformationUsedCount(taiwuId, metaDataId);
		if (effect >= difficulty)
		{
			if (CheckEndRelationSucceed(charId, selectedCharId, relationType, isBothWayRelation))
			{
				if (taiwuId == selectedCharId)
				{
					ApplyEndRelationByThreadNeedle(charId, selectedCharId, relationType, succeed: true, isBothWayRelation);
					return 8;
				}
				ApplyEndRelationByThreadNeedle(charId, selectedCharId, relationType, succeed: true, isBothWayRelation);
				return 9;
			}
			if (relationType == 16384 || relationType == 32768)
			{
				ApplyEndRelationByThreadNeedle(charId, selectedCharId, relationType, succeed: false, isBothWayRelation);
				return 9;
			}
			return 7;
		}
		if (taiwuId == selectedCharId)
		{
			return 5;
		}
		return 6;
	}

