	public static List<GameData.Domains.Character.Character> SetSectMemberApproveTaiwu(sbyte sectId, byte countMax, sbyte gradeMin = 0, sbyte gradeMax = 8)
	{
		List<GameData.Domains.Character.Character> allMembers = GetSectCharListWithInfantFilter(sectId, 0, 8);
		for (int i = allMembers.Count - 1; i >= 0; i--)
		{
			if (!IsSectCharApprovedTaiwu(allMembers[i].GetId()))
			{
				OrganizationInfo orgInfo = allMembers[i].GetOrganizationInfo();
				if (orgInfo.Grade > gradeMax || orgInfo.Grade < gradeMin)
				{
					allMembers.RemoveAt(i);
				}
			}
		}
		countMax = (byte)Math.Min(countMax, allMembers.Count);
		List<GameData.Domains.Character.Character> retList = new List<GameData.Domains.Character.Character>();
		CollectionUtils.Shuffle(Domain.MainThreadDataContext.Random, allMembers);
		for (int j = 0; j < countMax; j++)
		{
			SetSectCharApprovedTaiwu(allMembers[j].GetId());
			retList.Add(allMembers[j]);
		}
		return retList;
	}

