	public static void RecommendPupil(int charId, GameData.Domains.Character.Character student, short settlementId)
	{
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		ChangeRoleResource(taiwu, 7, -200);
		RequestRoleLeaveGroup(charId);
		JoinOrganization(student, settlementId, 0);
		OrganizationMemberItem orgMemberConfig = OrganizationDomain.GetOrgMemberConfig(student.GetOrganizationInfo());
		int addSeniority = 0;
		for (sbyte i = 0; i < orgMemberConfig.LifeSkillsAdjust.Length; i++)
		{
			short adjust = orgMemberConfig.LifeSkillsAdjust[i];
			if (adjust >= 0)
			{
				short value = student.GetLifeSkillQualification(i);
				AddSeniority(value, adjust);
			}
		}
		for (sbyte i2 = 0; i2 < orgMemberConfig.CombatSkillsAdjust.Length; i2++)
		{
			short adjust2 = orgMemberConfig.CombatSkillsAdjust[i2];
			if (adjust2 >= 0)
			{
				short value2 = student.GetCombatSkillQualification(i2);
				AddSeniority(value2, adjust2);
			}
		}
		for (sbyte i3 = 0; i3 < orgMemberConfig.MainAttributesAdjust.Length; i3++)
		{
			short adjust3 = orgMemberConfig.MainAttributesAdjust[i3];
			if (adjust3 >= 0)
			{
				short value3 = student.GetMaxMainAttribute(i3);
				AddSeniority(value3, adjust3);
			}
		}
		DataContext context = Domain.MainThreadDataContext;
		if (addSeniority > 0)
		{
			DomainManager.Extra.ChangeProfessionSeniority(context, 8, addSeniority);
		}
		void AddSeniority(short arg, short arg2)
		{
			ProfessionFormulaItem formula = ProfessionFormula.Instance[59];
			addSeniority += formula.Calculate(arg, arg2);
		}
	}

	public static void JoinOrganization(GameData.Domains.Character.Character character, short settlementId, sbyte grade)
	{
		DataContext context = Domain.MainThreadDataContext;
		int charId = character.GetId();
		DomainManager.Adventure.DynamicUnbindCharacterAndUnhideFromMap(context, character);
		if (DomainManager.Character.IsTemporaryIntelligentCharacter(charId))
		{
			DomainManager.Character.ConvertTemporaryIntelligentCharacter(context, character);
		}
		OrganizationInfo originalOrgInfo = character.GetOrganizationInfo();
		Settlement settlement = DomainManager.Organization.GetSettlement(settlementId);
		if (originalOrgInfo.OrgTemplateId == settlement.GetOrgTemplateId())
		{
			if (originalOrgInfo.Grade != grade)
			{
				DomainManager.Organization.ChangeGrade(context, character, grade, destPrincipal: true);
			}
			return;
		}
		OrganizationInfo targetOrgInfo = new OrganizationInfo
		{
			OrgTemplateId = settlement.GetOrgTemplateId(),
			Grade = grade,
			SettlementId = settlementId,
			Principal = true
		};
		DomainManager.Organization.ChangeOrganization(Domain.MainThreadDataContext, character, targetOrgInfo);
	}

