	public static short GetSectCompetitionClothingTemplateId(short organizationId)
	{
		sbyte level = DomainManager.World.GetXiangshuLevel();
		int offset = 0;
		if (level >= 2)
		{
			offset = 0;
		}
		if (level >= 4)
		{
			offset = 1;
		}
		if (level >= 6)
		{
			offset = 2;
		}
		int startIndex = 18;
		int templateId = (organizationId - 1) * 3 + startIndex + offset;
		if (organizationId > 4)
		{
			templateId++;
		}
		return (short)templateId;
	}

	public static void GetSectCompetitionRewards(EventArgBox argBox, bool getExtra, bool getFeature, bool getClothing)
	{
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		Location location = taiwu.GetValidLocation();
		int sustainDegree = GetAdventureParameter("sustainDegree");
		int getAmount = Math.Min(sustainDegree / 20, 5);
		sbyte stateId = GetStateIdByAreaId(location.AreaId);
		sbyte orgTemplateId = GetStateSectOrgTemplateId(stateId);
		sbyte highGrade = 0;
		argBox.Get("LearnGrade", ref highGrade);
		sbyte nowGrade = Math.Min(8, highGrade);
		List<GameData.Domains.Character.Character> charList = SetSectMemberApproveTaiwu(orgTemplateId, (byte)getAmount, 0, nowGrade);
		foreach (GameData.Domains.Character.Character role in charList)
		{
			ChangeFavorabilityOptionalStoryEvent(role, argBox.GetCharacter("RoleTaiwu"), (short)GetRandom(3, 6001));
		}
		short settlementId = GetBelongSettlementId(location.AreaId, location.BlockId);
		AddMaxApprovingRateBonus(settlementId, 100, 36);
		if (getClothing)
		{
			short clothingTemplateId = GetSectCompetitionClothingTemplateId(orgTemplateId);
			ItemKey clothItem = CreateItem(3, clothingTemplateId);
			string key = "ConchShip_PresetKey_SectCompetitionClothing" + clothingTemplateId;
			SaveGlobalArg(key, value: true);
			argBox.Set(EventTriggerParameter.DefValue.SelectInventoryItemKey, clothItem);
			AddItemToRole(taiwu, clothItem, 1, -1);
		}
		if (getExtra)
		{
			if (getFeature)
			{
				taiwu.AddFeature(Domain.MainThreadDataContext, GetOrganizationMenteeFeature(orgTemplateId));
			}
			else
			{
				GetExpRewardInCombatMatch(argBox);
			}
		}
	}

	public static void GetExpRewardInCombatMatch(EventArgBox argBox)
	{
		int charId = -1;
		if (argBox.Get("HostId", ref charId) && DomainManager.Character.TryGetElement_Objects(charId, out var character))
