			sbyte grade = character.GetOrganizationInfo().Grade;
			int value = (1 + grade) * (1 + grade) * (1 + grade) * 20;
			ChangeRoleExp(DomainManager.Taiwu.GetTaiwu(), value);
			argBox.Set("ExpReward", value);
		}
	}

