	public static void BaihuaTryCreateAdventureFinale()
	{
		DataContext context = Domain.MainThreadDataContext;
		Location taiwuVillageLocation = DomainManager.Taiwu.GetTaiwuVillageLocation();
		List<MapBlockData> mapBlockDatas = new List<MapBlockData>();
		DomainManager.Map.GetLocationByDistance(taiwuVillageLocation, 4, 7, ref mapBlockDatas);
		CollectionUtils.Shuffle(context.Random, mapBlockDatas);
		foreach (MapBlockData mapBlockData in mapBlockDatas)
		{
			if (!DomainManager.Map.IsBlockSpecial(mapBlockData) && !DomainManager.Adventure.QueryAnyAdventureOrMajorEvent(mapBlockData))
			{
				MapBlockItem config = mapBlockData.GetConfig();
				if (config.SubType != EMapBlockSubType.DarkPool)
				{
					TryCreateMajorEventAdventure(mapBlockData.AreaId, mapBlockData.BlockId, 96382576, setBlockVisible: true);
					break;
				}
			}
		}
	}

