			DirectlySetFavorabilities(leukorpus.GetId(), taiwu.GetId(), 30000, 30000);
			DirectlySetFavorabilities(melanpsyche.GetId(), taiwu.GetId(), 30000, 30000);
			DirectlySetFavorabilities(leukoDeer.GetId(), taiwu.GetId(), 30000, 30000);
			DirectlySetFavorabilities(melanoOwl.GetId(), taiwu.GetId(), 30000, 30000);
