	public static int BaihuaGetLMInteractDialog(bool isLeuko)
	{
		DataContext context = Domain.MainThreadDataContext;
		EventArgBox sectArgBox = GetSectMainStoryEventArgBox(3);
		sectArgBox.Get(isLeuko ? SectMainStoryEventArgKey.DefValue.BaihuaLeukoDialogNotTriggered : SectMainStoryEventArgKey.DefValue.BaihuaMelanoDialogNotTriggered, out IntList dialogNotTriggered);
		if (dialogNotTriggered.Items == null)
		{
			dialogNotTriggered = IntList.Create();
			for (int i = 0; i < 5; i++)
			{
				dialogNotTriggered.Items.Add(i);
			}
		}
		int dialogIndex = 0;
		if (dialogNotTriggered.Items.Count == 0)
		{
			dialogIndex = context.Random.Next(0, 5);
		}
		else
		{
			dialogIndex = dialogNotTriggered.Items.GetRandom(context.Random);
			dialogNotTriggered.Items.Remove(dialogIndex);
		}
		SaveArgToSectMainStory(3, isLeuko ? SectMainStoryEventArgKey.DefValue.BaihuaLeukoDialogNotTriggered : SectMainStoryEventArgKey.DefValue.BaihuaMelanoDialogNotTriggered, dialogNotTriggered);
		return dialogIndex;
	}

