	public static string GetCommonCloseUINextEvent(EventArgBox argBox, bool isCheck)
	{
		string uiName = string.Empty;
		int presetInt = -1;
		argBox.Get(EventTriggerParameter.DefValue.PresetInt, ref presetInt);
		bool presetBool = false;
		argBox.Get(EventTriggerParameter.DefValue.PresetBool, ref presetBool);
		if (argBox.Get(EventTriggerParameter.DefValue.UIName, ref uiName))
		{
			if (uiName.Equals("UI_SkillBreakPlate") && IsExtraTaskInProgress(167))
			{
				argBox.Set("CombatSkillId", presetInt);
				EventArgBox sectArgBox = GetSectMainStoryEventArgBox(4);
				bool triggered = false;
				sectArgBox.Get(SectMainStoryEventArgKey.DefValue.WudangFrontEventTriggered, ref triggered);
				if (!triggered)
				{
					return string.Empty;
				}
				short count = 0;
				sectArgBox.Get(SectMainStoryEventArgKey.DefValue.WudangSkillReverseBreakCount, ref count);
				count++;
				Log($"WudangSkillReverseBreakCount:{count}");
				if (!isCheck)
				{
					sectArgBox.Set(SectMainStoryEventArgKey.DefValue.WudangSkillReverseBreakCount, count);
					SaveSectMainStoryEventArgBox(4);
				}
				if (count == 1)
				{
					return "f0b1b365-dc9b-43e9-bac1-ff25747b9e4a";
				}
				if (count >= 2)
				{
					return "a90f00be-20ae-48c7-9b84-cf7888c923a6";
				}
			}
			if (uiName.Equals("WudangHeavenlyTreeSeed"))
			{
				return "255b9791-c39b-43a1-8336-295ad6858dae";
			}
			if (uiName.Equals("UI_CombatResult"))
			{
				if (IsExtraTaskInProgress(189) && IsShixiangSettlementEnemyClean())
				{
					argBox.Set("EnemyTemplateId", presetInt);
					return "1010bcdb-c7eb-4667-a085-efbcdb104135";
				}
				if (IsExtraTaskInProgress(192) && IsShixiangSettlementTraitorClean())
				{
					EventArgBox sectArgBox2 = GetSectMainStoryEventArgBox(6);
					int date = int.MaxValue;
					int currDate = GetGameDate();
					if (sectArgBox2.Get(SectMainStoryEventArgKey.DefValue.StartFightShixiangTraitorsDate, ref date) && currDate <= date + 36)
					{
						return "48690ac2-63a1-4ec1-99e3-da83adb9cf2a";
					}
				}
				if ((IsExtraTaskInProgress(172) || IsExtraTaskInProgress(364)) && GameData.Domains.Character.Character.IsXiangshuMinion((short)presetInt))
				{
					argBox.Set("EnemyTemplateId", presetInt);
					if (IsRandomEnemyBelongHeavenlyTree(argBox))
					{
						EventArgBox sectArgBox3 = GetSectMainStoryEventArgBox(4);
						if (!sectArgBox3.Contains<bool>(SectMainStoryEventArgKey.DefValue.WudangKillRandomEnemyTriggered))
						{
							return "6134ab9d-cb0a-419b-8c07-727997310fa5";
						}
						GameData.Domains.Character.Character character = argBox.GetCharacter("CharacterId");
						HeavenlyTreeGrewUp(character, 20, argBox);
						return string.Empty;
					}
				}
			}
			if (uiName.Equals("WuxianWugFairy"))
			{
				return "21f6f8b1-9f4f-4704-bdec-c23419a4c785";
			}
			if (uiName.Equals("GetSectMainStoryFulongFeatherCoat") && IsExtraTaskInProgress(304))
			{
				return "93e5c667-8ce2-4301-8c22-0d6c8f61b425";
			}
			if (uiName.Equals("PutOutFire") && IsExtraTaskInProgress(308))
			{
				return "4f741f8e-de51-4b07-b131-08f3893c12ec";
			}
			if (uiName.Equals("UI_ExtraProfessionSkillConfirmed"))
			{
				argBox.Set("FeatureId", presetInt);
				return "65347229-45f4-4fca-be3d-5bbb70c9fcea";
			}
			if (uiName.Equals("ShaolinInterruptDemonSlayerTrial"))
			{
				argBox.Set("Count", presetInt);
				if (presetInt == 0)
				{
					return "f5acf8d7-9fb1-4f26-a582-7c13923bdc5b";
				}
				if (presetInt > 0 && presetInt <= 8)
				{
					return "867d8930-2a48-43da-9a4d-8c561b9d0714";
				}
				return string.Empty;
			}
			if (uiName.Equals("UI_MonthNotify") && TryGetJingangChapter3PatchEventGuid(out var guid))
			{
				TriggerJingangChapter3Patch(isCheck);
				return guid;
			}
		}
		return string.Empty;
	}

