	public static void SaveWhiteApeBlockId()
	{
		DataContext context = Domain.MainThreadDataContext;
		Location apeLocation = Location.Invalid;
		short blockId = 0;
		if (GetSectMainStoryEventArgBox(2).Get(SectMainStoryEventArgKey.DefValue.WhiteApeBlockIdTmpSave, ref blockId))
		{
			apeLocation.AreaId = DomainManager.Organization.GetSettlementByOrgTemplateId(2).GetLocation().AreaId;
			apeLocation.BlockId = blockId;
			RemoveArgFromSectMainStory<short>(2, SectMainStoryEventArgKey.DefValue.WhiteApeBlockIdTmpSave);
		}
		else
		{
			apeLocation = GetEmeiSpecifyLocation();
		}
		SaveArgToSectMainStory(2, SectMainStoryEventArgKey.DefValue.WhiteApeBlockId, apeLocation.BlockId);
		MapBlockData mapBlockData = DomainManager.Map.GetBlockData(apeLocation.AreaId, apeLocation.BlockId);
		if (!mapBlockData.Visible)
		{
			mapBlockData.SetVisible(visible: true, context);
		}
		GameData.Domains.Character.Character gibbon = GetOrCreateFixedCharacterByTemplateId(562);
		GameData.Domains.Character.Character shiHoujiu = GetOrCreateFixedCharacterByTemplateId(567);
		int taiwuId = DomainManager.Taiwu.GetTaiwuCharId();
		DirectlySetFavorabilities(gibbon.GetId(), taiwuId, 0, 0);
		DirectlySetFavorabilities(shiHoujiu.GetId(), taiwuId, 0, 0);
	}

