		DomainManager.Extra.ClearEmeiBlood(Domain.MainThreadDataContext);
	}

	public static Location GetEmeiSpecifyLocation()
	{
		List<MapBlockData> nonDevelopedMapBlockDatas = ObjectPool<List<MapBlockData>>.Instance.Get();
		GetValidEmeiSpecifyLocations(nonDevelopedMapBlockDatas);
		if (nonDevelopedMapBlockDatas.Count == 0)
		{
			return Location.Invalid;
		}
		Location location = nonDevelopedMapBlockDatas[Domain.MainThreadDataContext.Random.Next(0, nonDevelopedMapBlockDatas.Count)].GetLocation();
		ObjectPool<List<MapBlockData>>.Instance.Return(nonDevelopedMapBlockDatas);
		return location;
	}

	public static void GetValidEmeiSpecifyLocations(List<MapBlockData> nonDevelopedMapBlockDatas)
	{
		Settlement emeiSettlement = DomainManager.Organization.GetSettlementByOrgTemplateId(2);
		Location centerLocation = emeiSettlement.GetLocation();
		List<MapBlockData> mapBlockDatas = ObjectPool<List<MapBlockData>>.Instance.Get();
		MapBlockItem config = MapBlock.Instance[(short)20];
		GetLocationByDistance(centerLocation, config.Range + 3, config.Range + 3, ref mapBlockDatas);
		foreach (MapBlockData mapBlockData in mapBlockDatas)
		{
			if (mapBlockData.GetConfig().SubType != EMapBlockSubType.DLCLoong && mapBlockData.IsNonDeveloped())
			{
				nonDevelopedMapBlockDatas.Add(mapBlockData);
			}
		}
		ObjectPool<List<MapBlockData>>.Instance.Return(mapBlockDatas);
	}

	public static bool CheckHomicideCase0()
	{
		if (!SectMainStory.DefValue.Emei.IsReady())
		{
			return false;
		}
		short apeBlockId = -1;
		EventArgBox sectArgBox = GetSectMainStoryEventArgBox(2);
		if (!sectArgBox.Get(SectMainStoryEventArgKey.DefValue.WhiteApeBlockId, ref apeBlockId))
		{
			return false;
		}
		if (sectArgBox.Contains<bool>(SectMainStoryEventArgKey.DefValue.HomocideCase0Triggered))
		{
			return false;
		}
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		Location taiwuLocation = taiwu.GetLocation();
		MapBlockData taiwuBlockData = GetMapBlockData(taiwuLocation.AreaId, taiwuLocation.BlockId);
		Location emeiLocation = GetSettlementByOrgTemplateId(2).GetLocation();
		if (emeiLocation.AreaId != taiwuLocation.AreaId)
		{
			return false;
		}
		ByteCoordinate apeBlockPos = GetMapBlockData(emeiLocation.AreaId, apeBlockId).GetBlockPos();
		return taiwuBlockData.GetManhattanDistanceToPos(apeBlockPos.X, apeBlockPos.Y) <= 3;
	}

