	public static void CreateEmeiRole(EventArgBox argBox)
	{
		EventActorData jiaEventActorData = CreateAdventureActor(140, "CharIdJia", argBox);
		EventActorData yiEventActorData = CreateAdventureActor(141, "CharIdYi", argBox);
		EventActorData bingEventActorData = CreateAdventureActor(142, "CharIdBing", argBox);
		EventActorData dingEventActorData = CreateAdventureActor(143, "CharIdDing", argBox);
		EventActorData wuEventActorData = CreateAdventureActor(144, "CharIdWu", argBox);
		EventActorData siEventActorData = CreateAdventureActor(145, "CharIdSi", argBox);
		EventActorData gengEventActorData = CreateAdventureActor(146, "CharIdGeng", argBox);
		EventActorData xinEventActorData = CreateAdventureActor(147, "CharIdXin", argBox);
