	public static void EmeiRemoveRelatedFixedCharacter(bool includeGibbon = true, bool includeShiHoujiu = true)
	{
		DataContext context = Domain.MainThreadDataContext;
		if (includeGibbon)
		{
			GameData.Domains.Character.Character emeiWhiteGibbon0 = GetOrCreateFixedCharacterByTemplateId(562);
			DomainManager.Character.RemoveNonIntelligentCharacter(context, emeiWhiteGibbon0);
		}
		if (includeShiHoujiu)
		{
			GameData.Domains.Character.Character shiHoujiu = GetOrCreateFixedCharacterByTemplateId(567);
			DomainManager.Character.RemoveNonIntelligentCharacter(context, shiHoujiu);
		}
		GameData.Domains.Character.Character emeiWhiteGibbon1 = GetOrCreateFixedCharacterByTemplateId(560);
		DomainManager.Character.RemoveNonIntelligentCharacter(context, emeiWhiteGibbon1);
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		ItemKey itemKey = taiwu.GetInventory().GetInventoryItemKey(12, 332);
		if (itemKey.IsValid())
		{
			taiwu.RemoveInventoryItem(context, itemKey, 1, deleteItem: true);
		}
	}

