	public static void EmeiAdventureTwoSetCharacterArgs(EventArgBox argBox)
	{
		for (int i = 0; i < 4; i++)
		{
			string name = $"ParticipateCharacter_0_{i}";
			GameData.Domains.Character.Character elder = argBox.GetCharacter(name);
			name = $"EmeiElder0{i + 1}";
			argBox.Set(name, elder.GetId());
			if (IsTemporaryIntelligentCharacter(elder.GetId()))
			{
				KeepTemporaryCharacterAfterAdventure(elder);
			}
		}
		for (int j = 0; j < 11; j++)
		{
			string name2 = $"ParticipateCharacter_1_{j}";
			GameData.Domains.Character.Character follower = argBox.GetCharacter(name2);
			name2 = $"EmeiFollower{j + 1}";
			argBox.Set(name2, follower.GetId());
			if (IsTemporaryIntelligentCharacter(follower.GetId()))
			{
				KeepTemporaryCharacterAfterAdventure(follower);
			}
		}
		GameData.Domains.Character.Character emeiWhiteGibbon = GetOrCreateFixedCharacterByTemplateId(562);
		GameData.Domains.Character.Character shiHoujiu = GetOrCreateFixedCharacterByTemplateId(567);
		argBox.Set("ShiHoujiu", shiHoujiu.GetId());
		argBox.Set("EmeiGibbon", emeiWhiteGibbon.GetId());
		CreateAdventureActor(150, "EmeiBlackMan", argBox);
	}

	public static bool EmeiAdventureTwoSetPathArgs(EventArgBox argBox)
	{
		int pathEventTriggerCount = 0;
		if (!argBox.Contains<int>(SectMainStoryEventArgKey.DefValue.EmeiAdventureTwoPathEventTriggerCount))
		{
			argBox.Set(SectMainStoryEventArgKey.DefValue.EmeiAdventureTwoPathEventTriggerCount, 1);
			pathEventTriggerCount = 1;
		}
		else
		{
			argBox.Get(SectMainStoryEventArgKey.DefValue.EmeiAdventureTwoPathEventTriggerCount, ref pathEventTriggerCount);
			pathEventTriggerCount++;
			argBox.Set(SectMainStoryEventArgKey.DefValue.EmeiAdventureTwoPathEventTriggerCount, pathEventTriggerCount);
		}
		if (pathEventTriggerCount >= 6)
		{
			return false;
		}
		GameData.Domains.Character.Character character = argBox.GetCharacter("EmeiFollower" + (pathEventTriggerCount + 5));
		argBox.Set("EmeiFollowerRandom", character.GetId());
		return true;
	}

	public static void OpenEmeiCombatSkillSpecialBreak(string afterEvent, EventArgBox argBox, short charTemplateId, int characterId)
	{
		if (!string.IsNullOrEmpty(afterEvent))
		{
			Domain.SetListenerWithActionName(afterEvent, argBox, "CombatSkillSpecialBreak");
		}
		bool flag;
		switch (charTemplateId)
		{
		case 560:
		case 562:
		case 563:
		case 564:
			flag = true;
			break;
		default:
			flag = false;
			break;
		}
		bool isEmeiWhiteGibbon = flag;
		GameData.GameDataBridge.GameDataBridge.AddDisplayEvent(DisplayEventType.OpenCombatSkillSpecialBreak, charTemplateId, isEmeiWhiteGibbon);
	}

	public static void Follow(GameData.Domains.Character.Character character, int distance)
	{
		DataContext context = Domain.MainThreadDataContext;
		List<MapBlockData> taiwuNeighborBlocks = ObjectPool<List<MapBlockData>>.Instance.Get();
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		Location taiwuLocation = taiwu.GetLocation();
		if (!taiwuLocation.IsValid())
		{
			taiwuLocation = taiwu.GetValidLocation();
		}
		DomainManager.Map.GetRealNeighborBlocks(taiwuLocation.AreaId, taiwuLocation.BlockId, taiwuNeighborBlocks, distance);
		MapBlockData blockData = taiwuNeighborBlocks[context.Random.Next(0, taiwuNeighborBlocks.Count)];
		ObjectPool<List<MapBlockData>>.Instance.Return(taiwuNeighborBlocks);
		MoveFixedCharacter(character, blockData.GetLocation());
	}

	public static bool IsEmeiHomocideCasesInteractionId(int charId)
	{
		EventArgBox sectArgBox = GetSectMainStoryEventArgBox(2);
		if (!sectArgBox.Contains<IntList>(SectMainStoryEventArgKey.DefValue.EmeiEmeiHomocideCasesInteractionIds))
		{
			return false;
		}
		IntList idList = sectArgBox.Get<IntList>(SectMainStoryEventArgKey.DefValue.EmeiEmeiHomocideCasesInteractionIds);
		if (idList.Items == null)
		{
			return false;
		}
		return idList.Items.Contains(charId);
	}

	public static void AddEmeiHomocideCasesInteractionId(int charId)
	{
		EventArgBox sectArgBox = GetSectMainStoryEventArgBox(2);
		IntList idList;
		if (!sectArgBox.Contains<IntList>(SectMainStoryEventArgKey.DefValue.EmeiEmeiHomocideCasesInteractionIds))
		{
			idList = IntList.Create();
		}
		else
		{
			idList = sectArgBox.Get<IntList>(SectMainStoryEventArgKey.DefValue.EmeiEmeiHomocideCasesInteractionIds);
			if (idList.Items == null)
			{
				idList = IntList.Create();
			}
		}
		idList.Items.Add(charId);
		SaveArgToSectMainStory(2, SectMainStoryEventArgKey.DefValue.EmeiEmeiHomocideCasesInteractionIds, idList);
	}

