	public static bool FulongAdventureCanDrinkWine()
	{
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		return CanEatItemExceptMisc(taiwu) && taiwu.GetDisorderOfQi() <= 6000;
	}

	public static void FulongAdventureDrinkWine(EventArgBox argBox, GameData.Domains.Character.Character character)
	{
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		short templateId = 0;
		if (character.GetOrganizationInfo().Grade == 1)
		{
			templateId = 1;
		}
		else if (character.GetOrganizationInfo().Grade == 2)
		{
			templateId = 2;
		}
		TeaWineItem config = Config.TeaWine.Instance[templateId];
		ChangeFavorabilityOptional(character, taiwu, (short)config.BaseFavorabilityChange, 4);
		ItemKey itemWineTaiwuDrink = AddItemToRole(taiwu, 9, templateId, 1, -1);
		AddEatingItem(taiwu.GetId(), itemWineTaiwuDrink);
		if (CanEatItemExceptMisc(character))
		{
			ItemKey itemWineCharacterDrink = AddItemToRole(character, 9, templateId, 1, -1);
			AddEatingItem(character.GetId(), itemWineCharacterDrink);
		}
	}

