	public static List<short> FulongGetPutOutFireReward()
	{
		int count = 0;
		EventArgBox sectArgBox = GetSectMainStoryEventArgBox(14);
		sectArgBox.Get(SectMainStoryEventArgKey.DefValue.FulongPutOutFireCount, ref count);
		sbyte rewardGrade = (sbyte)(count + 2);
		Span<short> span = stackalloc short[3];
		SpanList<short> reward = span;
		List<short> templateIds = new List<short>();
		reward.Add(77);
		reward.Add(78);
		reward.Add(80);
		SpanList<short>.Enumerator enumerator = reward.GetEnumerator();
		while (enumerator.MoveNext())
		{
			short materialId = enumerator.Current;
			MakeItemResult result = MakeItemSubType.Instance[MakeItemType.Instance[Config.Material.Instance[materialId].CraftableItemTypes[0]].MakeItemSubTypes[0]].Result;
			short templateId = (short)(result.TemplateId - Config.Food.Instance[result.TemplateId].Grade + rewardGrade);
			templateIds.Add(templateId);
		}
		return templateIds;
	}

	public static void FulongPutOutOnceFire()
	{
		DataContext context = Domain.MainThreadDataContext;
		List<FulongInFlameArea> flameAreas = GetAllFulongInFlameAreas();
		for (int i = 0; i < flameAreas.Count; i++)
		{
			FulongInFlameArea flameArea = flameAreas[i];
			List<short> lightedBlocks = flameArea.LightedBlocks.Keys.ToList();
			lightedBlocks = lightedBlocks.Except(flameArea.ExtinguishedBlocks).Except(flameArea.MineBlocks).ToList();
			if (lightedBlocks.Count > 2)
			{
				short blockId = lightedBlocks.GetRandom(context.Random);
				DomainManager.Extra.ExtinguishFulongInFlameArea(context, blockId, isEvent: true);
			}
		}
	}

	public static bool FulongGuideCanTrigger()
	{
		if (!IsExtraTaskInProgress(311))
		{
			return false;
		}
		EventArgBox eventArgBox = GetSectMainStoryEventArgBox(14);
		bool triggered = false;
		eventArgBox.Get(SectMainStoryEventArgKey.DefValue.FulongFireFightingGuideTriggered, ref triggered);
		if (triggered)
		{
			return false;
		}
		Settlement settlement = DomainManager.Organization.GetSettlementByOrgTemplateId(14);
		Location fulongLocation = settlement.GetLocation();
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		Location taiwuLocation = taiwu.GetLocation();
		if (taiwuLocation.AreaId != fulongLocation.AreaId)
		{
			return false;
		}
		List<FulongInFlameArea> fulongInFlameAreas = GetAllFulongInFlameAreas();
		List<MapBlockData> mapBlockDatas = ObjectPool<List<MapBlockData>>.Instance.Get();
		DomainManager.Map.GetLocationByDistance(taiwuLocation, 1, 1, ref mapBlockDatas);
		for (int i = 0; i < mapBlockDatas.Count; i++)
		{
			Location location = mapBlockDatas[i].GetLocation();
			for (int j = 0; j < fulongInFlameAreas.Count; j++)
			{
				if (fulongInFlameAreas[j].LightedBlocks.Keys.Contains(location.BlockId))
				{
					ObjectPool<List<MapBlockData>>.Instance.Return(mapBlockDatas);
					return true;
				}
			}
		}
		ObjectPool<List<MapBlockData>>.Instance.Return(mapBlockDatas);
		return false;
	}

