	public static int FulongMonvState(EventArgBox argBox)
	{
		EventArgBox sectArgBox = GetSectMainStoryEventArgBox(14);
		bool fulongTravelWithLazuliMonvTalkTriggered = false;
		sectArgBox.Get(SectMainStoryEventArgKey.DefValue.FulongTravelWithLazuliMonvTalkTriggered, ref fulongTravelWithLazuliMonvTalkTriggered);
		if (fulongTravelWithLazuliMonvTalkTriggered)
		{
			return 3;
		}
		DomainManager.Character.TryGetFixedCharacterByTemplateId(201, out var juniorMonv);
		if (juniorMonv != null && juniorMonv.GetLocation().AreaId == DomainManager.Taiwu.GetTaiwuVillageLocation().AreaId)
		{
			argBox.Set("Monv", juniorMonv.GetId());
			return 0;
		}
		for (short i = 120; i <= 128; i++)
		{
			DomainManager.Character.TryGetFixedCharacterByTemplateId(i, out var weakenedMonv);
			if (weakenedMonv != null && weakenedMonv.GetLocation().AreaId == DomainManager.Taiwu.GetTaiwuVillageLocation().AreaId)
			{
				return 1;
			}
		}
		sbyte xiangshuAvatarId = XiangshuAvatarIds.GetXiangshuAvatarIdByCharacterTemplateId(201);
		if (DomainManager.World.GetElement_XiangshuAvatarTaskStatuses(xiangshuAvatarId).SwordTombStatus < 2)
		{
			return 2;
		}
		return 3;
	}

