	public static string FulongGetTravelWithLazuliLocationEvent(EventArgBox eventArgBox)
	{
		if (!DomainManager.World.IsExtraTaskInProgress(301) && !DomainManager.World.IsExtraTaskInProgress(310))
		{
			return string.Empty;
		}
		int charId = GetOrCreateFixedCharacterByTemplateId(900).GetId();
		eventArgBox.Set("ChickenKing", charId);
		GameData.Domains.Character.Character reudhLazuli = GetOrCreateFixedCharacterByTemplateId(831);
		eventArgBox.Set("ReudhLazuli", reudhLazuli.GetId());
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		Location taiwuLocation = taiwu.GetLocation();
		MapBlockData taiwuBlockData = GetMapBlockData(taiwuLocation.AreaId, taiwuLocation.BlockId);
		MapBlockData taiwuRootBlockData = taiwuBlockData.GetRootBlock();
		EventArgBox argBox = GetSectMainStoryEventArgBox(14);
		MapBlockItem config = taiwuRootBlockData.GetConfig();
		EMapBlockSubType subType = config.SubType;
		if ((subType == EMapBlockSubType.Fuzhou || subType == EMapBlockSubType.Shouchun || subType == EMapBlockSubType.Yangzhou) ? true : false)
		{
			if (!argBox.Contains<bool>(SectMainStoryEventArgKey.DefValue.FulongTravelWithLazuliCityTriggered))
			{
				SaveArgToSectMainStory(14, SectMainStoryEventArgKey.DefValue.FulongTravelWithLazuliCityTriggered, value: true);
				return "3cf8d2b1-0684-43df-9423-d52b9dcfcc1f";
			}
			return string.Empty;
		}
		if (config.Type == EMapBlockType.Sect && config.SubType != EMapBlockSubType.FulongTan)
		{
			if (!argBox.Contains<bool>(SectMainStoryEventArgKey.DefValue.FulongTravelWithLazuliSectTriggered))
			{
				SaveArgToSectMainStory(14, SectMainStoryEventArgKey.DefValue.FulongTravelWithLazuliSectTriggered, value: true);
				return "42ab2896-df4f-4c62-a3bb-519d04257835";
			}
			return string.Empty;
		}
		if (config.TemplateId == 0 && DomainManager.World.IsExtraTaskInProgress(310))
		{
			if (!argBox.Contains<bool>(SectMainStoryEventArgKey.DefValue.FulongTravelWithLazuliTaiwuVillageTriggered))
			{
				SaveArgToSectMainStory(14, SectMainStoryEventArgKey.DefValue.FulongTravelWithLazuliTaiwuVillageTriggered, value: true);
				return "034492a8-e1a5-40c8-99bf-87b1b6d0d080";
			}
			return string.Empty;
		}
		if (config.TemplateId == 34 && AtTargetArea(taiwuLocation))
		{
			if (!argBox.Contains<bool>(SectMainStoryEventArgKey.DefValue.FulongTravelWithLazuliVillageTriggered))
			{
				SaveArgToSectMainStory(14, SectMainStoryEventArgKey.DefValue.FulongTravelWithLazuliVillageTriggered, value: true);
				return "bb456d3f-5598-4c34-9784-2f3c2e17fb43";
			}
			return string.Empty;
		}
		if (config.TemplateId == 35 && AtTargetArea(taiwuLocation))
		{
			if (!argBox.Contains<bool>(SectMainStoryEventArgKey.DefValue.FulongTravelWithLazuliTownTriggered))
			{
				SaveArgToSectMainStory(14, SectMainStoryEventArgKey.DefValue.FulongTravelWithLazuliTownTriggered, value: true);
				return "ef05aa29-0841-4bf1-b951-3856bf6ac993";
			}
			return string.Empty;
		}
		if (config.TemplateId == 36 && AtTargetArea(taiwuLocation))
		{
			if (!argBox.Contains<bool>(SectMainStoryEventArgKey.DefValue.FulongTravelWithLazuliStockadeTriggered))
			{
				SaveArgToSectMainStory(14, SectMainStoryEventArgKey.DefValue.FulongTravelWithLazuliStockadeTriggered, value: true);
				return "08a7773e-e5fa-43fd-9c00-92edd8710891";
			}
			return string.Empty;
		}
		if (DomainManager.Extra.TryGetAnimalsByLocation(taiwuLocation, out var animals) && animals.Count > 0)
		{
			for (int i = animals.Count - 1; i >= 0; i--)
			{
				if (FiveLoongDlcEntry.IsCharacterLoong(animals[i].CharacterTemplateId) || FiveLoongDlcEntry.IsCharacterMinionLoong(animals[i].CharacterTemplateId) || animals[i].ItemKey.IsValid())
				{
					animals.RemoveAt(i);
				}
			}
			if (animals.Count <= 0)
			{
				return string.Empty;
			}
			if (!argBox.Contains<bool>(SectMainStoryEventArgKey.DefValue.FulongTravelWithLazuliAnimalTriggered))
			{
				eventArgBox.Set("AnimalTemplateId", animals[0].CharacterTemplateId);
				SaveArgToSectMainStory(14, SectMainStoryEventArgKey.DefValue.FulongTravelWithLazuliAnimalTriggered, value: true);
				return "b8b34225-1aae-41e4-a72c-6a757ced4c49";
			}
		}
		if (taiwuBlockData.TemplateEnemyList != null)
		{
			string nextString = string.Empty;
			for (int j = 0; j < taiwuBlockData.TemplateEnemyList.Count; j++)
			{
				short templateId = taiwuBlockData.TemplateEnemyList[j].TemplateId;
				if (templateId >= 366 && templateId <= 374)
				{
					if (!argBox.Contains<bool>(SectMainStoryEventArgKey.DefValue.FulongTravelWithLazuliXiangshuMinionTriggered))
					{
						eventArgBox.Set("EnemyTemplateId", taiwuBlockData.TemplateEnemyList[j].TemplateId);
						SaveArgToSectMainStory(14, SectMainStoryEventArgKey.DefValue.FulongTravelWithLazuliXiangshuMinionTriggered, value: true);
						nextString = "e12aabfa-3947-4ce2-b16b-005a7f193966";
						break;
					}
					continue;
				}
				templateId = taiwuBlockData.TemplateEnemyList[j].TemplateId;
				if (templateId >= 375 && templateId <= 383)
				{
					sbyte fameType = taiwu.GetFameType();
					if (fameType != 1 && fameType != 0)
					{
						nextString = string.Empty;
						break;
					}
				}
				if (!argBox.Contains<bool>(SectMainStoryEventArgKey.DefValue.FulongTravelWithLazuliRandomEnemyTriggered))
				{
					eventArgBox.Set("EnemyTemplateId", taiwuBlockData.TemplateEnemyList[j].TemplateId);
					SaveArgToSectMainStory(14, SectMainStoryEventArgKey.DefValue.FulongTravelWithLazuliRandomEnemyTriggered, value: true);
					nextString = "209b1ffb-b465-4d37-8111-1191d9769b11";
					break;
				}
			}
			if (!nextString.Equals(string.Empty))
			{
				DomainManager.Map.ClearBlockRandomEnemies(Domain.MainThreadDataContext, taiwuBlockData);
			}
			return nextString;
		}
		int moveCount = 0;
		argBox.Get(SectMainStoryEventArgKey.DefValue.FulongTravelWithLazuliMoveCount, ref moveCount);
		SaveArgToSectMainStory(14, SectMainStoryEventArgKey.DefValue.FulongTravelWithLazuliMoveCount, ++moveCount);
		int areaId = 0;
		argBox.Get(SectMainStoryEventArgKey.DefValue.FulongTravelWithLazuliMoveAreaId, ref areaId);
		if (moveCount > 6 || areaId != taiwuLocation.AreaId)
		{
			if (areaId != taiwuLocation.AreaId)
			{
				SaveArgToSectMainStory((sbyte)14, SectMainStoryEventArgKey.DefValue.FulongTravelWithLazuliMoveAreaId, (int)taiwuLocation.AreaId);
			}
			if (!argBox.Contains<bool>(SectMainStoryEventArgKey.DefValue.FulongTravelWithLazuliChicken1))
			{
				SaveArgToSectMainStory(14, SectMainStoryEventArgKey.DefValue.FulongTravelWithLazuliChicken1, value: true);
				SaveArgToSectMainStory(14, SectMainStoryEventArgKey.DefValue.FulongTravelWithLazuliMoveCount, 0);
				return "242a1283-5b57-4c40-80f6-6a6e7d7be970";
			}
			if (!argBox.Contains<bool>(SectMainStoryEventArgKey.DefValue.FulongTravelWithLazuliChicken2))
			{
				SaveArgToSectMainStory(14, SectMainStoryEventArgKey.DefValue.FulongTravelWithLazuliChicken2, value: true);
				SaveArgToSectMainStory(14, SectMainStoryEventArgKey.DefValue.FulongTravelWithLazuliMoveCount, 0);
				return "97c2d89a-ab79-4960-a469-b433133510cb";
			}
		}
		return string.Empty;
		static bool AtTargetArea(Location location)
		{
			short shouchunAreaId = DomainManager.Map.GetAreaIdByAreaTemplateId(13);
			short fuzhouAreaId = DomainManager.Map.GetAreaIdByAreaTemplateId(9);
			short yangzhouAreaId = DomainManager.Map.GetAreaIdByAreaTemplateId(15);
			if (location.AreaId == shouchunAreaId || location.AreaId == fuzhouAreaId || location.AreaId == yangzhouAreaId)
			{
				return true;
			}
			return false;
		}
	}

