	public static bool FulongSpecialInteractVisible(GameData.Domains.Character.Character character)
	{
		EventArgBox argBox = GetSectMainStoryEventArgBox(14);
		bool fulongSpecialInteractOpen = false;
		argBox.Get(SectMainStoryEventArgKey.DefValue.FulongSpecialInteractOpen, ref fulongSpecialInteractOpen);
		if (!fulongSpecialInteractOpen)
		{
			return false;
		}
		int fulongMessengerAppearTime = int.MaxValue;
		argBox.Get(SectMainStoryEventArgKey.DefValue.FulongMessengerAppearTime, ref fulongMessengerAppearTime);
		bool isSecondState = GetGameDate() > fulongMessengerAppearTime + 3;
		OrganizationInfo orgInfo = character.GetOrganizationInfo();
		bool flag = !isSecondState;
		bool flag2 = flag;
		if (flag2)
		{
			bool flag3;
			switch (orgInfo.OrgTemplateId)
			{
			case 16:
			case 29:
			case 33:
			case 35:
				flag3 = true;
				break;
			default:
				flag3 = false;
				break;
			}
			flag2 = flag3;
		}
		if (flag2)
		{
			return IsCharacterAtOrganizationRange(character, orgInfo.OrgTemplateId);
		}
		if (isSecondState && ((OrganizationDomain.IsSect(orgInfo.OrgTemplateId) && orgInfo.OrgTemplateId != 14) || orgInfo.OrgTemplateId == 16))
		{
			return true;
		}
		return false;
	}

