	public static bool FulongCheckChickenFeather()
	{
		if (!DomainManager.World.IsExtraTaskInProgress(303))
		{
			return false;
		}
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		Location taiwuLocation = taiwu.GetLocation();
		MapBlockData mapBlockData = DomainManager.Map.GetBlockData(taiwuLocation.AreaId, taiwuLocation.BlockId);
		Location taiwuRootLocation = mapBlockData.GetRootBlock().GetLocation();
		if (DomainManager.Taiwu.GetTaiwuVillageLocation().Equals(taiwuRootLocation))
		{
			return false;
		}
		Settlement settlement = DomainManager.Organization.GetSettlementByLocation(taiwuRootLocation);
		if (settlement != null)
		{
			List<int> chickenIds = DomainManager.Building.GetSettlementChickenIdList(taiwuRootLocation);
			List<int> loseFeatherChickens = DomainManager.Extra.GetSectFulongLoseFeatherChickens();
			for (int i = 0; i < chickenIds.Count; i++)
			{
				int id = chickenIds[i];
				if (loseFeatherChickens.Count <= 0 || !loseFeatherChickens.Contains(id))
				{
					return true;
				}
			}
		}
		return false;
	}

	public static bool FulongLazuliLetterCanTrigger()
	{
		if (!DomainManager.World.IsExtraTaskInProgress(303))
		{
			return false;
		}
		Settlement settlement = DomainManager.Organization.GetSettlementByOrgTemplateId(14);
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		Location taiwuLocation = taiwu.GetLocation();
		EventArgBox eventArgBox = DomainManager.Extra.GetSectMainStoryEventArgBox(14);
		bool triggered = false;
		eventArgBox.Get(SectMainStoryEventArgKey.DefValue.FulongLazuliLetterTriggered, ref triggered);
		if (triggered)
		{
			return false;
		}
		if (settlement.GetLocation().AreaId != taiwuLocation.AreaId)
		{
			return true;
		}
		int moveCount = 0;
		eventArgBox.Get(SectMainStoryEventArgKey.DefValue.FulongChickenKingLetterMoveCount, ref moveCount);
		if (moveCount >= 4)
		{
			return true;
		}
		SaveArgToSectMainStory(14, SectMainStoryEventArgKey.DefValue.FulongChickenKingLetterMoveCount, ++moveCount);
		return false;
	}

	public static void FulongCreateMessenger()
	{
		DataContext context = Domain.MainThreadDataContext;
		short templateId = SectMainStoryRelatedConstants.GetTemplateIdOfFixedCharacterCombatWith(836, 5);
		List<short> blocks = ObjectPool<List<short>>.Instance.Get();
		List<sbyte> settlementTemplateIds = new List<sbyte> { 16, 35, 33, 29 };
		IntList characterIds = IntList.Create();
		for (int i = 0; i < settlementTemplateIds.Count; i++)
		{
			Location settlementLocation = DomainManager.Organization.GetSettlementByOrgTemplateId(settlementTemplateIds[i]).GetLocation();
			blocks.Clear();
			DomainManager.Map.GetSettlementBlocksAndAffiliatedBlocks(settlementLocation.AreaId, settlementLocation.BlockId, blocks);
			CollectionUtils.Shuffle(context.Random, blocks);
			int count = GetRandom(3, 6);
			for (int j = 0; j < count; j++)
			{
				GameData.Domains.Character.Character character = DomainManager.Character.CreateFixedEnemy(context, templateId, isTemporary: false);
				DomainManager.Character.CompleteCreatingCharacter(character.GetId());
				Location validBlockLocation = new Location(settlementLocation.AreaId, blocks[j]);
				MoveFixedEnemy(character, validBlockLocation);
				characterIds.Items.Add(character.GetId());
			}
		}
		SaveArgToSectMainStory(14, SectMainStoryEventArgKey.DefValue.FulongMessengerIdList, characterIds);
		ObjectPool<List<short>>.Instance.Return(blocks);
	}

	public static void FulongRemoveMessengerAndZealot()
	{
		EventArgBox argBox = GetSectMainStoryEventArgBox(14);
		IntList characterIds = argBox.Get<IntList>(SectMainStoryEventArgKey.DefValue.FulongMessengerIdList);
		if (characterIds.Items != null)
		{
			for (int i = 0; i < characterIds.Items.Count; i++)
			{
				int characterId = characterIds.Items[i];
				if (DomainManager.Character.TryGetElement_Objects(characterId, out var character))
				{
					RemoveNonIntelligentCharacter(character);
				}
			}
		}
		DomainManager.Extra.RemoveAllFulongOutLaws(Domain.MainThreadDataContext);
	}

