	public static int FulongLazuliPersuadeSetCharacter()
	{
		Settlement settlement = DomainManager.Organization.GetSettlementByOrgTemplateId(14);
		List<int> members = new List<int>();
		settlement.GetMembers().GetAllMembers(members);
		DataContext context = Domain.MainThreadDataContext;
		CollectionUtils.Shuffle(context.Random, members);
		for (int i = 0; i < members.Count; i++)
		{
			int characterId = members[i];
			if (DomainManager.Character.TryGetElement_Objects(characterId, out var character) && character.GetAgeGroup() >= 2 && character.GetOrganizationInfo().Grade <= 6 && !character.IsActiveExternalRelationState(188uL) && character.GetKidnapperId() < 0 && character.GetLegendaryBookOwnerState() != 3 && character.GetLegendaryBookOwnerState() != 2 && !character.IsCompletelyInfected())
			{
				return characterId;
			}
		}
		return -1;
	}

