	public static void FulongAdvenrureThreeSetCharacter(EventArgBox argBox)
	{
		GameData.Domains.Character.Character friend1 = argBox.GetAdventureMajorCharacter(0, 1);
		if (IsTemporaryIntelligentCharacter(friend1.GetId()))
		{
			KeepTemporaryCharacterAfterAdventure(friend1);
		}
		argBox.Set("FulongFriend1", friend1.GetId());
		GameData.Domains.Character.Character friend2 = argBox.GetAdventureMajorCharacter(0, 2);
		if (IsTemporaryIntelligentCharacter(friend2.GetId()))
		{
			KeepTemporaryCharacterAfterAdventure(friend2);
		}
		argBox.Set("FulongFriend2", friend2.GetId());
		GameData.Domains.Character.Character friend3 = argBox.GetAdventureMajorCharacter(0, 3);
		if (IsTemporaryIntelligentCharacter(friend3.GetId()))
		{
			KeepTemporaryCharacterAfterAdventure(friend3);
		}
		argBox.Set("FulongFriend3", friend3.GetId());
	}

	public static void FulongAdventureThreePathEventSetCharacterId(EventArgBox argBox, int count)
	{
		argBox.Set(arg: (count switch
		{
			0 => argBox.GetAdventureMajorCharacter(0, 4), 
			1 => argBox.GetAdventureMajorCharacter(0, 5), 
			2 => argBox.GetAdventureMajorCharacter(0, 6), 
			_ => argBox.GetAdventureMajorCharacter(0, 7), 
		}).GetId(), key: EventTriggerParameter.DefValue.CharacterId.ArgBoxKey);
	}

