	public static void FulongEndEffect(bool goodEnd, bool adventureComplete = true)
	{
		FinishAllTaskInChain(47);
		SaveArgToSectMainStory(14, SectMainStoryEventArgKey.DefValue.FulongChickenKingLeaveHome, value: false);
		if (adventureComplete)
		{
			DomainManager.Organization.SetSectFunctionStatus(Domain.MainThreadDataContext, 14, SectFunctionStatuses.SectFunctionStatusType.SpecialInteractionUnlocked, value: true);
		}
		DomainManager.Story.TriggerSectMainStoryEndingCountDown(Domain.MainThreadDataContext, 14, goodEnd, goodEnd ? 1 : 1);
		if (!goodEnd)
		{
			FulongDefeatEffect();
		}
	}

	public static void FulongCombatWonEffect()
	{
		TriggerExtraTask(47, 306);
		GameData.Domains.Character.Character reudhLazuliFeather = GetOrCreateFixedCharacterByTemplateId(833);
		Settlement settlement = DomainManager.Organization.GetSettlementByOrgTemplateId(14);
		List<MapBlockData> mapBlockDatas = ObjectPool<List<MapBlockData>>.Instance.Get();
		DomainManager.Map.GetLocationByDistance(settlement.GetLocation(), 3, 5, ref mapBlockDatas);
		Location targetLocation = Location.Invalid;
		for (int i = 0; i < mapBlockDatas.Count; i++)
		{
			MapBlockData mapBlockData = mapBlockDatas[i];
			MapBlockItem config = mapBlockData.GetConfig();
			if (config.SubType != EMapBlockSubType.Ruin && config.SubType != EMapBlockSubType.DLCLoong && config.SubType != EMapBlockSubType.DarkPool)
			{
				targetLocation = mapBlockData.GetLocation();
			}
		}
		if (targetLocation.Equals(Location.Invalid))
		{
			targetLocation = mapBlockDatas.GetRandom(Domain.MainThreadDataContext.Random).GetLocation();
		}
		MoveFixedCharacter(reudhLazuliFeather, targetLocation);
		ObjectPool<List<MapBlockData>>.Instance.Return(mapBlockDatas);
	}

