	public static bool JingangVillagerCanInteraction(int charId)
	{
		DomainManager.Character.TryGetElement_Objects(charId, out var character);
		OrganizationInfo organizationInfo = character.GetOrganizationInfo();
		OrganizationItem config = Config.Organization.Instance[organizationInfo.OrgTemplateId];
		if (config.IsSect)
		{
			return false;
		}
		List<short> settlementIds = ObjectPool<List<short>>.Instance.Get();
		short areaId = DomainManager.Map.GetAreaIdByAreaTemplateId(26);
		DomainManager.Map.GetAreaSettlementIds(areaId, settlementIds, containsMainCity: true);
		if (!settlementIds.Contains(organizationInfo.SettlementId))
		{
			ObjectPool<List<short>>.Instance.Return(settlementIds);
			return false;
		}
		EventArgBox sectArgBox = DomainManager.Extra.GetSectMainStoryEventArgBox(11);
		sectArgBox.Get(SectMainStoryEventArgKey.DefValue.JingangTriggeredInteractionVillagers, out IntList triggeredInteractionVillagers);
		if (triggeredInteractionVillagers.Items != null && triggeredInteractionVillagers.Items.Contains(charId))
		{
			ObjectPool<List<short>>.Instance.Return(settlementIds);
			return false;
		}
		List<int> items = triggeredInteractionVillagers.Items;
		if (items != null && items.Count >= 5)
		{
			ObjectPool<List<short>>.Instance.Return(settlementIds);
			return false;
		}
		ObjectPool<List<short>>.Instance.Return(settlementIds);
		return DomainManager.World.IsExtraTaskInProgress(196) || DomainManager.World.IsExtraTaskInProgress(204) || DomainManager.World.IsExtraTaskInProgress(197) || DomainManager.World.IsExtraTaskInProgress(199) || DomainManager.World.IsExtraTaskInProgress(205) || DomainManager.World.IsExtraTaskInProgress(206) || DomainManager.World.IsExtraTaskInProgress(207) || DomainManager.World.IsExtraTaskInProgress(212) || DomainManager.World.IsExtraTaskInProgress(213) || DomainManager.World.IsExtraTaskInProgress(214);
	}

