	public static Location JingangCreateAdventure()
	{
		short areaId = DomainManager.Map.GetAreaIdByAreaTemplateId(11);
		Span<MapBlockData> blocks = DomainManager.Map.GetAreaBlocks(areaId);
		MapBlockData selected = null;
		List<MapBlockData> neighbors = ObjectPool<List<MapBlockData>>.Instance.Get();
		for (int i = 0; i < blocks.Length; i++)
		{
			MapBlockData blockData = blocks[i];
			if (!blockData.IsNonDeveloped())
			{
				continue;
			}
			EMapBlockSubType subType = blockData.GetConfig().SubType;
			if ((subType >= EMapBlockSubType.Ruin && subType <= EMapBlockSubType.None) || DomainManager.Map.IsBlockSpecial(blockData) || DomainManager.Adventure.QueryAnyAdventureOrMajorEvent(blockData))
			{
				continue;
			}
			Location location = blockData.GetLocation();
			neighbors.Clear();
			DomainManager.Map.GetLocationByDistance(location, 1, 1, ref neighbors);
			bool hasDeveloped = false;
			for (int j = 0; j < neighbors.Count; j++)
			{
				if (!neighbors[j].IsNonDeveloped())
				{
					hasDeveloped = true;
				}
			}
			if (hasDeveloped)
			{
				selected = blockData;
				break;
			}
		}
		ObjectPool<List<MapBlockData>>.Instance.Return(neighbors);
		Tester.Assert(selected != null);
		DataContext context = Domain.MainThreadDataContext;
		DomainManager.Adventure.GenerateMajorEvent(context, 142172897, selected.GetLocation());
		selected.SetVisible(visible: true, context);
		return selected.GetLocation();
	}

