	public static bool JingangWesternBuddhistMonkFollow()
	{
		TryGetFixedCharacterByTemplateId(777, out var westernBuddhistMonk);
		if (westernBuddhistMonk == null)
		{
			return false;
		}
		if (!DomainManager.Story.JingangIsInSpreadSutraTask())
		{
			return false;
		}
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		Location taiwuLocation = taiwu.GetValidLocation();
		MapBlockData taiwuBlockData = DomainManager.Map.GetBlockData(taiwuLocation.AreaId, taiwuLocation.BlockId);
		Location monkLocation = westernBuddhistMonk.GetLocation();
		MapBlockData monkBlockData = DomainManager.Map.GetBlockData(monkLocation.AreaId, monkLocation.BlockId);
		ByteCoordinate monkPos = monkBlockData.GetBlockPos();
		if (taiwuBlockData.GetManhattanDistanceToPos(monkPos.X, monkPos.Y) > 2)
		{
			DataContext context = Domain.MainThreadDataContext;
			List<MapBlockData> taiwuNeighborBlocks = ObjectPool<List<MapBlockData>>.Instance.Get();
			DomainManager.Map.GetRealNeighborBlocks(taiwuLocation.AreaId, taiwuLocation.BlockId, taiwuNeighborBlocks, 2);
			for (int i = taiwuNeighborBlocks.Count - 1; i >= 0; i--)
			{
				MapBlockData blockData = taiwuNeighborBlocks[i];
				if (IsLocationAtOrganizationRange(blockData.GetLocation(), 11))
				{
					taiwuNeighborBlocks.RemoveAt(i);
				}
			}
			if (taiwuNeighborBlocks.Count > 0)
			{
				MapBlockData targetBlockData = taiwuNeighborBlocks[context.Random.Next(0, taiwuNeighborBlocks.Count)];
				MoveFixedCharacter(westernBuddhistMonk, targetBlockData.GetLocation());
			}
			ObjectPool<List<MapBlockData>>.Instance.Return(taiwuNeighborBlocks);
		}
		return false;
	}

	public static void JingangCreateCentralPlainsMonk()
	{
		int stage = JingangSpreadSecInfoStage();
		if (stage == -1)
		{
			return;
		}
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		Location taiwuLocation = taiwu.GetValidLocation();
		MapBlockData taiwuMapBlockData = DomainManager.Map.GetBlockData(taiwuLocation.AreaId, taiwuLocation.BlockId);
		List<Location> selectNeighbors = new List<Location>();
		List<MapBlockData> blocks = DomainManager.Map.GetAreaBlocks(taiwuLocation.AreaId).ToArray().ToList();
		blocks.Sort((MapBlockData l, MapBlockData r) => l.GetBlockPos().GetManhattanDistance(taiwuMapBlockData.GetBlockPos()) - r.GetBlockPos().GetManhattanDistance(taiwuMapBlockData.GetBlockPos()));
		if (DomainManager.Map.IsAreaBroken(taiwuLocation.AreaId))
		{
			for (int i = 0; i < blocks.Count; i++)
			{
				selectNeighbors.Add(blocks[i].GetLocation());
				if (selectNeighbors.Count >= 3)
				{
					break;
				}
			}
		}
		else
		{
			for (int i2 = 0; i2 < blocks.Count; i2++)
			{
				if (!blocks[i2].IsNonDeveloped() && blocks[i2].IsPassable())
				{
					selectNeighbors.Add(blocks[i2].GetLocation());
					if (selectNeighbors.Count >= 9)
					{
						break;
					}
				}
			}
		}
		short startTemplateId = 0;
		if (stage >= 0 && stage <= 2)
		{
			startTemplateId = JingangGetStartMonkTemplateIdByStage(stage);
			for (short i3 = 0; i3 < 3; i3++)
			{
				GameData.Domains.Character.Character monk = GetOrCreateFixedCharacterByTemplateId((short)(i3 + startTemplateId));
				MoveFixedCharacter(monk, (selectNeighbors.Count >= 9) ? selectNeighbors[i3 * 3] : selectNeighbors[i3]);
			}
			SaveArgToSectMainStory(11, SectMainStoryEventArgKey.DefValue.JingangCreateCentralPlainsMonkTaiwuAreaId, taiwuLocation.AreaId);
		}
		else if (stage == 3)
		{
			GameData.Domains.Character.Character monk2 = GetOrCreateFixedCharacterByTemplateId(789);
			MoveFixedCharacter(monk2, selectNeighbors[1]);
			SaveArgToSectMainStory(11, SectMainStoryEventArgKey.DefValue.JingangCreateCentralPlainsMonkTaiwuAreaId, taiwuLocation.AreaId);
		}
	}

