	public static void ThreeCorpsesFollowingTaiwu()
	{
		sbyte status = GetSectMainStoryTaskStatus(7);
		switch (status)
		{
		case 0:
			if (IsExtraTaskChainInProgress(44))
			{
				break;
			}
			return;
		case 2:
			return;
		}
		foreach (short templateId in SectMainStoryRelatedConstants.RanshanThreeCorpsesCharacterTemplateIdList)
		{
			SectStoryThreeCorpsesCharacter corpse = DomainManager.Extra.GetRanshanThreeCorpsesCharacterByTemplateId(templateId);
			if (corpse == null || !corpse.IsAroundTaiwu || corpse.Target >= 0)
			{
				continue;
			}
			switch (status)
			{
			case 0:
				if (corpse.Progress != 3)
				{
					break;
				}
				continue;
			case 1:
				if (corpse.IsGoodEnd)
				{
					break;
				}
				continue;
			}
			GameData.Domains.Character.Character character = GetOrCreateFixedCharacterByTemplateId(templateId);
			Location location = character.GetLocation();
			if (location == Location.Invalid)
			{
				DomainManager.Extra.SetRanshanThreeCorpsesCharacterLocation(Domain.MainThreadDataContext, templateId);
				break;
			}
			GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
			Location taiwuLocation = taiwu.GetValidLocation();
			MapBlockData taiwuBlockData = DomainManager.Map.GetBlockData(taiwuLocation.AreaId, taiwuLocation.BlockId);
			ByteCoordinate pos = DomainManager.Map.GetBlockData(location.AreaId, location.BlockId).GetBlockPos();
			if (taiwuBlockData.GetManhattanDistanceToPos(pos.X, pos.Y) > 2)
			{
				DomainManager.Extra.SetRanshanThreeCorpsesCharacterLocation(Domain.MainThreadDataContext, templateId);
			}
		}
	}

