		foreach (short blockId in blockIds)
		{
			MapBlockData block = DomainManager.Map.GetBlock(location.AreaId, blockId);
			if (!DomainManager.Map.IsBlockOccupiedByCriticalAdventure(location.AreaId, block.BlockId) && DomainManager.Adventure.GenerateMajorEvent(Domain.MainThreadDataContext, 881422255, location))
			{
				block.SetVisible(visible: true, Domain.MainThreadDataContext);
				break;
			}
		}
	}

