	public static void SetCharacterSkeleton(int charId)
	{
		if (!DomainManager.Character.TryGetElement_Objects(charId, out var character))
		{
			return;
		}
		DataContext context = Domain.MainThreadDataContext;
		AvatarData avatarData = new AvatarData(character.GetAvatar());
		avatarData.ConvertAvatarToSkeleton();
		character.SetAvatar(avatarData, context);
		ItemKey oldClothingKey = character.GetEquipment()[4];
		sbyte grade = character.GetOrganizationInfo().Grade;
		if (1 == 0)
		{
		}
		short num;
		if (grade <= 5)
		{
			num = (short)((grade < 0 || grade > 2) ? 70 : 69);
		}
		else
		{
			if (grade > 8)
			{
				throw new Exception($"character {charId} has an invalid grade {character.GetOrganizationInfo().Grade}");
			}
			num = 71;
		}
		if (1 == 0)
		{
		}
		short clothingId = num;
		ItemKey newClothingKey = DomainManager.Item.CreateItem(context, 3, clothingId);
		character.AddInventoryItem(context, newClothingKey, 1);
		character.ChangeEquipment(context, -1, 4, newClothingKey);
		if (oldClothingKey.IsValid())
		{
			character.RemoveInventoryItem(context, oldClothingKey, 1, deleteItem: true);
		}
	}

	public static void SetRanshanChapter3AdventureCharacterArgs(EventArgBox argBox)
	{
		MonthlyActionsItem config = MonthlyActions.Instance[(short)82];
		int total = 0;
		IRandomSource random = Domain.MainThreadDataContext.Random;
		ushort betrayTags = 0;
		for (int i = 0; i < config.ParticipateTargetFilterList.Length; i++)
		{
			int count = argBox.GetAdventureParticipateCharacterCount(i);
			for (int j = 0; j < count; j++)
			{
				argBox.Set($"RanshanMentee{total++}", argBox.GetAdventureParticipateCharacter(i, j).GetId());
			}
		}
		argBox.Set("MenteeCount", total);
		int half = total / 2;
		for (int k = 0; k < half; k++)
		{
			betrayTags = BitOperation.SetBit(betrayTags, k, bit: true);
		}
		for (int i2 = total - 1; i2 > 0; i2--)
		{
			int swapIdx = random.Next(i2 + 1);
			bool a = BitOperation.GetBit(betrayTags, i2);
			bool b = BitOperation.GetBit(betrayTags, swapIdx);
			betrayTags = BitOperation.SetBit(betrayTags, i2, b);
			betrayTags = BitOperation.SetBit(betrayTags, swapIdx, a);
		}
		argBox.Set("BetrayTags", betrayTags);
	}

