	public static bool IsRanshanChapter3CharacterContainsBetrayTag(EventArgBox argBox)
	{
		int charId = -1;
		if (argBox.Get("CharA", ref charId))
		{
			int total = argBox.GetInt("MenteeCount");
			ushort betrayTags = argBox.GetUshort("BetrayTags");
			for (int i = 0; i < total; i++)
			{
				if (argBox.GetInt($"RanshanMentee{i}") == charId && BitOperation.GetBit(betrayTags, i))
				{
					return true;
				}
			}
		}
		return false;
	}

	public static void PickRanshanChapter3AdventureCharacters(EventArgBox argBox, int stage, bool needBetrayTag, bool betrayTag)
	{
		int total = argBox.GetInt("MenteeCount");
		ushort betrayTags = argBox.GetUshort("BetrayTags");
		int index = GetRanshanChapter3AdventureIntelligentCharacter(argBox, total, betrayTags, needBetrayTag, betrayTag);
		int charA = argBox.GetInt($"RanshanMentee{index}");
		int charB = ((stage == 1) ? argBox.GetInt($"RanshanMentee{GetRanshanChapter3AdventureIntelligentCharacter(argBox, total, betrayTags, needBetrayTag, betrayTag, index)}") : GetRanshanChapter3AdventureTemporaryCharacter(DomainManager.Character.GetElement_Objects(charA).GetOrganizationInfo().Grade, stage));
		argBox.Set("CharA", charA);
		argBox.Set("CharB", charB);
	}

	public static int GetRanshanChapter3AdventureIntelligentCharacter(EventArgBox argBox, int total, ushort betrayTags, bool needBetrayTag, bool betrayTag, int banned = -1)
	{
		ushort selectedTags = argBox.GetUshort("SelectedTags");
		for (int i = 0; i < total; i++)
		{
			if (!BitOperation.GetBit(selectedTags, i) && (!needBetrayTag || BitOperation.GetBit(betrayTags, i) == betrayTag) && i != banned)
			{
				selectedTags = BitOperation.SetBit(selectedTags, i, bit: true);
				argBox.Set("SelectedTags", selectedTags);
				return i;
			}
		}
		ResetRanshanChapter3AdventureSelectedCharacters(argBox);
		for (int j = 0; j < total; j++)
		{
			if ((!needBetrayTag || BitOperation.GetBit(betrayTags, j) == betrayTag) && j != banned)
			{
				selectedTags = BitOperation.SetBit(selectedTags, j, bit: true);
				argBox.Set("SelectedTags", selectedTags);
				return j;
			}
		}
		return -1;
	}

