	public static void RanshanChapter3AdventureAllCharacterChangeAge(EventArgBox argBox, int delta = 0)
	{
		DataContext context = Domain.MainThreadDataContext;
		if (!argBox.Get("Teammate", out CharacterSet currTeammate))
		{
			currTeammate = default(CharacterSet);
		}
		HashSet<int> collection = DomainManager.Taiwu.GetGroupCharIds().GetCollection();
		foreach (int charId in collection)
		{
			if (DomainManager.Character.TryGetElement_Objects(charId, out var character))
			{
				DomainManager.Character.RevertAllTemporaryModifications(context, character);
				if (delta > 0)
				{
					DomainManager.Character.TemporarilyModifyHealth(Domain.MainThreadDataContext, character, (short)(character.GetHealth() + delta * 10));
					DomainManager.Character.TemporarilyModifyCurrAge(Domain.MainThreadDataContext, character, (short)(character.GetCurrAge() + delta));
				}
				character.SetAvatar(context, character.GetAvatar());
				if (IsCharacterWearingChildClothing(character))
				{
					character.ForceReplaceClothing(context, 0);
				}
			}
			currTeammate.Add(charId);
		}
		GameData.Domains.Character.Character footman = GetOrCreateFixedCharacterByTemplateId(697);
		DomainManager.Character.RevertAllTemporaryModifications(context, footman);
		if (delta > 0)
		{
			DomainManager.Character.TemporarilyModifyHealth(Domain.MainThreadDataContext, footman, (short)(footman.GetHealth() + delta * 10));
			DomainManager.Character.TemporarilyModifyCurrAge(Domain.MainThreadDataContext, footman, (short)(footman.GetCurrAge() + delta));
		}
		footman.SetAvatar(context, footman.GetAvatar());
		if (IsCharacterWearingChildClothing(footman))
		{
			footman.ForceReplaceClothing(context, 37);
		}
		else
		{
			ReplaceCharacterClothingForChild(footman);
		}
		int total = argBox.GetInt("MenteeCount");
		ushort selectedTags = argBox.GetUshort("SelectedTags");
		argBox.Set("EventCharacterId", argBox.GetInt("RanshanMentee0"));
		for (int i = 0; i < total; i++)
		{
			int charId2 = argBox.GetInt($"RanshanMentee{i}");
			GameData.Domains.Character.Character character2 = DomainManager.Character.GetElement_Objects(charId2);
			DomainManager.Character.RevertAllTemporaryModifications(context, character2);
			if (delta > 0)
			{
				DomainManager.Character.TemporarilyModifyHealth(Domain.MainThreadDataContext, character2, (short)(character2.GetHealth() + delta * 10));
				DomainManager.Character.TemporarilyModifyCurrAge(Domain.MainThreadDataContext, character2, (short)(character2.GetCurrAge() + delta));
			}
			character2.SetAvatar(context, character2.GetAvatar());
			if (BitOperation.GetBit(selectedTags, i))
			{
				argBox.Set("EventCharacterId", charId2);
			}
		}
		if (delta == 0 && currTeammate.GetCount() > 0)
		{
			HashSet<int> collectionAllTeammate = currTeammate.GetCollection();
			foreach (int charId3 in collectionAllTeammate)
			{
				if (DomainManager.Character.TryGetElement_Objects(charId3, out var character3))
				{
					DomainManager.Character.RevertAllTemporaryModifications(context, character3);
					ReplaceCharacterClothingForChild(character3);
				}
			}
		}
		argBox.Set("Teammate", currTeammate);
	}

