	public static bool ShaolinLearnCombatSkill(string afterEvent, EventArgBox argBox)
	{
		DataContext context = Domain.MainThreadDataContext;
		EventArgBox sectArgBox = DomainManager.Extra.GetSectMainStoryEventArgBox(1);
		sbyte combatSkillType = -1;
		combatSkillType = (sbyte)((sectArgBox.Get(SectMainStoryEventArgKey.DefValue.ShaolinCombatSkillType, ref combatSkillType) && combatSkillType >= 0) ? combatSkillType : 0);
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		int taiwuCharId = DomainManager.Taiwu.GetTaiwuCharId();
		Dictionary<short, GameData.Domains.CombatSkill.CombatSkill> learnedCombatSkills = DomainManager.CombatSkill.GetCharCombatSkills(taiwuCharId);
		int expectedGradeGroup = sectArgBox.GetInt(SectMainStoryEventArgKey.DefValue.ShaolinDamoFightTimes);
		IReadOnlyList<CombatSkillItem> learnableCombatSkills = CombatSkillDomain.GetLearnableCombatSkills(1, combatSkillType);
		sbyte directProb = (sbyte)((!argBox.GetBool("Reverse")) ? 100 : 0);
		List<(ItemKey, int)> bookItemKeys = new List<(ItemKey, int)>();
		foreach (CombatSkillItem combatSkillCfg in learnableCombatSkills)
		{
			if (CombatSkillDomain.GetCombatSkillGradeGroup(combatSkillCfg.Grade, 1, combatSkillType) == expectedGradeGroup)
			{
				if (!learnedCombatSkills.ContainsKey(combatSkillCfg.TemplateId))
				{
					LearnCombatSkill(taiwuCharId, combatSkillCfg.TemplateId);
				}
				short bookTemplateId = combatSkillCfg.BookId;
				ItemKey itemKey = DomainManager.Item.CreateSkillBook(context, bookTemplateId, 5, -1, -1, directProb);
				taiwu.AddInventoryItem(context, itemKey, 1);
				bookItemKeys.Add((itemKey, 1));
			}
		}
		if (bookItemKeys.Count <= 0)
		{
			return false;
		}
		TaskInfoItem taskInfo = TaskInfo.Instance[139];
		string[] combatSkillIdsEventArgBoxKey = taskInfo.CombatSkillIdsEventArgBoxKey;
		if (combatSkillIdsEventArgBoxKey != null && combatSkillIdsEventArgBoxKey.Length > 0)
		{
			for (int i = 0; i < taskInfo.CombatSkillIdsEventArgBoxKey.Length; i++)
			{
				string key = taskInfo.CombatSkillIdsEventArgBoxKey[i];
				int bookId = ((i < bookItemKeys.Count) ? bookItemKeys[i].Item1.TemplateId : (-1));
				int value = ((bookId >= 0) ? Config.SkillBook.Instance[bookId].CombatSkillTemplateId : (-1));
				sectArgBox.Set(key, value);
			}
		}
		DomainManager.Extra.SaveSectMainStoryEventArgumentBox(context, 1);
		ShowGetItemPageForItems(bookItemKeys, afterEvent, argBox);
		return true;
	}

