	public static void StartDemonSlayerCombat(string afterEvent, EventArgBox argBox)
	{
		int index = -1;
		argBox.Get(EventTriggerParameter.DefValue.BossIndex, ref index);
		SectShaolinDemonSlayerData data = DomainManager.Extra.GetSectShaolinDemonSlayerData();
		DemonSlayerTrialItem config = data.GetTrialingDemon(index);
		if (config == null)
		{
			return;
		}
		DataContext context = Domain.MainThreadDataContext;
		int taiwuCharId = DomainManager.Taiwu.GetTaiwuCharId();
		foreach (DemonSlayerTrialRestrictItem restrict in data.GetTrialingRestricts(index))
		{
			if (!string.IsNullOrEmpty(restrict.EffectClassName))
			{
				Type type = Type.GetType(restrict.EffectClassName);
				Tester.Assert(type != null, "type != null");
				IReadOnlyList<int> parameters = restrict.EffectParameters;
				object effect = Activator.CreateInstance(type, taiwuCharId, parameters);
				SectShaolinDemonSlayerData sectShaolinDemonSlayerData = data;
				if (sectShaolinDemonSlayerData.TrialingRestrictEffects == null)
				{
					sectShaolinDemonSlayerData.TrialingRestrictEffects = new List<object>();
				}
				data.TrialingRestrictEffects.Add((SpecialEffectBase)effect);
			}
		}
		GameData.Domains.Character.Character character = DomainManager.Story.CreateFixedDemon(context, config.CharacterId);
		short configId = data.GetTrialingRestricts(index).GetCombatConfigId();
		StartCombat(character.GetId(), configId, afterEvent, argBox);
	}

	public static void GetSectShaolinDemonSlayerReward(string afterEvent, EventArgBox argBox)
	{
		SectShaolinDemonSlayerData data = DomainManager.Extra.GetSectShaolinDemonSlayerData();
		int index = -1;
		argBox.Get(EventTriggerParameter.DefValue.BossIndex, ref index);
		DemonSlayerTrialItem config = data.GetTrialingDemon(index);
		if (config == null)
		{
			return;
		}
		sbyte combatStatus = DomainManager.Combat.GetCombatStatus();
		if (combatStatus != 3 && combatStatus != 5)
		{
			return;
		}
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		ChangeRoleExp(taiwu, data.TrialingLevel.RewardExp);
		bool giveFirstTimeRewards = false;
		if (!data.IsDemonDefeated(config.TemplateId))
		{
			giveFirstTimeRewards = true;
			data.MarkDemonAsDefeated(config.TemplateId);
		}
		List<(ItemKey, int)> showItems = new List<(ItemKey, int)>();
		if (giveFirstTimeRewards)
		{
			ItemKey firstTimeReward = AddItemToRole(taiwu, 2, config.FirstTimeRewards, 1, -1);
			showItems.Add((firstTimeReward, 1));
		}
		foreach (PresetInventoryItem item in data.TrialingLevel.RewardItems)
		{
			ItemKey itemKey = AddItemToRole(taiwu, item.Type, item.TemplateId, item.Amount, -1);
			showItems.Add((itemKey, item.Amount));
		}
		ShowGetItemPageForItems(showItems, afterEvent, argBox);
	}

