	public static void CreateShixiangEnemy()
	{
		DataContext content = Domain.MainThreadDataContext;
		Location shixiangLocation = DomainManager.Organization.GetSettlementByOrgTemplateId(6).GetLocation();
		MapBlockItem config = MapBlock.Instance[(short)24];
		List<MapBlockData> mapBlockDataList = new List<MapBlockData>();
		DomainManager.Map.GetValidBlocksForRandomEnemy(shixiangLocation.AreaId, shixiangLocation.BlockId, config.Range, onSettlement: false, nearTaiwu: true, mapBlockDataList);
		short beginEnemyTemplateId = SectMainStoryRelatedConstants.GetBeginEnemyTemplateIdByXiangshuLevel();
		int enemyCount = content.Random.Next(10, 16);
		int count = enemyCount / 4;
		int extra = enemyCount % 4;
		DomainManager.Map.CreateRandomEnemiesOnValidBlocks(Domain.MainThreadDataContext, 4, shixiangLocation, beginEnemyTemplateId, count + extra, mapBlockDataList);
		DomainManager.Map.CreateRandomEnemiesOnValidBlocks(Domain.MainThreadDataContext, 4, shixiangLocation, (short)(beginEnemyTemplateId + 1), count, mapBlockDataList);
		DomainManager.Map.CreateRandomEnemiesOnValidBlocks(Domain.MainThreadDataContext, 4, shixiangLocation, (short)(beginEnemyTemplateId + 2), count, mapBlockDataList);
		DomainManager.Map.CreateRandomEnemiesOnValidBlocks(Domain.MainThreadDataContext, 4, shixiangLocation, (short)(beginEnemyTemplateId + 3), count, mapBlockDataList);
	}

	public static void CreateShixiangTraitorEnemy()
	{
		DataContext content = Domain.MainThreadDataContext;
		int enemyCount = content.Random.Next(15, 21);
		Location shixiangLocation = DomainManager.Organization.GetSettlementByOrgTemplateId(6).GetLocation();
		MapBlockItem config = MapBlock.Instance[(short)24];
		List<MapBlockData> mapBlockDataList = new List<MapBlockData>();
		DomainManager.Map.GetValidBlocksForRandomEnemy(shixiangLocation.AreaId, shixiangLocation.BlockId, config.Range, onSettlement: false, nearTaiwu: true, mapBlockDataList);
		short templateId = SectMainStoryRelatedConstants.GetTemplateIdOfFixedCharacterCombatWith(681, 5);
		int count = enemyCount / (templateId + 1 - 681);
		int extra = enemyCount % (templateId + 1 - 681);
		for (short i = 681; i < templateId + 1; i++)
		{
			CreateShixiangFixedEnemiesOnValidBlocks(i, (i == templateId) ? count : (count + extra), mapBlockDataList, -1);
		}
	}

	public static void CreateShixiangBarbarianEnemy()
	{
		DataContext content = Domain.MainThreadDataContext;
		int enemyCount = content.Random.Next(30, 41);
		Location shixiangLocation = DomainManager.Organization.GetSettlementByOrgTemplateId(6).GetLocation();
		MapBlockItem config = MapBlock.Instance[(short)24];
		List<MapBlockData> mapBlockDataList = new List<MapBlockData>();
		DomainManager.Map.GetValidBlocksForRandomEnemy(shixiangLocation.AreaId, shixiangLocation.BlockId, config.Range, onSettlement: false, nearTaiwu: true, mapBlockDataList);
		short templateId = SectMainStoryRelatedConstants.GetTemplateIdOfFixedCharacterCombatWith(686, 5);
		int count = enemyCount / (templateId + 1 - 686);
		int extra = enemyCount % (templateId + 1 - 686);
		for (short i = 686; i < templateId + 1; i++)
		{
			short hairColorTemplateId = SectMainStoryRelatedConstants.BarbarianMasterHairColorTemplateId[content.Random.Next(SectMainStoryRelatedConstants.BarbarianMasterHairColorTemplateId.Length)];
			CreateShixiangFixedEnemiesOnValidBlocks(i, (i == templateId) ? count : (count + extra), mapBlockDataList, hairColorTemplateId);
		}
	}

	public static void CreateShixiangFixedEnemiesOnValidBlocks(short enemyTemplateId, int enemyAmount, IList<MapBlockData> validBlocks, short hairColorId = -1)
	{
		if (enemyTemplateId <= 0)
		{
			return;
		}
		DataContext context = Domain.MainThreadDataContext;
		Tester.Assert(Config.Character.Instance[enemyTemplateId].CreatingType == 3);
		for (int i = 0; i < enemyAmount; i++)
		{
			if (validBlocks.Count == 0)
			{
				break;
			}
			int index = context.Random.Next(0, validBlocks.Count);
			Location validBlockLocation = new Location(validBlocks[index].AreaId, validBlocks[index].BlockId);
			GameData.Domains.Character.Character enemy = DomainManager.Character.CreateFixedEnemy(Domain.MainThreadDataContext, enemyTemplateId, isTemporary: false);
			int charId = enemy.GetId();
			DomainManager.Character.CompleteCreatingCharacter(charId);
			if (hairColorId != -1)
			{
				AvatarData avatarData = enemy.GetAvatar();
				avatarData.FrontHairId = hairColorId;
				avatarData.BackHairId = hairColorId;
				enemy.SetAvatar(avatarData, context);
				DomainManager.Extra.AddShixiangBarbarianMasterId(context, enemy.GetId());
			}
			MoveFixedEnemy(enemy, validBlockLocation);
		}
	}

	public static bool IsSettlementRandomEnemyClean(sbyte orgTemplateId, short charTemplateId)
	{
		Location location = DomainManager.Organization.GetSettlementByOrgTemplateId(orgTemplateId).GetLocation();
		List<short> blockList = ObjectPool<List<short>>.Instance.Get();
		blockList.Clear();
		DomainManager.Map.GetSettlementBlocksAndAffiliatedBlocks(location.AreaId, location.BlockId, blockList);
		bool flag = true;
		for (int i = 0; i < blockList.Count; i++)
		{
			MapBlockData blockData = DomainManager.Map.GetBlockData(location.AreaId, blockList[i]);
			List<MapTemplateEnemyInfo> templateEnemyList = blockData.TemplateEnemyList;
			if (templateEnemyList == null || templateEnemyList.Count <= 0)
			{
				continue;
			}
			for (int j = 0; j < blockData.TemplateEnemyList.Count; j++)
			{
				if (blockData.TemplateEnemyList[j].TemplateId == charTemplateId)
				{
					flag = false;
					break;
				}
			}
			if (!flag)
			{
				break;
			}
		}
		ObjectPool<List<short>>.Instance.Return(blockList);
		return flag;
	}

	public static bool IsSettlementFixedEnemyClean(sbyte orgTemplateId, short charTemplateId)
	{
		Location location = DomainManager.Organization.GetSettlementByOrgTemplateId(orgTemplateId).GetLocation();
		List<short> blockList = ObjectPool<List<short>>.Instance.Get();
		blockList.Clear();
		DomainManager.Map.GetSettlementBlocksAndAffiliatedBlocks(location.AreaId, location.BlockId, blockList);
		bool flag = true;
		for (int i = 0; i < blockList.Count; i++)
		{
			MapBlockData blockData = DomainManager.Map.GetBlockData(location.AreaId, blockList[i]);
			HashSet<int> enemyCharacterSet = blockData.EnemyCharacterSet;
			if (enemyCharacterSet == null || enemyCharacterSet.Count <= 0)
			{
				continue;
			}
			foreach (int charId in blockData.EnemyCharacterSet)
			{
				DomainManager.Character.TryGetElement_Objects(charId, out var character);
				if (character.GetTemplateId() == charTemplateId)
				{
					flag = false;
					break;
				}
			}
			if (!flag)
			{
				break;
			}
		}
		ObjectPool<List<short>>.Instance.Return(blockList);
		return flag;
	}

