	public static void UpdateShixiangEnemy(GameData.Domains.Character.Character enemy)
	{
		Location location = enemy.GetLocation();
		MapBlockData blockData = DomainManager.Map.GetBlockData(location.AreaId, location.BlockId);
		List<int> charIds = ObjectPool<List<int>>.Instance.Get();
		charIds.Clear();
		if (CharacterIsBarbarianMaster(enemy))
		{
			int count = 0;
			foreach (int charId in blockData.EnemyCharacterSet)
			{
				if (DomainManager.Character.TryGetElement_Objects(charId, out var character) && CharacterIsBarbarianMaster(character))
				{
					count++;
					charIds.Add(charId);
				}
			}
			if (IsExtraTaskInProgress(193))
			{
				EventArgBox sectArgBox = GetSectMainStoryEventArgBox(6);
				int taiwuKillCount1 = 0;
				sectArgBox.Get(SectMainStoryEventArgKey.DefValue.TaiwuKillBarbarianMasterCount, ref taiwuKillCount1);
				int taiwuKillCount2 = 0;
				sectArgBox.Get(SectMainStoryEventArgKey.DefValue.TaiwuKillBarbarianMasterCount2, ref taiwuKillCount2);
				SaveArgToSectMainStory(6, SectMainStoryEventArgKey.DefValue.TaiwuKillBarbarianMasterCount, taiwuKillCount1 + count);
				SaveArgToSectMainStory(6, SectMainStoryEventArgKey.DefValue.TaiwuKillBarbarianMasterCount2, taiwuKillCount2 + count);
			}
		}
		else if (CharacterIsShixiangTraitor(enemy))
		{
			foreach (int charId2 in blockData.EnemyCharacterSet)
			{
				if (DomainManager.Character.TryGetElement_Objects(charId2, out var character2) && CharacterIsShixiangTraitor(character2))
				{
					charIds.Add(charId2);
				}
			}
		}
		foreach (int charId3 in charIds)
		{
			if (DomainManager.Character.TryGetElement_Objects(charId3, out var character3))
			{
				RemoveNonIntelligentCharacter(character3);
			}
		}
		ObjectPool<List<int>>.Instance.Return(charIds);
	}

	public static void ShixiangHelpCharacterReadBook(ItemKey book, GameData.Domains.Character.Character character)
	{
		Tester.Assert(book.ItemType == 10);
		SkillBookItem bookCfg = Config.SkillBook.Instance[book.TemplateId];
		List<GameData.Domains.Character.LifeSkillItem> charLifeSkills = character.GetLearnedLifeSkills();
		int charSkillIndex = character.FindLearnedLifeSkillIndex(bookCfg.LifeSkillTemplateId);
		if (charSkillIndex < 0)
		{
			return;
		}
		GameData.Domains.Character.LifeSkillItem lifeSkillItem = charLifeSkills[charSkillIndex];
		for (byte i = 0; i < 5; i++)
		{
			if (!lifeSkillItem.IsPageRead(i))
			{
				DataContext context = Domain.MainThreadDataContext;
				character.ReadLifeSkillPage(context, charSkillIndex, i);
