	public static bool IsWuDangPrologueCheckPass(bool isConfirm)
	{
		if (DomainManager.TutorialChapter.InGuiding)
		{
			return false;
		}
		if (GetSectMainStoryTaskStatus(4) != 0)
		{
			return false;
		}
		if (!IsSectAllowLearning(4))
		{
			return false;
		}
		EventArgBox sectArgBox = GetSectMainStoryEventArgBox(4);
		if (sectArgBox.Contains<int>("ConchShip_PresetKey_SectMainStoryTriggeringStatus"))
		{
			return false;
		}
		Location taiwuLocation = DomainManager.Taiwu.GetTaiwu().GetLocation();
		Location wudangLocation = GetSettlementByOrgTemplateId(4).GetLocation();
		if (taiwuLocation.AreaId != wudangLocation.AreaId)
		{
			return false;
		}
		bool triggered = false;
		sectArgBox.Get(SectMainStoryEventArgKey.DefValue.WudangFrontEventTriggered, ref triggered);
		if (triggered)
		{
			return false;
		}
		if (!isConfirm && CheckProbability(50))
		{
			return false;
		}
		return true;
	}

