	public static void BlockOverWrittenByHeavenlyTree(int id, bool isSuccess)
	{
		DataContext context = Domain.MainThreadDataContext;
		if (!DomainManager.Extra.TryGetHeavenlyTreeById(id, out var tree))
		{
			return;
		}
		if (isSuccess)
		{
			DomainManager.Map.ChangeBlockTemplate(context, tree.Location, GetBlockTemplateIdByHeavenlyTreeTemplateId(tree.TemplateId), isTurnVisible: true);
		}
		else
		{
			MapBlockData cellBlockData = DomainManager.Map.GetBlock(tree.Location);
			if (cellBlockData.BlockSubType != EMapBlockSubType.DLCLoong)
			{
				DomainManager.Map.MakeBlockDestroyed(context, cellBlockData);
			}
			TriggerWudangHeavenlyTreeExtraTask(176);
			WudangIntEventArgChange(SectMainStoryEventArgKey.DefValue.FinishFairylandStoryCount.ArgBoxKey, -1);
		}
		DomainManager.Extra.RemoveHeavenlyTree(context, tree.Id);
		DomainManager.Character.TryGetElement_Objects(tree.Id, out var character);
		RemoveNonIntelligentCharacter(character);
		if (GetGrowingHeavenlyTreeCount() == 0)
		{
			FinishExtraTask(36, 174);
		}
		if (GetNormalSeedAndTreeCount() == 0)
		{
			FinishExtraTask(51, 364);
		}
		if (GetFindFairylandCount() == 0)
		{
			FinishExtraTask(36, 170);
		}
		if (tree.MetInDream)
		{
			DomainManager.Extra.RemoveWudangFairyland(context, tree.Location);
		}
	}

	public static short GetBlockTemplateIdByHeavenlyTreeTemplateId(short templateId)
	{
		if (1 == 0)
		{
		}
		EMapBlockSubType eMapBlockSubType = templateId switch
		{
			316 => EMapBlockSubType.Mountain, 
			317 => EMapBlockSubType.Cave, 
			318 => EMapBlockSubType.Canyon, 
			319 => EMapBlockSubType.Swamp, 
			320 => EMapBlockSubType.Hill, 
			321 => EMapBlockSubType.TaoYuan, 
			322 => EMapBlockSubType.Field, 
			323 => EMapBlockSubType.Lake, 
			324 => EMapBlockSubType.Woodland, 
			325 => EMapBlockSubType.Jungle, 
			326 => EMapBlockSubType.RiverBeach, 
			327 => EMapBlockSubType.Valley, 
			304 => EMapBlockSubType.Mountain, 
			305 => EMapBlockSubType.Cave, 
			306 => EMapBlockSubType.Canyon, 
			307 => EMapBlockSubType.Swamp, 
			308 => EMapBlockSubType.Hill, 
			309 => EMapBlockSubType.TaoYuan, 
			310 => EMapBlockSubType.Field, 
			311 => EMapBlockSubType.Lake, 
			312 => EMapBlockSubType.Woodland, 
			313 => EMapBlockSubType.Jungle, 
			314 => EMapBlockSubType.RiverBeach, 
			315 => EMapBlockSubType.Valley, 
			_ => EMapBlockSubType.Invalid, 
		};
		if (1 == 0)
		{
		}
		EMapBlockSubType type = eMapBlockSubType;
		List<int> selection = new List<int>();
		for (int index = 0; index < MapBlock.Instance.Count; index++)
		{
			if (MapBlock.Instance[index].SubType == type)
			{
				selection.Add(index);
			}
		}
		return MapBlock.Instance[selection[Domain.MainThreadDataContext.Random.Next(0, selection.Count)]].TemplateId;
	}

	public static void PlantHeavenlyTree(short itemTemplateId)
	{
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		Location taiwuLocation = taiwu.GetLocation();
		DataContext context = Domain.MainThreadDataContext;
		GameData.Domains.Character.Character character = DomainManager.Character.CreateFixedEnemy(context, 598, isTemporary: false);
		int charId = character.GetId();
		DomainManager.Character.CompleteCreatingCharacter(charId);
		character.SetLocation(taiwuLocation, context);
		DomainManager.Extra.PlantHeavenlyTree(context, charId, itemTemplateId, taiwuLocation);
		MapBlockData mapBlockData = DomainManager.Map.GetBlockData(taiwuLocation.AreaId, taiwuLocation.BlockId);
		DomainManager.Map.SetBlockData(context, mapBlockData);
		List<MapBlockData> bloodLightNeighborBlocks = ObjectPool<List<MapBlockData>>.Instance.Get();
		DomainManager.Map.GetRealNeighborBlocks(taiwuLocation.AreaId, taiwuLocation.BlockId, bloodLightNeighborBlocks, 3, includeCenter: true);
		foreach (MapBlockData neighborBlock in bloodLightNeighborBlocks)
		{
			if (!neighborBlock.Visible)
			{
				neighborBlock.SetVisible(visible: true, context);
			}
		}
		ObjectPool<List<MapBlockData>>.Instance.Return(bloodLightNeighborBlocks);
		if (!ItemTemplateHelper.CheckIsHeavenlyNormalTreeSeeds(12, itemTemplateId))
		{
			TriggerWudangHeavenlyTreeExtraTask(174);
		}
		if (GetHeavenlyTreeSeedCount() == 0)
		{
			FinishExtraTask(36, 173);
		}
		if (GetNormalSeedAndTreeCount() > 0)
		{
			TriggerExtraTask(51, 364);
		}
	}

