	public static short GetFightSnakeTemplateId(int id)
	{
		DataContext context = Domain.MainThreadDataContext;
		SectStoryHeavenlyTreeExtendable tree = GetHeavenlyTree(id);
		if (tree.SnakeTemplateId > 0)
		{
			return tree.SnakeTemplateId;
		}
		EventArgBox sectArgBox = GetSectMainStoryEventArgBox(4);
		short snakeTemplateId = -1;
		sectArgBox.Get(SectMainStoryEventArgKey.DefValue.WudangSankeFighted, out GameData.Utilities.ShortList snakes);
		if (snakes.Items == null || snakes.Items.Count == 0)
		{
			snakeTemplateId = SectMainStoryRelatedConstants.SnakeItemInfo[context.Random.Next(0, SectMainStoryRelatedConstants.SnakeItemInfo.Length)].Item1;
		}
		else
		{
			List<short> canSelect = ObjectPool<List<short>>.Instance.Get();
			for (int i = 0; i < SectMainStoryRelatedConstants.SnakeItemInfo.Length; i++)
			{
				if (!snakes.Items.Contains(SectMainStoryRelatedConstants.SnakeItemInfo[i].Item1))
				{
					canSelect.Add(SectMainStoryRelatedConstants.SnakeItemInfo[i].Item1);
				}
			}
			snakeTemplateId = canSelect[context.Random.Next(0, canSelect.Count)];
			ObjectPool<List<short>>.Instance.Return(canSelect);
		}
		SetHeavenlyTreeSnakeTemplateId(id, snakeTemplateId);
		AddFightSnakeTemplateId(snakeTemplateId);
		return snakeTemplateId;
	}

