	public static void GetHeavenlyTreeSeed(string afterString, EventArgBox argBox)
	{
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		short seedOneTemplateId = -1;
		argBox.Get("SeedOneTemplateId", ref seedOneTemplateId);
		short seedTwoTemplateId = -1;
		argBox.Get("SeedTwoTemplateId", ref seedTwoTemplateId);
		short seedThreeTemplateId = -1;
		argBox.Get("SeedThreeTemplateId", ref seedThreeTemplateId);
		ItemKey seedOne = ItemKey.Invalid;
		ItemKey seedTwo = ItemKey.Invalid;
		ItemKey seedThree = ItemKey.Invalid;
		if (seedOneTemplateId != -1)
		{
			seedOne = AddItemToRole(taiwu, 12, seedOneTemplateId, 1, -1);
		}
		if (seedTwoTemplateId != -1)
		{
			seedTwo = AddItemToRole(taiwu, 12, seedTwoTemplateId, 1, -1);
		}
		if (seedThreeTemplateId != -1)
		{
			seedThree = AddItemToRole(taiwu, 12, seedThreeTemplateId, 1, -1);
		}
		List<(ItemKey, int)> list = new List<(ItemKey, int)>();
		if (!seedOne.Equals(ItemKey.Invalid))
		{
			list.Add((seedOne, 1));
		}
		if (!seedTwo.Equals(ItemKey.Invalid))
		{
			if (!seedOne.Equals(ItemKey.Invalid) && seedTwo.Equals(seedOne))
			{
				list[0] = (seedTwo, 2);
			}
			else
			{
				list.Add((seedTwo, 1));
			}
		}
		if (!seedThree.Equals(ItemKey.Invalid))
		{
			bool found = false;
			for (int i = 0; i < list.Count; i++)
			{
				if (list[i].Item1.Equals(seedThree))
				{
					found = true;
					list[i] = (seedThree, list[i].Item2 + 1);
					break;
				}
			}
			if (!found)
			{
				list.Add((seedThree, 1));
			}
		}
		TriggerWudangHeavenlyTreeExtraTask(173);
		ShowGetItemPageForItems(list, afterString, argBox);
	}

