	public static void GetMeetImmortalAccessory(string afterString, EventArgBox argBox)
	{
		EventArgBox sectArgBox = GetSectMainStoryEventArgBox(4);
		int count = sectArgBox.GetInt(SectMainStoryEventArgKey.DefValue.MeetImmortalEventCount);
		ItemKey item1 = ItemKey.Invalid;
		ItemKey item2 = ItemKey.Invalid;
		ItemKey item3 = ItemKey.Invalid;
		switch (count)
		{
		case 1:
		{
			int index2 = 0;
			for (sbyte i2 = 0; i2 < 3; i2++)
			{
				switch (index2)
				{
				case 0:
					item1 = GetRandomItemByGrade(i2, 200);
					break;
				case 1:
					item2 = GetRandomItemByGrade(i2, 200);
					break;
				default:
					item3 = GetRandomItemByGrade(i2, 200);
					break;
				}
				index2++;
			}
			break;
		}
		case 2:
		{
			int index3 = 0;
			for (sbyte i3 = 3; i3 < 6; i3++)
			{
				if (index3 == 0)
				{
					item1 = GetRandomItemByGrade(i3, 200);
				}
				if (index3 == 1)
				{
					item2 = GetRandomItemByGrade(i3, 200);
				}
				if (index3 == 2)
				{
					item3 = GetRandomItemByGrade(i3, 200);
				}
				index3++;
			}
			break;
		}
		default:
		{
			int index = 0;
			for (sbyte i = 6; i <= 8; i++)
			{
				if (index == 0)
				{
					item1 = GetRandomItemByGrade(i, 200);
				}
				if (index == 1)
				{
					item2 = GetRandomItemByGrade(i, 200);
				}
				if (index == 2)
				{
					item3 = GetRandomItemByGrade(i, 200);
				}
				index++;
			}
			break;
		}
		}
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		ItemKey itemKey1 = AddItemToRole(taiwu, item1.ItemType, item1.TemplateId, 1, -1);
		ItemKey itemKey2 = AddItemToRole(taiwu, item2.ItemType, item2.TemplateId, 1, -1);
		ItemKey itemKey3 = AddItemToRole(taiwu, item3.ItemType, item3.TemplateId, 1, -1);
		ShowGetItemPageForItems(new List<(ItemKey, int)>
		{
			(itemKey1, 1),
			(itemKey2, 1),
			(itemKey3, 1)
		}, afterString, argBox);
	}

