			GameData.Domains.Character.Character character = DomainManager.Character.GetElement_Objects(tree.Id);
			short templateId = character.GetTemplateId();
			if (templateId < 602 && templateId >= 598)
			{
				return true;
			}
		}
		return false;
	}

