	public static void AddWudangReadBookToTree(int treeId, short templateId)
	{
		DomainManager.Extra.TryGetHeavenlyTreeById(treeId, out var tree);
		SectStoryHeavenlyTreeExtendable sectStoryHeavenlyTreeExtendable = tree;
		if (sectStoryHeavenlyTreeExtendable.ReadBookList == null)
		{
