	public static void WuxianChapterOneWishComeTrueCharmed()
	{
		List<int> idList = GetWuxianSettlementMembers();
		HashSet<int> idList2 = new HashSet<int>();
		DataContext context = Domain.MainThreadDataContext;
		int taiwuId = DomainManager.Taiwu.GetTaiwuCharId();
		int date = DomainManager.World.GetCurrDate();
		LifeRecordCollection collection = DomainManager.LifeRecord.GetLifeRecordCollection();
		foreach (int id in idList)
		{
			if (!DomainManager.Character.TryGetElement_Objects(id, out var char1))
			{
				continue;
			}
			RelatedCharacters relatedChar = DomainManager.Character.GetRelatedCharacters(id);
			if (relatedChar == null)
			{
				continue;
			}
			idList2.Clear();
			relatedChar.GetAllRelatedCharIds(idList2);
			foreach (int id2 in idList2)
			{
				if (id2 != taiwuId && DomainManager.Character.TryGetElement_Objects(id2, out var char2) && char1.GetCreatingType() == 1 && char2.GetCreatingType() == 1)
				{
					DomainManager.Character.ChangeFavorabilityOptional(context, char1, char2, -1200, 4);
				}
			}
			collection.AddWuxianDecreasedFavorability(id, date);
		}
	}

