	public static void WuxianChapterOneWishComeTrueRich()
	{
		List<int> idList = GetWuxianSettlementMembers();
		DataContext context = Domain.MainThreadDataContext;
		List<MapBlockData> neighborBlockList = new List<MapBlockData>();
		int date = DomainManager.World.GetCurrDate();
		LifeRecordCollection collection = DomainManager.LifeRecord.GetLifeRecordCollection();
		foreach (int id in idList)
		{
			if (!DomainManager.Character.TryGetElement_Objects(id, out var npc))
			{
				continue;
			}
			Location location = npc.GetLocation();
			if (location.Equals(Location.Invalid))
			{
				continue;
			}
			DomainManager.Map.GetNeighborBlocks(location.AreaId, location.BlockId, neighborBlockList);
			if (neighborBlockList.Count == 0)
			{
				continue;
			}
			for (int i = 0; i < 3; i++)
			{
				Inventory inventory = npc.GetInventory();
				if (inventory.Items.Count == 0)
				{
					continue;
				}
				sbyte minGrade = 8;
				ItemKey itemKey = ItemKey.Invalid;
				foreach (KeyValuePair<ItemKey, int> item in inventory.Items)
				{
					item.Deconstruct(out var key, out var value);
					ItemKey key2 = key;
					int count = value;
					sbyte grade = ItemTemplateHelper.GetGrade(key2.ItemType, key2.TemplateId);
					if (grade == minGrade && context.Random.NextBool())
					{
						itemKey = key2;
					}
					else if (grade < minGrade)
					{
						minGrade = grade;
						itemKey = key2;
					}
				}
				if (!itemKey.Equals(ItemKey.Invalid))
				{
					npc.RemoveInventoryItem(context, itemKey, 1, deleteItem: false);
					DomainManager.Map.AddBlockItem(context, neighborBlockList[context.Random.Next(neighborBlockList.Count)], itemKey, 1);
				}
			}
			collection.AddWuxianLoseItem(id, date, location);
		}
	}

