	public static string GetRanXinduText(sbyte type, EventArgBox argBox, bool usePrevious = false)
	{
		string res = "";
		if (usePrevious)
		{
			argBox.Get("WuxianRanXinduText", ref res);
			return "<Language Key=" + res + "/>";
		}
		DataContext context = Domain.MainThreadDataContext;
		if (type == 1)
		{
			if (context.Random.NextBool())
			{
				Location taiwuLocation = DomainManager.Taiwu.GetTaiwu().GetLocation();
				sbyte i;
				for (i = 1; i <= 15; i++)
				{
					if (GetStateIdByAreaId(DomainManager.Organization.GetSettlementByOrgTemplateId(i).GetLocation().AreaId) == GetStateIdByAreaId(taiwuLocation.AreaId))
					{
						res = SectMainStoryRelatedConstants.RanXinduFairyTexts[0][i - 1];
						break;
					}
				}
				if (i > 15)
				{
					res = SectMainStoryRelatedConstants.RanXinduFairyTexts[1][context.Random.Next(SectMainStoryRelatedConstants.RanXinduFairyTexts[1].Length)];
				}
			}
			else
			{
				res = SectMainStoryRelatedConstants.RanXinduFairyTexts[1][context.Random.Next(SectMainStoryRelatedConstants.RanXinduFairyTexts[1].Length)];
			}
		}
		else
		{
			res = SectMainStoryRelatedConstants.RanXinduFairyTexts[type][context.Random.Next(SectMainStoryRelatedConstants.RanXinduFairyTexts[type].Length)];
		}
		argBox.Set("WuxianRanXinduText", res);
		return "<Language Key=" + res + "/>";
	}

