	public static ItemKey XuannvCreateRandomJadeItemWithGradeToTaiwu(sbyte gradeMin, sbyte gradeMax, int amount = 1)
	{
		short jadeOuterItemTemplateBegin = 28;
		short jadeInnerItemTemplateBegin = 35;
		List<short> jadeMatIdList = new List<short>();
		while (gradeMin <= gradeMax)
		{
			jadeMatIdList.Add((short)(jadeOuterItemTemplateBegin + gradeMin));
			jadeMatIdList.Add((short)(jadeInnerItemTemplateBegin + gradeMin));
			gradeMin++;
		}
		CollectionUtils.Shuffle(Domain.MainThreadDataContext.Random, jadeMatIdList);
		short templateId = jadeMatIdList.GetRandom(Domain.MainThreadDataContext.Random);
		GameData.Domains.Character.Character taiwuChar = DomainManager.Taiwu.GetTaiwu();
		return AddItemToRole(taiwuChar, 5, templateId, amount, -1);
	}

