	public static bool XuannvHasTaiwuLearnedAllXuannvCombatSkills()
	{
		int taiwuCharId = DomainManager.Taiwu.GetTaiwuCharId();
		Dictionary<short, GameData.Domains.CombatSkill.CombatSkill> learnedCombatSkills = DomainManager.CombatSkill.GetCharCombatSkills(taiwuCharId);
		IReadOnlyList<IReadOnlyList<CombatSkillItem>> learnableCombatSkills = CombatSkillDomain.GetLearnableCombatSkills(8);
		foreach (IReadOnlyList<CombatSkillItem> typeCombatSkills in learnableCombatSkills)
		{
			foreach (CombatSkillItem combatSkillCfg in typeCombatSkills)
			{
				if (!learnedCombatSkills.ContainsKey(combatSkillCfg.TemplateId))
				{
					return false;
				}
			}
		}
		return true;
	}

	public static List<(ItemKey, int)> XuannvLearnCombatSkill(bool isRevers)
	{
		EventArgBox argBox = DomainManager.Extra.GetSectMainStoryEventArgBox(8);
		sbyte combatSkillType = -1;
		Tester.Assert(argBox.Get(SectMainStoryEventArgKey.DefValue.XuannvStoryPartTwoCombatSkillType, ref combatSkillType));
		int completeTimes = argBox.GetInt(SectMainStoryEventArgKey.DefValue.XuannvStoryPartThreeSearchLoverCount);
		HashSet<sbyte>[] gradeHashDistribution = new HashSet<sbyte>[3]
		{
			new HashSet<sbyte> { 0, 1, 2 },
			new HashSet<sbyte> { 3, 4, 5 },
			new HashSet<sbyte> { 6, 7, 8 }
		};
		DataContext context = Domain.MainThreadDataContext;
		GameData.Domains.Character.Character taiwuChar = DomainManager.Taiwu.GetTaiwu();
		int charId = DomainManager.Taiwu.GetTaiwuCharId();
		List<short> learnedSkills = taiwuChar.GetLearnedCombatSkills();
		IReadOnlyList<CombatSkillItem> learnableCombatSkills = CombatSkillDomain.GetLearnableCombatSkills(8, combatSkillType);
		List<(ItemKey, int)> bookList = new List<(ItemKey, int)>();
		SectMainStoryEventArgKeyItem[] keys = new SectMainStoryEventArgKeyItem[3]
		{
			SectMainStoryEventArgKey.DefValue.XuannvStoryPartThreeLearningSkillId0,
			SectMainStoryEventArgKey.DefValue.XuannvStoryPartThreeLearningSkillId1,
			SectMainStoryEventArgKey.DefValue.XuannvStoryPartThreeLearningSkillId2
		};
		int keyIndex = 0;
		foreach (CombatSkillItem skill in learnableCombatSkills)
		{
			if (gradeHashDistribution[completeTimes].Contains(skill.Grade))
			{
				short templateId = skill.TemplateId;
				if ((!learnedSkills.Contains(templateId) || !XuannvTaiwuCanLearnCombatSkill(templateId)) && keys.CheckIndex(keyIndex))
				{
					argBox.Set(keys[keyIndex++], templateId);
				}
				short bookTemplateId = Config.CombatSkill.Instance[templateId].BookId;
				ItemKey itemKey = DomainManager.Item.CreateSkillBook(context, bookTemplateId, 5, -1, -1, (sbyte)((!isRevers) ? 100 : 0));
				DomainManager.Taiwu.GetTaiwu().AddInventoryItem(context, itemKey, 1);
				bookList.Add((itemKey, 1));
				if (!learnedSkills.Contains(templateId))
				{
					LearnCombatSkill(charId, templateId);
				}
			}
		}
		argBox.Set(SectMainStoryEventArgKey.DefValue.XuannvStoryPartThreeLearningSkill, arg: true);
		SaveSectMainStoryEventArgBox(8);
		return bookList;
	}

	public static List<(ItemKey, int)> XuannvAddSkillBookOnly(bool isRevers)
	{
		EventArgBox argBox = DomainManager.Extra.GetSectMainStoryEventArgBox(8);
		sbyte combatSkillType = -1;
		if (!argBox.Get(SectMainStoryEventArgKey.DefValue.XuannvStoryPartTwoCombatSkillType, ref combatSkillType))
		{
			combatSkillType = 0;
		}
		int completeTimes = argBox.GetInt(SectMainStoryEventArgKey.DefValue.XuannvStoryPartThreeSearchLoverCount);
		HashSet<sbyte>[] gradeHashDistribution = new HashSet<sbyte>[3]
		{
			new HashSet<sbyte> { 0, 1, 2 },
			new HashSet<sbyte> { 3, 4, 5 },
			new HashSet<sbyte> { 6, 7, 8 }
		};
		DataContext context = Domain.MainThreadDataContext;
		IReadOnlyList<CombatSkillItem> learnableCombatSkills = CombatSkillDomain.GetLearnableCombatSkills(8, combatSkillType);
		List<(ItemKey, int)> bookList = new List<(ItemKey, int)>();
		foreach (CombatSkillItem skill in learnableCombatSkills)
		{
			if (gradeHashDistribution[completeTimes].Contains(skill.Grade))
			{
				short templateId = skill.TemplateId;
				short bookTemplateId = Config.CombatSkill.Instance[templateId].BookId;
				ItemKey itemKey = DomainManager.Item.CreateSkillBook(context, bookTemplateId, 5, -1, -1, (sbyte)((!isRevers) ? 100 : 0));
				DomainManager.Taiwu.GetTaiwu().AddInventoryItem(context, itemKey, 1);
				bookList.Add((itemKey, 1));
			}
		}
		SaveSectMainStoryEventArgBox(8);
		return bookList;
	}

	public static bool XuannvCombatSkillPracticeCanFightJuner()
	{
		if (XuannvHasTaiwuLearnedAllXuannvCombatSkills())
		{
			return true;
		}
		EventArgBox argBox = DomainManager.Extra.GetSectMainStoryEventArgBox(8);
		sbyte combatSkillType = -1;
		Tester.Assert(argBox.Get(SectMainStoryEventArgKey.DefValue.XuannvStoryPartTwoCombatSkillType, ref combatSkillType));
		int completeTimes = argBox.GetInt(SectMainStoryEventArgKey.DefValue.XuannvStoryPartThreeSearchLoverCount);
		(sbyte min, sbyte max) groupGradeRange = Grade.GetGroupGradeRange((sbyte)completeTimes);
		sbyte minGarde = groupGradeRange.min;
		sbyte maxGrade = groupGradeRange.max;
		GameData.Domains.Character.Character taiwuChar = DomainManager.Taiwu.GetTaiwu();
		List<short> learnedSkills = taiwuChar.GetLearnedCombatSkills();
		IReadOnlyList<CombatSkillItem> learnableCombatSkills = CombatSkillDomain.GetLearnableCombatSkills(8, combatSkillType);
		foreach (CombatSkillItem skill in learnableCombatSkills)
		{
			if (skill.Grade <= maxGrade && skill.Grade >= minGarde)
			{
				short templateId = skill.TemplateId;
				if (!learnedSkills.Contains(templateId))
				{
					return false;
				}
				if (!XuannvTaiwuCanLearnCombatSkill(templateId))
				{
					return false;
				}
			}
		}
		return true;
	}

	public static void XuannvInitJunerLoverReincarnateLocations()
	{
		EventArgBox sectArgBox = GetSectMainStoryEventArgBox(8);
		if (sectArgBox.Contains<short>(SectMainStoryEventArgKey.DefValue.XuannvStoryPartThreeLoverReincarnateSettlementId1))
		{
			return;
		}
		IRandomSource randomSource = Domain.MainThreadDataContext.Random;
		Span<short> selectables = stackalloc short[4] { 47, 49, 84, 83 };
		CollectionUtils.Shuffle(randomSource, selectables, 4);
		List<SettlementInfo> settlementList = new List<SettlementInfo>();
		Settlement taiwuSettlement = DomainManager.Organization.GetSettlementByOrgTemplateId(16);
		Span<short> span = selectables;
		for (int i = 0; i < span.Length; i++)
		{
			short areaTemplateId = span[i];
			short areaId = DomainManager.Map.GetAreaIdByAreaTemplateId(areaTemplateId);
			if (DomainManager.Map.IsAreaBroken(areaId))
			{
				continue;
			}
			MapAreaData areaData = DomainManager.Map.GetElement_Areas(areaId);
			for (int j = 0; j < 3; j++)
			{
				SettlementInfo settlementInfo = areaData.SettlementInfos[j];
				if (settlementInfo.SettlementId != taiwuSettlement.GetId() && settlementInfo.SettlementId >= 0)
				{
					settlementList.Add(settlementInfo);
				}
			}
			break;
		}
		if (settlementList.Count < 3)
		{
			Location xuannvLocation = DomainManager.Organization.GetSettlementByOrgTemplateId(8).GetLocation();
			sbyte stateTemplateId = (sbyte)(randomSource.NextBool() ? 8 : 3);
			sbyte stateId = DomainManager.Map.GetStateIdByStateTemplateId(stateTemplateId);
			List<short> areas = ObjectPool<List<short>>.Instance.Get();
			DomainManager.Map.GetAllRegularAreaInState(stateId, areas);
			areas.Remove(xuannvLocation.AreaId);
			while (settlementList.Count < 3)
			{
				short randomAreaId = areas.GetRandom(randomSource);
				areas.Remove(randomAreaId);
				MapAreaData areaData2 = DomainManager.Map.GetElement_Areas(randomAreaId);
				for (int k = 0; k < 3; k++)
				{
					SettlementInfo settlementInfo2 = areaData2.SettlementInfos[k];
					if (settlementInfo2.SettlementId != taiwuSettlement.GetId() && settlementInfo2.SettlementId >= 0)
					{
						settlementList.Add(settlementInfo2);
					}
				}
				if (areas.Count <= 0)
				{
					break;
				}
			}
			ObjectPool<List<short>>.Instance.Return(areas);
		}
		settlementList.RemoveAll(delegate(SettlementInfo e)
		{
			sbyte orgTemplateId = e.OrgTemplateId;
			return orgTemplateId >= 1 && orgTemplateId <= 15;
		});
		CollectionUtils.Shuffle(Domain.MainThreadDataContext.Random, settlementList);
		SettlementInfo randomResult = settlementList.GetRandom(Domain.MainThreadDataContext.Random);
		sectArgBox.Set(SectMainStoryEventArgKey.DefValue.XuannvStoryPartThreeLoverReincarnateSettlementId1, randomResult.SettlementId);
		if (settlementList.Count > 1)
		{
			settlementList.RemoveAll((SettlementInfo e) => e.SettlementId == randomResult.SettlementId);
		}
		randomResult = settlementList.GetRandom(Domain.MainThreadDataContext.Random);
		sectArgBox.Set(SectMainStoryEventArgKey.DefValue.XuannvStoryPartThreeLoverReincarnateSettlementId2, randomResult.SettlementId);
		if (settlementList.Count > 1)
		{
			settlementList.RemoveAll((SettlementInfo e) => e.SettlementId == randomResult.SettlementId);
		}
		randomResult = settlementList.GetRandom(Domain.MainThreadDataContext.Random);
		sectArgBox.Set(SectMainStoryEventArgKey.DefValue.XuannvStoryPartThreeLoverReincarnateSettlementId3, randomResult.SettlementId);
		SaveSectMainStoryEventArgBox(8);
	}

