	public static bool XuannvInquireSecretGuestOptionOne(EventArgBox argBox)
	{
		if (!IsExtraTaskInProgress(149))
		{
			return false;
		}
		int charId = argBox.GetInt(EventTriggerParameter.DefValue.CharacterId);
		if (IsInAnySect(charId) || CharacterIsInTaiwuGroup(charId))
		{
			return false;
		}
		short xuannvAreaId = GetAreaIdByAreaTemplateId(23);
		GameData.Domains.Character.Character role = argBox.GetCharacter();
		if (role.GetLocation().AreaId != xuannvAreaId)
		{
			return false;
		}
		EventArgBox sectArgBox = GetSectMainStoryEventArgBox(8);
		int roleId = role.GetId();
		if (sectArgBox.Contains<int>(SectMainStoryEventArgKey.DefValue.XuannvStoryPartOneNoneSectNpcInquireSecretGuest1) && sectArgBox.GetInt(SectMainStoryEventArgKey.DefValue.XuannvStoryPartOneNoneSectNpcInquireSecretGuest1) == roleId)
		{
			return false;
		}
		if (sectArgBox.Contains<int>(SectMainStoryEventArgKey.DefValue.XuannvStoryPartOneNoneSectNpcInquireSecretGuest2) && sectArgBox.GetInt(SectMainStoryEventArgKey.DefValue.XuannvStoryPartOneNoneSectNpcInquireSecretGuest2) == roleId)
		{
			return false;
		}
		if (sectArgBox.Contains<int>(SectMainStoryEventArgKey.DefValue.XuannvStoryPartOneNoneSectNpcInquireSecretGuest3) && sectArgBox.GetInt(SectMainStoryEventArgKey.DefValue.XuannvStoryPartOneNoneSectNpcInquireSecretGuest3) == roleId)
		{
			return false;
		}
		return true;
	}

