			throw new Exception("failed when creating character:ReincarnationWoman");
		}
		Location taiwuLocation = DomainManager.Taiwu.GetTaiwu().GetLocation();
		ConvertFixedCharacter(character, taiwuLocation, recreateAttributesAndQualifications: true);
		int charId = character.GetId();
		XuannvMakeSureTargetCharacterNotWhiteHair(character);
		AvatarData avatarData = character.GetAvatar();
		List<byte> allSkinColors = AvatarSkinColors.Instance.GetAllKeys();
		byte whiteSkinColorId = 0;
		allSkinColors.Remove(whiteSkinColorId);
		avatarData.ColorSkinId = allSkinColors.GetRandom(Domain.MainThreadDataContext.Random);
		character.SetAvatar(avatarData, Domain.MainThreadDataContext);
		SaveArgToSectMainStory(8, SectMainStoryEventArgKey.DefValue.XuannvStoryHeYouyuanCharId, charId);
		return charId;
	}

	public static int XuannvCreateReliveCharacter()
	{
		EventArgBox sectArgBox = GetSectMainStoryEventArgBox(8);
		sbyte gender = sectArgBox.GetSbyte(SectMainStoryEventArgKey.DefValue.XuannvStoryPartOneGuessGenderKey);
		short areaId = GetAreaIdByAreaTemplateId(8);
		MapAreaData areaData = DomainManager.Map.GetElement_Areas(areaId);
		short settlementId = areaData.SettlementInfos.GetRandom(Domain.MainThreadDataContext.Random).SettlementId;
		GameData.Domains.Character.Character taiwuChar = DomainManager.Taiwu.GetTaiwu();
		Location taiwuLocation = taiwuChar.GetLocation();
		sbyte grade = (sbyte)Domain.MainThreadDataContext.Random.Next(0, 7);
		short charAge = 16;
		if (taiwuChar.GetAgeGroup() <= 1)
		{
			charAge = taiwuChar.GetCurrAge();
		}
		GameData.Domains.Character.Character character = CreateIntelligentCharacter(taiwuLocation, gender, charAge, 900, settlementId, grade);
		if (taiwuChar.GetAgeGroup() == 2)
		{
			ItemKey equipKey = AddItemToRole(character, 3, 4, 1, -1);
			ChangeEquipment(character.GetId(), -1, 4, equipKey);
		}
		string behaviorKey = sectArgBox.GetString(SectMainStoryEventArgKey.DefValue.XuannvStoryPartOneOptionMarkKey);
		if (1 == 0)
		{
		}
		sbyte b = behaviorKey switch
		{
			"A" => 0, 
			"B" => 1, 
			"C" => 2, 
			"D" => 3, 
			"E" => 4, 
			_ => GameData.Domains.Character.BehaviorType.GetRandomBehaviorType(Domain.MainThreadDataContext.Random), 
		};
		if (1 == 0)
		{
		}
		sbyte behaviorType = b;
		character.SetBaseMorality(GameData.Domains.Character.BehaviorType.GetMiddleMoralityByBehaviorType(behaviorType), Domain.MainThreadDataContext);
		if (character.GetAgeGroup() == 2 && taiwuChar.GetAgeGroup() == 2)
		{
			ApplyRelationBecomeAdore(character, taiwuChar, targetLoveBack: false);
		}
		int unlockMusicCount = DomainManager.Extra.GetSectXuannvUnlockedMusicCount();
		short favorValue = 0;
		for (int i = SectMainStoryRelatedConstants.XuannvUnlockMusicCountToFavorability.Length - 1; i >= 0; i--)
		{
			var (count, value) = SectMainStoryRelatedConstants.XuannvUnlockMusicCountToFavorability[i];
			if (unlockMusicCount >= count)
			{
				favorValue = value;
				break;
			}
		}
		int charId = character.GetId();
		DirectlySetFavorabilities(charId, taiwuChar.GetId(), favorValue, favorValue);
		SetCharBaseLifeSkillQualification(charId, 0, 90);
		SetCharBaseLifeSkillQualification(charId, 2, 90);
