	public static void XuannvMakeSureTargetCharacterNotWhiteHair(GameData.Domains.Character.Character character)
	{
		if (character == null)
		{
			throw new Exception("null character can not XuannvMakeSureTargetCharacterNotWhiteHair");
		}
		AvatarData avatarData = character.GetAvatar();
		AvatarGroup avatarGroup = AvatarManager.Instance.GetAvatarGroup(avatarData.AvatarId);
		while (avatarData.FrontHairId == 0 || avatarData.BackHairId == 0)
		{
			(avatarData.FrontHairId, avatarData.BackHairId) = avatarGroup.GetRandomHairs(Domain.MainThreadDataContext.Random);
		}
		List<byte> allHairColors = AvatarHairColors.Instance.GetAllKeys();
		byte whiteHairColorId = 42;
		allHairColors.Remove(whiteHairColorId);
		avatarData.ColorBackHairId = (avatarData.ColorFrontHairId = allHairColors.GetRandom(Domain.MainThreadDataContext.Random));
		character.SetAvatar(avatarData, Domain.MainThreadDataContext);
	}

	public static void XuannvAdjustShiWeizhiAvatar(GameData.Domains.Character.Character character)
	{
		if (character == null)
		{
			throw new Exception("null character can not XuannvAdjustShiWeizhiAvatar");
		}
		XuannvMakeSureTargetCharacterNotWhiteHair(character);
		AvatarData avatarData = character.GetAvatar();
		avatarData.ColorSkinId = 0;
		character.SetAvatar(avatarData, Domain.MainThreadDataContext);
	}

	public static void XuannvUpdateLoverLocationInArgBox()
	{
		EventArgBox sectArgBox = GetSectMainStoryEventArgBox(8);
		int searchLoveCount = sectArgBox.GetInt(SectMainStoryEventArgKey.DefValue.XuannvStoryPartThreeSearchLoverCount);
		short settlementId = sectArgBox.GetShort(SectMainStoryEventArgKey.DefValue.XuannvStoryPartThreeLoverReincarnateSettlementId1);
		switch (searchLoveCount)
		{
		case 1:
			settlementId = sectArgBox.GetShort(SectMainStoryEventArgKey.DefValue.XuannvStoryPartThreeLoverReincarnateSettlementId2);
			break;
		case 2:
			settlementId = sectArgBox.GetShort(SectMainStoryEventArgKey.DefValue.XuannvStoryPartThreeLoverReincarnateSettlementId3);
