		Location location = GetSettlementLocation(settlementId);
		SaveArgToSectMainStory(8, SectMainStoryEventArgKey.DefValue.XuannvStoryPartThreeLoverReincarnateLocation, location);
	}

	public static void XuannvTryUnlockCurrentLocationMusic()
	{
