		Location taiwuLocation = taiwuChar.GetLocation();
		MapBlockData blockData = DomainManager.Map.GetBlock(taiwuLocation);
		if (blockData.IsCityTown())
		{
			short blockTemplateId = blockData.GetConfig().TemplateId;
