		EventArgBox sectArgBox = GetSectMainStoryEventArgBox(15);
		bool xuehouStoryPartOneTriggered = false;
		bool result1 = sectArgBox.Get(SectMainStoryEventArgKey.DefValue.XuehouStoryPartOneTriggered, ref xuehouStoryPartOneTriggered);
		bool stillAtYangzhou = false;
		bool result2 = sectArgBox.Get(SectMainStoryEventArgKey.DefValue.StillAtYangzhou, ref stillAtYangzhou);
		if (IsCharacterAtTargetSectLocation(taiwu, 35) && (!result1 || !xuehouStoryPartOneTriggered) && (!result2 || !stillAtYangzhou) && !sectArgBox.Contains<int>("ConchShip_PresetKey_SectMainStoryTriggeringStatus"))
		{
			return true;
		}
		return false;
	}

	public static void KillXuehouFollower()
	{
		List<GameData.Domains.Character.Character> characters = GetSectCharList(15, 0, 8);
		for (int i = characters.Count - 1; i >= 0; i--)
		{
			if (characters[i].GetAgeGroup() < 2)
			{
				characters.RemoveAt(i);
			}
		}
		characters.Sort((GameData.Domains.Character.Character l, GameData.Domains.Character.Character r) => l.GetOrganizationInfo().Grade.CompareTo(r.GetOrganizationInfo().Grade));
		if (characters.Count > 0)
		{
			GameData.Domains.Character.Character victim = characters[0];
			DomainManager.Character.MakeCharacterDead(Domain.MainThreadDataContext, victim, 0);
		}
	}

