	public static int MeetSkeletonWithBellExtraProb(int graveId)
	{
		if (!XuehouCanGetBell(graveId))
		{
			return 0;
		}
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		EventArgBox sectArgBox = DomainManager.Extra.GetSectMainStoryEventArgBox(15);
		int prob = sectArgBox.GetInt(SectMainStoryEventArgKey.DefValue.MeetSkeletonWithBellExtraProb);
		int newProb = taiwu.GetConsummateLevel() * 8 + prob;
		sectArgBox.Set(SectMainStoryEventArgKey.DefValue.MeetSkeletonWithBellExtraProb, newProb);
		return newProb;
	}

	public static bool XuehouCanGetBell(int graveId)
	{
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		if (!DomainManager.World.IsExtraTaskInProgress(115))
		{
			return false;
		}
		if (taiwu.GetInventory().GetInventoryItemCount(12, 371) > 0)
		{
			return false;
		}
		DomainManager.Character.TryGetElement_Graves(graveId, out var grave);
		if (grave == null)
		{
			return false;
		}
		DeadCharacter deadCharacter = DomainManager.Character.GetDeadCharacter(grave.GetId());
		if (grave.GetLocation().AreaId == DomainManager.Organization.GetSettlementByOrgTemplateId(15).GetLocation().AreaId && deadCharacter.OrganizationInfo.OrgTemplateId == 15)
		{
			return true;
		}
		return false;
	}

	public static int GetXuehouSkeletonGraveId()
	{
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		Location taiwuLocation = taiwu.GetLocation();
		List<MapBlockData> mapBlockList = ObjectPool<List<MapBlockData>>.Instance.Get();
		DomainManager.Map.GetNeighborBlocks(taiwuLocation.AreaId, taiwuLocation.BlockId, mapBlockList);
		for (int i = 0; i < mapBlockList.Count; i++)
		{
			MapBlockData mapBlock = mapBlockList[i];
			MapBlockData blockData = DomainManager.Map.GetBlockData(mapBlock.AreaId, mapBlock.BlockId);
			if (blockData.GraveSet == null)
			{
				continue;
			}
			foreach (int graveId in blockData.GraveSet)
			{
				DeadCharacter deadCharacter = DomainManager.Character.TryGetDeadCharacter(graveId);
				if (deadCharacter != null)
				{
					sbyte consummateLevel = deadCharacter.GetConsummateLevel();
					if (XuehouCanGetBell(graveId) && AgeGroup.GetAgeGroup(deadCharacter.CurrAge) == 2 && Math.Abs(consummateLevel - taiwu.GetConsummateLevel()) <= 2)
					{
						return graveId;
					}
				}
			}
		}
		ObjectPool<List<MapBlockData>>.Instance.Return(mapBlockList);
		return -1;
	}

