	public static bool IsShowSpecialTalk(EventArgBox argBox)
	{
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		GameData.Domains.Character.Character jixi = argBox.GetCharacter("CharacterId");
		sbyte favorType = GetFavorabilityType(jixi, taiwu);
		EventArgBox sectArgBox = GetSectMainStoryEventArgBox(15);
		bool jixiFavorite1TalkTriggered = false;
		sectArgBox.Get(SectMainStoryEventArgKey.DefValue.JixiFavorite1TalkTriggered, ref jixiFavorite1TalkTriggered);
		bool jixiFavorite2TalkTriggered = false;
		sectArgBox.Get(SectMainStoryEventArgKey.DefValue.JixiFavorite2TalkTriggered, ref jixiFavorite2TalkTriggered);
		bool jixiFavorite3TalkTriggered = false;
		sectArgBox.Get(SectMainStoryEventArgKey.DefValue.JixiFavorite3TalkTriggered, ref jixiFavorite3TalkTriggered);
		bool jixiFavorite4TalkTriggered = false;
		sectArgBox.Get(SectMainStoryEventArgKey.DefValue.JixiFavorite4TalkTriggered, ref jixiFavorite4TalkTriggered);
		bool jixiFavorite5TalkTriggered = false;
		sectArgBox.Get(SectMainStoryEventArgKey.DefValue.JixiFavorite5TalkTriggered, ref jixiFavorite5TalkTriggered);
		if ((!jixiFavorite1TalkTriggered && favorType == 1) || (!jixiFavorite2TalkTriggered && favorType == 2) || (!jixiFavorite3TalkTriggered && favorType == 3) || (!jixiFavorite4TalkTriggered && favorType == 4) || (!jixiFavorite5TalkTriggered && favorType == 5))
		{
			return true;
		}
		return false;
	}

