	public static void SettlementTreasurySetInfo(short buildingTemplateId, EventArgBox argBox)
	{
		Settlement settlement = GetTaiwuLocationSettlement();
		sbyte settlementTreasuryLayerIndex = DomainManager.Organization.GetCurrentTreasuryLayer();
		SettlementTreasury settlementTreasury = DomainManager.Organization.GetTreasury(settlement.GetId(), settlementTreasuryLayerIndex);
		argBox.Set("SettlementId", settlement.GetId());
		argBox.Set("AreaId", settlement.GetLocation().AreaId);
		bool isSect = SettlementIsSect(settlement.GetId());
		argBox.Set("IsSect", isSect);
		if (isSect)
		{
			SectSettlementSetGuardInfo(settlement, argBox);
		}
		else
		{
			int i = 0;
			DataContext context = Domain.MainThreadDataContext;
			foreach (int charId in settlement.GetGuards(context, argBox.GetSbyte(EventTriggerParameter.DefValue.TreasuryOrPrisonCurrentPage)))
			{
				argBox.Set($"Guard{++i}", charId);
			}
			argBox.Set("GuardCount", i);
		}
		bool isMidLayer = argBox.GetSbyte(EventTriggerParameter.DefValue.TreasuryOrPrisonCurrentPage) == 1;
		int supportValue = ((!isSect) ? (isMidLayer ? GlobalConfig.Instance.TreasuryRquireSpiritualDebtMid : GlobalConfig.Instance.TreasuryRquireSpiritualDebtHigh) : (isMidLayer ? GlobalConfig.Instance.TreasuryRquireApprovingMid : GlobalConfig.Instance.TreasuryRquireApprovingHigh));
		argBox.Set("SupportValue", supportValue);
	}

