	public static (bool canUse, bool wasPreviouslyAllowed) SettlementTreasuryCanUse(short settlementId, EventArgBox argBox)
	{
		bool canUse = false;
		Settlement settlement = DomainManager.Organization.GetSettlement(settlementId);
		sbyte layerIndex = 0;
		argBox.Get(EventTriggerParameter.DefValue.TreasuryOrPrisonCurrentPage, ref layerIndex);
		if (layerIndex == 0)
		{
			canUse = true;
		}
		else
		{
			bool isSect = SettlementIsSect(settlementId);
			bool isMidLayer = layerIndex == 1;
			if (isSect)
			{
				sbyte orgTemplateId = settlement.GetOrgTemplateId();
				int requiredApproving = (isMidLayer ? GlobalConfig.Instance.TreasuryRquireApprovingMid : GlobalConfig.Instance.TreasuryRquireApprovingHigh);
				canUse = GetSectApprovingRate(orgTemplateId) >= requiredApproving * 10;
			}
			else
			{
				short areaId = settlement.GetLocation().AreaId;
				int requiredSpiritualDebt = (isMidLayer ? GlobalConfig.Instance.TreasuryRquireSpiritualDebtMid : GlobalConfig.Instance.TreasuryRquireSpiritualDebtHigh);
				canUse = DomainManager.Extra.GetAreaSpiritualDebt(areaId) >= requiredSpiritualDebt;
			}
		}
		bool wasPreviouslyAllowed = settlement.HasTriggeredAllowEntryEvent[layerIndex];
		settlement.HasTriggeredAllowEntryEvent[layerIndex] = canUse;
		return (canUse: canUse, wasPreviouslyAllowed: wasPreviouslyAllowed);
	}

	public static void SettleTreasuryOperate(EventArgBox argBox)
	{
		short settlementId = GetTaiwuLocationSettlementId();
		bool takeEffect = false;
		argBox.Get("TakeEffect", ref takeEffect);
		bool startCombat = false;
		argBox.Get("StartCombat", ref startCombat);
		bool isSect = false;
		argBox.Get("IsSect", ref isSect);
		bool restart = false;
		argBox.Get("Restart", ref restart);
		sbyte settlementAlterTime = 0;
		if (startCombat)
		{
			sbyte layerIndex = 0;
			if (!argBox.Get(EventTriggerParameter.DefValue.TreasuryOrPrisonCurrentPage, ref layerIndex))
			{
				AdaptableLog.Warning($"EventArgKeys.CurrentPage not found:\n{new StackTrace()}", appendWarningMessage: true);
				layerIndex = 2;
			}
			switch (layerIndex)
			{
			case 0:
				settlementAlterTime = SettlementTreasuryEventEffect.DefValue.IntrudeSectTreasuryLow.AlterTime;
				break;
			case 1:
				settlementAlterTime = SettlementTreasuryEventEffect.DefValue.IntrudeSectTreasuryMid.AlterTime;
				break;
			case 2:
				settlementAlterTime = SettlementTreasuryEventEffect.DefValue.IntrudeSectTreasuryHigh.AlterTime;
				break;
			default:
				settlementAlterTime = SettlementTreasuryEventEffect.DefValue.IntrudeSectTreasuryHigh.AlterTime;
				AdaptableLog.Warning($"EventArgKeys.CurrentPage value {layerIndex} out of range:{new StackTrace()}", appendWarningMessage: true);
				break;
			}
		}
		DomainManager.Organization.SettleTreasuryOperate(Domain.MainThreadDataContext, settlementId, takeEffect, startCombat, isSect, restart, (byte)Math.Max(0, settlementAlterTime));
		if (!startCombat)
		{
			GameData.GameDataBridge.GameDataBridge.AddDisplayEvent(DisplayEventType.SettlementTreasuryEffect);
		}
	}

	public static void SettlementTreasuryBreakingEffect(EventArgBox argBox)
	{
		short settlementId = GetTaiwuLocationSettlementId();
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		RecordRoleFameAction(taiwu, 79, -1, 1);
		DataContext context = Domain.MainThreadDataContext;
		bool isSect = SettlementIsSect(settlementId);
		sbyte layerIndex = argBox.GetSbyte(EventTriggerParameter.DefValue.TreasuryOrPrisonCurrentPage);
		if (1 == 0)
		{
		}
		short num = layerIndex switch
		{
			0 => 0, 
			1 => 1, 
			2 => 2, 
			_ => throw new ArgumentOutOfRangeException("argBox", "EventArgKeys.CurrentPage value is out of valid range"), 
		};
		if (1 == 0)
		{
		}
		short effectTemplateId = num;
		SettlementTreasuryEventEffectItem effectCfg = SettlementTreasuryEventEffect.Instance[effectTemplateId];
		(CharacterSet, CharacterSet, CharacterSet, CharacterSet) affectedCharInfo = DomainManager.Organization.ApplySettlementTreasuryEventEffect(context, effectCfg, settlementId, 0, DomainManager.Organization.GetCurrentTreasuryLayer());
		LifeRecordCollection lifeRecordCollection = DomainManager.LifeRecord.GetLifeRecordCollection();
		int currDate = DomainManager.World.GetCurrDate();
		int taiwuCharId = taiwu.GetId();
		foreach (int charId in affectedCharInfo.Item1.GetCollection())
		{
			bool becomeEnemy = affectedCharInfo.Item2.Contains(charId);
			bool disapproveTaiwu = affectedCharInfo.Item4.Contains(charId);
			if (becomeEnemy && disapproveTaiwu)
			{
				lifeRecordCollection.AddIntrudeTreasuryCancelSupportMakeEnemy(charId, currDate, taiwuCharId, settlementId);
			}
			else if (becomeEnemy)
			{
				lifeRecordCollection.AddIntrudeTreasuryMakeEnemyOthers(charId, currDate, taiwuCharId, settlementId);
			}
			else if (disapproveTaiwu)
			{
				lifeRecordCollection.AddIntrudeTreasuryCancelSupport(charId, currDate, taiwuCharId, settlementId);
			}
			else
			{
				lifeRecordCollection.AddIntrudeTreasuryLostMorale(charId, currDate, taiwuCharId, settlementId);
			}
		}
		if (affectedCharInfo.Item1.GetCount() != 0)
		{
			int becomeEnemyCount = affectedCharInfo.Item2.GetCount();
			int disapproveCount = affectedCharInfo.Item4.GetCount();
			if (becomeEnemyCount > 0 && disapproveCount > 0)
			{
				lifeRecordCollection.AddIntrudeTreasuryBeCancelSupportMakeEnemy(taiwuCharId, currDate, settlementId);
			}
			else if (becomeEnemyCount > 0)
			{
				lifeRecordCollection.AddIntrudeTreasuryBeMakeEnemyOthers(taiwuCharId, currDate, settlementId);
			}
			else if (disapproveCount > 0)
			{
				lifeRecordCollection.AddIntrudeTreasuryBeCancelSupport(taiwuCharId, currDate, settlementId);
			}
			else
			{
				lifeRecordCollection.AddIntrudeTreasuryBeLostMorale2(taiwuCharId, currDate, settlementId);
			}
		}
		if (!isSect)
		{
			int debtChange = effectCfg.CalcSpiritualDebtChange(0);
			if (debtChange != 0)
			{
				lifeRecordCollection.AddIntrudeTreasuryBeLostMorale(taiwuCharId, currDate, settlementId, (float)Math.Abs(debtChange) / 10f);
			}
		}
		SettlementTreasuryRecordCollection treasuryRecordCollection = DomainManager.Organization.GetSettlementTreasuryRecordCollection(context, settlementId);
		if (isSect)
		{
			treasuryRecordCollection.AddIntrudeSectTreasury(currDate, settlementId, taiwuCharId);
		}
		else
		{
			treasuryRecordCollection.AddIntrudeTownTreasury(currDate, settlementId, taiwuCharId);
		}
		DomainManager.Organization.SetSettlementTreasuryRecordCollection(context, settlementId, treasuryRecordCollection);
	}

	public static void SettlementTreasuryStoreEffect(EventArgBox argBox)
	{
		short settlementId = GetTaiwuLocationSettlementId();
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		bool isSect = SettlementIsSect(settlementId);
		LifeRecordCollection lifeRecordCollection = DomainManager.LifeRecord.GetLifeRecordCollection();
		int currDate = DomainManager.World.GetCurrDate();
		int taiwuCharId = taiwu.GetId();
		DataContext context = Domain.MainThreadDataContext;
		int totalValue = argBox.GetInt("TotalValue");
		SettlementTreasuryRecordCollection treasuryRecordCollection = DomainManager.Organization.GetSettlementTreasuryRecordCollection(context, settlementId);
		if (isSect)
		{
			treasuryRecordCollection.AddDonateSectTreasury(currDate, settlementId, taiwuCharId);
		}
		else
		{
			treasuryRecordCollection.AddDonateTownTreasury(currDate, settlementId, taiwuCharId);
		}
		DomainManager.Organization.SetSettlementTreasuryRecordCollection(context, settlementId, treasuryRecordCollection);
		if (totalValue <= 0)
		{
			return;
		}
		short effectTemplateId = (short)(isSect ? 4 : 7);
		SettlementTreasuryEventEffectItem effectCfg = SettlementTreasuryEventEffect.Instance[effectTemplateId];
		(CharacterSet, CharacterSet, CharacterSet, CharacterSet) affectedCharInfo = DomainManager.Organization.ApplySettlementTreasuryEventEffect(context, effectCfg, settlementId, totalValue, DomainManager.Organization.GetCurrentTreasuryLayer());
		foreach (int charId in affectedCharInfo.Item1.GetCollection())
		{
			if (affectedCharInfo.Item3.Contains(charId))
			{
				lifeRecordCollection.AddDonateTreasuryProvideSupport(charId, currDate, taiwuCharId, settlementId);
			}
			else
			{
				lifeRecordCollection.AddDonateTreasuryGetMorale(charId, currDate, taiwuCharId, settlementId);
			}
		}
		if (affectedCharInfo.Item1.GetCount() != 0)
		{
			int approveCount = affectedCharInfo.Item3.GetCount();
			if (approveCount > 0)
			{
				lifeRecordCollection.AddDonateTreasuryBeProvideSupport(taiwuCharId, currDate, settlementId);
			}
			else
			{
				lifeRecordCollection.AddDonateTreasuryGetMorale2(taiwuCharId, currDate, settlementId);
			}
		}
		if (!isSect)
		{
			int debtChange = effectCfg.CalcSpiritualDebtChange(totalValue);
			if (debtChange != 0)
			{
				lifeRecordCollection.AddDonateTreasuryBeGetMorale(taiwuCharId, currDate, settlementId, (float)Math.Abs(debtChange) / 10f);
			}
		}
		if (totalValue >= Config.Accessory.Instance[(short)8].BaseValue / 15)
		{
			short fameMultiplier = SettlementTreasuryEventEffectHelper.CalcFameMultiplierByContribution(totalValue);
			RecordRoleFameAction(taiwu, 81, -1, fameMultiplier);
		}
	}

