	public static void ProcessShaveResult(DataContext context, GameData.Domains.Character.Character npcChar, GameData.Domains.Character.Character taiwuChar, ShaveResultType resultType)
	{
		sbyte npcGrade = npcChar.GetInteractionGrade();
		int gradeFactor = (npcGrade + 2) * (npcGrade + 2);
		int npcCharId = npcChar.GetId();
		int taiwuCharId = taiwuChar.GetId();
		switch (resultType)
		{
		case ShaveResultType.SucceedGift:
		{
			int moneyAmount3 = gradeFactor * 50;
			int expAmount3 = gradeFactor * 25;
			ProcessNpcPaymentToTaiwu(context, npcChar, taiwuChar, moneyAmount3, expAmount3);
			break;
		}
		case ShaveResultType.FightTaiwuWin:
			if (!DomainManager.Taiwu.IsInGroup(npcCharId))
			{
				MoveCharacterToAdjacentBlock(context, npcChar);
			}
			break;
		case ShaveResultType.FightTaiwuLose:
			DomainManager.Character.ChangeFavorabilityOptionalMonthlyEvolution(context, npcChar, taiwuChar, -4000);
			DomainManager.Character.ChangeAlertness(context, npcCharId, 10000);
			taiwuChar.RecordFameAction(context, 92, -1, 1);
			break;
		case ShaveResultType.DebateTaiwuWin:
			if (!DomainManager.Taiwu.IsInGroup(npcCharId))
			{
				MoveCharacterToAdjacentBlock(context, npcChar);
			}
			break;
		case ShaveResultType.DebateTaiwuLose:
			DomainManager.Character.ChangeFavorabilityOptionalMonthlyEvolution(context, npcChar, taiwuChar, -4000);
			DomainManager.Character.ChangeAlertness(context, npcCharId, 10000);
			taiwuChar.RecordFameAction(context, 92, -1, 1);
			break;
		case ShaveResultType.TaiwuFightWin:
		{
			if (!DomainManager.Taiwu.IsInGroup(npcCharId))
			{
				MoveCharacterToAdjacentBlock(context, npcChar);
			}
			int moneyAmount2 = gradeFactor * 50;
			int expAmount2 = gradeFactor * 25;
			ProcessNpcPaymentToTaiwu(context, npcChar, taiwuChar, moneyAmount2, expAmount2);
			break;
		}
		case ShaveResultType.TaiwuFightLose:
			DomainManager.Character.ChangeFavorabilityOptionalMonthlyEvolution(context, npcChar, taiwuChar, -2000);
			DomainManager.Character.ChangeAlertness(context, npcCharId, 5000);
			break;
		case ShaveResultType.TaiwuDebateWin:
		{
			int moneyAmount = gradeFactor * 50;
			int expAmount = gradeFactor * 25;
			ProcessNpcPaymentToTaiwu(context, npcChar, taiwuChar, moneyAmount, expAmount);
			break;
		}
		case ShaveResultType.TaiwuDebateLose:
			DomainManager.Character.ChangeFavorabilityOptionalMonthlyEvolution(context, npcChar, taiwuChar, -2000);
			DomainManager.Character.ChangeAlertness(context, npcCharId, 5000);
			break;
		}
	}

	private static void MoveCharacterToAdjacentBlock(DataContext context, GameData.Domains.Character.Character character)
	{
		Location currLocation = character.GetLocation();
		short adjacentBlockId = DomainManager.Map.GetRandomAdjacentBlockId(context.Random, currLocation.AreaId, currLocation.BlockId);
		Location newLocation = new Location(currLocation.AreaId, adjacentBlockId);
		DomainManager.Character.GroupMove(context, character, newLocation);
	}

	public static int ProcessTaiwuCompensation(DataContext context, GameData.Domains.Character.Character taiwuChar, GameData.Domains.Character.Character receiverChar, int targetAmount)
	{
		int taiwuMoney = taiwuChar.GetResource(6);
		int actualAmount = Math.Min(taiwuMoney, targetAmount);
		if (actualAmount > 0)
		{
			taiwuChar.ChangeResource(context, 6, -actualAmount);
			receiverChar.ChangeResource(context, 6, actualAmount);
		}
		return actualAmount;
	}

	private static void ProcessNpcPaymentToTaiwu(DataContext context, GameData.Domains.Character.Character npcChar, GameData.Domains.Character.Character taiwuChar, int moneyAmount, int expAmount)
	{
		List<ItemDisplayData> itemDisplayDataList = new List<ItemDisplayData>();
		int npcMoney = npcChar.GetResource(6);
		if (npcMoney >= moneyAmount)
		{
			npcChar.ChangeResource(context, 6, -moneyAmount);
			taiwuChar.ChangeResource(context, 6, moneyAmount);
			itemDisplayDataList.Add(ItemDisplayData.CreateResource(6, moneyAmount));
		}
		else
		{
			taiwuChar.ChangeExp(context, expAmount);
			ItemKey expItemKey = new ItemKey(12, 0, 8, 0);
			itemDisplayDataList.Add(new ItemDisplayData(expItemKey, expAmount));
		}
		GameData.GameDataBridge.GameDataBridge.AddDisplayEvent(DisplayEventType.OpenGetItem_Item, itemDisplayDataList, arg2: false);
	}

