	public static void StartSelectTeammateAgeGroup(EventArgBox argBox, CharacterSelectFilter filter, bool includeTaiwu, short operatorId, sbyte ageGroup, bool includeSpecial, Action onSelectFinish = null, List<int> excludeCharIds = null)
	{
		Tester.Assert(filter.FilterTemplateId == -1);
		if (!argBox.Get("SelectCharacterData", out EventSelectCharacterData data))
		{
			data = new EventSelectCharacterData();
			argBox.Set("SelectCharacterData", data);
		}
		if (data.FilterList == null)
		{
			data.FilterList = new List<CharacterSelectFilter>();
		}
		if (onSelectFinish != null)
		{
			data.OnSelectComplete = onSelectFinish;
		}
		CharacterSet teammateSet = DomainManager.Taiwu.GetGroupCharIds();
		filter.AvailableCharactersDisplayDataList = new List<CharacterDisplayData>();
		foreach (int charId in teammateSet.GetCollection())
		{
			if ((charId == DomainManager.Taiwu.GetTaiwuCharId() && !includeTaiwu) || (excludeCharIds != null && excludeCharIds.Contains(charId)))
			{
				continue;
			}
			if (ageGroup >= 0)
			{
				if (DomainManager.Character.TryGetElement_Objects(charId, out var character) && EventConditions.PerformOperation(operatorId, character.GetAgeGroup(), ageGroup))
				{
					filter.AvailableCharactersDisplayDataList.Add(DomainManager.Character.GetCharacterDisplayData(charId));
				}
			}
			else
			{
				filter.AvailableCharactersDisplayDataList.Add(DomainManager.Character.GetCharacterDisplayData(charId));
			}
		}
		if (includeSpecial)
		{
			AddSpecialTeammateToFilter(ref filter);
		}
		data.FilterList.Add(filter);
	}

	private static void AddSpecialTeammateToFilter(ref CharacterSelectFilter filter)
	{
		IReadOnlySet<int> group = DomainManager.Character.GetSpecialGroup(DomainManager.Taiwu.GetTaiwuCharId());
		foreach (int groupCharId in group)
		{
			if (!DomainManager.Character.TryGetElement_Objects(groupCharId, out var groupChar))
			{
				throw new Exception($"Trying to find {groupCharId} in {DomainManager.Taiwu.GetTaiwuCharId()}'s group, but target is no longer alive.");
			}
			filter.AvailableCharactersDisplayDataList.Add(DomainManager.Character.GetCharacterDisplayData(groupChar.GetId()));
		}
	}

	public static void StartSelectTeammateAndPrisoner(EventArgBox argBox, CharacterSelectFilter filter, bool avoidBaby, bool includeSpecial, Action onSelectFinish = null, List<int> excludeCharIds = null)
	{
		Tester.Assert(filter.FilterTemplateId == -1);
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		if (!argBox.Get("SelectCharacterData", out EventSelectCharacterData data))
		{
			data = new EventSelectCharacterData();
			argBox.Set("SelectCharacterData", data);
		}
		if (data.FilterList == null)
		{
			data.FilterList = new List<CharacterSelectFilter>();
		}
		if (onSelectFinish != null)
		{
			data.OnSelectComplete = onSelectFinish;
		}
		CharacterSet teammateSet = DomainManager.Taiwu.GetGroupCharIds();
		filter.AvailableCharactersDisplayDataList = new List<CharacterDisplayData>();
		HashSet<int> collection = teammateSet.GetCollection();
		List<int> teams = collection.ToList();
		if (DomainManager.Character.TryGetKidnappedCharacters(taiwu.GetId(), out var kidnappedCharacterList))
		{
			teams.AddRange(kidnappedCharacterList.GetCollection().ConvertAll((KidnappedCharacter e) => e.CharId));
		}
		foreach (int charId in teams)
		{
			if (charId == DomainManager.Taiwu.GetTaiwuCharId() || (excludeCharIds != null && excludeCharIds.Contains(charId)))
			{
				continue;
			}
			if (avoidBaby)
			{
				if (DomainManager.Character.TryGetElement_Objects(charId, out var character) && character.GetAgeGroup() != 0)
				{
					filter.AvailableCharactersDisplayDataList.Add(DomainManager.Character.GetCharacterDisplayData(charId));
				}
			}
			else
			{
				filter.AvailableCharactersDisplayDataList.Add(DomainManager.Character.GetCharacterDisplayData(charId));
			}
		}
		if (includeSpecial)
		{
			AddSpecialTeammateToFilter(ref filter);
		}
		short settlementId = -1;
		argBox.Get("SettlementId", ref settlementId);
		SettlementBountyDisplayData settlementBountyDisplayData = DomainManager.Organization.GetSettlementBountyDisplayData(settlementId);
		Dictionary<int, sbyte> bountyDict = settlementBountyDisplayData.BountyCharacterDisplayDataDict.ToDictionary((KeyValuePair<int, CharacterDisplayDataForSettlementBounty> v) => v.Key, (KeyValuePair<int, CharacterDisplayDataForSettlementBounty> v) => v.Value.SettlementBounty.PunishmentSeverity);
		sbyte currOrgTemplateId = (sbyte)settlementBountyDisplayData.OrgTemplateId;
		foreach (CharacterDisplayData item in filter.AvailableCharactersDisplayDataList)
		{
			if (bountyDict.ContainsKey(item.CharacterId))
			{
				item.BountyPunishmentSeverity = bountyDict[item.CharacterId];
				item.CurrOrgTemplate = currOrgTemplateId;
				item.BountyOrgTemplate = currOrgTemplateId;
			}
		}
		filter.AvailableCharactersDisplayDataList = (from x in filter.AvailableCharactersDisplayDataList.Select((CharacterDisplayData item2, int index) => new
			{
				Item = item2,
				Index = index
			})
			orderby (x.Item.CurrOrgTemplate != currOrgTemplateId) ? 1 : 0, (x.Item.CurrOrgTemplate == currOrgTemplateId) ? x.Item.BountyPunishmentSeverity : int.MinValue descending, x.Index
			select x.Item).ToList();
		data.FilterList.Add(filter);
	}

