	public static void TaiwuSelectItem(EventArgBox argBox, SelectItemFilter filter, Action onSelectFinish = null, bool includeEquipment = true, bool includeTransfer = true)
	{
		if (!argBox.Get("SelectItemInfo", out EventSelectItemData data))
		{
			data = new EventSelectItemData();
			argBox.Set("SelectItemInfo", data);
		}
		if (data.CanSelectItemList == null)
		{
			data.CanSelectItemList = new List<ITradeableContent>();
		}
		if (onSelectFinish != null)
		{
			data.OnSelectFinish = onSelectFinish;
		}
		if (data.FilterList == null)
		{
			data.FilterList = new List<SelectItemFilter>();
		}
		data.FilterList.Add(filter);
		GameData.Domains.Character.Character taiwuChar = argBox.GetCharacter("RoleTaiwu");
		if (filter.DisplayDataFilterId != 0)
		{
			List<ItemDisplayData> itemList = DomainManager.Character.GetAllInventoryItems(taiwuChar.GetId());
			if (includeEquipment)
			{
				List<ItemDisplayData> equipmentItems = DomainManager.Character.GetAllEquipmentItems(taiwuChar.GetId());
				itemList.AddRange(equipmentItems.Where((ItemDisplayData d) => d.Key.IsValid()));
			}
			Predicate<ItemDisplayData> predicate = ItemDisplayDataFilters.GetFilter(filter.DisplayDataFilterId);
			if (predicate == null)
			{
				return;
			}
			{
				foreach (ItemDisplayData itemDisplayData in itemList)
				{
					if (predicate(itemDisplayData) && !data.CanSelectItemList.Exists((ITradeableContent d) => d.Key.Equals(itemDisplayData.Key)))
					{
						data.CanSelectItemList.Add(itemDisplayData);
					}
				}
				return;
			}
		}
		List<(ItemKey, int)> items = new List<(ItemKey, int)>();
		CharacterItemFilterWrappers.FindByItemFilterRule(taiwuChar, filter.FilterTemplateId, items, searchInventory: true, includeEquipment);
		List<ItemDisplayData> filterItems = CharacterDomain.GetItemDisplayData(taiwuChar.GetId(), items, ItemSourceType.Inventory);
		foreach (ItemDisplayData itemDisplayData2 in filterItems)
		{
			if (!data.CanSelectItemList.Exists((ITradeableContent d) => d.Key.Equals(itemDisplayData2.Key)) && (includeTransfer || ItemTemplateHelper.IsTransferable(itemDisplayData2.Key.ItemType, itemDisplayData2.Key.TemplateId)))
			{
				data.CanSelectItemList.Add(itemDisplayData2);
			}
		}
	}

	public static void SelectCharacterItemRequest(int charId, EventArgBox argBox, SelectItemFilter filter, Action onSelectFinish = null, bool includeEquipment = true, bool skipAddItem = false)
	{
		SelectCharacterItemRequestWithResource(charId, argBox, filter, onSelectFinish, includeEquipment, skipAddItem);
	}

	public static void SelectCharacterItemRequestWithResource(int charId, EventArgBox argBox, SelectItemFilter filter, Action onSelectFinish = null, bool includeEquipment = true, bool skipAddItem = false, bool onlyResource = false, bool expectResource = false)
	{
		GameData.Domains.Character.Character character = DomainManager.Character.GetElement_Objects(charId);
		if (character == null)
		{
			throw new Exception("EventHelper SelectCharacterItemRequest Exception: can not find character!");
		}
		if (!argBox.Get("SelectItemInfo", out EventSelectItemData data))
		{
			data = new EventSelectItemData();
			argBox.Set("SelectItemInfo", data);
		}
		if (data.CanSelectItemList == null)
		{
			data.CanSelectItemList = new List<ITradeableContent>();
		}
		if (onSelectFinish != null)
		{
			data.OnSelectFinish = onSelectFinish;
		}
		if (data.FilterList == null)
		{
			data.FilterList = new List<SelectItemFilter>();
		}
		data.FilterList.Add(filter);
		if (skipAddItem)
		{
			return;
		}
		if (filter.DisplayDataFilterId != 0)
		{
			List<ItemDisplayData> itemList = DomainManager.Character.GetAllInventoryItems(charId);
			if (includeEquipment)
			{
				List<ItemDisplayData> equipmentItems = DomainManager.Character.GetAllEquipmentItems(charId);
				itemList.AddRange(equipmentItems.Where((ItemDisplayData d) => d.Key.IsValid()));
			}
			Predicate<ItemDisplayData> predicate = ItemDisplayDataFilters.GetFilter(filter.DisplayDataFilterId);
			if (predicate == null)
			{
				return;
			}
			ushort displayDataFilterId = filter.DisplayDataFilterId;
			bool flag = ((displayDataFilterId == 2 || displayDataFilterId == 5) ? true : false);
			bool isItemTransferable = flag;
			if (!onlyResource)
			{
				foreach (ItemDisplayData itemDisplayData in itemList)
				{
					if (predicate(itemDisplayData) && !data.CanSelectItemList.Exists((ITradeableContent d) => d.Key.Equals(itemDisplayData.Key)))
					{
						data.CanSelectItemList.Add(itemDisplayData);
					}
				}
			}
			if (isItemTransferable && !expectResource)
			{
				List<ItemDisplayData> resourceItemList = DomainManager.Character.GetResourceItemDisplayDataList(charId);
				data.CanSelectItemList.AddRange(resourceItemList);
			}
			return;
		}
		List<(ItemKey, int)> items = new List<(ItemKey, int)>();
		CharacterItemFilterWrappers.FindByItemFilterRule(character, filter.FilterTemplateId, items, searchInventory: true, includeEquipment);
		List<ItemDisplayData> filterItems = CharacterDomain.GetItemDisplayData(charId, items, ItemSourceType.Inventory);
		foreach (ItemDisplayData itemDisplayData2 in filterItems)
		{
			if (!data.CanSelectItemList.Exists((ITradeableContent d) => d.Key.Equals(itemDisplayData2.Key)))
			{
				data.CanSelectItemList.Add(itemDisplayData2);
			}
		}
	}

	public static void ExcludeItemsForEventSelectItemData(EventArgBox eventArgBox, ushort matcherId)
	{
		if (!eventArgBox.Get("SelectItemInfo", out EventSelectItemData data) || data == null)
		{
			return;
		}
		Predicate<ITradeableContent> predicate = ItemDisplayDataFilters.GetFilter(matcherId);
		if (predicate == null)
		{
			return;
		}
		for (int i = data.CanSelectItemList.Count - 1; i >= 0; i--)
		{
			ITradeableContent itemDisplayData = data.CanSelectItemList[i];
			bool flag = ((matcherId == 2 || matcherId == 5) ? true : false);
			if ((!flag || !ItemTemplateHelper.MiscResourceCanExchange(itemDisplayData.Key.ItemType, itemDisplayData.Key.TemplateId)) && !predicate(itemDisplayData))
			{
				data.CanSelectItemList.RemoveAt(i);
			}
		}
	}

