	public static void AddLearnableCombatSkillsForEventSelectItemData(EventArgBox eventArgBox, int charId)
	{
		if (!eventArgBox.Get("SelectItemInfo", out EventSelectItemData data) || data == null)
		{
			return;
		}
		GameData.Domains.Character.Character targetCharactger = DomainManager.Character.GetElement_Objects(charId);
		sbyte learnGrade = (sbyte)(GetXiangshuLevel() + 1);
		if (learnGrade < 0)
		{
			return;
		}
		List<short> canLearn = GetCharCombatSkillList(charId, -1, -1, 0, learnGrade, needBreak: false, requireTaiwuNotLearnAndRead: true);
		HashSet<short> learnableBookTemplateIds = new HashSet<short>();
		foreach (short item in canLearn)
		{
			short bookId = Config.CombatSkill.Instance[item].BookId;
			learnableBookTemplateIds.Add(bookId);
			ItemDisplayData bookData = new ItemDisplayData(10, bookId);
			bookData.IsSpecialInteract = true;
			data.CanSelectItemList.Add(bookData);
			bookData.AlertFactor = targetCharactger.GetItemAlertFactor(bookData.Key, 1);
		}
		for (int i = data.CanSelectItemList.Count - 1; i >= 0; i--)
		{
			ITradeableContent selectItem = data.CanSelectItemList[i];
			if (selectItem.Key.ItemType == 10 && !selectItem.IsSpecialInteract && learnableBookTemplateIds.Contains(selectItem.Key.TemplateId))
			{
				data.CanSelectItemList.RemoveAt(i);
			}
		}
	}

