	public static bool TryGetAppointmentOfCharacter(int charId, out Location location)
	{
		location = Location.Invalid;
		if (!DomainManager.Character.TryGetElement_Objects(charId, out var character))
		{
			return false;
		}
		CharacterGoalData currGoal = character.ActionPlanningData.PrimaryGoal;
		if (currGoal == null || currGoal.GoalTemplateId != 254 || currGoal.CurrentAction == null)
		{
			return false;
		}
		location = currGoal.CurrentAction.TargetLocation;
		if (!location.IsValid())
		{
			return false;
		}
		return true;
	}

