	{
		if (DomainManager.Character.TryGetElement_Objects(charId, out var character))
		{
			character.RemoveGoal(Domain.MainThreadDataContext, 254);
			DomainManager.Taiwu.RemoveAppointment(Domain.MainThreadDataContext, charId);
		}
	}

	public static void AppointmentChangeFavorability(int charId)
	{
		if (DomainManager.Character.TryGetElement_Objects(charId, out var character))
		{
			sbyte charBehaviorType = GetRoleBehavior(character);
			GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
			sbyte taiwuBehaviorType = GetRoleBehavior(taiwu);
			int factor = (GameData.Domains.Character.BehaviorType.IsHarmonious(charBehaviorType, taiwuBehaviorType) ? 6 : ((!GameData.Domains.Character.BehaviorType.IsConflicting(charBehaviorType, taiwuBehaviorType)) ? 4 : 2));
			short baseValue = GetTaiwuFavorabilityHotChangeValue();
			short changeValue = ClampFavorabilityChangeValue(baseValue * factor);
			ChangeFavorabilityOptionalRepeatedEvent(character, taiwu, changeValue);
		}
	}

	public static void TryAddRandomPositiveFeature()
	{
		GameData.Domains.Character.Character charTaiwu = DomainManager.Taiwu.GetTaiwu();
		List<short> featureIdList = charTaiwu.GetFeatureIds();
		List<CharacterFeatureItem> curFeatureItemList = featureIdList.ConvertAll<CharacterFeatureItem>(CharacterFeature.Instance.GetItem);
		List<short[]> canAddFeatureIdList = new List<short[]>();
		CharacterFeature.Instance.Iterate(delegate(CharacterFeatureItem cell)
		{
			if (cell.Mergeable && cell.Level == 1 && curFeatureItemList.Find((CharacterFeatureItem e) => e.MutexGroupId == cell.MutexGroupId) == null)
			{
				canAddFeatureIdList.Add(new short[2] { cell.TemplateId, cell.AppearProb });
			}
			return true;
		});
		if (canAddFeatureIdList.Count > 0)
		{
			short[] addCellData = GetRandomCellFromWeightCore(canAddFeatureIdList);
			featureIdList.Add(addCellData[0]);
			charTaiwu.SetFeatureIds(featureIdList, Domain.MainThreadDataContext);
		}
	}

