			{
				type = merchant.SelfDecideMerchantType;
			}
			return Config.MerchantType.Instance[type].TaiwuVillagerMerchantChangingTypeContent;
		}
		throw new Exception($"can not get character villager role,Id = {character.GetId()}");
	}

