	public static bool IsAbleToStartChickenEvent()
	{
		if (GetBoolFromGlobalArgBox("CheckChickenCrossSave") && DomainManager.Map.IsLocationOnSettlementBlock(DomainManager.Taiwu.GetTaiwu().GetLocation(), DomainManager.Taiwu.GetTaiwuVillageSettlementId()))
		{
			short taiwuSettlementId = DomainManager.Taiwu.GetTaiwuVillageSettlementId();
			List<short> chickens = DomainManager.Global.GetOwnedChickens();
			foreach (short templateId in chickens)
			{
				int id = DomainManager.Building.GetChickenByTemplateId(templateId);
				if (id < 0 || DomainManager.Building.GetChickenData(id).CurrentSettlementId != taiwuSettlementId)
				{
					return true;
				}
			}
		}
		return false;
	}

	public static void GetChicken()
	{
		List<GameData.Domains.Building.Chicken> displayingChickens = new List<GameData.Domains.Building.Chicken>();
		short taiwuSettlementId = DomainManager.Taiwu.GetTaiwuVillageSettlementId();
		List<short> chickens = DomainManager.Global.GetOwnedChickens();
		foreach (short templateId in chickens)
		{
			int id = DomainManager.Building.GetChickenByTemplateId(templateId);
			if (id < 0)
			{
				DomainManager.Building.AddChicken(Domain.MainThreadDataContext, taiwuSettlementId, templateId);
			}
			else if (DomainManager.Building.GetChickenData(id).CurrentSettlementId != taiwuSettlementId)
			{
				DomainManager.Building.TransferChicken(Domain.MainThreadDataContext, id, taiwuSettlementId);
			}
		}
		foreach (short templateId2 in chickens)
		{
			displayingChickens.Add(DomainManager.Building.GetChickenData(DomainManager.Building.GetChickenByTemplateId(templateId2)));
		}
		GameData.GameDataBridge.GameDataBridge.AddDisplayEvent(DisplayEventType.OpenGetItem_Chicken, displayingChickens);
	}

