	public static void SelectBequests(int charId, EventArgBox argBox)
	{
		List<ItemKey> items = DomainManager.Taiwu.GetBequest(charId);
		if (!argBox.Get("SelectItemInfo", out EventSelectItemData selectItemData))
		{
			selectItemData = new EventSelectItemData();
			selectItemData.CanSelectItemList = new List<ITradeableContent>();
			selectItemData.FilterList = new List<SelectItemFilter>();
			selectItemData.MinSelectAmount = 1;
			argBox.Set("SelectItemInfo", selectItemData);
		}
		selectItemData.FilterWithOrOperate = true;
		selectItemData.CheckSameByReferenceOnly = true;
		for (int i = 0; i < items.Count; i++)
		{
			selectItemData.FilterList.Add(new SelectItemFilter
			{
				Key = $"Bequest{i}",
				DisplayDataFilterId = 0,
				FilterTemplateId = -1
			});
			selectItemData.CanSelectItemList.Add(DomainManager.Item.GetItemDisplayData(items[i]));
		}
	}

	public static void ConfirmSelectBequests(int charId, EventArgBox argBox)
	{
		List<ItemKey> items = DomainManager.Taiwu.GetBequest(charId);
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		List<(ItemKey, int)> getItems = new List<(ItemKey, int)>();
		int count = items.Count;
		for (int i = 0; i < count; i++)
		{
			if (argBox.Get($"Bequest{i}", out ItemKey key) && key.IsValid())
			{
				ItemBase item = DomainManager.Item.GetBaseItem(key);
				if (item.Owner.Equals(new ItemOwnerKey(ItemOwnerType.BequestBook, taiwu.GetId())))
				{
					DomainManager.Item.RemoveOwner(key, ItemOwnerType.BequestBook, taiwu.GetId());
				}
				AddInventoryItem(taiwu, key);
				items.Remove(key);
				getItems.Add((key, 1));
			}
		}
		ClearBequests(charId);
		ShowGetItemPageForItems(getItems, "b5f48d91-5e87-4441-91f5-911065c3c94b", argBox);
	}

