	public static void KidnappedPrepareEscape(GameData.Domains.Character.Character kidnapper, GameData.Domains.Character.Character kidnapped)
	{
		if (DomainManager.Character.TryGetKidnappedCharacters(kidnapper.GetId(), out var list))
		{
			KidnappedCharacter kidnappedCharacter = list.GetCollection().Find((KidnappedCharacter e) => e.CharId == kidnapped.GetId());
			int resistance = DomainManager.Character.CalcKidnappedCharacterTotalResistance(kidnapper, kidnappedCharacter);
			if (kidnappedCharacter.WillEscape(resistance))
			{
				int kidnappedCharCount = list.GetCollection().Count;
				int exceedingAmount = Math.Max(0, kidnappedCharCount - kidnapper.GetKidnapMaxSlotCount());
				GameData.Domains.Character.Character character = DomainManager.Character.GetElement_Objects(kidnappedCharacter.CharId);
				int escapeRate = kidnappedCharacter.CalcEscapeRate(resistance, exceedingAmount, character.IsEscapeCertainly());
				InstantNotificationCollection instantNotifications = DomainManager.World.GetInstantNotificationCollection();
				instantNotifications.AddPrepareEscape(kidnapper.GetId(), kidnapped.GetId(), escapeRate);
			}
		}
	}

