	}

	public static short GetTargetPastSelfTaiwuPriorityRelation(int charId)
	{
		ushort relation = GetPastSelfRelationToTaiwu(charId);
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		Genealogy genealogy = DomainManager.Character.GetGenealogy(taiwu.GetId());
		if (RelationType.HasRelation(relation, 32768))
		{
			return 9;
		}
		if (RelationType.HasRelation(relation, 73))
		{
			return 0;
		}
		if (RelationType.HasRelation(relation, 1024))
		{
			return 1;
		}
		if (RelationType.HasRelation(relation, 146))
		{
			return 2;
		}
		if (RelationType.HasRelation(relation, 292))
		{
			return 3;
		}
		if (RelationType.HasRelation(relation, 512))
		{
			return 4;
		}
		if (RelationType.HasRelation(relation, 16384))
		{
			return 5;
		}
		if (RelationType.HasRelation(relation, 8192))
		{
			return 6;
		}
		if (charId == genealogy.GrandfatherId || charId == genealogy.GrandmotherId || charId == genealogy.MaternalGrandfatherId || charId == genealogy.MaternalGrandmotherId)
		{
			return 7;
		}
		if (DomainManager.Extra.IsCharacterDreamBackTaiwuGrandchild(charId))
		{
			return 8;
		}
		return -1;
	}

