	public unsafe static void HuanxinSavedByFuyuSwordAndAutoAllocateNeili()
	{
		GameData.Domains.Character.Character huanxinChar = DomainManager.Taiwu.GetTaiwu();
		huanxinChar.ChangeConsummateLevel(Domain.MainThreadDataContext, 18);
		huanxinChar.ChangeExtraNeili(Domain.MainThreadDataContext, 32000);
		huanxinChar.ChangeCurrNeili(Domain.MainThreadDataContext, 32000);
		for (int i = 0; i < 100; i++)
		{
			NeiliAllocation neiliAllocation = huanxinChar.GetNeiliAllocation();
			if (neiliAllocation.Items[1] < 90)
			{
				huanxinChar.AllocateNeili(Domain.MainThreadDataContext, 1);
			}
			if (neiliAllocation.Items[3] < 90)
			{
				huanxinChar.AllocateNeili(Domain.MainThreadDataContext, 3);
			}
			if (neiliAllocation.Items[0] < 90)
			{
				huanxinChar.AllocateNeili(Domain.MainThreadDataContext, 0);
			}
			if (neiliAllocation.Items[2] < 90)
			{
				huanxinChar.AllocateNeili(Domain.MainThreadDataContext, 2);
			}
		}
	}

