	private static void OnCombatWithSnakeDistanceChange(DataContext context, CombatCharacter mover, short distanceOffset, bool isMove, bool isForced)
	{
		if (isMove && !isForced && distanceOffset < 0)
		{
			short distance = DomainManager.Combat.GetCurrentDistance();
			if (distance == 50)
			{
				Events.UnRegisterHandler_DistanceChanged(OnCombatWithSnakeDistanceChange);
				Domain.TriggerListener("CombatDistanceWithEnemyChanged", value: true);
				DomainManager.Combat.ClearMobilityAndForbidRecover(context, mover.GetId());
				DomainManager.Combat.PermitNormalAttackInTutorial(DomainManager.Taiwu.GetTaiwuCharId());
			}
		}
	}

