				DomainManager.Combat.SetAttackForceMiss(DomainManager.Taiwu.GetTaiwuCharId(), 1);
				DomainManager.TutorialChapter.Counter = 0;
				DomainManager.TutorialChapter.CounterTarget = 1;
				Events.RegisterHandler_NormalAttackAllEnd(OnHuanxinAttackSnakeMiss);
