				DomainManager.Combat.AddInjury(Domain.MainThreadDataContext, monkCharId, 3, isInner: false, 6);
				DomainManager.Combat.AddInjury(Domain.MainThreadDataContext, monkCharId, 4, isInner: false, 6);
