	public static void StartCricketCombatWithChild(int enemyId, string onFinishEventId, EventArgBox argBox)
	{
		DataContext context = Domain.MainThreadDataContext;
		GameData.Domains.Character.Character enemyChar = DomainManager.Character.GetElement_Objects(enemyId);
		Inventory inventory = enemyChar.GetInventory();
		ItemKey wagerKey = inventory.GetInventoryItemKey(12, 93);
		if (!wagerKey.IsValid())
		{
			ItemKey itemKey = (wagerKey = DomainManager.Item.CreateMisc(context, 93));
			enemyChar.AddInventoryItem(context, itemKey, 1);
		}
		EventCricketBettingData data = DomainManager.TaiwuEvent.GetCricketBettingData();
		List<CricketWagerData> betRewards = data.BetRewards;
		if (betRewards != null && betRewards.Count == 1 && data.BetRewards[0].Wager.ItemKey == wagerKey)
		{
			AddCricketBattleDisplayEvent(enemyId, onFinishEventId, argBox, withConfig: false, doubleDamage: false, onlyNoInjuryCricket: false, 0, 8, data.BetRewards);
			return;
		}
		Wager wager = Wager.CreateItem(wagerKey, 1);
		CricketWagerData wagerData = new CricketWagerData();
		wagerData.Wager = wager;
		wagerData.MinWagerValue = DomainManager.Item.CalcMinWagerValue(wager);
		wagerData.PreRandomizedShowCricketIndex = byte.MaxValue;
		wagerData.Crickets = new List<ItemDisplayData>(3);
		for (int i = 0; i < 3; i++)
		{
			short templateId = (short)i;
			ItemKey cricket = DomainManager.Item.CreateCricket(context, templateId);
			wagerData.Crickets.Add(DomainManager.Item.GetItemDisplayData(cricket));
		}
		AddCricketBattleDisplayEvent(enemyId, onFinishEventId, argBox, withConfig: false, doubleDamage: false, onlyNoInjuryCricket: false, 0, 8, new List<CricketWagerData> { wagerData });
	}

	public static void StartCricketCombat(int enemyId, string onFinishEventId, EventArgBox argBox)
	{
		AddCricketBattleDisplayEvent(enemyId, onFinishEventId, argBox, withConfig: false, doubleDamage: false, onlyNoInjuryCricket: false, 0, 8);
	}

	public static void StartCricketCombatWithConfig(int characterId, bool doubleDamage, bool onlyNoInjuryCricket, sbyte minGrade, sbyte maxGrade, string onFinishEventId, EventArgBox argBox)
	{
		AddCricketBattleDisplayEvent(characterId, onFinishEventId, argBox, withConfig: true, doubleDamage, onlyNoInjuryCricket, minGrade, maxGrade);
	}

	public static void AddCricketBattleDisplayEvent(int enemyId, string onFinishEventId, EventArgBox argBox, bool withConfig = false, bool doubleDamage = false, bool onlyNoInjuryCricket = false, sbyte minGrade = 0, sbyte maxGrade = 8, List<CricketWagerData> specialWagerData = null)
	{
		EventCricketBettingData data = DomainManager.TaiwuEvent.GetCricketBettingData();
		if (data.IsConfirmed)
		{
			data.IsComplete = false;
			data.IsConfirmed = false;
			SetInteractionCooldown(enemyId, 7);
			Events.RaiseCricketCombatStarted(Domain.MainThreadDataContext);
			Domain.SetListenerWithActionName(onFinishEventId, argBox, "CricketCombatOver");
			if (withConfig)
			{
				GameData.GameDataBridge.GameDataBridge.AddDisplayEvent(DisplayEventType.OpenCricketBattleWithConfig, enemyId, data.Wager, data.BetRewards[data.Index], doubleDamage, onlyNoInjuryCricket, minGrade, maxGrade);
			}
			else
			{
				GameData.GameDataBridge.GameDataBridge.AddDisplayEvent(DisplayEventType.OpenCricketBattle, enemyId, data.Wager, data.BetRewards[data.Index]);
			}
		}
		else if (!data.IsComplete)
		{
			DomainManager.Item.SetCricketBattleConfig(minGrade, maxGrade, onlyNoInjuryCricket);
			data.DoubleDamage = doubleDamage;
			data.OnlyNoInjuryCricket = onlyNoInjuryCricket;
			data.MinGrade = minGrade;
			data.MaxGrade = maxGrade;
			DomainManager.Item.ResetCricketWagerData(enemyId);
			GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
			int taiwuId = taiwu.GetId();
			data.IsValid = true;
			data.AutoBet = DomainManager.Taiwu.RequestCricketBettingAutoBet();
			data.SelfCharacter = DomainManager.Character.GetCharacterDisplayData(taiwuId);
			data.TargetCharacter = DomainManager.Character.GetCharacterDisplayData(enemyId);
			data.BetRewards = specialWagerData ?? DomainManager.Item.SelectCricketWagers(Domain.MainThreadDataContext);
			data.BetItems = DomainManager.Character.GetAllInventoryItems(taiwuId);
			data.BetCharacters = new List<CharacterDisplayData>();
			data.BetCharacterValueMap.Clear();
			data.BetItems.Insert(0, new ItemDisplayData());
			for (sbyte type = 0; type < 8; type++)
			{
				int amount = taiwu.GetResource(type);
				if (amount > 0)
				{
					short templateId = Convert.ToInt16((int)type);
					ItemKey itemKey = new ItemKey(12, 0, templateId, 0);
					ItemDisplayData itemData = new ItemDisplayData
					{
						Key = itemKey,
						Amount = amount,
						Value = GlobalConfig.ResourcesWorth[type] * amount
					};
					data.BetItems.Add(itemData);
				}
			}
			foreach (int charId in DomainManager.Taiwu.GetGroupCharIds().GetCollection())
			{
				if (IsCharacterAdult(charId) && charId != taiwuId && charId != enemyId)
				{
					data.BetCharacters.Add(DomainManager.Character.GetCharacterDisplayData(charId));
				}
			}
			if (DomainManager.Character.TryGetKidnappedCharacters(taiwuId, out var list))
			{
				foreach (KidnappedCharacter victim in list.GetCollection())
				{
					if (IsCharacterAdult(victim.CharId) && victim.CharId != enemyId)
					{
						data.BetCharacters.Add(DomainManager.Character.GetCharacterDisplayData(victim.CharId));
					}
				}
			}
			foreach (CharacterDisplayData displayData in data.BetCharacters)
			{
				GameData.Domains.Character.Character character = DomainManager.Character.GetElement_Objects(displayData.CharacterId);
				data.BetCharacterValueMap[displayData.CharacterId] = Wager.CreateChar(displayData.CharacterId).CalcWagerValue(0, character.GetFame(), character.GetAttraction(), character.GetPhysiologicalAge(), character.GetGender(), character.GetOrganizationInfo().Grade);
			}
		}
		else
		{
			data.IsComplete = false;
		}
		Domain.SetCricketBettingData(data, Domain.MainThreadDataContext);
	}

