			throw new Exception("can not set empty character name to Assassination");
		}
		DomainManager.Character.SetTargetedForAssassination(charName, Domain.MainThreadDataContext);
		GameData.Domains.Character.Character sectLeader = DomainManager.Organization.GetSettlementByOrgTemplateId(13).GetLeader();
		if (sectLeader != null)
		{
			(string surname, string givenName) realName = CharacterDomain.GetRealName(sectLeader);
			string surname = realName.surname;
			string givenName = realName.givenName;
			string fullName = LocalStringManager.FormatFullName(surname, givenName);
			if (fullName == charName)
			{
				AchievementManager.RequestSetStat(Domain.MainThreadDataContext, 236, 1);
			}
		}
	}

