	private static void ItemList2DisplayData(List<(ItemKey, int)> itemList, List<ItemDisplayData> resultList)
	{
		Dictionary<ItemKey, int> dict = new Dictionary<ItemKey, int>();
		foreach (var item in itemList)
		{
			dict[item.Item1] = item.Item2;
		}
		resultList.AddRange(CharacterDomain.GetItemDisplayData(DomainManager.Taiwu.GetTaiwuCharId(), dict, ItemSourceType.Invalid));
	}

	private static void ResourceList2DisplayData(List<(ItemKey, int)> resourceList, List<ItemDisplayData> resultList)
	{
		for (int i = 0; i < resourceList.Count; i++)
		{
			ItemDisplayData resourceData = new ItemDisplayData(resourceList[i].Item1.ItemType, resourceList[i].Item1.TemplateId);
			resourceData.Amount = resourceList[i].Item2;
			resultList.Add(resourceData);
		}
	}

