	public static void SendToOutterWorld(GameData.Domains.Character.Character character)
	{
		HideIntelligentCharacter(character);
		LifeRecordCollection lifeRecordCollection = GetLifeRecordCollection();
		int currDate = GetGameDate();
		lifeRecordCollection.AddGoToOuterWorlds(character.GetId(), currDate);
		DomainManager.Character.SetOutterWorldCharacter(character.GetId(), Domain.MainThreadDataContext);
	}

	public static void ReturnFromOutterWorld(GameData.Domains.Character.Character character)
	{
		DataContext context = Domain.MainThreadDataContext;
		DomainManager.Character.UnhideCharacterOnMap(context, character, 16uL);
		if (character.GetCurrAge() < 16)
		{
			short oldAge = character.GetCurrAge();
			character.SetCurrAge(16, context);
			Events.RaiseCharacterAgeChanged(context, character, oldAge, 16);
			AvatarData avatar = character.GetAvatar();
			if (avatar.UpdateGrowableElementsShowingAbilities(character))
			{
				character.SetAvatar(avatar, context);
			}
			short temp = (short)((context.Random.Next(0, 2) == 1) ? 9 : 0);
			character.ForceReplaceClothing(context, temp);
		}
		character.RecreateFeaturesByUpgradeCount(context, 9, 3);
		character.AddFeature(context, 879);
		DomainManager.Taiwu.JoinGroup(context, character.GetId());
		LifeRecordCollection lifeRecordCollection = GetLifeRecordCollection();
		int currDate = GetGameDate();
		lifeRecordCollection.AddBackFromOuterWorlds(character.GetId(), currDate);
		DomainManager.Character.SetOutterWorldCharacter(-1, context);
	}

	private static CharacterFeatureItem FindDifferentFeatureInGroup(short fid, bool upgrade)
	{
		int newFid = (upgrade ? (fid + 1) : (fid - 1));
		CharacterFeatureItem oriConfig = CharacterFeature.Instance[fid];
		CharacterFeatureItem newConfig = CharacterFeature.Instance.GetItem((short)newFid);
		int targetLevel = oriConfig.Level + 1;
		if (newConfig == null || newConfig.MutexGroupId != oriConfig.MutexGroupId || newConfig.Level != targetLevel)
		{
			CharacterFeature.Instance.Iterate(delegate(CharacterFeatureItem config)
			{
				if (config.MutexGroupId == oriConfig.MutexGroupId && config.Level == targetLevel)
				{
					newConfig = config;
					return false;
				}
				return true;
			});
		}
		return newConfig;
	}

