	public static List<OptionConsumeInfo> GetEventConsumeInfoForProfessionSkill(int skillId)
	{
		ProfessionSkillItem skillConfig = ProfessionSkill.Instance[skillId];
		List<OptionConsumeInfo> result = new List<OptionConsumeInfo>();
		foreach (ResourceInfo item in skillConfig.ResourcesCost)
		{
			result.Add(new OptionConsumeInfo
			{
				ConsumeType = item.ResourceType,
				AutoConsume = false,
				ConsumeCount = item.ResourceCount
			});
		}
		return result;
	}
}
